-- Guide texts (zhCN) for the Polestar_Guides_Horde pack.
-- Includes the official Polestar_zhCN texts (they win) and fills every gap,
-- so the addon stays complete whatever order the addons load in.

local _, E = ...
if not (GetLocale and GetLocale() == "zhCN") then return end
if not E.enabled then return end

local G = E.guides

-- Format:
--

G["forever/class/hunter/taming-the-beast-horde"] = {
	["Adult Plainstrider"] = "成年平原陆行鸟",
	["Adult Plainstriders (level 6-7) walk the plains south-west and north-west of {area:222}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). A plainstrider flees at 25% health, so do not damage it first. Keep each rod: it goes back to Yaw."] = "成年平原陆行鸟（6-7级）在{area:222}西南和西北方的平原上活动。驯服棒用法：选中一只活着的野兽，使用{item:15908}，在整个引导期间站着不动，任由它攻击你；移动、还击或其他人帮忙都会打断引导，并消耗驯服棒本就不多的使用次数（次数用完后：摧毁驯服棒，放弃任务，再重新接受）。陆行鸟在生命值降至25%时会逃跑，所以不要先攻击它。保留每根驯服棒：要交还给雅文·刺鬃。",
	["Armored Scorpid"] = "装甲蝎",
	["At 10 go to {npc:3065}, who stands at the north edge of {area:222}. The Hunter's Path from {npc:3038} in {zone:1456}, {npc:3407} in {zone:1454} or {npc:3171} in {area:362} also leads here, for a little experience; it is only a pointer."] = "10级时，找站在 {area:222} 北缘的 {npc:3065}。{zone:1456} 的 {npc:3038}、{zone:1454} 的 {npc:3407} 或 {area:362} 的 {npc:3171} 提供的“猎人之道”也会指引你来这里，并奖励少量经验；它只是引导任务。",
	["At 10 go to {npc:3171}, the hunter trainer inside the barracks in {area:362}. If {npc:3407} in {zone:1454}, {npc:11814} in {area:367} or {npc:3038} in {zone:1456} hands you The Hunter's Path, take it and hand it to {npc:3171} for a little experience; it is only a pointer, and you can take the first rod without it."] = "10级时，找 {area:362} 兵营里的猎人训练师 {npc:3171}。如果 {zone:1454} 的 {npc:3407}、{area:367} 的 {npc:11814} 或 {zone:1456} 的 {npc:3038} 给你“猎人之道”，就接下并交给 {npc:3171}，获得少量经验；这只是引导任务，不做也能拿到第一根驯兽棒。",
	["At 10, {npc:254084}, a hunter trainer on {zone:2521}, may send you on to {area:16638} with {quest:94007}. It is only a pointer: skip it if you are already in {area:16638}."] = "10 级时，{zone:2521} 上的猎人训练师 {npc:254084} 可能会给你 {quest:94007}，让你前往 {area:16638}。这只是引导任务：如果已经在 {area:16638}，可以跳过。",
	["Dire Mottled Boar"] = "凶恶斑纹野猪",
	["Dire Mottled Boars (level 6-7) roam just north and west of {area:362}. How the rod works: target a living beast, use the {item:15908} from inside its range and stand still for the whole channel while the beast hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from {npc:3171}. The boars charge from 20 yards, so start with the rod, not {spell:75}. The tamed boar becomes your pet for practice. Keep each rod: it goes back to {npc:3171}."] = "可怕的杂斑野猪（6-7 级）在 {area:362} 正北和西边游荡。驯兽棒用法：选中一只活着的野兽，在使用范围内施放 {item:15908}，任由野兽攻击，并在整个引导期间保持不动。移动、还击、接受其他人的治疗，或任何其他人攻击野兽，都会打断引导，并消耗驯兽棒本就不多的使用次数；次数耗尽后，摧毁驯兽棒、放弃任务，再找 {npc:3171} 重新接受任务。野猪会从 20 码外冲锋，所以要用驯兽棒起手，不要用 {spell:75}。驯服的野猪会成为供你练习的宠物。每根驯兽棒都要留着：需要交回给 {npc:3171}。",
	["Dismiss the crawler first (right-click the pet portrait, {spell:2641}). Ornery Galestriders graze in the {area:16626}, the fields a short walk west and south-west of {area:16638}."] = "先解散爬行者（右键点击宠物头像，选择{spell:2641}）。暴躁的疾风陆行鸟在{area:16626}觅食，那片田野位于{area:16638}以西及西南不远处。",
	["Dismiss the crawler. Armored Scorpids (level 7-8) crawl the dry plains west and south-west of {area:362}, some just south of the road west out of town; {spell:1494} shows them. Their hits can break the channel: start at full health and keep still."] = "解散爬行蟹。硬甲蝎（7-8 级）在 {area:362} 西边和西南的干燥平原爬行，有些就在出镇向西的道路南侧；用 {spell:1494} 可以找到它们。它们的攻击可能打断引导：满血开始，并保持不动。",
	["Dismiss the galestrider. Vuldren Alphas hunt in the same {area:16626}, a little further south."] = "解散疾风陆行鸟。瓦尔德伦头狼也在{area:16626}猎食，位置稍靠南。",
	["Dismiss the plainstrider first (right-click the pet portrait, {spell:2641}): a released practice pet may attack you. Prairie Stalkers (level 7-8) roam the grass north of {area:222}."] = "先解散陆行鸟（右键点击宠物头像，选择{spell:2641}）：被释放的练习宠物可能会攻击你。草原捕食者（7-8级）在{area:222}北面的草地游荡。",
	["Dismiss the stalker. Swoops (level 7-9) glide over the plains north-west and north-east of Bloodhoof; the Taloned Swoops do not count. A {npc:2970}'s knockdown breaks the channel, but it lands only once per channel: start the rod just after it has used it."] = "解散捕猎者。猛鹫（7—9级）在血蹄村西北和东北的平原上空滑翔；长爪猛鹫不计数。{npc:2970} 的击倒会打断引导，但每次引导期间只会击中一次：等它刚用过击倒后再使用驯兽棒。",
	["First dismiss the boar (right-click your pet's portrait, {spell:2641}): a released practice pet can turn on you. Surf Crawlers (level 7-8) walk the beaches around {area:367} and the {area:368}; the small Pygmy Surf Crawlers do not count. A crawler runs for help at 15% health, so do not hurt it."] = "先解散野猪（右键点击宠物头像，选择 {spell:2641}）：放走的练习宠物可能会反过来攻击你。海浪蟹（7-8 级）在 {area:367} 和 {area:368} 周围的海滩活动；体型较小的小海浪蟹不算。海浪蟹生命值降到 15% 时会逃跑求援，因此不要伤害它。",
	["Follow the road north to {zone:1454}'s gate. {npc:3352} stands with the hunter trainers in the {object:172958}, up the ramp at the city's east side; {npc:10088}, the pet trainer, is a few steps north of him."] = "沿路向北前往 {zone:1454} 的城门。{npc:3352} 与其他猎人训练师一起站在 {object:172958} 内，从城市东侧的坡道上去即可找到；宠物训练师 {npc:10088} 就在他北边几步远处。",
	["Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away."] = "快乐度：看宠物头像框上的表情。宠物不高兴时只造成正常伤害的四分之三，高兴时则额外造成四分之一伤害。快乐度会缓慢降低，宠物死亡后降得更快；宠物长期不高兴可能会逃跑。",
	["Head north to {zone:1456} and take a lift up. {npc:3039} stands with the hunter trainers on {area:1641}; {npc:10086}, the pet trainer, is nearby."] = "向北前往 {zone:1456}，搭乘升降梯上去。{npc:3039} 与猎人训练师们一起站在 {area:1641}；宠物训练师 {npc:10086} 就在附近。",
	["Hunter"] = "猎人",
	["Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in {spell:5149} (pet level times loyalty rank minus one)."] = "忠诚度会随相处时间和击杀增长。每提升一级忠诚等级，都能增加可用于{spell:5149}的训练点数（宠物等级乘以“忠诚等级减一”）。",
	["Near Bloodhoof: Flatland Prowlers (cats, level 9) and Prairie Wolf Alphas (wolves, 9-10) roam the plains of northern {zone:1412}; at 11-12, Savannah Huntresses (cats) prowl around the Crossroads in the {zone:1413}."] = "血蹄村附近：平原徘徊者（猫科，9级）和草原狼前锋（狼，9-10）游荡在{zone:1412}北部平原；到11-12级时，可找{zone:1413}十字路口周围的雌性草原狮（猫科）。",
	["Near Bloodhoof: Flatland Prowlers (cats, level 9) and Prairie Wolf Alphas (wolves, 9-10) roam the plains of northern {zone:1412}; at 11-12, Savannah Huntresses (cats) prowl around the {area:380} in the {zone:1413}."] = "血蹄村附近：平原徘徊者（猫科，9级）和草原狼首领（狼，9-10级）在{zone:1412}北部的平原上游荡；11-12级时，草原雌猎手（猫科）在{zone:1413}的{area:380}一带徘徊。",
	["Near {area:16638}: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the {area:16626}; Shriekling Matriarchs (raptors, level 9) nest just west of {area:16638}; Shadowgale Urseras (bears, 10-11) roam the north of {zone:2521}."] = "{area:16638} 附近：瓦尔德伦头狼（10级）在 {area:16626} 觅食，它们就是你最后一次练习驯服的野兽；尖啸幼兽主母（迅猛龙，9级）在 {area:16638} 西侧筑巢；影风乌萨拉（熊，10—11级）在 {zone:2521} 北部游荡。",
	["Near {area:362}: Durotar Tigers (cats, level 7-8) roam the south of {zone:1411}, from {area:367} down the coast; Venomtail Scorpids (9-10) the north-west toward {zone:1454}; at 11-12, Savannah Huntresses (cats) prowl the plains around the Crossroads in the {zone:1413}."] = "{area:362}附近：杜隆塔尔猛虎（猫科，7-8级）游荡在{zone:1411}南部，从{area:367}向南沿海岸分布；毒尾蝎（9-10）位于西北边、通往{zone:1454}的方向。到11-12级时，可找{zone:1413}十字路口周围平原上的雌性草原狮（猫科）。",
	["Near {area:362}: Durotar Tigers (cats, level 7-8) roam the south of {zone:1411}, from {area:367} down the coast; Venomtail Scorpids (9-10) the north-west toward {zone:1454}; at 11-12, Savannah Huntresses (cats) prowl the plains around the {area:380} in the {zone:1413}."] = "{area:362}附近：杜隆塔尔虎（猫科，7-8级）在{zone:1411}南部、从{area:367}沿海岸一带游荡；毒尾蝎（9-10级）在西北靠{zone:1454}的方向；11-12级时，草原雌猎手（猫科）在{zone:1413}的{area:380}周围的平原徘徊。",
	["Ornery Galestrider"] = "暴躁风行者",
	["Pet trainers sell {spell:1853} ranks and resistances. Horde: Harruk in {area:362}, {npc:3688} at Bloodhoof, {npc:10088} in {zone:1454}'s {object:172958}, {npc:10086} on {zone:1456}'s {area:1641}, {npc:254411} in {area:16638}, later Grokor in {area:75} and Zudd at {object:3202}."] = "宠物训练师出售各等级的 {spell:1853} 和抗性技能。部落：{area:362} 的哈鲁克、血蹄村的 {npc:3688}、{zone:1454} 的 {object:172958} 内的 {npc:10088}、{zone:1456} 的 {area:1641} 上的 {npc:10086}、{area:16638} 的 {npc:254411}，之后还有 {area:75} 的格罗科尔和 {object:3202} 处的祖德。",
	["Prairie Stalker"] = "草原潜伏者",
	["Surf Crawler"] = "海滨爬行者",
	["Swoop"] = "俯冲者",
	["Tame a beast of your level to keep"] = "驯服一只与你同级的野兽，作为长期宠物。",
	["Tame {npc:250874}"] = "驯服{npc:250874}",
	["Tame {npc:251707}"] = "驯服{npc:251707}",
	["Tame {npc:254588}"] = "驯服{npc:254588}",
	["Use the {item:15908} on a living alpha"] = "对一只活着的头狼使用{item:15908}",
	["Use the {item:15908} on a living boar"] = "对一头活着的野猪使用{item:15908}",
	["Use the {item:15908} on a living crawler"] = "对一只活着的爬行者使用{item:15908}",
	["Use the {item:15908} on a living galestrider"] = "对一只活着的风行者使用 {item:15908}。",
	["Use the {item:15908} on a living plainstrider"] = "对一只活着的陆行鸟使用{item:15908}",
	["Use the {item:15908} on a living scorpid"] = "对一只活蝎子使用 {item:15908}",
	["Use the {item:15908} on a living stalker"] = "对一只活着的捕食者使用{item:15908}",
	["Use the {item:15908} on a living {npc:2970}"] = "对一只活着的 {npc:2970} 使用 {item:15908}。",
	["Use the {item:15908} on a living {npc:3107}"] = "对一只活着的 {npc:3107} 使用 {item:15908}。",
	["Vuldren Alpha"] = "乌尔德伦首领",
	["Windsong Crawler"] = "鸣风爬行者",
	["Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of {area:16638}, among the crabs. How the rod works: target a living crawler, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs a charge. Killing one does not count."] = "风歌爬行者只生活在水边：最近的在 {area:16638} 西南面海岸，混在螃蟹中爬行。驯兽棒的用法：选中活着的爬行者，使用 {item:15908}，在整个引导过程中站着不动，任它攻击你；移动、还击或其他人的协助都会打断引导并消耗一次使用次数。击杀不计入进度。",
	["Your first pet"] = "你的第一只宠物",
	["Your own pet at 10: three practice tames with a {item:15908} teach {spell:1515}, then {spell:5149}."] = "10级获得自己的宠物：用{item:15908}练习驯服三次，学会{spell:1515}，然后学会{spell:5149}。",
	["{npc:252389} in {area:16638}"] = "{area:16638}的{npc:252389}",
	["{npc:252389} stands with the trainers by {area:16638}'s west gate, {npc:254411} beside her."] = "{npc:252389} 与训练师们一起站在 {area:16638} 西门旁，{npc:254411} 就在她身边。",
	["{npc:252389}: the first {item:15908}"] = "{npc:252389}：第一份{item:15908}",
	["{npc:254411}, beside her: {spell:5149}"] = "{npc:254411}，在她旁边：{spell:5149}",
	["{npc:3039} in {zone:1456}"] = "{zone:1456}的{npc:3039}",
	["{npc:3065} at Bloodhoof"] = "血蹄村的 {npc:3065}",
	["{npc:3065}: the first {item:15908}"] = "{npc:3065}：第一份{item:15908}",
	["{npc:3171} in {area:362}"] = "{area:362}的{npc:3171}",
	["{npc:3171}: the first {item:15908}"] = "{npc:3171}：第一份{item:15908}",
	["{npc:3352} in {zone:1454}"] = "{zone:1454}的{npc:3352}",
	["{quest:6061} (Horde)"] = "{quest:6061}（部落）",
	["{spell:1515} works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and {spell:17253}) and a boar takes more punishment."] = "{spell:1515} 的用法与驯兽棒相同：目标必须是等级不高于你的野兽，引导期间不能移动，而野兽会一直攻击你。宠物在驯服后保留原有等级，并随你一起升级；它的等级永远不能超过你，因此尽量驯服等级接近自己的野兽。在无限服，每个宠物家族都有专属技能（例如野猪的冲锋）。练级时，猫科伤害最高（爪击和 {spell:17253}），野猪则更耐打。",
	["{spell:1584}: open your spellbook, cast {spell:1584} and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Grimtak the butcher and {npc:6928} in {area:362} sell meat, {npc:3025} in {zone:1456} and the innkeepers on {zone:2521} too; Bloodhoof's innkeeper and bakers sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat."] = "{spell:1584}：打开法术书，施放{spell:1584}，再点击一种你的宠物所属家族能吃的食物（宠物的鼠标提示会列出食谱：猫科吃肉和鱼，野猪几乎什么都吃）。从野兽身上拾取的生肉也可以。购买地点：{area:362}的屠夫格瑞姆塔克和{npc:6928}出售肉类，{zone:1456}的{npc:3025}以及{zone:2521}的旅店老板也有出售；血蹄村的旅店老板和面包师出售面包。等级接近宠物的食物提供的快乐值最多；等级低很多的食物大约只有一半效果。战斗中无法喂食。",
	["{spell:5149} (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master ({npc:9987} in {area:362}, Seikwa at Bloodhoof, {npc:265756} on {zone:2521}, {npc:9988} in {zone:1454}), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with {spell:5149}. A pet holds four active abilities at most."] = "{spell:5149}（法术书的综合分页）可以将你已掌握的技能教给当前宠物。要学习新技能或更高等级：先将宠物寄放在兽栏管理员处（{area:362}的{npc:9987}、血蹄村的希克瓦、{zone:2521}的{npc:265756}或{zone:1454}的{npc:9988}），驯服一只拥有该技能的野兽（宠物法术书分页会显示它的技能），在战斗中使用该技能，直到游戏提示你已经学会，再领回自己的宠物，用{spell:5149}教给它。一只宠物最多拥有4个主动技能。",
	["{spell:883}, {spell:2641} and {spell:982} are in your spellbook now; {spell:136} comes from your trainer at 12. A dead pet needs {spell:982}; one that is away more than about 100 yards is dismissed and comes back with {spell:883}."] = "现在你的法术书中已有 {spell:883}、{spell:2641} 和 {spell:982}；到12级时，可以找训练师学习 {spell:136}。宠物死亡后需要用 {spell:982}；离你超过约100码时，宠物会被解散，可用 {spell:883} 再次召回。",
}

G["forever/class/mage/ju-ju-heaps"] = {
	["A staff or an off-hand orb at 10: Orcs and Trolls on the {area:368}, the Undead at a Tirisfal farm."] = "10级时的法杖或副手宝珠：兽人和巨魔去{area:368}，亡灵去提瑞斯法的农场。",
	["At 10 {npc:2128}, the {area:159} mage trainer upstairs in the {area:2119}, sends you to {npc:4568} in the {zone:1458}. Taking it shuts out {quest:1884}; if {quest:1883} (from {zone:1454} or {zone:1456}) is in your log, abandon it first or {npc:2128} cannot give you this one. (A Troll who took this one in {area:159} follows the Balnir steps; an Undead who took {quest:1884} in Sen'jin, the {area:368} steps.)"] = "10级时，{area:159}{area:2119}楼上的法师训练师{npc:2128}会派你去{zone:1458}找{npc:4568}。接受此任务后将无法接受{quest:1884}；如果你的任务日志中有{quest:1883}（来自{zone:1454}或{zone:1456}），请先放弃，否则{npc:2128}无法给你这个任务。（在{area:159}接受此任务的巨魔按照巴尔尼尔的步骤进行；在森金村接受{quest:1884}的亡灵按照{area:368}的步骤进行。）",
	["Back to Anastasia"] = "返回安娜斯塔西娅·哈特威尔处",
	["Back to Un'thuwa"] = "回到安苏瓦那里",
	["Ley or {item:9514} or Orb (Horde)"] = "魔网、{item:9514}或宝珠（部落）",
	["Mage"] = "法师",
	["The orb is an off-hand for a one-hand weapon; the staff is a two-hander."] = "宝珠是与单手武器搭配的副手物品，法杖则是双手武器。",
	["The {quest:1884}"] = "{quest:1884}",
	["Un'thuwa"] = "安苏瓦",
	["Un'thuwa, the troll mage trainer, stands in {area:367} on the {zone:1411} coast south of {area:362}. Orcs coming from {zone:1454} can take {quest:1883} from {npc:7311} in the {object:172961} first; it is only a pointer and Un'thuwa gives {quest:1884} without it. Taking it shuts out the {zone:1458}'s {area:165}."] = "巨魔法师训练师安苏瓦位于{zone:1411}海岸、{area:362}以南的{area:367}。从{zone:1454}出发的兽人，可先到{object:172961}找{npc:7311}接取{quest:1883}，但它只用于指引，安苏瓦无需此前置也会提供{quest:1884}。接取此任务会锁定路线，无法再做{zone:1458}的{area:165}路线。",
	["Un'thuwa: {item:7508} or {item:9513}"] = "安苏瓦：{item:7508}或{item:9513}",
	["Wade across the shallows south-east of Sen'jin to the main Echo Isle, where Zalazane (level 10) holds his camp with Hexed and Voodoo Trolls (level 8). The heaps you can click are the skull piles inside the raised huts around his camp, one hut holding two, more in the huts to the north; the skulls lying on the ground outside cannot be clicked. Destroy four. There are seven and each comes back 30 seconds after it is destroyed."] = "从森金向东南涉水，前往回音群岛主岛。10 级的扎拉赞恩与 8 级妖术巨魔和巫毒巨魔在此扎营。可点击的是营地周围高脚小屋内的颅骨堆，其中一间小屋有两堆，北侧小屋也有；屋外地面散落的颅骨无法点击。摧毁四堆即可，总共有七堆，被摧毁后三十秒刷新。",
	["Walk south from {area:159} to the {area:153} and take the lift down into the {zone:1458}. Anastasia stands in the {object:36082}, the north-east ring of the city."] = "从{area:159}向南步行前往{area:153}，乘升降梯下到{zone:1458}。安娜斯塔西娅·哈特威尔位于城市东北环区的{object:36082}。",
	["{npc:4568}: {item:7507} or {item:9514}"] = "{npc:4568}：{item:7507}或{item:9514}",
	["{object:102986}, four of them"] = "{object:102986}，摧毁四个",
	["{quest:1882} lies south-east of {area:159}, south of the road east to the {area:152}. The snapdragons grow in the farm's garden and look more like bushes than flowers; any of them will do and you need no {skill:182}. They come back within seconds."] = "{quest:1882}位于{area:159}东南侧、向东通往{area:152}的道路南侧。金鱼草生长在农场菜园里，看起来更像灌木而非花朵，任意一株都能采集，无需{skill:182}。数秒内即可刷新。",
}

G["forever/class/mage/nether-lace-garment"] = {
	["A robe or a tunic for Horde mages in their late 20s."] = "一件给20多级后期部落法师的长袍或外衣。",
	["Back to {npc:5885}"] = "回到{npc:5885}那里",
	["Fly to {area:431} and swim north up the river past the big lake to its far northern end, where the zone text reads {area:429}; satyrs hold the ruins around it and a few river beasts are in the way. Swim right in under the highest waterfall until you touch the rock wall, then use the flask (you can stay in the water). The waterfalls on the western Falfarren fork do not work."] = "飞往{area:431}，沿河向北游，经过大湖直到最北端，区域文字显示为{area:429}。周围废墟由萨特占据，河中也有一些野兽。游到最高瀑布正下方，贴到岩壁后使用药瓶，保持在水里即可。西侧弗伦河支流的瀑布无效。",
	["Mage"] = "法师",
	["Take the zeppelin to {zone:1454} (or use {spell:3567}, which lands you on the upper floor of {object:173161}). {npc:5885} stands with the mage trainers on the lower floor of {object:173161} in the {object:172961}. She hands you {item:7269}."] = "乘飞艇前往{zone:1454}，或施放{spell:3567}，传送落点在{object:173161}上层。{npc:5885}与其他法师训练师站在{object:172961}的{object:173161}下层，她会交给你{item:7269}。",
	["The {object:174797}"] = "{object:174797}",
	["The {quest:1945}"] = "{quest:1945}",
	["The {quest:1945}, dryads of level 24-25, roam around the {area:426} in central {zone:1440}; every one drops a hair and they come back after 5 minutes. They often resist fire (and some frost and shadow): arcane spells land best. Each runs for help at low health. Keep clear of the guards by the white tower of the retreat, who hit hard."] = "24–25 级树妖{quest:1945}在{zone:1440}中部的{area:426}周围活动，每只必掉一根头发，五分钟刷新。它们经常抵抗火系法术，部分也会抵抗冰霜和暗影，奥术命中最好。低血量时会逃跑求援。远离林居白塔附近的守卫，它们伤害很高。",
	["{item:7269}, under the falls"] = "在瀑布下使用{item:7269}",
	["{npc:3484}, a troll tailor, works at the Crossroads. The robe gives intellect, stamina and spirit; the tunic more intellect and stamina but no spirit."] = "{npc:3484}是一名在十字路口工作的巨魔裁缝。长袍提供智力、耐力和精神；外套的智力、耐力更高，但没有精神。",
	["{npc:3484}, a troll tailor, works at the {area:380}. The robe gives intellect, stamina and spirit; the tunic more intellect and stamina but no spirit."] = "巨魔裁缝{npc:3484}在{area:380}工作。长袍提供智力、耐力和精神；外衣提供更多智力和耐力，但没有精神。",
	["{npc:4568} stands in the {zone:1458}'s {object:36082}. Orcs and Trolls use {spell:3563} or take the zeppelin from {zone:1454} to {zone:1420} for her."] = "{npc:4568}位于{zone:1458}的{object:36082}。兽人和巨魔可施放{spell:3563}，或从{zone:1454}乘飞艇前往{zone:1420}。",
}

G["forever/class/mage/spellfire-robes"] = {
	["A robe at 15 for Horde mages, from the {zone:1458} and {zone:1421}."] = "部落法师15级的长袍，任务在{zone:1458}和{zone:1421}。",
	["Algernon's alchemist shop is in the Apothecarium. Stand on the steps or the bridge outside the shop and read the {item:7308}: up to four invisible Rift Spawns (level 16-17) appear and attack at once, and the city guards do not help. Hit one with a single-target spell and back off over the bridge: the others give up and fade, the one you hit follows. Beat it down on the shop's half of the bridge (past halfway the coffer will not work on it) until it stops fighting and sits stunned under a spiral, use the {item:7247} on it, then click the {item:7292} once it appears on the floor (clicking too early wastes a charge). Three are needed."] = "奥格诺恩的炼金店位于炼金房。在店外台阶或桥上阅读{item:7308}，最多四只隐形的 16–17 级裂隙怒灵会同时出现并攻击，城内守卫不会帮忙。用单体法术攻击一只，再退过桥，其他敌人会放弃并消失，被攻击的那只会追来。在桥上靠商店的一半区域战斗，超过桥中央后盒子将无法生效。将它打到停止战斗、头顶转圈并昏迷时，使用{item:7247}，再等地面出现{item:7292}后点击，点得太早会浪费次数。共需三个。",
	["Back to the {zone:1458}. {npc:4576}, {npc:11048} and {npc:11049} keep the tailor's shop in the {object:36082}. Hand the gems and cloth to {npc:4576} and let the three of them talk for a moment; then take {quest:1962} (Forever's quest data has {npc:11049} offering it; if the \"!\" shows over {npc:4576} instead, take it from him) and hand it to {npc:4576} for the robe."] = "回到{zone:1458}。{npc:4576}、{npc:11048}和{npc:11049}在{object:36082}里经营裁缝店。把宝石和布料交给{npc:4576}，让他们三人交谈片刻；然后接{quest:1962}（无限的任务数据里由{npc:11049}提供；如果“!”出现在{npc:4576}头上，就改从他那里接取），再把任务交回给{npc:4576}换取法袍。",
	["Back to the {zone:1458}. {npc:4576}, {npc:11048} and {npc:11049} keep the tailor's shop in the {object:36082}. Hand the gems and cloth to {npc:4576} and let the three of them talk for a moment; then {npc:4576} offers {quest:1962}: take it and hand it straight back to him for the robe."] = "回到{zone:1458}。{npc:4576}、{npc:11048}和{npc:11049}在{object:36082}里经营裁缝店。把宝石和布交给{npc:4576}，等她们三个说几句；然后{npc:4576}会给{quest:1962}：接下后立刻交回给他，换长袍。",
	["Back to {npc:4568}"] = "回到{npc:4568}处",
	["Leave the {zone:1458} and follow the road south through {zone:1421}. Every {area:279} human drops a {item:7293} four times in five, and {item:2589} too: the easiest are the Dalaran Apprentices (level 13-14, {spell:116}) on the hills south-east of the {area:228}, either side of the road south; deeper in, the walled town of {area:233} in south-east Silverpine has Watchers (18-19, {spell:134} and {spell:2120}) and Wizards (19-20, {spell:122}) that come back every 4 1/2 minutes and run for help at low health, so pull at the edge. Ten {item:2589} also come from any humanoid or the Undercity Auction House."] = "离开{zone:1458}，沿路向南穿过{zone:1421}。所有{area:279}人类约五分之四几率掉落{item:7293}，也掉落{item:2589}。最容易的是{area:228}东南侧、南下道路两侧山丘上的达拉然学徒，13–14 级，使用{spell:116}。更深入的银松东南部{area:233}城墙内，有 18–19 级守护者，使用{spell:134}和{spell:2120}；19–20 级巫师使用{spell:122}，四分半刷新，低血量时逃跑求援，从外围拉怪。所需十个{item:2589}也可从任意人形生物取得，或在幽暗城拍卖行购买。",
	["Mage"] = "法师",
	["Rift Spawn"] = "裂隙生物",
	["The alchemist shop"] = "炼金商店",
	["{item:7247}, on the stunned {npc:6492}"] = "对昏迷的{npc:6492}使用{item:7247}",
	["{npc:2128} is the {area:159} mage trainer, upstairs in the {area:2119}: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:2128}是{area:159}的法师训练师，在{area:2119}楼上：从室内楼梯上去，箭头无法区分楼层。",
	["{npc:4568} stands in the {object:36082}. The {item:7247} and the {item:7308} lie on the ledge behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them."] = "{npc:4568}站在{object:36082}，她身后的台沿上有{item:7247}和{item:7308}，被拿走后均五分钟刷新。最后交任务时需要两件物品，请保留。",
	["{npc:6492}, down to the stun"] = "{npc:6492}：攻击至其昏迷",
	["{npc:7311} is one of {zone:1454}'s mage trainers, in {object:173161} in the {object:172961}. Then take the zeppelin to {zone:1420} from the tower outside {zone:1454}'s main gate."] = "{npc:7311}是{zone:1454}的法师训练师之一，位于{object:172961}的{object:173161}内。随后从{zone:1454}正门外高塔乘飞艇前往{zone:1420}。",
}

G["forever/class/mage/teleports-horde"] = {
	["At 20 go to {object:173161} in {zone:1454}'s {object:172961}, where the mage trainers live. {npc:5958}, the portal trainer, stands on the upper floor and teaches {spell:3567} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor), so carry a few."] = "20 级时，前往{zone:1454}的{object:172961}，进入法师训练师所在的{object:173161}。传送门训练师{npc:5958}在上层，花费 20 银教授{spell:3567}。每次传送消耗一个{item:17031}，任意施法材料商人以 10 银出售，记得随身备几个。",
	["At 30. {zone:1456} is in {zone:1412}: fly there from {zone:1454} or the Crossroads. {npc:5957}, the portal trainer, stands with the mage trainers in the {area:2197}, the cave under {area:1640}: go down inside, the arrow cannot tell the floors apart. She teaches {spell:3566} for 80 silver."] = "30级时。{zone:1456}位于{zone:1412}，可从{zone:1454}或十字路口飞去。传送门训练师{npc:5957}与法师训练师们一起待在{area:2197}，那是{area:1640}下方的洞穴；要走进洞穴下层，箭头无法区分楼层。她收取80银币，教授{spell:3566}。",
	["At 30. {zone:1456} is in {zone:1412}: fly there from {zone:1454} or the {area:380}. {npc:5957}, the portal trainer, stands with the mage trainers on {area:1640} and teaches {spell:3566} for 80 silver."] = "30级时。{zone:1456}位于{zone:1412}内：从{zone:1454}或{area:380}飞过去。传送门训练师{npc:5957}和法师训练师们一起站在{area:1640}上，以80银教授{spell:3566}。",
	["At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:5958} in {object:173161} has {spell:11417}; teleport to the {zone:1458} for {npc:2492}'s {spell:11418}."] = "40 级时，可向训练师学习供全队穿过的传送门，每项技能 1 金 50 银。每次施放消耗一个{item:17032}，任意施法材料商人以 20 银出售。找{object:173161}的{npc:5958}学习{spell:11417}，再传送到{zone:1458}，向{npc:2492}学习{spell:11418}。",
	["At 50 {npc:5957} in {zone:1456} teaches the last one, {spell:11420}, for 3 gold 20 silver. Use your {spell:3566} to get there."] = "50级时，{zone:1456}的{npc:5957}会教最后一个{spell:11420}，3金20银。用你的{spell:3566}过去。",
	["At 50 {npc:5957}, down in the {area:2197} under {area:1640} in {zone:1456}, teaches the last one, {spell:11420}, for 3 gold 20 silver. Use your {spell:3566} to get there."] = "50级时，{zone:1456}{area:1640}下方{area:2197}里的{npc:5957}教授最后一个法术{spell:11420}，花费3金20银。用你的{spell:3566}过去。",
	["Mage"] = "法师",
	["Portals to {zone:1454} and the {zone:1458}"] = "前往{zone:1454}和{zone:1458}的传送门",
	["Take the zeppelin from the tower outside {zone:1454}'s gate to {zone:1420} and walk into the {zone:1458}. {npc:2492}, the portal trainer, stands in the {object:36082} with the mage trainers: {spell:3563}, 20 silver. {npc:4575} beside him sells the runes."] = "从{zone:1454}城门外高塔乘飞艇前往{zone:1420}，再步行进入{zone:1458}。传送门训练师{npc:2492}与法师训练师一起站在{object:36082}，花费 20 银学习{spell:3563}。旁边的{npc:4575}出售传送符文。",
	["Teleports and Portals (Horde)"] = "传送与传送门（部落）",
	["Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer."] = "20级和30级学习主城传送，40级和50级学习小队传送门，均由各主城的传送门训练师教授。",
	["{item:17031}, 10s each"] = "{item:17031}，每个 10 银",
	["{item:17032}, 20s each"] = "{item:17032}，每个 20 银",
}

G["forever/class/paladin/lumina-windsinger"] = {
	["At 18 {npc:246378}, inside {area:16602} on the bluffs north-west of the {area:156}, sends you south to the {area:228} in {zone:1421}."] = "18级时，位于{area:156}西北高地、{area:16602}内部的{npc:246378}会让你向南前往{zone:1421}的{area:228}。",
	["At 20 {npc:259620} asks for a blade that can kill {quest:95140}. Talk to {npc:248840} beside her for his Weapon Notes, which list the parts, and keep them: he wants them back with the parts. Three parts, in any order: two from dungeons (a group of five each) and a gem from elite naga outside a third."] = "20级时，{npc:259620} 会让你找一把能杀死 {quest:95140} 的剑。与她身旁的 {npc:248840} 交谈，取得他的 特雷凡的武器笔记，上面列有部件清单，请保留：交部件时也要将笔记还给他。共三种部件，可按任意顺序收集：两种来自地下城（各需五人小队），一颗宝石来自第三个地下城外的精英纳迦。",
	["Back to the {area:228}"] = "回到{area:228}",
	["Back to {npc:248840} in the {area:228}'s lower part: he hands you the {item:268484}, a two-handed sword."] = "回到{area:228}下层的{npc:248840}处：他会给你双手剑{item:268484}。",
	["Back to {npc:259620} in the {area:228} with the {item:268484} (the quest asks for it): she takes it and blesses it with the magic of her people into {item:267369}."] = "带着 {item:268484} 回到 {area:228} 找 {npc:259620}（任务要求携带它）：她会收下，用她族人的魔法祝福它，使其变成 {item:267369}。",
	["Back to {npc:259649} at Zoram'gar: he cleanses the gem. Keep the {item:272448} for {npc:248840}."] = "返回佐拉姆加的 {npc:259649} 处，让他净化宝石。保留 {item:272448}，之后要交给 {npc:248840}。",
	["Bring the lumber, the ingot and the gem to {npc:248840} in the {area:228}. He gives you a {item:268192} for a smith in {area:272}: keep it in your bags."] = "把木材、锭和宝石带给 {area:228} 的 {npc:248840}。他会给你一个 {item:268192}，要交给 {area:272} 的铁匠：把它留在背包里。",
	["Equip the {item:268484}. {quest:95140}, the great worgen, roams the woods south of the {area:228} toward the gates of {area:17065}. He is elite (level 25): grouping up is encouraged; one player needed a second, another soloed him at 25. A purple shield guards him until your first swing with the blade lands: a message tells you it broke."] = "装备 {item:268484}。巨型狼人 {quest:95140} 在 {area:228} 南侧、通往 {area:17065} 大门方向的林地游荡。他是精英（25 级）：建议组队；有玩家需要再找一人帮忙，也有玩家在 25 级时独自击败了他。你用这把剑第一次击中他前，他会受到紫色护盾保护；护盾破裂时会出现提示。",
	["Equip the {item:268484}. {quest:95140}, the great worgen, roams the woods south of the {area:228} toward the gates of {area:17065}. He is elite (level 25): the guide waits for level 22 first, and grouping up is encouraged; players have killed him from 22 up, one needed a second, another soloed him at 25. A purple shield guards him until your first swing with the blade lands: a message tells you it broke."] = "装备 {item:268484}。巨型狼人 {quest:95140} 在 {area:228} 南侧、通往 {area:17065} 大门方向的林地游荡。他是精英（25 级）：指南会先等到 22 级，并建议组队；玩家从 22 级起就击杀过他，有人需要再找一人帮忙，也有人在 25 级时独自击败了他。你用这把剑第一次击中他前，他会受到紫色护盾保护；护盾破裂时会出现提示。",
	["Free {npc:248755}"] = "解救{npc:248755}",
	["Goblin Woodcarvers, inside"] = "地精木匠，在副本内",
	["Hand in the key first: starting the escort before that gives the key quest no credit. Then open the cage: {npc:248755} walks out through the keep and its courtyard while the gnolls attack, then runs for the dock and makes her own way back to the {area:228}. Stay close and keep her alive; if she dies, take the quest again when she is back in her cage."] = "先交还钥匙：如果先开始护送，钥匙任务就不会计入完成进度。之后打开笼子：{npc:248755} 会穿过堡垒及庭院，途中豺狼人会发起攻击，随后她会跑向码头，自行返回 {area:228}。紧跟着她，保护她活下来；如果她死亡，等她回到笼子后重新接受任务。",
	["Old Fire-Eye"] = "老火眼",
	["Paladin"] = "圣骑士",
	["The Forsaken paladin's two-handed sword: rescue {quest:91862}, gather three parts, slay {quest:95140}."] = "被遗忘者圣骑士的双手剑：营救{quest:91862}，收集三个部件，杀死{quest:95140}。",
	["The blade is a two-handed sword, and you need the skill to hit a level 25 elite with it. {npc:11870}, the weapon master in the {zone:1458}'s {object:36070}, teaches {spell:202} for a small fee; then swing it on easy mobs until the skill is near its cap (five points per level)."] = "这把剑是双手剑，你需要足够的武器技能才能用它命中25级精英。{zone:1458} 的 {object:36070} 内的武器大师 {npc:11870} 收取少量费用，教授 {spell:202}；学会后先攻击容易对付的小怪，将技能练到接近上限（每级上限增加五点）。",
	["The naga stand in the flooded ruins and passages around the {area:2797} entrance, just north of Zoram'gar: you do not need to enter the instance (its first naga drop the gem too). Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24) drop the {item:6995}, one in two. All are elite: grouping up is encouraged. Players solo them one at a time, with difficulty; a group of three makes it easy. They heal themselves, run for help at low health, and the Sea Witches cast {spell:122} up close. Some players report no drop while in a raid group."] = "纳迦位于佐拉姆加北侧、{area:2797} 入口周围被水淹没的废墟和通道里，无需进入副本（副本内最前面的纳迦也掉这颗宝石）。黑暗深渊海潮祭司（20—21级）、黑暗深渊智者（21—22级）和 黑暗深渊海巫（23—24级）掉落 {item:6995}，掉率为二分之一。它们全是精英：建议组队。玩家可以逐个单杀，但比较困难；三人组队就很轻松。它们会自疗，低血量时会逃跑求援，黑暗深渊海巫 还会在近距离施放 {spell:122}。有玩家反馈，处于团队中时不掉落。",
	["The pyre on {area:172}"] = "{area:172}上的火堆",
	["The {item:267361}"] = "{item:267361}",
	["The {item:272448}"] = "{item:272448}",
	["The {item:6995}"] = "{item:6995}",
	["Watch {npc:3539} forge the blade"] = "看{npc:3539}锻造这把剑",
	["from the {object:566037}"] = "来自{object:566037}",
	["{area:1581} lies under {area:20} in {zone:1436}, Alliance land: a group of five at about 17-24. From the {zone:1458} take the zeppelin to {object:3202} in {zone:1434} and go north through {zone:1431} into {zone:1436}. The way in is the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in Sneed's mast room drop the lumber every time."] = "{area:1581}在{zone:1436}的{area:20}下方，那是联盟地盘：五个人，大约17-24级。从{zone:1458}坐飞艇到{zone:1434}的{object:3202}，再往北穿过{zone:1431}进入{zone:1436}。入口就是{area:20}的矿洞。斯尼德桅杆房里的地精木雕工（精英，18-19级）每次都掉木材。",
	["{area:1581} lies under {area:20} in {zone:1436}, Alliance land: a group of five at about 17-24. The way in is the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in Sneed's mast room drop the lumber every time."] = "{area:1581}位于{zone:1436}的{area:20}下方，属联盟领地：约17-24级的五人小队。入口是{area:20}的矿洞。斯尼德桅杆房里的地精木雕师（精英，18-19级）每次都掉木材。",
	["{area:1581}, in the {area:20} mine"] = "{area:1581}，在{area:20}的矿洞里",
	["{area:172} lies in the lake north-east of the {area:228}. The gnolls' pyre, with the {object:566037}, is on its shore: click the remains to hand in, and click them again for the next quest. The body is a tauren's, not the elf's."] = "{area:172}位于{area:228}东北方的湖中。豺狼人的火堆在湖岸上，{object:566037}就在其中：点击遗骸交还任务，再点击一次接受后续任务。那是牛头人的遗体，不是精灵的。",
	["{area:236} is the dungeon in south Silverpine, for a group of five in the low to mid 20s. The ingot sits on the table next to {npc:4275} at the very end. A friend's cleared instance works: walk in and run to the table."] = "{area:236} 是银松森林南部的地下城，适合由 20 级出头至 20 多级中段玩家组成的五人小队。金锭就在最深处 {npc:4275} 旁边的桌上。也可以借用朋友已清空的副本：进入后直接跑到桌旁即可。",
	["{item:267361}, on Arugal's table"] = "{item:267361}，在阿鲁高的桌上。",
	["{item:267412}, from the Rot Hide gnolls"] = "{item:267412}，来自腐皮豺狼人",
	["{item:267454}: talk to {npc:248840}"] = "{item:267454}：与 {npc:248840} 交谈",
	["{item:268484} and {item:267369} (Forsaken)"] = "{item:268484}和{item:267369}（被遗忘者）",
	["{npc:248840} stands in the lower part of the {area:228}, below the surface; {npc:259611} keeps watch near the town's entrance."] = "{npc:248840} 在 {area:228} 的地下区域；{npc:259611} 在镇子入口附近放哨。",
	["{npc:259620} waits beside {npc:248840} in the {area:228} (a different {npc:259620} from the one you escorted). For {quest:95034}, click through every line of her story."] = "{npc:259620} 在 {area:228} 内的 {npc:248840} 身边等候（这名 {npc:259620} 与你护送的那位不是同一个）。做 {quest:95034} 时，要逐项点击，听完她的全部故事。",
	["{npc:259620}, the {area:228}"] = "{npc:259620}，{area:228}",
	["{npc:259620}: hear her story to the end"] = "{npc:259620}：把她的故事听完",
	["{npc:259649} waits at {area:2897} on {zone:1440}'s west coast: from the {zone:1458} take the zeppelin to {zone:1454}, then go north through the {zone:1413} into {zone:1440} and west along the road. Andruk, the outpost's wind rider master, saves you the walk next time. Take {npc:259649}'s quest before you hunt the naga: the Kor Gem only drops while you have it."] = "{npc:259649}在{zone:1440}西海岸的{area:2897}等候：从{zone:1458}乘飞艇到{zone:1454}，再向北穿过{zone:1413}进入{zone:1440}，沿路西行。前哨站的飞行管理员安德鲁克下次能替你省去这段路。猎杀纳迦前先接{npc:259649}的任务：科尔宝石只在你持有任务时掉落。",
	["{npc:259649} waits at {area:2897} on {zone:1440}'s west coast: take the zeppelin from {object:3202} (or the {zone:1458}) to {zone:1454}, then go north through the {zone:1413} into {zone:1440} and west along the road. Andruk, the outpost's wind rider master, saves you the walk next time. Take {npc:259649}'s quest before you hunt the naga: the Kor Gem only drops while you have it."] = "{npc:259649}在{zone:1440}西海岸的{area:2897}等着：从{object:3202}（或{zone:1458}）坐飞艇到{zone:1454}，然后往北穿过{zone:1413}进入{zone:1440}，再沿路向西。前哨站的风骑手管理员安德鲁克能省掉你下次的路。猎杀纳迦之前先接{npc:259649}的任务：科尔宝石只在你有任务时才会掉。",
	["{npc:3539} gives you {quest:95125}"] = "{npc:3539} 会给你 {quest:95125}",
	["{npc:3539}, the weaponsmith, stands just south of {area:272} in {zone:1424}. Accepting {quest:95125} starts the forging: step back and wait near him until he is done."] = "武器锻造师 {npc:3539} 位于 {zone:1424} 的 {area:272} 正南边。接受 {quest:95125} 后，他就会开始锻造：退开一些，在附近等他完成。",
	["{quest:91862} is caged in the basement of {area:235}, at the north end of the isle. The Rot Hide gnolls (level 18-19) fill the keep: they pull in big groups across floors and players report very fast respawns, so clear a path and keep moving. Any of them can carry the {item:267412} (often the first kill); the rare {npc:1944} (22) and Snarlmane (23) can too. If her cage is empty, another player is escorting her: wait for her to come back."] = "{quest:91862} 被关在岛屿北端 {area:235} 地下室的笼子里。城堡中到处都是腐皮豺狼人（18-19 级）：它们会跨楼层成群被引来，而且玩家反映刷新极快，因此要清出一条路，持续前进。任意一只都可能携带 {item:267412}（经常第一只就掉）；稀有怪 {npc:1944}（22 级）和斯纳麦恩（23 级）也可能携带。如果她的笼子是空的，说明其他玩家正在护送她，等她回来即可。",
	["{quest:95140}, with the {item:268484} equipped"] = "装备 {item:268484} 后，对付 {quest:95140}",
}

G["forever/class/paladin/tyrs-watch"] = {
	["At 4 {npc:244808} sends you after a {npc:246143} who fled into the hills west of the church, just south of the bat cave. Talk to her to offer aid: she turns on you, and you have to put her down (level 3, easy)."] = "4级时，{npc:244808} 会派你寻找逃进教堂西边山丘的 {npc:246143}，位置就在蝙蝠洞南边。与她交谈表示愿意援助：她会转而攻击你，你必须将她击杀（3级，很容易）。",
	["At 8 {npc:246152} in {area:159} sends you to the order's keep on the west coast. {quest:91317} in {area:16881} and the crypt under it hit hard at 8-9: come at 10 or later."] = "8级时，{area:159}的{npc:246152}会让你去西海岸的教团要塞。{area:16881}及其下方墓穴里的{quest:91317}对8-9级角色威胁很大：建议10级或更高再来。",
	["Back to the keep"] = "回到要塞",
	["Back to {area:16602}, across the whole glades: Billmuth downstairs takes the plans, then {npc:246378}, back upstairs in the keep, teaches you {spell:7328}."] = "穿过整片林地，回到 {area:16602}：先把计划交给楼下的亡灵卫兵比尔穆斯，再回城堡楼上找 {npc:246378} 学习 {spell:7328}。",
	["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep. If you lose the symbol, {npc:246378} gives you another."] = "返回{area:16602}。{npc:246378}会给你{item:6866}；{npc:257655}在要塞楼下等候。如果弄丢了符记，{npc:246378}会再给你一个。",
	["Faintly Glowing Bones x6"] = "散发微光的骸骨 x6",
	["Follow the road east out of {area:154} to {area:159}. {npc:246152}, the paladin trainer, stands in town; she trains you from here on."] = "沿道路向东离开 {area:154}，前往 {area:159}。圣骑士训练师 {npc:246152} 站在镇内；从这里开始由她教你技能。",
	["Frightened Paladin"] = "受惊的圣骑士",
	["Heal 5 {npc:259377} with {spell:635}"] = "用 {spell:635} 治疗 5 名 {npc:259377}。",
	["Lumber Piles, in the cellar: the way down is here"] = "木材堆在地窖里：下去的入口就在这里",
	["Paladin"] = "圣骑士",
	["Talk to the {npc:246143}, then defeat her"] = "与 {npc:246143} 交谈，然后击败她",
	["Tarnished Drudge"] = "锈浊苦工",
	["Tarnished Drudges x8"] = "黯淡的苦工 x8",
	["Tarnished Zealot"] = "锈浊狂热者",
	["Tarnished Zealots x6"] = "黯淡的狂热者 x6",
	["The Scarlet Zealots (level 8-9), Friars (9-10) and Tarnished around {area:812} carry the attack plans. They run for help at low health and respawn in five minutes."] = "{area:812} 周围的血色狂热者（8-9 级）、血色修士（9-10 级）和黯淡者携带进攻计划。它们在生命值低时会逃跑求援，每五分钟刷新。",
	["The Scarlet attack plans"] = "血色十字军的进攻计划",
	["The Shadowvale Lurchers and Mystics (level 8-10) in the crypt drop the Faintly Glowing Bones: about one in two from Lurchers, more from one kind of Mystic, less from the other."] = "墓穴里的影谷潜伏者和秘法师雅尔金（8—10级）会掉落散发微光的骸骨：潜伏者掉率约为二分之一，其中一种秘法师雅尔金的掉率更高，另一种则更低。",
	["The Vile Fin murlocs (level 9-11) lurk on the bluffs along the road east of the keep and in the camps around the lake to the south-west, on the way down to {area:16881}."] = "邪鳍鱼人（9-11级）潜伏在城堡东侧道路沿线的高地上，以及西南方湖泊周围的营地中，就在下行前往{area:16881}的途中。",
	["The cellar is under the village, not on the surface: the way down is inside a burned-out house, where the arrow points. Twelve Lumber Piles (stacked beams) lie in the cellar, each good for one {item:246213}. {npc:260396}, an elite (level 11-13), sits at the far end: leave it alone."] = "地窖在村庄下方，不在地面上：下去的入口位于箭头所指的一间烧毁的房屋内。地窖里有十二堆木材（堆叠的木梁），每堆可取得一个 {item:246213}。最深处有精英 {npc:260396}（11—13级）：不要招惹它。",
	["The crypt under {area:16881}"] = "{area:16881}下方的墓穴",
	["The {item:286269}, a green crystal, lies on the floor in the left-hand part of the crypt."] = "{item:286269}是一块绿色水晶，就在墓穴左侧区域的地面上。",
	["The {item:6866}"] = "{item:6866}",
	["Tyr's Watch and {spell:7328} (Forsaken)"] = "提尔之望与{spell:7328}（被遗忘者）",
	["Vile Fin Attacker"] = "邪鳍袭击者",
	["Vile Fin Attackers x8"] = "邪鳍攻击者 x8",
	["Vile Fin Seer"] = "邪鳍先知",
	["Vile Fin Seers x8"] = "邪鳍先知 x8",
	["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:10181} holds court in the {object:36126}; {npc:257648} begs in the {object:36078}."] = "从{area:159}向南走到{area:153}，再下到{zone:1458}。{npc:10181}在{object:36126}接见臣民；{npc:257648}在{object:36078}乞讨。",
	["{area:16602} stands on the bluffs north-west of the {area:156} (the road west starts near 29,46). {npc:246349} waits at the gate. {npc:246389}, the keep's trainer, and {npc:259190}, its stable master, stand at the forest's edge just south of him. They only have work for you from level 10 and after A Righteous Cause from Leonid at the keep, the end of {npc:267009}'s chain that starts south-east of {area:159}; take their quests when you see them."] = "{area:16602}位于{area:156}西北的峭壁上（向西的路从29,46附近开始）。{npc:246349}在大门等你。城堡的训练师{npc:246389}和兽栏管理员{npc:259190}站在他南边森林的边缘。他们要到10级后、且完成城堡里Leonid的任务“A Righteous Cause”（{npc:267009}任务链的终点，起点在{area:159}东南）后才有工作给你；见到他们的任务就接。",
	["{area:16602} stands on the bluffs north-west of the {area:156} (the road west starts near 29,46). {npc:246349} waits at the gate. {npc:246389}, the keep's trainer, and {npc:259190}, its stable master, stand at the forest's edge just south of him. They only have work for you from level 10 and after {quest:96896} from Leonid at the keep, the end of {npc:267009}'s chain that starts south-east of {area:159}; take their quests when you see them."] = "{area:16602}位于{area:156}西北的悬崖上（向西的道路始于29,46附近）。{npc:246349}在大门口等候。要塞的训练师{npc:246389}和兽栏管理员{npc:259190}站在他南边不远处的森林边缘。他们要到你10级、并完成要塞中列奥尼德的{quest:96896}之后才有任务给你，该任务是{npc:267009}任务链的最后一环，任务链起始于{area:159}东南；看到他们的任务就接受。",
	["{area:812} is at the far east end of the glades, a long walk. Falgan lies dead among the Scarlet Crusaders there: target his body and use the {item:6866}, then talk to him at once, as he does not stay alive long. If he is already up (another player), just talk to him; if he died again, raise him again."] = "{area:812} 位于林地最东端，路途很远。亡灵卫兵法尔甘的尸体躺在那里的血色十字军中：选中尸体使用 {item:6866}，随后立刻与他交谈，因为他活不了多久。如果他已经被其他玩家复活，直接交谈即可；如果又死了，就再复活一次。",
	["{item:2589} x10"] = "{item:2589} × 10",
	["{npc:1569} gives you a {item:282423} after {quest:364}: read it, then bring it to {npc:244808} by the church. He asks you to heal five {npc:259377} lying around {area:154}. {spell:635} hurts a Forsaken paladin a little each time: watch your health."] = "完成{quest:364}后，{npc:1569}会给你一份{item:282423}：阅读它，然后交给教堂旁的{npc:244808}。他要你治疗躺在{area:154}周围的五名{npc:259377}。被遗忘者圣骑士每次施放{spell:635}都会受到少量伤害：注意你的生命值。",
	["{npc:246349} gives you a weapon, then sends you round the keep to speak with four of its people: {npc:246389} just south of the gate, {npc:246393} and {npc:246378} inside the keep, and {npc:246394}, the lookout, who walks the road south-east of the keep. Pick the conversation option with each."] = "{npc:246349}给你一件武器，然后让你与城堡的四个人交谈：大门正南的{npc:246389}、城堡内的{npc:246393}和{npc:246378}，以及在城堡东南道路上巡逻的哨兵{npc:246394}。与每人对话时选择对话选项。",
	["{npc:246349} gives you a weapon, then sends you round the keep to speak with four of its people: {npc:246389} just south of the gate, {npc:246394}, the lookout, who walks the road south-east of the keep, then {npc:246393} and {npc:246378} inside the keep. Pick the conversation option with each."] = "{npc:246349}给你一把武器，然后让你在要塞里转一圈，和它的四个人说话：城门正南的{npc:246389}，在要塞东南路上走动的哨兵{npc:246394}，然后是要塞里的{npc:246393}和{npc:246378}。每个人都选对话选项。",
	["{npc:246349}: {item:246164} or {item:246165}"] = "{npc:246349}：{item:246164}或{item:246165}",
	["{npc:246378} hands you {npc:259431}'s head for Sylvanas: keep it in your bags, it is what you hand in."] = "{npc:246378} 会给你 {npc:259431} 的头颅，让你交给希尔瓦娜斯：把它留在背包里，这是交还任务需要的物品。",
	["{npc:246378} leads the order from inside the keep; {npc:246393} stands beside it. {quest:91317} need level 9."] = "{npc:246378}在城堡内领导教团；{npc:246393}站在城堡旁。{quest:91317}需要9级。",
	["{npc:246378} offers the first Lesson in Divinity at level 12. Bring 10 {item:2589} if you have it: the {zone:1458} asks for it next."] = "{npc:246378}在12级时提供第一个神性一课任务。如果有，带上10块{item:2589}：接下来{zone:1458}会用到。",
	["{npc:246378}, back upstairs: {spell:7328}"] = "回到楼上找 {npc:246378}：{spell:7328}",
	["{npc:246389} and {npc:259190}"] = "{npc:246389}和{npc:259190}",
	["{npc:246389} and {npc:259190} wait at the forest's edge south of the gate."] = "{npc:246389}和{npc:259190}在大门南方的森林边缘等候。",
	["{npc:246389}'s bones"] = "{npc:246389} 的骸骨",
	["{npc:257648} needs 10 {item:2589}. Humanoids drop it: the Scarlet Zealots and Friars of the glades about three kills in ten. The Undercity Auction House sells it too."] = "{npc:257648}需要10块{item:2589}。人型生物会掉落：林地里的血色狂热者和修士约每击杀10个掉3次。幽暗城拍卖行也有出售。",
	["{npc:257655}, downstairs"] = "{npc:257655}，在楼下",
	["{npc:259190} waits at the forest's edge south of the gate, a few steps west of {npc:246389}."] = "{npc:259190}在城门以南的森林边缘等着，在{npc:246389}以西几步远。",
	["{npc:259190}'s crystal"] = "{npc:259190}的水晶",
	["{quest:91317} (level 8-9) hold the ruined village of {area:16881} in the {area:16616}, south-west of the keep. Commander {npc:259431} (level 10) stands on the upper floor of a house, with Drudges below him: clear the ground floor first."] = "{quest:91317}（8-9级）占据了要塞西南面{area:16616}中的废弃村庄{area:16881}。指挥官{npc:259431}（10级）站在一栋房子的楼上，楼下有苦工：先清掉一楼。",
	["{spell:7328} to raise fallen allies, plus a weapon and a shield for a new Forsaken paladin."] = "{spell:7328}可复活倒下的盟友，另有一把武器和一面盾牌，给新的被遗忘者圣骑士。",
}

G["forever/class/priest/hex-of-weakness-and-shadowguard"] = {
	["At 10 in the {zone:1458}, {npc:4606}, the priest trainer in the {object:36070}, hands you a {quest:5652} letter for {npc:6018} in {zone:1454} (the zeppelin from the tower outside the {zone:1458})."] = "在 {zone:1458} 达到10级后，{object:36070} 内的牧师训练师 {npc:4606} 会给你一封 {quest:5652} 的信，要你送给 {zone:1454} 的 {npc:6018}（搭乘 {zone:1458} 城外塔楼的飞艇前往）。",
	["At 10 in {zone:1412}, {npc:11407}, just south-west of {area:222}, hands you a {quest:5652} letter for {npc:6018} in {zone:1454}."] = "10 级时，在 {zone:1412} 的 {area:222} 西南不远处，{npc:11407} 会给你一封 {quest:5652} 的信，让你送给 {zone:1454} 的 {npc:6018}。",
	["At 10 in {zone:1456}, {npc:3044}, the priest trainer in the cave under {area:1640}, hands you a {quest:5652} letter for {npc:6018} in {zone:1454}."] = "10级时，{zone:1456} 的 {area:1640} 下方洞穴中的牧师训练师 {npc:3044} 会给你一封 {quest:5652} 的信，要交给 {zone:1454} 的 {npc:6018}。",
	["At 10, go to {npc:6018}, the priest trainer in a hut in the {object:172961}, {zone:1454}'s south-west corner: he gives {quest:5652} and takes it back at once. No letter needed."] = "10级时，去找{zone:1454}西南角{object:172961}一间小屋里的牧师训练师{npc:6018}：他会提供{quest:5652}，接受后即可立即交还。无需信件。",
	["At 10, {npc:3706}, the priest trainer inside the barracks of {area:362} (the first building on the right as you come up the road from the {area:363}), hands you a {quest:5652} letter for {npc:6018} in {zone:1454}. {area:362} is on the road north to the city."] = "10级时，{area:362} 兵营内的牧师训练师 {npc:3706} 会给你一封 {quest:5652} 的信，要你送给 {zone:1454} 的 {npc:6018}。兵营就是从 {area:363} 沿道路上来后右手边的第一栋建筑。{area:362} 位于向北通往城里的路上。",
	["At 20 in the {zone:1458}, {npc:4606} in the {object:36070} hands you a {quest:5642} letter for {npc:6018} in {zone:1454}."] = "在{zone:1458}达到20级时，{object:36070}里的{npc:4606}会交给你一封{quest:5642}信件，让你送给{zone:1454}的{npc:6018}。",
	["At 20 in {zone:1456}, {npc:3044} in the cave under {area:1640} hands you a {quest:5642} letter for {npc:6018} in {zone:1454}."] = "在{zone:1456}达到20级时，{area:1640}下方洞穴里的{npc:3044}会交给你一封{quest:5642}信件，让你送给{zone:1454}的{npc:6018}。",
	["At 20, {npc:6018} in the {object:172961} teaches {quest:5642} with a quest he gives and takes back at once."] = "达到 20 级后，{object:172961} 中的 {npc:6018} 会给予一个任务，并立即接受交还，以此教你 {quest:5642}。",
	["Follow the road north from {area:362} into {zone:1454} and west to the {object:172961}: {npc:6018} takes the letter and teaches {quest:5654}."] = "从 {area:362} 沿道路向北进入 {zone:1454}，再向西前往 {object:172961}：{npc:6018} 会收下信并教你 {quest:5654}。",
	["Hand the letter to {npc:6018} in the {object:172961}, {zone:1454} (from {zone:1412}: north through the {zone:1413} and east into {zone:1411}, or fly from {zone:1456} once you know {zone:1454}'s flight path)."] = "将信交给{zone:1454}的{object:172961}内的{npc:6018}（从{zone:1412}出发：向北穿过{zone:1413}，再向东进入{zone:1411}；也可以在开通{zone:1454}的飞行路线后从{zone:1456}飞过去）。",
	["Hand the letter to {npc:6018} in the {object:172961}, {zone:1454} (the zeppelin from {zone:1420} lands outside {zone:1454})."] = "把信交给 {zone:1454} 的 {object:172961} 内的 {npc:6018}（从 {zone:1420} 出发的飞艇会停在 {zone:1454} 城外）。",
	["Priest"] = "牧师",
	["The Troll priest spells: {quest:5652} at 10, {quest:5642} at 20. Free, no objectives."] = "巨魔牧师法术：10级{quest:5652}，20级{quest:5642}。免费，无任务目标。",
