G["forever/class/rogue/blade-of-cunning-horde"] = {
	["A dagger at 10 from your home town's rogue quests."] = "10级时来自家乡潜行者任务的一把匕首。",
	["At 10 {npc:2130}, the rogue trainer upstairs in the {area:2119} in {area:159}, sends you to {quest:1885} in the {zone:1458}."] = "10级时，{area:159}的{area:2119}楼上的盗贼训练师{npc:2130}会派你去{zone:1458}找{quest:1885}。",
	["At 10 {npc:3170}, the rogue trainer in {area:362}, sends you to {quest:1859} in {zone:1454}. It is only a pointer: an Orc already in {zone:1454} can skip it and take {quest:1963} from {quest:1859} straight away."] = "10级时，{area:362}的盗贼训练师{npc:3170}会派你去{zone:1454}找{quest:1859}。这只是引导任务：已经在{zone:1454}的兽人可以跳过，直接从{quest:1859}处接受{quest:1963}。",
	["Back to {npc:6446}"] = "回到{npc:6446}那里",
	["Back to {npc:6467}"] = "回到{npc:6467}那里",
	["Pick Pocket Gamon for {item:7208}"] = "从加摩尔身上偷取{item:7208}",
	["Rogue"] = "潜行者",
	["The {object:36073}"] = "{object:36073}",
	["{item:7208}: Pick Pocket Gamon"] = "{item:7208}：偷窃加摩尔的口袋",
	["{item:7209}, once you have the key"] = "{item:7209}，拿到钥匙后",
	["{item:7295}, from the satchel"] = "{item:7295}，来自挎包",
	["{item:7298} (Horde)"] = "{item:7298}（部落）",
	["{npc:6446}'s reward"] = "{npc:6446}的奖励",
	["{npc:6467} and {npc:2425}"] = "{npc:6467}与{npc:2425}",
	["{npc:6467} sends the ledger on to {npc:2425}, the big demon in the middle of the Hall of the Dark Lady in the {object:36126}, past its elite guards; the way in is the passage off the Apothecarium. If you lose the ledger, take another from {npc:6522}'s bookshelf."] = "{npc:6467}会让你把账本继续送给{npc:2425}，就是{object:36126}中黑暗女王大厅中央的巨大恶魔，需要经过精英守卫；入口是炼金房旁的通道。若弄丢账本，可从{npc:6522}的书架再拿一本。",
	["{npc:6494} (level 13, not elite) is a troll pirate on the {area:391} south of {area:392}: he walks the fenced hill path between the lower pirate camp by the beached ship and the upper camp by a big tree. Fight him at the foot of the hill, away from the camps. He always drops his satchel and is back 4 1/2 minutes after a death; one satchel per kill, so two rogues need two kills. Hand the satchel in unopened: picking its lock now destroys it and you must kill him again."] = "{npc:6494}（13 级，非精英）是一名巨魔海盗，位于 {area:392} 南侧的 {area:391}：他沿着有围栏的山路，在搁浅船只旁的下层海盗营地与大树旁的上层营地之间来回走动。在山脚下远离营地的地方与他战斗。他必定掉落背包，死亡 4 分半后刷新；每次只掉一个背包，因此两名潜行者需要击杀两次。交还背包前不要打开：现在开锁会毁掉它，你就必须再杀他一次。",
	["{npc:6497} (level 13) walks the road between the {area:228} and the {zone:1458}, north of the {area:228}. He looks like a friendly traveller with no quest mark. Talk to him and pick both of his answers: he turns hostile. Kill him for the letter (it always drops). Fight him away from guards, who can take the kill and leave no loot; only one rogue per kill gets the letter. He is back 5 minutes after a death."] = "{npc:6497}（13级）在 {area:228} 北面、{area:228} 与 {zone:1458} 之间的道路上行走。他看起来像友善的旅人，没有任务标记。与他交谈，选过他的两个对话选项后，他会转为敌对。杀死他取得信件（必定掉落）。远离卫兵再战斗，否则卫兵可能抢走击杀，导致无法拾取；每次击杀只有一名潜行者能拿到信。他死亡后5分钟刷新。",
	["{npc:6522} is in the Apothecarium, in its biggest room, where two huge guards watch a small bridge. His ledger is on the bookshelf in the back room behind him, not the shelf on the wall next to him."] = "{npc:6522}在炼金房最大的一间房里，那里有两名高大守卫看守一座小桥。他的账本在他身后里间的书架上，不在他旁边墙上的架子上。",
	["{quest:1859} hands the satchel back: now open it. {npc:6466} (level 12) kneels by the innkeeper in the inn in the {object:172982}; stealth up and pick his pocket for {item:7208} (do not kill him: the key almost never drops). Players often kill him, so you may wait up to 5 minutes for him. Then use the key on {item:7209} in your bags. If you have trained {spell:1804}, you can pick the satchel's lock instead."] = "{quest:1859}会把背包还给你：现在打开它。{npc:6466}（12级）跪在{object:172982}旅店的旅店老板旁；潜行靠近，偷窃获得{item:7208}（不要杀他：钥匙几乎不会掉落）。玩家常常会杀他，因此可能需要等最多5分钟。然后用钥匙打开背包中的{item:7209}。如果已经学会{spell:1804}，也可以直接撬开背包的锁。",
	["{quest:1859} stands in the {object:172960}, the canyon under the {object:172982}. Trolls: take {quest:1963} from him at 10."] = "{quest:1859}站在{object:172960}，也就是{object:172982}下方的峡谷里。巨魔：10级时从他那里接受{quest:1963}。",
	["{quest:1885} stands in the {object:36073}."] = "{quest:1885}站在{object:36073}。",
}

G["forever/class/rogue/plundering-the-plunderers"] = {
	["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "16级时，{area:362}的潜行者训练师{npc:3170}会让你去找{zone:1454}的{npc:3401}。",
	["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "16级时，{object:36073}的{npc:6467}会让你去找{zone:1454}的{npc:3401}。同时从他那里接受{quest:1998}；它在本指南最后于{zone:1421}完成。",
	["Back to {npc:6467}"] = "回到{npc:6467}处",
	["Back to {npc:7161}"] = "回到{npc:7161}处",
	["Fly or walk to {area:392} on the {zone:1413} coast. {npc:7161} stands in a small shed near the bank, up the hill to the left before the docks. His Gizmotronic Apparatus beside him hands out what the job needs: take an {item:7970} and {item:5060} ({spell:1804} does not work without the tools in your bags)."] = "飞行或步行前往{zone:1413}海岸的{area:392}。{npc:7161}站在银行附近的小棚屋里，位置在码头前左侧的山坡上。他身旁的维尼克斯的机械设备会提供任务所需物品：领取{item:7970}和{item:5060}（背包里没有工具就无法使用{spell:1804}）。",
	["Follow the coast south from {area:392} to the first beached pirate ship, the Tide Razor, and climb aboard up its bow. On the middle deck the Buccaneer's Strongboxes come back fast: pick them until your Lockpicking is about 30 (a few are trapped with a frost nova or turn you into a rat; picking still works as a rat). Keep picking while they still give skill: the poisons job at 20 ends at a lockbox that needs about 75, and these boxes are the closest practice. Then go down to the bottom hold and pick the lock of {object:123462}: it is empty, but opening it calls a giant level 50 {npc:7168} into the next room. Stay stealthed, put the {item:7970} on your action bar, target {npc:7168} and use it: the parrot shrinks to level 18. Kill it for the {item:7968}."] = "从 {area:392} 沿海岸向南，到第一艘搁浅的海盗船“海浪剃刀号”，从船头爬上去。中层甲板上的海盗的保险箱刷新很快：一直开锁练到开锁技能约 30（有些箱子带陷阱，会释放冰霜新星或把你变成老鼠；老鼠形态仍能开锁）。只要还能涨技能，就继续开：20 级的制毒任务最后有个箱子，需要约 75 点开锁，这里是最近的练习地点。然后下到底层货舱，撬开 {object:123462}：里面是空的，但打开会在隔壁房间召出一只巨大的 50 级 {npc:7168}。保持潜行，把 {item:7970} 放到动作条上，选中 {npc:7168} 并使用它：鹦鹉就会缩小，降到 18 级。杀死它，拾取 {item:7968}。",
	["If you have no {item:5060} left, ask {npc:6566}, the outfitter in the {object:36073}."] = "如果 {item:5060} 已经用完，向 {object:36073} 的装备商 {npc:6566} 索取。",
	["Rogue"] = "潜行者",
	["Take the zeppelin from {zone:1454} to the {zone:1458} and head south into Silverpine. {quest:1998} (level 16) stands alone on the old ferry dock on {area:1338}, north-east of the {area:228}. His Uppercut knocks you back, so do not fight him at the dock's edge. He always drops his head and is back 4 1/2 minutes after a death."] = "从 {zone:1454} 乘飞艇前往 {zone:1458}，再向南进入银松森林。{quest:1998}（16 级）独自站在 {area:1338} 的旧渡口码头上，位于 {area:228} 东北方。他的上勾拳会将你击退，因此不要在码头边缘与他战斗。他必定掉落头颅，死亡 4 分半后刷新。",
	["Ten {item:7676}, the rogue energy drink, from the Horde lockpicking jobs at 16."] = "十份{item:7676}——潜行者的能量饮料，来自16级的部落开锁任务。",
	["The Kirin Tor keep their reports in walled {area:233}, in south-east Silverpine. Facing the town hall, take the building on the right: the {object:103815} is in a corner room upstairs (any Lockpicking opens it; the {item:5060} must be in your bags). Three casters of level 19-20 guard that floor and see through stealth, one walking in and out of the strongbox room: time it or fight them one at a time."] = "肯瑞托把报告放在银松森林东南部、有围墙的 {area:233}。面朝镇公所时，进入右手边的建筑：{object:103815} 在楼上的一间角落房间里（任何开锁技能等级都能打开，但背包必须带着 {item:5060}）。该层由三名 19-20 级施法者看守，它们能识破潜行，其中一名会在保险箱房间内外来回走动：看准时机，或逐一击杀。",
	["Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}. Train {spell:1804} from {npc:3401} (or any rogue trainer) now if you lack it: this job is a lockpicking test."] = "亡灵角色搭乘 {zone:1458} 城外塔楼的飞艇前往 {zone:1411}。{npc:3401} 和 {quest:2379} 位于 {object:172960}，即 {object:172982} 下方的峡谷。如果还没有 {spell:1804}，现在就向 {npc:3401}（或任意潜行者训练师）学习：这项任务是开锁测试。",
	["{item:7968}: {npc:7168}, after the {item:7970}"] = "{item:7968}：获得{item:7970}后找{npc:7168}",
	["{npc:3401} and {quest:2379}"] = "{npc:3401}和{quest:2379}",
	["{npc:7161}: ten {item:7676}"] = "{npc:7161}：十份{item:7676}",
}

G["forever/class/rogue/poisons-horde"] = {
	["/salute {npc:3401}"] = "对{npc:3401}使用/salute",
	["Back to {npc:3401}"] = "回到{npc:3401}处",
	["Fly back to {zone:1454} ({area:392} or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {item:6947} takes one of each."] = "飞回{zone:1454}（从{area:392}或十字路口起飞；在塔边死亡，再通过灵魂医者回到十字路口更快）。之后保留{item:8072}。离开{area:263}前，向雷库尔购买{item:2928}和空瓶：希诺特教会你制毒后，每制作一份{item:6947}都要各用一个。",
	["Fly back to {zone:1454} ({area:392} or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {spell:8681} takes one of each."] = "飞回{zone:1454}（从{area:392}或十字路口起飞；在塔边死亡，再通过灵魂医者回到十字路口更快）。之后保留{item:8072}。离开{area:263}前，向雷库尔购买{item:2928}和空瓶：希诺特教会你制毒后，每制作一份{spell:8681}都要各用一个。",
	["Fly back to {zone:1454} ({area:392} or the {area:380}; dying at the tower and taking the spirit healer's way back to the {area:380} is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {item:6947} takes one of each."] = "飞回{zone:1454}（{area:392}或{area:380}；在塔楼那里死掉、走灵魂医者的路线回到{area:380}更快）。之后留着{item:8072}。离开{area:263}之前，向雷库尔购买{item:2928}和空瓶：希诺特教会你毒药后，每批{item:6947}都要各消耗一个。",
	["Fly to the Crossroads and head north to the Venture Co. tower above the {area:382}. Fizzule stands under a tree east of the tower, outside it, and is hostile until signalled. Target him from about 50 yards and fire the {item:8051} twice, then walk up in front of him and /salute. In any other order he attacks. Lost the {item:8051}? Abandon and retake from {npc:3401}."] = "飞往十字路口，向北前往{area:382}上方的风险投资公司高塔。费苏勒站在塔东边外面的一棵树下，发出信号前处于敌对状态。约50码外选中他，使用{item:8051}发射两次，再走到他面前使用/salute。顺序不对他就会攻击。丢了{item:8051}？放弃任务，再找{npc:3401}重接。",
	["Fly to the {area:380} and head north to the Venture Co. tower above the {area:382}. Fizzule stands under a tree east of the tower, outside it, and is hostile until signalled. Target him from about 50 yards and fire the {item:8051} twice, then walk up in front of him and /salute. In any other order he attacks. Lost the {item:8051}? Abandon and retake from {npc:3401}."] = "飞到{area:380}，向北前往{area:382}上方风险投资公司的塔楼。菲祖尔站在塔楼东侧的一棵树下、塔外，在收到信号前是敌对的。在约50码外选中他，发射{item:8051}两次，然后走到他面前 /敬礼。顺序不对他就会攻击。弄丢了{item:8051}？放弃任务，再找{npc:3401}重新接取。",
	["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "无限通过这条任务线而不是训练师来传授毒药；同时附带{item:7676}配方。",
	["Inside, floor by floor (everything comes back after 4 1/2 minutes): the Mutated Venture Co. Drones (level 25) on the ground floor die to one Ambush with a dagger; the Patrollers on the second floor take half their health from a one-point {spell:1943}; the Lookouts on the open third floor from a one-point {spell:2098}. {npc:7288} waits on the top floor: a level 23 elite, back 10 minutes after a kill. Open with Ambush (about half his health), then {spell:1776}, {spell:5277}, a healing potion and {item:7676}; a friend makes it easy. One head per kill. Then pick {object:129127} beside him for the cache: it poisons you with the {spell:9810}, which weakens your stealth and agility until {npc:2391} cures it."] = "进入后逐层推进（所有小怪都在 4 1/2 分钟后刷新）：底层的变异风险投资公司工人（25 级）会被一次匕首伏击直接杀死；二层的巡逻者会被一星 {spell:1943} 打掉一半生命值；三层露天的哨兵则会被一星 {spell:2098} 打掉一半生命值。{npc:7288} 在顶层等着：23 级精英，击杀后 10 分钟刷新。先用伏击起手（约打掉一半生命值），再用 {spell:1776}、{spell:5277}、治疗药水和 {item:7676}；有朋友帮忙会轻松很多。每次击杀只有一个头颅。然后撬开他身边的 {object:129127} 获取藏品：这会让你染上 {spell:9810}，削弱潜行和敏捷，直到 {npc:2391} 将其治好。",
	["Keep {item:8066} in your bags and use it on him every time you come near, or he turns hostile. {npc:7287} (level 22) walks by the tower: hug the wall, stealth up behind him and {spell:921} the key. Killing him does not give it; if his pockets are empty, kill him and wait 4 1/2 minutes for him to come back."] = "把{item:8066}留在背包中，每次靠近他时都对他使用，否则他会变为敌对。{npc:7287}（22级）在塔楼旁走动：紧贴墙壁，潜行绕到他身后，用{spell:921}偷取钥匙。击杀他不会获得钥匙；如果他口袋里空了，就杀掉他，等4分半钟刷新。",
	["Lockpicking about 75: pick the Buccaneer's Strongboxes on the Tide Razor"] = "开锁技能约75点：打开 海浪剃刀号上的海盗的保险箱",
	["Lockpicking practice"] = "开锁练习",
	["Mutated Venture Co. Drone"] = "变异的风险投资公司雄蜂",
	["Pick Pocket Foreman Silixiz for {item:8072}"] = "对工头希利克斯使用搜索，获得{item:8072}",
	["Poisons (Horde)"] = "毒药（部落）",
	["Rogue"] = "盗贼",
	["Take the zeppelin from {zone:1454} to the {zone:1458} and follow the road south through {zone:1421} into {area:287}, to {area:272}. {npc:2391} works in the building next to the flight path, beside {npc:2216}, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from {npc:3401}. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make {item:6947} from Rekkul's dust and vials, and use it on your weapon."] = "从 {zone:1454} 乘飞艇前往 {zone:1458}，再沿道路向南穿过 {zone:1421}，进入 {area:287}，前往 {area:272}。{npc:2391} 在飞行点旁的建筑中工作，就在 {npc:2216} 旁边，屋外有一辆货车。若弄丢了赞吉尔的药剂样品，放弃任务，再从 {npc:3401} 处重新接受。待在他身边约一分钟，等他调配解药；如果一直无法完成，放弃任务，再从他那里重新接受。随后在法术书中打开毒药，用雷库尔的粉尘和瓶子制作 {item:6947}，并将其涂在武器上。",
	["Take the zeppelin from {zone:1454} to the {zone:1458} and follow the road south through {zone:1421} into {area:287}, to {area:272}. {npc:2391} works in the building next to the flight path, beside {npc:2216}, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from {npc:3401}. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make {spell:8681} from Rekkul's dust and vials, and use it on your weapon."] = "从 {zone:1454} 乘飞艇前往 {zone:1458}，再沿道路向南穿过 {zone:1421}，进入 {area:287}，前往 {area:272}。{npc:2391} 在飞行点旁的建筑中工作，就在 {npc:2216} 旁边，屋外有一辆货车。若弄丢了赞吉尔的药剂样品，放弃任务，再从 {npc:3401} 处重新接受。待在他身边约一分钟，等他调配解药；如果一直无法完成，放弃任务，再从他那里重新接受。随后在法术书中打开毒药，用雷库尔的粉尘和瓶子制作 {spell:8681}，并将其涂在武器上。",
	["The Venture Co. tower"] = "风险投资公司的塔楼",
	["Tide Razor"] = "海浪剃刀号",
	["Venture Co. Lookout"] = "风险投资公司瞭望员",
	["Venture Co. Patroller"] = "风险投资公司巡逻者",
	["Wait for the cure"] = "等待解药",
	["{item:8051}, twice, at Fizzule"] = "在费苏勒处使用两次 {item:8051}。",
	["{item:8072}: Pick Pocket Foreman Silixiz"] = "{item:8072}：对工头西利克兹使用偷窃",
	["{item:8074}: {npc:7288} (elite)"] = "{item:8074}：{npc:7288}（精英）",
	["{item:8095}: clears the {spell:9810}"] = "{item:8095}：清除 {spell:9810}",
	["{npc:2391}: Poisons"] = "{npc:2391}：毒药",
	["{npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Take the quest and wait: he speaks three lines and salutes you. After his third line, target him and type /salute. If it does not count, abandon the quest and take it again. The tower job ahead is built around Ambush, which needs a dagger: if you have none, Kareth, the blade merchant in the {object:172960}, sells a Jambiya."] = "{npc:3401} 在 {object:172960}，也就是 {object:172982} 下方的峡谷里。接任务后等待：他会说三句话，然后向你敬礼。等第三句话说完，选中他并输入 /salute。如果没有完成目标，就放弃任务重新接取。接下来的高塔任务主要靠伏击，需要匕首：如果没有，{object:172960} 的刀剑商人卡雷斯出售曲刃短剑。",
	["{object:129127} at the end of the tower job needs Lockpicking of about 70-75. Train {spell:1804} from Gest or {npc:3401} in the {object:172960} if you lack it, carry {item:5060}, and pick the Buccaneer's Strongboxes on the middle deck of the Tide Razor, the beached pirate ship south of {area:392}: they come back fast. Your cap rises 5 per level."] = "塔楼任务最后的 {object:129127} 需要约70—75点开锁技能。如果还不会 {spell:1804}，就向盖斯特或 {object:172960} 的 {npc:3401} 学习；带上 {item:5060}，到 {area:392} 南边搁浅的海盗船“海浪剃刀号”的中层甲板，练习打开海盗的保险箱：它们刷新很快。你的技能上限每升一级提高5点。",
	["{quest:2458}: keep the {item:8051}"] = "{quest:2458}：保留{item:8051}",
}

G["forever/class/shaman/call-of-air-horde"] = {
	["At 30 Skyborne shamans get their own {quest:96136}. {npc:259119} waits where the airship from Zephras Isle lands, in northern {zone:1412} beside {zone:1456}. Your level 30 air totems need the Air Totem Prate Cloudseer gives. If she has nothing for you, head up to {npc:5906} in {zone:1456} (next step): the trainers' {quest:96136} is open to Skyborne and gives the same totem."] = "30 级时，天裔萨满祭司会获得专属的 {quest:96136}。{npc:259119} 在泽风岛飞船的降落点等着，位于 {zone:1412} 北部、{zone:1456} 旁边。30 级的空气系图腾需要普拉特·白云给予的空气图腾。如果她不给任务，就上去找 {zone:1456} 的 {npc:5906}（下一步）：训练师提供的 {quest:96136} 也对天裔开放，奖励同一个图腾。",
	["At 30 {npc:5892} in the {object:172957} sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} she gives."] = "30级时，{object:172957}的{npc:5892}会让你去找{zone:1441}的{npc:5905}。你的30级空气图腾（根基图腾、{spell:10596}）需要她给的{item:5178}。",
	["At 30 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the Air Totem Prate gives. Already carry {npc:5892}'s {quest:1531} from {zone:1454}? It goes to {npc:5905} too: skip {npc:5906}."] = "30 级时，{zone:1456} 的 {area:1640} 上的萨满祭司训练师 {npc:5906} 会让你去 {zone:1441} 找 {npc:5905}。30 级的空气系图腾（根基图腾、{spell:10596}）需要普拉特给予的空气图腾。已经带着 {zone:1454} 的 {npc:5892} 给你的 {quest:1531}？它也是去找 {npc:5905}：跳过 {npc:5906} 即可。",
	["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "需要五个扭曲的空气图腾。{zone:1443}西部{area:2408}以北和东北方的玛洛迪半人马（36-40级）会携带；斥候的掉率接近两只出一个。玛洛迪争斗者会施放网和缴械，玛洛迪逐风者会治疗，玛洛迪狂怒者会施放{spell:9654}：每次只引一个。刷新约需五分钟。",
	["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "五个扭曲的大地图腾。{zone:1435} 的 {area:75} 北侧及东北侧的失落者（鱼人，34-39 级）携带这些图腾；它们大多会在受伤后逃跑求援。",
	["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "需要五个扭曲的火焰图腾。它们由 {zone:1418} 的 {area:338} 南边的石窟穴居人携带（击颅者、断骨者和萨满祭司，37-41 级）；萨满祭司会放置火焰新星图腾和 {npc:3560}，断骨者受伤后会逃跑求援。大约五分钟刷新。",
	["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "五个扭曲的水之图腾。{zone:1445} 北部、{area:496} 东北面的 黑鳍 鱼人（35—38级）携带这些图腾。",
	["Fly to {area:484}. {npc:5905} stands on a ledge above a cave mouth in the canyon wall north-east of the post, not inside the cave: climb the slope beside it. She also gives you an hour of faster attacks and running."] = "飞往 {area:484}。{npc:5905} 站在哨站东北方峡谷崖壁洞口上方的岩台上，不在洞内：沿洞口旁的斜坡爬上去。她还会让你的攻击速度和奔跑速度提高一小时。",
	["Shaman"] = "萨满祭司",
	["The steam pools"] = "蒸汽池",
	["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "获得能放置空气图腾的{item:5178}，然后在40级自选一把武器。",
	["Twisted Air Totems"] = "扭曲的空气图腾",
	["Twisted Earth Totems"] = "扭曲的大地图腾",
	["Twisted Fire Totems"] = "扭曲的火焰图腾",
	["Twisted Water Totems"] = "扭曲的水之图腾",
	["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} 是位于 {zone:1413} 南缘的五人地下城（箭头指向入口）；{npc:4421}（33级精英）是最终首领。她会施放 {spell:8292}、对盟友施放 {spell:139}，还会使用 纯净术；{item:274463} 只有她会掉落。",
	["{item:212792}, from the {npc:216474}"] = "{item:212792}，来自{npc:216474}",
	["{item:274463}, from {npc:4421}"] = "{item:274463}，来自{npc:4421}",
	["{npc:4722} stands at {area:484}."] = "{npc:4722}站在{area:484}。",
	["{npc:5905} hands you the {item:268582}. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:5905} 会给你 {item:268582}。把 {item:268582} 放在 {area:484} 西北的蒸汽池，召出腐化元素，之后是 {npc:216474}；仪式进行期间，钢鬃野猪人也会加入战斗。这是小队任务：至少带一两位朋友。{item:212792} 大约每两次击杀掉落一次，每名队员都能拾取。",
	["{npc:5905}: your {item:5178}"] = "{npc:5905}：你的{item:5178}",
	["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}; the {item:280696} shield comes with it."] = "{npc:6176} 驻扎在 {zone:1416} 东部的遗迹里：从 {area:272} 出发，沿镇子东边的河流向北进入山区。选择武器：{item:280607}、{item:280605} 或 {item:280604}；另外还会一并获得盾牌 {item:280696}。",
	["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176}：{item:280696}和你的武器",
	["{quest:1531} and the Tempest's Weapons (Horde)"] = "{quest:1531}和风暴武器（部落）",
}

G["forever/class/shaman/call-of-earth-horde"] = {
	["Any Al'Aketh cultist can carry the {item:251924}: the Converts (level 2-3) around the standing stones just east of the village, or the Brutes and Neophytes (level 4) in the camp beyond {npc:252095}, south-west of the village. Keep killing until one drops it."] = "任何奥拉凯斯教徒都可能携带{item:251924}：村庄正东边立石周围的奥拉凯斯信徒（2-3级），或村庄西南方、{npc:252095}后面营地中的蛮兵和奥拉凯斯新教徒（4级）。持续击杀，直到掉落为止。",
	["Back to Boro in {area:16635}. He hands you the {quest:1462}: do not drink it yet."] = "返回 {area:16635} 的波罗处。他会给你 {quest:1462}：先不要喝。",
	["Back to the Seer in {area:221}. She hands you the {quest:1462}: do not drink it yet."] = "返回 {area:221} 的先知处。她会给你 {quest:1462}：先不要喝。",
	["Back to {npc:5887} outside the Den. She hands you the {quest:1462}: do not drink it yet."] = "返回 大兽穴 外的{npc:5887}身边。她会给你{quest:1462}：先别喝。",
	["Bring the {item:6656} back to Boro. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "把 {item:6656} 带回给波罗。把 {item:5175} 永久留在背包里：所有大地系图腾都需要它。",
	["Bring the {item:6656} back to the Seer. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "把 {item:6656} 带回给先知。将 {item:5175} 永久保留在背包中：所有大地图腾都需要它。",
	["Bring the {item:6656} back to {npc:5887} outside the Den. Keep the {item:5175} she gives you in your bags for good: every earth totem needs it."] = "将{item:6656}带回给 大兽穴 外的{npc:5887}。她给你的{item:5175}要永久保留在背包中：所有大地图腾都需要它。",
	["Felstalker Hooves"] = "地狱捕猎者的蹄子",
	["Felstalkers (level 3-4) prowl the slope below the {area:365}, the cave in the north of the valley, and just inside its mouth among the Vile Familiars. Nearly every {npc:3102} drops a hoof (four kills in five); they respawn in a little over three minutes."] = "地狱捕猎者（3-4级）在山谷北部洞穴{area:365}下方的斜坡，以及洞口内的邪灵劣魔之间游荡。{npc:3102}几乎每只都会掉落蹄子（约五只出四个）；刷新时间略多于三分钟。",
	["Lost the {quest:1462}?"] = "弄丢了{quest:1462}？",
	["Lost the {quest:1463}?"] = "弄丢了{quest:1463}？",
	["Only if the {quest:1462} is gone from your bags: the Seer gives you another."] = "仅当背包中的 {quest:1462} 已经不在时：先知会再给你一份。",
	["Only if the {quest:1463} is gone from your bags (drunk away from the rock, or sold): {npc:5887} gives you another."] = "仅在 {quest:1463} 已经不在背包里时需要（在远离岩石的地方喝掉了，或卖掉了）：{npc:5887} 会再给你一份。",
	["Shaman"] = "萨满",
	["The Bristleback Shamans (level 3-4) stand among the quilboar huts of {area:358}, east of the camp, and throw the odd {spell:403}. Four kills in five drop a salve; they respawn in about four minutes."] = "刺背萨满祭司（3—4级）在营地东边 {area:358} 的野猪人小屋之间，偶尔会施放 {spell:403}。药膏掉率为五次击杀约四次；它们大约四分钟刷新。",
	["The {area:16988}"] = "{area:16988}",
	["The {area:16988} is the hilltop shrine north-east of Boro: the path up starts on the hill just above the clearing where the flies were. Drink the {item:6635} beside the shrine and speak to the {npc:251166} before it fades."] = "{area:16988} 是波罗东北方山顶的神殿：上山小路的起点就在之前有苍蝇的空地上方的山坡上。在神殿旁喝下 {item:6635}，并在效果消失前与 {npc:251166} 交谈。",
	["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "你的{item:5175}：没有它就无法施放任何大地图腾。4级时随之获得{spell:8071}。",
	["it hands you the {item:6656}: keep it"] = "它会给你 {item:6656}：留着它",
	["the level 4 shaman spells"] = "4级萨满祭司法术",
	["{area:637} is a small pillar on a low mound due east of {npc:2991}'s well, east of the camp; it only shows from about fifteen yards away, and hostile boars graze around it. Stand beside it and drink the {item:6635}, then speak to the {npc:5891} before it fades (drink again if it does)."] = "{area:637}是营地东面、{npc:2991}水井正东边矮土丘上的一根小石柱；大约15码内才能看到，周围有敌对野猪觅食。站在旁边喝下{item:6635}，再在效果消失前与{npc:5891}交谈（如果消失了就再喝一次）。",
	["{area:639} sits on a ledge in the hills just south of the Den. The {area:638} up starts at the foot of the hills south-west of the Den, between two idle peons; it climbs south-west into the hills, then bends back east to the rock. Stand right beside the stone and drink the {item:6635}: the {npc:5891} appears for a short while, so speak to it at once (walk almost under it if it does not answer). Coming back, you can drop down the ledge towards the Den instead of walking the path."] = "{area:639}位于大兽穴正南方山丘的一处凸台上。上行的{area:638}从兽穴西南方山脚、两名闲置苦工之间开始，先向西南爬上山丘，再转向东到达岩石。紧靠石头站好，喝下{item:6635}：{npc:5891}只会短暂出现，立刻与它交谈（如果没有回应，就走到几乎位于它正下方的位置）。返回时可朝兽穴方向跳下凸台，无需沿原路步行。",
	["{item:6635}, beside the shrine"] = "在神龛旁使用{item:6635}",
	["{item:6635}, beside {area:637}"] = "{item:6635}，在 {area:637} 旁边",
	["{item:6635}, beside {area:639}"] = "{item:6635}，在 {area:639} 旁边",
	["{npc:251374}, the shaman trainer, stands in {area:16635}. The quest opens at level 3."] = "萨满祭司训练师{npc:251374}站在{area:16635}。任务3级开放。",
	["{npc:251374}: {spell:8071} and your {item:5175}"] = "{npc:251374}：{spell:8071}和你的{item:5175}",
	["{npc:5887} stands just outside the Den, the cave in the middle of the {area:363}. The quest opens at level 4."] = "{npc:5887}站在大兽穴外，兽穴就是{area:363}中央的洞穴。任务4级开放。",
	["{npc:5887}: a new {quest:1463}"] = "{npc:5887}：新的{quest:1463}",
	["{npc:5887}: {spell:8071} and your {item:5175}"] = "{npc:5887}：{spell:8071}和你的{item:5175}",
	["{npc:5888} stands in {area:221}. She may show no quest mark over her head: speak to her anyway. The quest opens at level 4."] = "{npc:5888} 站在 {area:221}。她头顶可能没有任务标记：仍然与她交谈。该任务4级开放。",
	["{npc:5888}: a new {quest:1462}"] = "{npc:5888}：新的{quest:1462}",
	["{npc:5888}: {spell:8071} and your {item:5175}"] = "{npc:5888}：{spell:8071}和你的{item:5175}",
	["{quest:1516} (Horde)"] = "{quest:1516}（部落）",
}

G["forever/class/shaman/call-of-fire-horde"] = {
	["At 10 {npc:252382}, the shaman trainer beside {npc:251968} in {area:16638}, hands you the {item:6653} ({npc:254082} offers the same quest). Already left the isle? A {quest:97243} sends you back to them: take the skycutter from the cliffs south of {area:17045}, north of {zone:1456}. Learn {spell:8050} from her now: {npc:268605}, later in the chain, only takes fire damage."] = "达到 10 级后，{area:16638} 中、{npc:251968} 旁的萨满祭司训练师 {npc:252382} 会给你 {item:6653}（{npc:254082} 也提供同一任务）。已经离岛了？{quest:97243} 会让你回去找他们：到 {zone:1456} 北方、{area:17045} 南侧的悬崖乘坐空艇。现在就向她学习 {spell:8050}：任务链后面的 {npc:268605} 只受火焰伤害。",
	["At 10 {npc:3066}, the shaman trainer in {area:222}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5906}'s letter from {zone:1456}? It goes to {npc:5907} too: skip Narm."] = "10 级时，{area:222} 的萨满祭司训练师 {npc:3066} 会让你去 {zone:1413} 找 {npc:5907}。已经带着 {zone:1456} 的 {npc:5906} 给你的信？那也是去找 {npc:5907}：跳过纳姆即可。",
	["At 10 {npc:3173}, the shaman trainer on the east side of {area:362}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5892}'s letter from {zone:1454}? It goes to {npc:5907} too: skip {npc:3173}."] = "达到 10 级后，{area:362} 东侧的萨满祭司训练师 {npc:3173} 会让你去找 {zone:1413} 的 {npc:5907}。已经带着 {zone:1454} 的 {npc:5892} 给的信？那封信也交给 {npc:5907}：可跳过 {npc:3173}。",
	["Back east over the bridge, then south along the {zone:1411} bank of the river to where the mountains meet the water. The trail up starts at the foot of the mountain beside a small dark stone carved with symbols, near the quilboar camp; it is narrow, and a slip costs fall damage. {npc:5900} keeps the shrine at the top."] = "向东过桥返回，再沿河流的 {zone:1411} 一侧河岸南下，直到山体与水面相接的地方。上山小径的起点在山脚，旁边有一块刻着符号的深色小石头，靠近野猪人营地；小路很窄，失足会受到坠落伤害。{npc:5900} 看守着山顶的神龛。",
	["Back to {npc:268592} at the Shrine of Flames."] = "返回供奉火焰的神龛旁的{npc:268592}处。",
	["Back to {npc:268592}. Accept the last quest, then wait by the {npc:268762} while he performs the ritual; when the fire spirits light the {object:148418}, hold the torch to it. From then you have six minutes: carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638}, with no detours or fights. Timer out? Abandon the quest and take it again from {npc:268592}."] = "回到 {npc:268592} 处。接受最后一个任务，然后在 {npc:268762} 身旁等他进行仪式；火焰之灵点燃 {object:148418} 时，将火炬靠上去。从那一刻起你有六分钟：径直将火焰送到 {area:16638} 的 {npc:252382} 身旁的 {npc:268679} 处，不要绕路，也不要战斗。如果超时，就放弃任务，再从 {npc:268592} 处重接。",
	["Back up the trail to {npc:5900}. He makes the {quest:1464} from the tar and the pouch and hands it to you with the torch: keep both."] = "沿小径回到山上找 {npc:5900}。他会用焦油和小袋制作 {quest:1464}，并连同火炬一起交给你：两件都要保留。",
	["Click the {object:61934} on the plateau with the torch in your bags to place the ember, then click it a second time: the next quest does not open by itself. It gives you the lit {item:277329}."] = "确保火炬在背包中，点击高地上的 {object:61934} 放置火种，然后再点击一次：下一个任务不会自动出现。它会给你点燃的 {item:277329}。",
	["Down the trail, back over the bridge to {npc:5907} by his tower. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "沿小径下山，过桥回到塔楼旁的 {npc:5907} 处。将 {item:5176} 永久保留在背包中：所有火焰图腾都需要它。",
	["Drink the {item:6636} beside the {object:63674}, the big grey stone just below the summit, then climb to the plateau. Of the fire elementals there only the one in the middle can be attacked: it is level 12, immune to fire and grows stronger the longer the fight lasts, so open at once with {spell:8017} and {spell:8042} and leave the others alone. Its {item:6655} drops every time."] = "在{object:63674}旁喝下{item:6636}，它是接近山顶处的一块灰色巨石，然后登上平台。那里的火元素只有中间那只能攻击：它为12级，免疫火焰，战斗拖得越久就越强，所以立即用{spell:8017}和{spell:8042}开打，别碰其他火元素。它必定掉落{item:6655}。",
	["Keep the {item:5176} in your bags for good: every fire totem needs it."] = "始终把 {item:5176} 留在背包中：每次使用火焰图腾都需要它。",
	["Lost the {quest:1464}?"] = "弄丢了{quest:1464}？",
	["Only if the {quest:1464} is gone from your bags: {npc:5900} gives you another."] = "仅在 {quest:1464} 已经不在背包里时需要：{npc:5900} 会再给你一份。",
	["Shaman"] = "萨满祭司",
	["The Burning Blade Cultists (level 10-11, they call imps and cast {spell:348}) live deep in {area:371} north of {area:362}: climb the ramp just north-east of town and stay on the high ground above the ravines. The orcs at the cave mouth are not cultists; the cultists are further in, off to the left. Three kills in four drop a pouch. {area:817} by {zone:1454} is the wrong cave."] = "火刃祭司（10-11 级，会召唤小鬼并施放 {spell:348}）在 {area:362} 北边的 {area:371} 深处：从镇子东北不远处的斜坡上去，一直沿沟壑上方的高地走。洞口的兽人不是祭司；祭司在更深处偏左的位置。大约每四次击杀有三次掉落袋子。{zone:1454} 旁的 {area:817} 不是要找的洞穴。",
	["The Razormane casters north-east of the Crossroads drop the {item:5026} three times in four: Water Seekers and Thornweavers (level 10-11), Geomancers (level 12-13, they throw Fireballs and run for help when hurt) and Mystics (level 13-14, they heal themselves at low health). Pull them one at a time."] = "十字路口东北边的钢鬃施法者约每四只掉三个{item:5026}：寻水者和织棘者（10-11级）、地卜师（12-13级，会施放火球术，受伤后会逃跑求援）、秘法师（13-14级，低血量时会自疗）。逐只引来击杀。",
	["The Razormane casters north-east of the {area:380} drop the {item:5026} three times in four: Water Seekers and Thornweavers (level 10-11), Geomancers (level 12-13, they throw Fireballs and run for help when hurt) and Mystics (level 13-14, they heal themselves at low health). Pull them one at a time."] = "{area:380}东北方的刺背部落施法者约四次击杀掉三个{item:5026}：寻水者和织棘者（10-11级）、地卜师（12-13级，会扔火球，受伤就逃跑喊人）和秘法师（13-14级，血量低时会治疗自己）。一次拉一只打。",
	["The Shrine of Flames hides on the island's outer rim south-west of {area:16638}, just south-east of {area:16663}: {npc:268592} keeps it."] = "火焰神殿藏在 {area:16638} 西南的岛屿外缘，位于 {area:16663} 东南不远处：由 {npc:268592} 看守。",
	["The {npc:5893}"] = "{npc:5893}",
	["The {object:148418}"] = "{object:148418}",
	["The {object:61934}"] = "{object:61934}",
	["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "获得用于所有火焰图腾的{item:5176}、借此学会的{spell:3599}，以及无限的{item:263412}。",
	["the ritual, then the {npc:268679} in {area:16638}"] = "先完成仪式，再去找{area:16638}的{npc:268679}",
	["{item:6636}, beside the {object:63674}"] = "在 {object:63674} 旁使用 {item:6636}",
	["{npc:252382}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:252382}：{spell:3599}、你的 {item:5176} 和 {item:263412}",
	["{npc:268602} (level 10, a turncoat Windshaper with a single spawn) holds the farm north-east past {area:16638}, just south of the {area:16629}, on the hill west of the falls north of the {area:17675}. Kill him and take his heart."] = "{npc:268602}（10级，叛变的 塑风者，只有一个刷新点）占据了{area:16638}东北方向更远处的农场，就在{area:16629}南面、{area:17675}北面瀑布以西的山丘上。击杀他并取走心脏。",
	["{npc:5900}: a new {quest:1464}"] = "{npc:5900}：新的{quest:1464}",
	["{npc:5907} hands you the {item:6653}: keep it until the end of the chain."] = "{npc:5907} 会给你 {item:6653}：一直保留到任务链结束。",
	["{npc:5907} is not in the Crossroads: take the road north from the Crossroads and fork east towards {zone:1411}; past {area:1704} he paces by a tall tower east of the road (from {zone:1411}: over the Southfury bridge, past {area:379}). If you reach {zone:1440} you went too far."] = "{npc:5907}不在十字路口：从十字路口沿路向北，在岔路转向东边的{zone:1411}，经过{area:1704}后，他就在路东一座高塔旁来回走动（从{zone:1411}出发：过怒水河大桥，再经过{area:379}）。如果走到{zone:1440}，就是走过头了。",
	["{npc:5907} is not in the {area:380}: take the road north from the {area:380} and fork east towards {zone:1411}; past {area:1704} he paces by a tall tower east of the road (from {zone:1411}: over the Southfury bridge, past {area:379}). If you reach {zone:1440} you went too far."] = "{npc:5907}不在{area:380}：从{area:380}沿路向北，在岔口向东朝{zone:1411}走；过了{area:1704}，他就在大路东侧一座高塔旁踱步（从{zone:1411}出发：过南怒河大桥，经过{area:379}）。要是走到{zone:1440}，说明你走过头了。",
	["{npc:5907}: {npc:3066}'s letter"] = "{npc:5907}：{npc:3066} 的信。",
	["{npc:5907}: {npc:3173}'s letter"] = "{npc:5907}：{npc:3173} 的信。",
	["{npc:5907}: {npc:5892}'s letter"] = "{npc:5907}：{npc:5892} 的信。",
	["{npc:5907}: {npc:5906}'s letter"] = "{npc:5907}：{npc:5906} 的信。",
	["{npc:5907}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:5907}：{spell:3599}、你的 {item:5176} 和 {item:263412}",
	["{object:660848} is the twisted stump on the hilltop by the Shen'dar Highlands Anchor Pylon, west of {area:16638}, in the hills south of the Windsong Crawlers' lakes. Knock on it to call {npc:268605} (level 10). The spirit shrugs off most magic: only fire hurts it, so keep {spell:8050} on it. Take its wooden mask."] = "{object:660848}是申达尔高地锚点水晶塔旁山顶上的扭曲树桩，在{area:16638}西面、风歌爬行者所在湖泊以南的山丘中。敲击它即可召出{npc:268605}（10级）。该灵体几乎不受魔法影响：只有火焰能伤到它，所以持续保持{spell:8050}。取走它的木制面具。",
	["{object:660848}: knock on the bark"] = "{object:660848}：敲击树皮",
	["{quest:1522} (Horde)"] = "{quest:1522}（部落）",
}

G["forever/class/shaman/call-of-water-horde"] = {
	["At 20 {npc:5892} in the {object:172957} sends you to {npc:5901} in the {zone:1413}. (Swart in {area:362} gives the same letter: carry either.)"] = "达到 20 级后，{object:172957} 中的 {npc:5892} 会让你去找 {zone:1413} 的 {npc:5901}。（{area:362} 的斯瓦特也会给你同样的信：带任意一封即可。）",
	["At 20 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5901} in the {zone:1413}. ({npc:3066} in {area:222} gives the same letter: carry either.)"] = "20级时，{zone:1456} 的 {area:1640} 上的萨满祭司训练师 {npc:5906} 会派你去 {zone:1413} 找 {npc:5901}。（{area:222} 的 {npc:3066} 也会给同样的信：带任意一封即可。）",
	["Back to {npc:5899}. She gives you the {item:7810} for {npc:5901}."] = "返回{npc:5899}身边。她会给你{item:7810}，让你交给{npc:5901}。",
	["Back to {npc:5901} south of {area:392}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "返回 {area:392} 南侧的 {npc:5901} 处。务必将 {item:5177} 永久留在背包中：所有水之图腾都需要它。",
	["Click the {object:113791} to place the bracers and the drops. A few seconds later the pure {npc:5895} rises on the stone in the middle of the pool: speak to it while the {spell:8202} lasts (drink again by the stone if it has worn off). It gives you the {item:7813} for {npc:5901}. Gone before you could speak to it? Back at {npc:5901} ask for {quest:63} (a fresh {quest:972} for {npc:7007}, who stands just west of the shrine): hand it to Tiev, stay close while he calls the spirit back, then speak to it."] = "点击 {object:113791}，放上护腕和水滴。几秒后，纯净的 {npc:5895} 会在池中央的石头上出现：趁 {spell:8202} 仍然有效时与它交谈（若效果已经消失，在石头旁再喝一次）。它会给你要带给 {npc:5901} 的 {item:7813}。还没来得及交谈它就消失了？回 {npc:5901} 处索取 {quest:63}（一份新的 {quest:972}，交给站在神殿西侧不远处的 {npc:7007}）：把它交给提夫，留在附近等他再次召唤灵魂，再与灵魂交谈。",
	["Fly to the {area:228}. The shrine lies in a hollow just south-west of it: go round the back of the crypt to the thick tree between the two hills, hop past it onto the rocks and drop west down the slope to the pool (each drop costs a little health). Drink the {item:6637} beside the tall standing stone by the pool: several water elementals appear, and only the corrupt one near the middle can be attacked (Tab picks it). The {npc:5894} is level 22 and casts {spell:8056} and {spell:122}; if someone just killed it, it is back in about three minutes. Its bracers always drop."] = "飞往{area:228}。神龛在其西南不远处的洼地中：绕到墓穴后方，找到两座山丘之间的粗树，跳过树旁登上岩石，再向西沿坡跳下到水池（每次落下都会损失少量生命值）。在池边高耸的竖石旁喝下{item:6637}：会出现几个水元素，只有接近中央的腐化水元素能攻击（按 Tab 可选中）。{npc:5894}为22级，会施放{spell:8056}和{spell:122}；若刚被别人击杀，约3分钟后刷新。它必定掉落护腕。",
	["Lost the {quest:972}?"] = "弄丢了{quest:972}？",
	["Only if the {quest:972} is gone from your bags: {npc:5901} gives you another."] = "仅在 {quest:972} 已经不在背包里时需要：{npc:5901} 会再给你一份。",
	["Shaman"] = "萨满",
	["The muddy pond below {npc:5899}'s hut. Step right into the puddle before you use the {item:7766} (too far away and it refuses). Filling it calls a hostile {npc:3456} (level 20): kill it, and watch for the quilboar hunter by the pond, who may start shooting afterwards."] = "就在 {npc:5899} 小屋下方的泥塘。先走进水洼，再使用 {item:7766}（距离太远会无法使用）。装水会召来一只敌对的 {npc:3456}（20 级）：击杀它，并留意池边的野猪人猎人，后者可能随后开始射击。",
	["The right fountain stands in a ring of standing stones on the island of the small green lake south of {area:415}, west of Lake Mystral (not the island in Lake Mystral itself). From the {zone:1413} take the road north through the {area:1703} and on west. Water elementals and walking treants guard the lake and root you in place; an elite {npc:12836} roams {zone:1440} and can pass close by. Use the {item:7767} beside the fountain."] = "正确的泉水位于{area:415}以南、密斯特拉湖以西的绿色小湖岛上，周围有一圈竖石（不是密斯特拉湖本身的岛）。从{zone:1413}沿路向北穿过{area:1703}，再向西走。湖边有水元素和巡游的树人守卫，它们会将你定身；精英{npc:12836}在{zone:1440}游荡，可能从附近经过。在泉水旁使用{item:7767}。",
	["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "让你能放置水图腾的{item:5177}，以及随之而来的{spell:5394}。",
	["The {npc:5895}"] = "{npc:5895}",
	["The {object:107045}"] = "{object:107045}",
	["The {object:107045} stands in the middle of {area:272}, just outside the church. From the {zone:1413}: the zeppelin from {zone:1454} to {zone:1420}, then south past the {zone:1458} and through {zone:1421} (or fly once you have the {area:272} flight path). {area:287} is contested: Alliance players may attack. Stand beside the well and use the {item:7768}."] = "{object:107045} 就在 {area:272} 中央、教堂外面。从 {zone:1413} 出发：在 {zone:1454} 坐飞艇到 {zone:1420}，然后向南经过 {zone:1458}，穿过 {zone:1421}（开通 {area:272} 的飞行路线后也可以飞过去）。{area:287} 是争夺中的领土：联盟玩家可能会攻击你。站在井旁使用 {item:7768}。",
	["The {object:107046}"] = "{object:107046}",
	["The {object:113791}"] = "{object:113791}",
	["the {item:7810}, for {npc:5901}"] = "{item:7810}，交给{npc:5901}",
	["{item:6637}, beside the standing stone"] = "在竖立的石碑旁使用 {item:6637}。",
	["{item:7766}, standing in the puddle"] = "{item:7766}，站在水洼里使用",
	["{item:7767}, beside the fountain"] = "{item:7767}，在喷泉旁",
	["{item:7768}, beside the well"] = "{item:7768}，在井边",
	["{npc:5899} lives in the southern {zone:1413}, south of {area:378}: her hut sits on a hilltop of {area:1701} with a spinning windmill beside it, and the way up is the ridge by the lone tree. Quilboar camp all around the hill; Stormhides, thunderhawks and hyenas roam the plains on the way."] = "{npc:5899} 住在 {zone:1413} 南部、{area:378} 以南：她的小屋在 {area:1701} 的山顶，旁边有一座转动的风车，沿孤树旁的山脊可以上去。山周围到处是野猪人营地；沿途平原有雷角蜥蜴、雷鹰和土狼游荡。",
	["{npc:5901} hands you the {item:6637} and the {item:7811}: take everything she offers before you leave for Silverpine, or you will be back for more."] = "{npc:5901} 会给你 {item:6637} 和 {item:7811}：前往银松森林前，拿齐她给的所有物品，否则还得回来补拿。",
	["{npc:5901} is not in {area:392}: take the small coast road south from {area:392} past the pirate camp and over a low hill; her fishing hut, with a shark strung up outside, stands by the water before the pirate ship. If you reach the ship you went too far."] = "{npc:5901} 不在 {area:392} 里：从 {area:392} 沿海边小路向南，经过海盗营地，翻过一座小山；她的钓鱼小屋在海盗船前的水边，屋外挂着一条鲨鱼。走到船边就过头了。",
	["{npc:5901}: Narm's letter"] = "{npc:5901}：纳姆的信。",
	["{npc:5901}: Swart's letter"] = "{npc:5901}：斯瓦特的信",
	["{npc:5901}: a new {quest:972}"] = "{npc:5901}：新的{quest:972}",
	["{npc:5901}: your {item:6637}"] = "{npc:5901}：你的{item:6637}",
	["{npc:5901}: {npc:5892}'s letter"] = "{npc:5901}：{npc:5892} 的信。",
	["{npc:5901}: {npc:5906}' letter"] = "{npc:5901}：{npc:5906}的信",
	["{npc:5901}: {spell:5394} and your {item:5177}"] = "{npc:5901}：{spell:5394}和你的{item:5177}",
	["{quest:63} (Horde)"] = "{quest:63}（部落）",
}

G["forever/class/shaman/darkreaver"] = {
	["200 Horde reputation"] = "200点部落声望",
	["A five-player dungeon event: {area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}. In the {object:179746}'s basement, first clear every mob in the room, then use the {item:18746} at its centre: four waves of spirits follow, each closing with an Aspect mini-boss (the first wave weak and slow, the rest elite). Fight in a corner so nothing else joins, and drink between waves: it is long. Then {npc:14516} (level 62 elite) appears: he Cleaves, casts {spell:686} and {spell:6958}, and Dominates a player's mind against the group. His head always drops."] = "这是一个五人地下城事件：{area:2057} 位于 {zone:1422} 东南部岛上城镇 {area:2298} 的下方。在 {object:179746} 的地下室中，先清光房间里所有怪物，再在中央使用 {item:18746}：随后会出现四波灵魂，每波最后都有一名“之貌”小首领（陈腐之貌、堕落之貌、恶毒之貌或暗影之貌；第一波弱且行动迟缓，其余都是精英）。在角落作战，以免引到其他怪物，并在每波之间喝水：战斗很漫长。随后 {npc:14516}（62 级精英）出现：他会顺劈斩，施放 {spell:686} 和 {spell:6958}，还会控制一名玩家攻击小队。他必定掉落头颅。",
	["A {area:2057} fight at 60 for Horde reputation; the {item:20134} may be gone in Forever."] = "60级时在{area:2057}的一场战斗，奖励部落声望；无限可能已移除{item:20134}。",
	["At 58 {npc:13417}, the shaman trainer in the {object:172957}, asks for two rare diamonds; every Horde shaman goes to him. Skyborne: Forever's quest page lists this quest for Orcs, Tauren and Trolls only: ask before you buy the diamonds."] = "58级时，{object:172957} 的萨满祭司训练师 {npc:13417} 会索要两颗稀有钻石；所有部落萨满祭司都要来找他。天裔角色注意：无限服的任务页面显示，此任务仅限兽人、牛头人和巨魔；买钻石前先确认能否接到。",
	["Both diamonds are rare: the auction house is the quick way. Miners find the {item:12800} in about one Thorium vein in a hundred (the Small Thorium Veins north of {area:2418} in the {zone:1428} respawn every five minutes). The {item:18335} drops from high-level elites at about one in a hundred, best from the rare elite Revanchion (about one in nine)."] = "两种钻石都很稀有：在拍卖行购买最快。矿工采掘瑟银矿脉时，取得 {item:12800} 的概率约为百分之一（{zone:1428} 的 {area:2418} 北侧的瑟银矿脉每五分钟刷新）。高等级精英掉落 {item:18335} 的概率约为百分之一，最好找稀有精英雷瓦克安，掉落概率约为九分之一。",
	["Shaman"] = "萨满祭司",
	["Two diamonds"] = "两颗钻石",
	["he hands you the {item:18746}"] = "他会交给你{item:18746}",
	["{npc:13417}: 200 Horde reputation; the {item:20134} may be gone"] = "{npc:13417}：200点部落声望；{item:20134} 可能已经消耗掉",
	["{quest:7668} needs level 60."] = "{quest:7668}需要60级。",
}

G["forever/class/shaman/spirit-totem"] = {
	["A five-player dungeon: needs a group of five, about level 50-55. Fly to {area:75} and ride east. The {area:1417} ({area:1477}) stands in the middle of the {area:74}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Two feathers of each colour, one from each of six elite troll mini-bosses (level 51-52) on the balconies around the temple's great round room, every kill, and each player on the quest loots their own: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Mijan heals the others ({spell:139}, a {npc:3560}): kill him first; Hukku summons guardians and throws Shadow Bolt Volleys."] = "这是五人地下城：需要约 50-55 级的五人小队。飞往 {area:75}，骑马向东。{area:1417}（{area:1477}）位于 {area:74} 中央：登上遗迹南侧的阶梯，潜入被水淹没的大厅，向下游过大厅，再沿楼梯和通道继续向下到传送门。神庙圆形大厅周围的阳台上有六名精英巨魔小首领（51-52 级），每名都必定掉落一根羽毛，每种颜色共两根，队伍中每位有任务的玩家都能拾取自己的：加什尔和 {npc:5716} 掉落琥珀色，胡库和米杉掉落蓝色，祖罗和洛若掉落绿色。米杉会治疗其他首领（{spell:139}、{npc:3560}）：先杀他；胡库会召唤守卫并施放群体暗影箭。",
	["At 50 {npc:13417}, the shaman trainer in the {object:172957}, asks for the four elements for {npc:6176}."] = "50级时，{object:172957} 内的萨满祭司训练师 {npc:13417} 会让你收集四种元素，交给 {npc:6176}。",
	["At 50 {npc:3032}, a shaman trainer on {area:1640} in {zone:1456}, asks for the four elements for {npc:6176}. Skyborne: Forever's quest page lists {quest:8410} and {quest:8412} for Orcs, Tauren and Trolls only; if {npc:3032} has nothing for you, {npc:6176}'s own {quest:8411} is open to every Horde race, but {quest:8412} after it may still turn you away."] = "50级时，{zone:1456}的{area:1640}上的萨满祭司训练师{npc:3032}会让你为{npc:6176}收集四种元素。天裔注意：无限服任务页面列出的{quest:8410}和{quest:8412}仅限兽人、牛头人和巨魔；如果{npc:3032}没有任务给你，{npc:6176}自己的{quest:8411}向所有部落种族开放，但后续{quest:8412}仍可能不让你接受。",
	["Eight of each. Fly or ride to the {area:813} and on to the west edge of the {zone:1422}, north-west of {area:3197}: the Venom Mist Lurkers (level 50-51, they poison) give the {item:20610} and the Diseased Black Bears (level 51-52, {spell:3427}) the {item:20611}, one kill in five each; the two Carrion Vultures there drop either. The bigger Diseased Grizzlies and Plague Lurkers further east almost never drop them. A few bears and lurkers also roam south-east of {area:159} in Tirisfal."] = "每种各八个。飞行或骑马前往 {area:813}，再到 {zone:1422} 西缘、{area:3197} 西北方：毒雾潜伏者（50—51级，会施毒）掉落 {item:20610}，生病的黑熊（51—52级，使用 {spell:3427}）掉落 {item:20611}，两者掉率均为五分之一；那里的两只食腐秃鹫则两种都可能掉落。更东边体形较大的生病的灰熊和瘟疫潜伏者几乎不掉。提瑞斯法的 {area:159} 东南方也有少量熊和潜伏者游荡。",
	["Experience and gold"] = "经验和金币",
	["Experience and gold at 50, ending in the {area:1417}; the Classic item choice may be gone in Forever."] = "50级时获取经验和金币，最终前往{area:1417}；无限 可能取消了经典版的物品选择。",
	["One each of {item:7069}, Fire, Earth and Water; all four trade, so the auction house is quickest. To farm them, {zone:1417} has the exiles near {area:320} (level 38-39, about one kill in eight to ten, respawn under seven minutes): Thundering Exiles south-east of it (air), Rumbling Exiles south-west (earth), Burning Exiles far to the north-west (fire), and the {npc:2794} far to the south-west (water, about one in seven). Water comes easier from the Patches of Elemental Water in {zone:1447} (two in five) or {npc:14269} by {area:69} in Redridge."] = "{item:7069}、元素火焰、元素之土和元素之水各一个；四种都可交易，所以拍卖行最快。自行刷取的话，{zone:1417}的{area:320}附近有流放者（38-39级，约八到十只出一个，刷新不到七分钟）：东南方的雷霆流放者掉空气，西南方的顽石流放者掉土，远处西北方的烈焰流放者掉火，远处西南方的{npc:2794}掉水（约七只出一个）。水更容易从{zone:1447}的元素之水水域（五次出两个），或赤脊山{area:69}旁的{npc:14269}处获得。",
	["Shaman"] = "萨满祭司",
	["Spider eye and bear claw"] = "蜘蛛眼和熊爪",
	["The four elements"] = "四种元素",
	["The {area:1417}"] = "{area:1417}",
	["{item:20606}: Gasher, {npc:5716}"] = "{item:20606}：加什尔、{npc:5716}",
	["{item:20607}: Hukku, Mijan"] = "{item:20607}：胡库、米杉",
	["{item:20608}: Zolo, Loro"] = "{item:20608}：祖罗、洛若尔",
	["{item:7067}: Rumbling Exiles"] = "{item:7067}：{npc:2592}",
	["{item:7068}: Burning Exiles"] = "{item:7068}：{npc:2760}",
	["{item:7069}: Thundering Exiles"] = "{item:7069}：{npc:2762}",
	["{item:7070}: the {npc:2794}, or {zone:1447}'s water patches"] = "{item:7070}：由 {npc:2794} 掉落，或前往 {zone:1447} 的水域寻找",
	["{npc:6176} camps in the ruins of the east of {zone:1416}: from {area:272} follow the river east of town north into the hills."] = "{npc:6176} 在 {zone:1416} 东部的废墟中扎营：从 {area:272} 沿镇东的河流向北进入山地。",
	["{npc:6176}: the old item choice may be gone, count on the experience"] = "{npc:6176}：原来的物品奖励选项可能已移除，按只有经验奖励来打算。",
	["{quest:8412} and {quest:8413}"] = "{quest:8412}与{quest:8413}",
}

G["forever/class/warlock/felhunter-horde"] = {
	["At 30 {npc:5675}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}. Take only one {quest:2996}: if {npc:6251} offers nothing, drop the duplicate from your log."] = "30级时，{object:36082} 的 {npc:5675} 会派你去找 {area:392} 的 {npc:6251}。从 {zone:1420} 出发的飞艇前往 {zone:1411}。只接一个 {quest:2996}：如果 {npc:6251} 没有任务可接，就放弃任务日志中重复的那个。",
	["At 30 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:6251} in {area:392}."] = "30级时，{object:172982}下方{object:172960}的{npc:5875}会让你去{area:392}找{npc:6251}。",
	["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "回到 {area:392} 找 {npc:6251}。接受任务后，他会画出召唤法阵，学徒们会在上方引导出一个更大的法阵：留在塔内，等两者都完成。然后对法阵使用 {quest:1804}。地狱猎犬（30级，非精英）会沉默并消耗法力，而且两分钟后就会消失：提前召出虚空行者，开战立刻施加持续伤害技能，让虚空行者扛住。如果你死亡或战斗失败，就放弃 {quest:1795}，再从 {npc:6251} 处重接。保留魔典：{npc:6251} 会收回它。",
	["Back to {npc:6293}"] = "返回{npc:6293}处",
	["Felhunter (Horde)"] = "地狱猎犬（部落）",
	["Rods of Channeling"] = "导能魔棒",
	["Rods of Channeling, from the Dragonmaw casters"] = "从龙喉施法者处获取引导魔棒。",
	["Summoned Felhunter"] = "召唤的地狱犬",
	["The Dragonmaw hold {area:1036} in the hills east of the road through the {zone:1437}, south of the {area:881} you cross from {zone:1417}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "龙喉氏族占据了贯穿{zone:1437}的道路以东山丘中的{area:1036}，在你从{zone:1417}过来时经过的{area:881}南面。只有施法者掉落法杖，概率为五分之四：龙喉白骨守卫（27级，带骷髅宠物）和 龙喉暗影守卫（28级）。中央灵魂医者北面有一条陡峭小径，可绕过大多数战士进入营地。",
	["The centaur cave opens in the cliffs north of {area:484}. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "半人马洞穴入口位于 {area:484} 北边的悬崖上。进去后每个岔路都靠右走，穿过小瀑布旁的水池，打开墙边、大箱子旁的小型深色箱子：大箱子不是目标。只有接了任务才能打开。离开时，身后的半人马会重新刷新。",
	["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "地狱猎犬，对付施法者的恶魔，外加一个用来装灵魂碎片的{item:22244}。",
	["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "那本典籍是一本灰蓝色小书，躺在{area:271}西南面海岸鱼人营地的沙地上，靠近水边。有六七只鱼人守着，水下还潜伏着更多：它们会成群过来，用恐惧控制一只，让虚空行者扛住其他鱼人。走下到水边再点击书本；从山坡上点击会被箱子挡住鼠标。",
	["Warlock"] = "术士",
	["{area:392}'s flight point is a short flight from {zone:1454}'s. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6293} in the {zone:1458}."] = "从{zone:1454}飞到{area:392}的飞行点只需很短时间。{npc:6251}站在镇上方的山丘上、工程师小屋后方、自己的小塔旁；{npc:6266}和两名侍僧也在那里。他会让你去找{zone:1458}的{npc:6293}。",
	["{item:6931}, from the {quest:1803} on the sand"] = "{item:6931}，来自沙地上的 {quest:1803}",
	["{item:6997}, in the {object:92423}"] = "{item:6997}，在{object:92423}里",
	["{npc:6293} is in the {object:36082} of the {zone:1458}. He wants two lost pieces of the {quest:1801}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6293} 位于 {zone:1458} 的 {object:36082}。他需要找回 {quest:1801} 遗失的两部分：一部分在 {area:287} 海岸，一部分在 {zone:1441}。",
	["{npc:6293} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6293} 会将典籍拼好，并给你 {item:7006}：留着它，{npc:6251} 会连同魔棒一起收走。",
	["{quest:1804}, on the circle"] = "在法阵上使用 {quest:1804}。",
}

G["forever/class/warlock/imp-horde"] = {
	["Imp (Horde)"] = "小鬼（部落）",
	["Rattlecage Skulls"] = "断骨骷髅的颅骨",
	["The Rattlecage Skeletons (level 2-3) stand around the old smithy buildings just north of {area:154}, often right against the walls. Four kills in five drop a skull, so plan on about five; twenty of them spawn there and each comes back after five minutes."] = "断骨骷髅（2—3级）在 {area:154} 正北方的旧铁匠铺建筑附近，常常紧贴着墙。颅骨掉率约为五分之四，因此预计需击杀五只左右；那里共有二十只刷新，每只五分钟刷新一次。",
	["The {quest:1485} (level 3-4) swarm the {area:365}, the cave north of the Den, inside and around its mouth. Almost every kill drops a head (80%), so about eight kills does it; they throw small fireballs, so pull them one at a time. They respawn in just over three minutes. Other classes hunt the same imps for their own {quest:1485} quest."] = "{quest:1485}（3—4级）聚集在 {area:365}，即兽穴北面的洞穴内部和洞口周围。几乎每只都会掉落头颅（80%），因此大约击杀八只即可；它们会投掷小火球，一次只引一只。刷新时间略超过三分钟。其他职业也会为自己的 {quest:1485} 任务击杀这些小鬼。",
	["Vile Familiar Heads"] = "邪灵劣魔的头颅",
	["Warlock"] = "术士",
	["Your first demon at level 1-4: the imp, with a starter blade or staff for Orcs and Trolls."] = "1-4级获得你的第一个恶魔：小鬼，兽人和巨魔还可获得一把新手刀剑或法杖。",
	["Your first letter ({item:9578}, from {npc:1569} after The Mindless Ones) points you to Maximillion, the warlock trainer in {area:154}. {npc:5667} waits inside the building beside him and asks for three Rattlecage Skulls."] = "你的第一封信（完成“无脑的僵尸”后由{npc:1569}给予的{item:9578}）会指引你去找{area:154}的术士训练师马克希米林。{npc:5667}在他旁边的建筑里等候，要你收集3个断骨骷髅的颅骨。",
	["Your first letter ({item:9579} for Orcs, {item:282346} for Trolls, from Gornek after Cutting Teeth) points you to Nartok, the warlock trainer in the Den. {npc:5765} stands just outside the Den in the {area:363} and asks for six Vile Familiar Heads."] = "你的第一封信（完成“小试身手”后由高内克提供，兽人为{item:9579}，巨魔为{item:282346}）会指引你去大兽穴找术士训练师纳托克。{npc:5765}站在{area:363}的大兽穴外，要求收集六个邪灵劣魔的头颅。",
	["{npc:5667} (Undead)"] = "{npc:5667}（亡灵）",
	["{npc:5667} teaches you {spell:688} when you hand in the skulls: summon it right away, it costs nothing and fights beside you."] = "交还头颅时，{npc:5667}会教你{spell:688}：马上召唤它，无需消耗，还能帮你战斗。",
	["{npc:5765} (Orcs and Trolls)"] = "{npc:5765}（兽人和巨魔）",
	["{npc:5765} teaches you {spell:688} when you hand in the heads: summon it right away, it costs nothing and fights beside you. Then speak with {npc:3145} a few steps away for a starter weapon."] = "交还头颅时，{npc:5765} 会教你 {spell:688}：马上召唤，不花钱，还能帮你战斗。然后找几步之外的 {npc:3145} 交谈，领取一件起步武器。",
}

G["forever/class/warlock/incubus-horde"] = {
	["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1472} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "达到 20 级后，{object:172982} 下方 {object:172960} 中的 {npc:5875} 会让你去找几步之外的 {npc:5909}。两名训练师可开启这些恶魔任务，分别是这里的 {npc:5875} 和 {zone:1458} 的 {npc:5675}，但你只能选择其中一人；本指南会跟随你已接受的 {quest:1472} 继续引导。{npc:5909} 提供 {zone:1454} 的两个分支：两个都接。",
	["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "20级：魅魔和无限服的夜魔（魅魔的男性孪生版本），各附赠一个装灵魂碎片的灵魂袋。",
	["Back to {npc:5675} with Dalin's and Corma's hearts. He hands you the {item:6286}: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, {npc:5675} takes them back."] = "带着达林和科尔玛的心脏回到{npc:5675}处。他把{item:6286}交给你：走到他下方的召唤法阵，站上去使用心脏。先召唤你的虚空行者，并把战斗控制在法阵上，否则守卫可能杀掉她且不算你的击杀。如果她赢了，再用一次心脏；留着心脏，{npc:5675}会收回。",
	["Back to {npc:5675} with Dalin's and {npc:5683}'s hearts. He hands you the {item:6286}: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, {npc:5675} takes them back."] = "带着达林和{npc:5683}的心脏返回{npc:5675}。他会给你{item:6286}：下到他下方的召唤法阵，站在阵中使用。先召出虚空行者，并将战斗保持在法阵内，否则卫兵可能杀掉她，导致击杀不算数。如果你输了，再次使用心脏即可；记得保留，{npc:5675}会收回。",
	["Back to {npc:5675} with the lovers' hearts, then place the {item:190181} on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: {npc:5675} takes them back."] = "带着恋人的心脏返回 {npc:5675} 处，再将 {item:190181} 放在同一个法阵上，击败召来的梦魇（20 级，非精英；会魅惑你）。保留心脏：{npc:5675} 会收回它们。",
	["Back to {npc:5875} with the pendant. He hands you {item:6626}: take it across the {object:172960} to {npc:3216}'s tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: {npc:5875} takes it back."] = "带着坠饰返回 {npc:5875} 处。他会给你 {item:6626}：穿过 {object:172960}，到 {npc:3216} 的帐篷，站在紫色法阵上使用。先召唤虚空行者，让它扛住攻击：魅魔（20级，非精英）会魅惑和鞭打，持续给她挂上持续伤害效果。如果她赢了，再次使用坠饰。保留坠饰：{npc:5875} 会收回它。",
	["Back to {npc:5875} with the scarf, then use the {item:190232} on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: {npc:5875} takes it back."] = "带着围巾返回 {npc:5875} 处，再到尼尔鲁帐篷中的同一个法阵上使用 {item:190232}，击败召来的梦魇（20 级，非精英），让虚空行者扛住攻击。保留围巾：{npc:5875} 会收回它。",
	["Corma Villard"] = "科尔玛·维拉德",
	["Corma Villard (level 22, not elite; Comar in older records) wanders the north of the {zone:1437} just past the {area:881}, to the right as you come off the bridge. From the {zone:1458} head through {area:287} and {zone:1417}, where the mobs are 30 and up. Attacking her flags you for PvP."] = "科尔玛·维拉德（22级，非精英；旧资料中写作科马尔）在{zone:1437}北部{area:881}以北游荡，下桥后向右转。从{zone:1458}出发要穿过{area:287}和{zone:1417}，那里的怪物都在30级以上。攻击她会开启你的PvP状态。",
	["Corma's Heart"] = "科尔玛的心脏",
	["Silverpine hearts"] = "银松森林的心脏",
	["Succubus and Incubus (Horde)"] = "魅魔和夜魔（部落）",
	["Summoned Incubus"] = "被召唤的男魅魔",
	["Summoned Succubus"] = "被召唤的魅魔",
	["Take the road west from the Crossroads into {zone:1442} and, just past the border, the faint trail up to the left (south): {area:2539} cannot be reached from the main road. {npc:4197} hands you her draught for {npc:5911}."] = "从十字路口沿路向西进入{zone:1442}，刚过边界就走左侧（南面）向上的隐约小径：从大路无法到达{area:2539}。{npc:4197}会将药剂交给你，送给{npc:5911}。",
	["Take the road west from the {area:380} into {zone:1442} and, just past the border, the faint trail up to the left (south): {area:2539} cannot be reached from the main road. {npc:4197} hands you her draught for {npc:5911}."] = "从{area:380}沿大路向西进入{zone:1442}，刚过边界就走左边（南边）那条模糊的上山小径：{area:2539}无法从主路到达。{npc:4197}把她调制的药剂交给你带给{npc:5911}。",
	["Warlock"] = "术士",
	["the incubus"] = "男魅魔",
	["the succubus"] = "魅魔",
	["{area:422} lies in southern {zone:1440}, south-west of {area:431}. The Shadethicket Stone Movers and Bark Rippers (level 25-26) around the lake drop the {item:190232} about one time in twenty, and the lone {npc:3931} (30) can drop it too: plan on a good number of kills, so come at 25 or later (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in {zone:1440}. They respawn in five minutes."] = "{area:422} 位于 {zone:1440} 南部、{area:431} 西南方。湖周围的移石沼泽兽和碎木沼泽兽（25-26 级）掉落 {item:190232} 的概率约为二十分之一，独自出现的 {npc:3931}（30 级）也可能掉落：预计需要击杀不少怪物，因此等到 25 级或更高再来（无限将本任务等级改为了 27 级）；若你已经绑定了魅魔，可以留到 20 多级在 {zone:1440} 升级时再做。它们每五分钟刷新。",
	["{area:422} lies in southern {zone:1440}, south-west of {area:431}. The Shadethicket Stone Movers and Bark Rippers (level 25-27) around the lake drop the {item:190232} about one time in twenty, and the lone {npc:3931} (30) can drop it too: plan on a good number of kills, so the guide waits for level 24 first (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in {zone:1440}. They respawn in five minutes."] = "{area:422} 位于 {zone:1440} 南部、{area:431} 西南方。湖周围的移石沼泽兽和裂木沼泽兽（25-27 级）掉落 {item:190232} 的概率约为二十分之一，独自出现的 {npc:3931}（30 级）也可能掉落：预计需要击杀不少怪物，因此指南会先等到 24 级（无限将本任务等级改为了 27 级）；若你已经绑定了魅魔，可以留到 20 多级在 {zone:1440} 升级时再做。它们每五分钟刷新。",
	["{item:6286}, on the circle below {npc:5675}"] = "{item:6286}，在 {npc:5675} 下方的法阵上",
	["{item:6626}, on the circle in Neeru's tent"] = "在尼尔鲁帐篷里的法阵上使用{item:6626}",
	["{npc:185333} (level 22) works as a tailor for the {area:279} wizards at {area:233}, in eastern Silverpine: the wizards around her are hostile. {npc:5682} (level 20, not elite) patrols near the {area:230} in the far south. Both are Alliance-friendly humans: attacking them can flag you for PvP. Each drops her or his heart."] = "{npc:185333}（22级）在银松森林东部的 {area:233} 为 {area:279} 的巫师担任裁缝：她周围的巫师是敌对的。{npc:5682}（20级，非精英）在最南端 {area:230} 附近巡逻。两者都是对联盟友善的人类：攻击可能使你进入PvP状态。他们各自掉落自己的心脏。",
	["{npc:185334} (level 22) works in {area:392}, on the {zone:1413} coast, at one of two spots in town: take the zeppelin to {zone:1411} and head south, or fly from {zone:1454}. He is an Alliance-friendly human: attacking him can flag you for PvP."] = "{npc:185334}（22级）在{zone:1413}海岸的{area:392}工作，会出现在镇内两个位置之一：乘飞艇到{zone:1411}后向南走，或从{zone:1454}飞过去。他是对联盟友善的人类：攻击他可能使你进入 PvP 状态。",
	["{npc:185335}, at the circle below {npc:5675}"] = "{npc:185335}，在 {npc:5675} 下方法阵处",
	["{npc:185335}, at the circle in Neeru's tent"] = "{npc:185335}，在尼尔鲁帐篷里的法阵处",
	["{npc:3363} keeps {object:173018} on the main street east of the {object:172960}. He asks you to look for his mate Krilge in {zone:1440}."] = "{npc:3363}经营着{object:172960}以东主街上的{object:173018}。他要你去{zone:1440}寻找伴侣 格莱基。",
	["{npc:3464} waits in front of the inn at the Crossroads. He sends you on to {npc:4197} at {area:2539}, in {zone:1442}."] = "{npc:3464}在十字路口旅店前。他会让你继续去找{zone:1442}的{area:2539}里的{npc:4197}。",
	["{npc:3464} waits in front of the inn at the {area:380}. He sends you on to {npc:4197} at {area:2539}, in {zone:1442}."] = "{npc:3464}在{area:380}的旅店门前等你。他让你去{zone:1442}的{area:2539}找{npc:4197}。",
	["{npc:5683} (level 22, not elite; Comar in older records) wanders the north of the {zone:1437} just past the {area:881}, to the right as you come off the bridge. From the {zone:1458} head through {area:287} and {zone:1417}, where the mobs are 30 and up. Attacking her flags you for PvP."] = "{npc:5683}（22级，非精英；旧记录中称为Comar）在{zone:1437}北部、刚过{area:881}的地方游荡，下桥后往右找。从{zone:1458}出发，穿过{area:287}和{zone:1417}，沿途怪物都在30级及以上。攻击她会使你进入PvP状态。",
	["{npc:5910} lives in a hut up on the cliffs on the west side of the city, above the {object:172982}: climb the wind rider tower, cross the bridge at its top to the west and turn right off it. She sends you to the Crossroads."] = "{npc:5910}住在城市西侧悬崖上的小屋里，就在{object:172982}上方：爬上风骑士塔，从塔顶向西过桥，下桥后右转。她会派你去十字路口。",
	["{npc:5910} lives in a hut up on the cliffs on the west side of the city, above the {object:172982}: climb the wind rider tower, cross the bridge at its top to the west and turn right off it. She sends you to the {area:380}."] = "{npc:5910}住在城西悬崖上的一座小屋里，就在{object:172982}上方：爬上双足飞龙塔，在塔顶过桥向西，下桥后右转。她让你去{area:380}。",
	["{npc:5911} stands at {area:378}, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for {npc:5875}. Keep it."] = "从十字路口沿路向南，{npc:5911}就在{area:378}。他会派你向北前往关押多格兰的野猪人营地：那里有两间并排的小屋，位于一处小屋分散的诱饵营地西北。有时会有一只22级稀有精英野猪人守在小屋旁：先让虚空行者冲进去，必要时牺牲它，然后与多格兰交谈。他会给你一条坠饰，交给{npc:5875}。留好它。",
	["{npc:5911} stands at {area:378}, south down the road from the {area:380}. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for {npc:5875}. Keep it."] = "{npc:5911}站在{area:378}，从{area:380}沿路向南。他让你向北去关押多格兰的野猪人营地：认准两座小屋并排的那座营地，它西北方还有一座小屋分开的诱饵营地。偶尔有一只稀有的22级精英野猪人守着小屋：让虚空行者先上，必要时牺牲它，然后与多格兰交谈。他给你一个交给{npc:5875}的坠饰。收好它。",
	["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} close by. {npc:5693} shows you an image of each quarry and offers both branches: take both."] = "这是 {object:1661} 的版本，适用于接受了 {npc:5675} 而非 {npc:5875} 的 {quest:1472} 的术士。达到 20 级后，{object:36082} 中的 {npc:5675} 会让你去找附近的 {npc:5693}。{npc:5693} 会展示每个目标的影像，并提供两个分支：两个都接。",
	["{quest:1474}: succubus ({zone:1458})"] = "{quest:1474}：魅魔（{zone:1458}）",
	["{quest:1513}: succubus ({zone:1454})"] = "{quest:1513}：魅魔（{zone:1454}）",
	["{quest:65597}: incubus ({zone:1458})"] = "{quest:65597}：梦魇（{zone:1458}）",
	["{quest:65604}: incubus ({zone:1454})"] = "{quest:65604}：梦魇（{zone:1454}）",
}

G["forever/class/warlock/voidwalker-horde"] = {
	["At 10 {npc:3294} sends you to {npc:5875}. He stands outside at the back of {area:362}'s barracks, the big building on the east side of town (not the inn), a few steps from {npc:3172}, the warlock trainer. {npc:5875} stands with the senior warlocks in the {object:172960}, the cavern under {zone:1454}'s {object:172982}. An Orc or Troll leveling in {zone:1420} can take the {zone:1458} version from {npc:5724} in {area:159} instead (the {zone:1458} steps below): you can do only one of the two."] = "10级时，{npc:3294}会派你去找{npc:5875}。他站在{area:362}兵营后面的室外，兵营是城镇东侧的大建筑（不是旅店），距术士训练师{npc:3172}只有几步。{npc:5875}和资深术士们在{object:172960}，即{zone:1454}的{object:172982}下方的洞穴中。在{zone:1420}练级的兽人或巨魔也可以改从{area:159}的{npc:5724}处接受{zone:1458}版本（见下方的{zone:1458}步骤）：两者只能做一个。",
	["At 10 {npc:5724}, upstairs in the {area:2119} in {area:159}, sends you to {npc:5675}: the version for the Undead, and for Orcs and Trolls who level in {zone:1420} instead of taking {npc:5875}'s. {npc:5675} stands in the {zone:1458}'s {object:36082}, by the Temple of the Damned."] = "10级时，{area:159}的{area:2119}楼上的{npc:5724}会让你去找{npc:5675}：这是亡灵的任务版本，也适用于在{zone:1420}练级、没有接受{npc:5875}任务的兽人和巨魔。{npc:5675}站在{zone:1458}的{object:36082}、诅咒神庙旁边。",
	["Back to {npc:5675}. He hands you the {item:6284}: go down the stairs from him to the summoning circle and use them while standing on it. Fight the voidwalker (level 10, not elite) on the circle: if it wanders off, the city guards may kill it and the kill does not count. {spell:14868}, Corruption and {spell:348} with your imp tanking bring it down; it hits harder below 30%. If you lose, use the runes again. Keep the runes: {npc:5675} takes them back."] = "回去找 {npc:5675}。他会给你 {item:6284}：沿他身边的楼梯下到召唤法阵，站在法阵上使用。就在法阵上与虚空行者战斗（10 级，非精英）：如果它走远，城里的守卫可能杀死它，那样就不算你的击杀。让小鬼扛着，用 {spell:14868}、腐蚀术和 {spell:348} 击败它；生命值低于 30% 后，它的攻击会更重。如果打输了，再使用符文。保留符文：{npc:5675} 会收回。",
	["Back to {npc:5875}. He hands you the {item:7464}: take them across the {object:172960} to {npc:3216}'s tent, stand on the purple circle on its floor and use them. The voidwalker (level 10, not elite) hits hard at 30% health and leaves after three minutes, so start at once: {spell:14868}, Corruption and {spell:348}, send your imp in, and Fear it when you need a breather. If it beats you or leaves, the glyphs are not used up: use them again on the circle. Keep the glyphs: {npc:5875} takes them back."] = "返回 {npc:5875} 处。他会给你 {item:7464}：穿过 {object:172960} 到 {npc:3216} 的帐篷，站在地面的紫色法阵上使用。虚空行者（10级，非精英）在生命降至30%时攻击很痛，且三分钟后会离开，因此立即开打：施放 {spell:14868}、腐蚀术和 {spell:348}，派小鬼攻击，需要喘息时用恐惧控制它。如果打输了或它离开了，符文不会消耗：在法阵上再次使用即可。保留符文：{npc:5875} 会收回它们。",
	["Summoned Voidwalker"] = "被召唤的虚空行者",
	["The Scarlet tower stands in the fields west of the {zone:1458}'s ruins (not the tower near {area:154}). The grimoire is in the small chest on the ground floor, under the stairs; ignore the chest upstairs. {npc:1662} (level 9) and a {npc:1537} guard it: kill them, or Fear the zealot while you deal with Perrine. Scarlet Missionaries and Zealots (level 7-9) walk the fields around the tower. The chest is back three seconds after anyone opens it."] = "血色塔楼位于 {zone:1458} 废墟西边的田地中（不是 {area:154} 附近那座塔）。魔典在底层楼梯下的小箱子里；不用管楼上的箱子。{npc:1662}（9级）和一名 {npc:1537} 守着它：可以都杀掉，也可以先恐惧狂热者，再对付派瑞恩。血色传教士和狂热者（7—9级）在塔周围的田地里走动。任何人开箱后三秒，箱子便会刷新。",
	["Voidwalker (Horde)"] = "虚空行者（部落）",
	["Warlock"] = "术士",
	["Your tank demon at 10: the voidwalker, after a stolen book and a fight at a summoning circle."] = "10级获得你的坦克恶魔：虚空行者。需先找回一本被盗的书，再在召唤法阵完成一场战斗。",
	["{area:817} is the cave in the cliffs just east of {zone:1454}'s gate. Inside, take the right-hand ramp up and follow it to the top: the {object:58595} sits on that upper ledge, which cannot be reached from the lower floor. The cave is packed with Burning Blade Apprentices and Fanatics (level 9-11, many with voidwalkers) that respawn quickly, and {npc:3204}, a level 14 Burning Blade warlock, stands near the stash. Old notes call him elite; Forever's data lists him as normal. At 10 it is hard alone: pull one pack at a time and Fear the extra, wait for 11, or go with a friend. The stash always holds the tablet."] = "{area:817} 是 {zone:1454} 城门东侧紧邻悬崖中的洞穴。进入后，沿右侧斜坡一路向上到顶：{object:58595} 就在上方岩台，无法从下层直接到达。洞里挤满了刷新很快的火刃学徒和狂热者（9-11 级，许多带着虚空行者），藏物处附近还站着 {npc:3204}，一名 14 级火刃术士。旧资料称他是精英，但无限的数据将其列为普通怪。10 级时独自完成很困难：每次只拉一组，多出的用恐惧术控制；也可以等到 11 级，或找朋友同行。藏物处必定有石板。",
	["{item:6284}, on the circle below {npc:5675}"] = "{item:6284}，在 {npc:5675} 下方的法阵上",
	["{item:6285}, in {object:37098}"] = "{item:6285}，在{object:37098}里",
	["{item:6535}, in the {object:58595}"] = "{item:6535}，在{object:58595}里",
	["{item:7464}, on the circle in Neeru's tent"] = "在尼尔鲁帐篷里的法阵上使用{item:7464}",
	["{npc:5724}, upstairs in the {area:159} inn"] = "{npc:5724}，在 {area:159} 旅店楼上",
	["{quest:1506} (Orcs and Trolls)"] = "{quest:1506}（兽人和巨魔）",
}

G["forever/class/warrior/brutal-armor"] = {
	["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "20级时，{zone:1456}的战士训练师{npc:3041}会让你去找{area:378}的{npc:6394}。",
	["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "20级时，{object:172958}的{npc:3354}会让你去找{area:378}的{npc:6394}。",
	["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "20级时，{zone:1458}的战士训练师{npc:4595}会让你去找{area:378}的{npc:6394}。",
	["Back to {npc:5878} on {area:1699}. {quest:1848} is the first piece; he then sends you to three crafters, one per piece: take all three."] = "回到{area:1699}的{npc:5878}处。{quest:1848}是第一件装备；之后他会让你去找三名工匠，每人负责一件：三个任务全接。",
	["Fly to {area:378}. {npc:6394} stands in the hut with the leatherworking and tailoring trainers."] = "飞往 {area:378}。{npc:6394} 站在制皮和裁缝训练师所在的小屋内。",
	["Four armor pieces at 30 (hauberk, helm, gauntlets, legguards) and a shield on the way."] = "30级的四件护甲（锁甲、头盔、护手、护腿），途中还有一面盾牌。",
	["Hillsbrad Miners"] = "{npc:2269}",
	["Iron Bars"] = "铁锭",
	["Iron Bars: {npc:8673}"] = "铁锭：{npc:8673}",
	["Roogug in {area:1717}"] = "{area:1717}中的鲁古格",
	["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, his guards come with him. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "鲁古格是 {area:1717} 内的一名精英野猪人（28 级），该地下城位于 {zone:1413} 最南端；这是五人地下城，需要五人小队，他的守卫会一起进入战斗。进去后第一个岔路走左边，跨过猪圈上方的藤桥，经过有大锅的房间：他在右侧房间里等着。他会施放 {spell:403}，并召唤地行者。药瓶必定掉落。",
	["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, his guards come with him. The guide waits for level 26 first. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "鲁古格是 {area:1717} 内的一名精英野猪人（28 级），该地下城位于 {zone:1413} 最南端；这是五人地下城，需要五人小队，他的守卫会一起进入战斗。指南会先等到 26 级。进去后第一个岔路走左边，跨过猪圈上方的藤桥，经过有大锅的房间：他在右侧房间里等着。他会施放 {spell:403}，并召唤地行者。药瓶必定掉落。",
	["Starts now at 20 at your trainer; four armor pieces at 30 (hauberk, helm, gauntlets, legguards), a shield on the way."] = "现在20级就能在训练师那里接到；30级时给出四件护甲（胸甲、头盔、手套、护腿），路上还有一面盾。",
	["Take the zeppelin from {zone:1454} to {zone:1420}; {npc:6411} works in the {zone:1458}'s {object:36078}. She wants 8 Sturdy Dragonmaw Shinbones."] = "搭乘飞艇从 {zone:1454} 前往 {zone:1420}；{npc:6411} 在 {zone:1458} 的 {object:36078} 工作。她需要8根结实的龙喉胫骨。",
	["The Dragonmaw orcs (level 26-30) camp in the middle of the {zone:1437}; from {area:321} in Arathi head south over the {area:881} ({area:150} is Alliance). Every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a {item:7131}: right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast {spell:686}, Bonewarders raise skeletons."] = "龙喉兽人（26-30级）在{zone:1437}中部扎营；从阿拉希的{area:321}向南翻过{area:881}（{area:150}属于联盟）。每个袭击者、沼泽行者、百夫长、守影者和守骨者都会掉落{item:7131}：右键点击来检验，大约四分之一是结实的，其余会断裂，所以8根预计要杀30只以上。移动或战斗时也能检验。兽人血量到15%会跑去求援；袭击者会用网，百夫长会盾击，守影者会施放{spell:686}，守骨者会召唤骷髅。",
	["The Dragonmaw orcs (level 26-30) camp in the middle of the {zone:1437}; from {area:321} in Arathi head south over the {area:881} ({area:150} is Alliance). With {quest:1846} from {npc:6411} in your log, every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a {item:7131} (without the quest they drop none): right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast {spell:686}, Bonewarders raise skeletons."] = "龙喉兽人（26-30 级）驻扎在 {zone:1437} 中部；从阿拉希的 {area:321} 向南跨过 {area:881} 前往（{area:150} 属于联盟）。任务日志中有来自 {npc:6411} 的 {quest:1846} 时，袭击者、沼泽行者、百夫长、暗影守卫和白骨守卫每只都会掉落一个 {item:7131}（没有该任务则不会掉落）：右键点击测试，大约四分之一是结实的，其余会碎掉，所以凑齐 8 个预计要杀 30 只以上。移动或战斗中也能测试。兽人在生命值降至 15% 时会逃跑求援；袭击者会撒网，百夫长会盾击，暗影守卫会施放 {spell:686}，白骨守卫会召起骷髅。",
	["The satyrs of {area:430}, north-east of {area:431} ({area:429}, level 28-30), and the Felmusk satyrs north-west of the post (25-27) drop a hoof four kills in five. A {area:429} satyr at 15% health may cast {spell:6925} and heal to full: finish it fast or stun it. Hellcallers throw Fireballs from 40 yards; Felmusk satyrs reek in melee and run for help at 15%."] = "{area:431}东北方{area:430}的萨特（{area:429}，28-30级），以及哨站西北方的魔草萨特（25-27级）掉蹄子的概率为五只出四个。{area:429}的萨特在生命值降至15%时可能施放{spell:6925}，恢复满血：尽快击杀或将其击昏。地狱召唤者会在40码外施放火球术；魔草萨特会在近战中散发恶臭，并在生命值降至15%时逃跑求援。",
	["The {npc:6167} (level 28, not elite, larger than the young ones around her) roams the south edge of the {area:465} in south-west Stonetalon, near the road to {zone:1443}. She is the only one: she returns 5 minutes after dying and drops the {item:6840} four kills in five. She spits {spell:3396} from 30 yards."] = "{npc:6167}（28级，非精英，体型比周围的幼崽大）在石爪山脉西南部{area:465}的南缘游荡，靠近通往{zone:1443}的道路。只有这一只：死亡后5分钟刷新，{item:6840}掉落概率为五分之四。她会从30码外喷吐{spell:3396}。",
	["Warrior"] = "战士",
	["You have 30 minutes, and each {item:7119} rots 15 minutes after you loot it, so take the quest only when ready (logging out does not stop the clock). The Silithid Mounds dot the {area:390} south of {area:378}; every silithid drops an antenna. Creepers (level 20-21) and Grubs are the easiest: Swarmers (21-22) call small swarms and Creepers lay eggs that hatch adds. The eastern part of the field has plenty of Creepers. {item:7120}, a shield, is the reward."] = "你有30分钟，而且每份 {item:7119} 都会在拾取后15分钟腐烂，所以准备好后再接任务（下线不会暂停计时）。{area:378} 南面的 {area:390} 散布着异种蝎土丘；每只异种蝎都掉落一根触角。爬行者（20—21级）和格拉布最容易对付：异种群居蝎（21—22级）会召来小虫群，爬行者 会产卵并孵出额外敌人。田地东部有很多 爬行者。奖励是盾牌 {item:7120}。",
	["You need 10 Iron Bars. Miners smelt them from {item:2772} (one ore a bar, {spell:3307} at {skill:186} 125); everyone else buys them at the auction house in {zone:1454}."] = "你需要10块铁锭。矿工可用{item:2772}熔炼（一块矿石熔成一块锭，{skill:186}达到125后学习{spell:3307}）；其他人可在{zone:1454}拍卖行购买。",
	["You need 10 {item:7127}. The Hillsbrad Miners (level 26-27) work the mine in the hills west of {area:271} and drop the azurite four kills in five; they fight in {spell:71}, sunder your armor and run for help at 30% health. Fly to {area:272} and head south-west."] = "你需要 10 个 {item:7127}。希尔斯布莱德矿工（26-27 级）在 {area:271} 西边山中的矿洞工作，碧蓝石掉率约为五分之四；它们以 {spell:71} 战斗，会破甲，并在生命值降到 30% 时逃跑求援。飞到 {area:272} 后向西南走。",
	["You need 10 {item:7127}. The guide waits for level 25 first. The Hillsbrad Miners (level 26-27) work the mine in the hills west of {area:271} and drop the azurite four kills in five; they fight in {spell:71}, sunder your armor and run for help at 30% health. Fly to {area:272} and head south-west."] = "你需要 10 个 {item:7127}。指南会先等到 25 级。希尔斯布莱德矿工（26-27 级）在 {area:271} 西边山中的矿洞工作，碧蓝石掉率约为五分之四；它们以 {spell:71} 战斗，会破甲，并在生命值降到 30% 时逃跑求援。飞到 {area:272} 后向西南走。",
	["You need 15 Smoky Iron Ingots. The {area:2160} lies at the east end of {area:461}, east of {area:460}; every Windshear kobold (level 19-23) drops an ingot four kills in five. Stonecutters, Geomancers and Overlords run for help when low; Geomancers cast {spell:116}."] = "需要15块烟雾铁锭。{area:2160} 位于 {area:461} 东端、{area:460} 以东；所有风剪狗头人（19—23级）都有约五分之四的概率掉落一块锭。切石者、地卜师和监工生命值低时会逃跑求援；地卜师会施放 {spell:116}。",
	["from the Dragonmaw orcs: right-click to test it"] = "从龙喉兽人身上获得：右键点击进行测试",
	["{item:6840}, from the {npc:6167}"] = "{item:6840}，来自{npc:6167}",
	["{item:6841}, from Roogug"] = "{item:6841}，来自鲁古格",
	["{item:7119}, from the silithid"] = "{item:7119}，由异种虫掉落",
	["{item:7126}, from the Windshear kobolds"] = "{item:7126}，由风剪狗头人掉落",
	["{item:7127}, from the Hillsbrad Miners"] = "{item:7127}，由希尔斯布莱德矿工掉落",
	["{npc:5878}'s hut sits on top of {area:1699}, east of the Crossroads: climb the broad ridge on the north or east side. {quest:1838} is a level 30 quest; take it now and gather on the way. {item:7587} list where each material comes from."] = "{npc:5878}的小屋在十字路口东边的{area:1699}顶部：从北侧或东侧宽阔的山脊爬上去。{quest:1838}是30级任务；现在先接取，沿途收集。{item:7587}列出了各项材料的来源。",
	["{npc:5878}'s hut sits on top of {area:1699}, east of the {area:380}: climb the broad ridge on the north or east side. {quest:1838} is a level 30 quest; take it now and gather on the way. {item:7587} list where each material comes from."] = "{npc:5878}的小屋位于{area:1699}顶上、{area:380}以东：从北侧或东侧的宽山脊爬上去。{quest:1838}是30级任务；现在就接，路上顺便收集。{item:7587}列出了每种材料的来源。",
	["{npc:6408} is in {area:367} on the {zone:1411} coast. He wants 7 Uncloven Satyr Hooves."] = "{npc:6408} 位于 {zone:1411} 海岸的 {area:367}。他需要 7 个完整的萨特之蹄。",
	["{npc:6410} works on {zone:1456}'s lowest level, close to the blacksmith."] = "{npc:6410} 在 {zone:1456} 的最底层、铁匠附近工作。",
}

G["forever/class/warrior/heirloom-weapon"] = {
	["At 10, {npc:2131}, the warrior trainer inside the inn of {area:159}, sends you to {npc:1496} by the graveyard on {area:159}'s west edge. This road and {npc:5810}'s exclude each other: drop {quest:1505} or {quest:1498} from your log if you hold one."] = "10级时，{area:159} 旅店内的战士训练师 {npc:2131} 会派你去找 {area:159} 西边缘墓地旁的 {npc:1496}。这条任务线与 {npc:5810} 的任务线互斥：如果任务日志里有 {quest:1505} 或 {quest:1498}，先放弃。",
	["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "10级时，{npc:252377}与训练师们站在{area:16638}西门旁。教徒{npc:257196}在{area:16629}持有她家的盾牌。",
	["At 10, {npc:3063}, the warrior trainer of {area:222}, sends you to {npc:5810} in the {zone:1413}. {npc:3041} in {zone:1456} offers it too."] = "10级时，{area:222} 的战士训练师 {npc:3063} 会派你去找 {zone:1413} 的 {npc:5810}。{zone:1456} 的 {npc:3041} 也提供这个任务。",
	["At 10, {npc:3169}, the warrior trainer in the barracks of {area:362}, sends you to {npc:5810} in the {zone:1413}. Sorek in {zone:1454}'s {object:172958} offers it too. Any Horde warrior may take one of the two roads, never both: heading to {zone:1420} at 10 anyway? {npc:2131} in {area:159}'s inn offers the other: one fight by {area:159}'s graveyard for the same stance, then the Agamand crypt for an heirloom weapon."] = "10级时，{area:362}兵营里的战士训练师{npc:3169}会让你去找{zone:1413}的{npc:5810}。{zone:1454}的{object:172958}里的索瑞克也提供此任务。所有部落战士都可以选择两条路线之一，但不能两条都做：如果10级本来就要去{zone:1420}，{area:159}旅店里的{npc:2131}提供另一条路线：先在{area:159}墓地旁打一场，学会同样的姿态，再去阿加曼德墓穴取一把传家武器。",
	["Back to {npc:1500}"] = "回到{npc:1500}那里",
	["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:5810}'s road below still gives a weapon later, once you reach Kalimdor."] = "回到{area:16638}找{npc:252377}。她会教你{spell:71}，并给你配套使用的盾牌{item:275290}。抵达卡利姆多后，沿下方{npc:5810}的任务路线继续，之后仍会获得武器。",
	["Back to {npc:5810} under his tree west of {area:379}."] = "回到 {area:379} 西边树下的 {npc:5810} 处。",
	["Dillinger stands by the graveyard on {area:159}'s west edge. An Orc, Troll, Tauren or Skyborne who took {quest:1818} from {npc:2131} instead of {npc:5810}'s road is led through {area:159} from here."] = "亡灵卫兵迪林格尔站在 {area:159} 西边缘的墓地旁。如果兽人、巨魔、牛头人或天裔角色接受了 {npc:2131} 的 {quest:1818}，而非选择 {npc:5810} 的任务线，接下来就会从这里沿 {area:159} 的路线进行。",
	["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "从 {area:16638} 向西北前往 {area:16629}。{npc:257196} 站在神殿入口通路的西侧，周围是教团的守护者、唤灵者和剑圣：先逐个拉出来清掉，再对付他。他会掉落 {item:263993}。",
	["Singed Scales in {area:369}"] = "{area:369}的烧焦的鳞片",
	["The four Agamand Weapon Racks are inside the {area:158} at the north end of {area:157}, north of {area:159}, one rack per room: one in the lowest room, two in the pair of rooms up the stairs, one in the room above those. The axe rack stands in a dark corner. The crypt's undead come in packs of three or more and return quickly; the ones in the top room are not linked. The axe, dagger and mace racks take 15 minutes to refill after someone loots them."] = "四个阿加曼德武器架位于 {area:159} 以北、{area:157} 北端的 {area:158} 内，每间房一个：最底层房间一个，上楼后的一对房间里各一个，再上一层的房间一个。斧架在一个阴暗角落。地穴中的亡灵每群至少三只，刷新很快；顶层房间的敌人不会一起参战。斧、匕首和锤的武器架被拾取后，需要15分钟才会补满。",
	["The {area:158}"] = "{area:158}",
	["The {object:58369} stands by a broken wagon in the Razormane camp north-west of {npc:5878}, north-east of the Crossroads. Two Razormanes guard it and their hunters pull more quilboar: clear them one at a time, then open the chest (it refills within seconds, so a friend can loot it too)."] = "{object:58369} 在 {npc:5878} 西北侧的钢鬃营地，靠着一辆损坏的货车，位于十字路口东北方。两名钢鬃野猪人守着箱子，猎手还会引来更多野猪人：逐只清掉，再开箱（箱内物品几秒内就会刷新，朋友也能拾取）。",
	["The {object:58369} stands by a broken wagon in the Razormane camp north-west of {npc:5878}, north-east of the {area:380}. Two Razormanes guard it and their hunters pull more quilboar: clear them one at a time, then open the chest (it refills within seconds, so a friend can loot it too)."] = "{object:58369}立在{npc:5878}西北、{area:380}东北的钢鬃营地中一辆破车旁。两个钢鬃野猪人守着它，他们的猎人还会引来更多野猪人：一个一个清掉，然后打开箱子（几秒内就会补满，所以朋友也能拾取）。",
	["Ulag the Cleaver"] = "劈砍者乌拉格",
	["Warrior"] = "战士",
	["You need five Singed Scales. Thunder Lizards (level 9-10) and Lightning Hides (10-11) live down in the {area:369} crevasse in north-west {zone:1411}, south of {zone:1454}: from the {zone:1413} bridge turn left and follow the river north into it. Both drop a scale about four kills in five; both cast {spell:5401}."] = "需要五片烧焦的鳞片。雷霆蜥蜴（9-10级）和闪电蜥蜴（10-11级）生活在{zone:1411}西北部、{zone:1454}以南的{area:369}裂谷底部：从{zone:1413}的桥过来后左转，沿河向北进入。两者掉鳞片的概率都约为五只出四片；两者都会施放{spell:5401}。",
	["Zaal Stormshield"] = "扎尔·风盾",
	["{item:263993}, from {npc:257196}"] = "{item:263993}，由{npc:257196}掉落",
	["{item:6486}, from the lizards"] = "{item:6486}，从蜥蜴身上获得",
	["{item:6534}, from the {object:58369}"] = "{item:6534}，来自{object:58369}",
	["{npc:1500} is in the {area:2119}, the inn on {area:159}'s east side."] = "{npc:1500} 在 {area:159} 东边的旅店 {area:2119} 内。",
	["{npc:252377} in {area:16638}"] = "{area:16638}的{npc:252377}",
	["{npc:5810} at {area:379}"] = "{area:379}的{npc:5810}",
	["{npc:5810} is easy to miss: he stands under a small canopy by a large tree just west of {area:379}, below the road's south side, with the post in sight to his east. Going straight south from the post does not lead to him. From {zone:1411} cross the bridge west; from {zone:1412} head north past the Crossroads."] = "{npc:5810} 很容易错过：他在 {area:379} 西边不远处的一棵大树旁，站在路南下方的小棚子里，向东能看见哨站。从哨站直接向南走找不到他。从 {zone:1411} 来就向西过桥；从 {zone:1412} 来则向北，经过十字路口。",
	["{npc:5810} is easy to miss: he stands under a small canopy by a large tree just west of {area:379}, below the road's south side, with the post in sight to his east. Going straight south from the post does not lead to him. From {zone:1411} cross the bridge west; from {zone:1412} head north past the {area:380}."] = "{npc:5810}很容易错过：他站在{area:379}正西一棵大树下的小棚子里，位于道路南侧下方，向东能看见哨站。从哨站直接往南走找不到他。从{zone:1411}向西过桥；从{zone:1412}向北经过{area:380}。",
	["{npc:5878}'s hut sits on top of {area:1699}, east of the Crossroads. Most slopes are too steep: climb the broad ridge on the north or east side."] = "{npc:5878} 的小屋在十字路口东侧的 {area:1699} 顶上。大多数山坡太陡：从北侧或东侧的宽阔山脊爬上去。",
	["{npc:5878}'s hut sits on top of {area:1699}, east of the {area:380}. Most slopes are too steep: climb the broad ridge on the north or east side."] = "{npc:5878}的小屋在{area:1699}顶上，位于{area:380}以东。大多数坡太陡：从北侧或东侧宽阔的山脊爬上去。",
	["{npc:6390} sleeps in the mausoleum in the graveyard just north of Dillinger. To wake him, click the flat skull plaque on the ground, left of the path to the mausoleum door; the seal lifts and {npc:6390} (level 11, not elite) walks out. Start at full health."] = "{npc:6390} 沉睡在迪林格正北边墓地的陵墓内。要唤醒他，点击通往陵墓大门的小径左侧、地上的扁平骷髅石板；封印解除后，{npc:6390}（11 级，非精英）就会走出来。满血再开始。",
	["{spell:71} and a Weapon (Horde)"] = "{spell:71}和一把武器（部落）",
	["{spell:71} at 10 and a one-hand weapon of your choice: {npc:5810}'s road, {area:159}'s crypt, or the Skybreaker shield."] = "10级时的{spell:71}和一把自选的单手武器：{npc:5810}的路线、{area:159}的墓穴，或破天者之盾。",
}

G["forever/collectibles/mounts/horde/black-war-mounts"] = {
	["Black War Mounts"] = "黑色战斗坐骑",
	["PvP rank 11"] = "PvP 军衔11",
	["{item:18247}, {spell:18995}, 100g"] = "{item:18247}，{spell:18995}，100 金",
	["{item:18248}, {spell:10906}, 100g"] = "{item:18248}，{spell:10906}，100 金",
	["{npc:12796} sells the mounts by the {area:2917} in {zone:1454}'s {object:172958}, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Orcs ride the wolf, Trolls the raptor, Tauren the kodo, Undead the skeletal warhorse. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city)."] = "{npc:12796} 在 {zone:1454} 的 {object:172958} 中、{area:2917} 旁出售坐骑，就在其他荣誉军需官附近。无限服客户端标价均为100金币。每种坐骑还需要对应的骑乘技能：兽人骑狼，巨魔骑迅猛龙，牛头人骑科多兽，亡灵骑骸骨战马。天裔或任何选择其他种族坐骑的玩家，都必须先从对应训练师处学习该骑乘技能（需要该种族主城声望达到崇拜）。",
	["{npc:14329}, {spell:825}, 100g"] = "{npc:14329}，{spell:825}，100金币",
	["{npc:14330}, {spell:10861}, 100g"] = "{npc:14330}，{spell:10861}，100金币",
	["{spell:1299382} come from battlegrounds, PvP quests and the season's weekly tasks, with a weekly cap; {spell:436438} (rank 11) unlocks the Black War mounts. The Player vs. Player tab of your character pane shows your rank and what you may buy. {skill:762} one at full speed needs Journeyman {skill:762} (level 60). Polestar cannot read your rank, so this step waits for level 60 and Journeyman {skill:762}."] = "{spell:1299382} 来自战场、PvP任务和赛季每周任务，有每周获取上限；{spell:436438}（军衔11级）可解锁黑色作战坐骑。角色面板的玩家对战分页会显示你的军衔及可购买的物品。以全速 {skill:762} 这些坐骑需要中级 {skill:762}（60级）。Polestar 无法读取你的军衔，因此此步骤会等待你达到60级并学会中级 {skill:762}。",
}

G["forever/collectibles/mounts/horde/frostwolf-howler"] = {
	["The Forever client lists it at 200g and level 60. It runs at full speed, so riding it needs Journeyman {skill:762}; any Horde race can ride it."] = "无限服客户端列出的价格为200金币，要求60级。它以最高速度奔跑，因此骑乘需要中级{skill:762}；所有部落种族都能骑。",
	["{area:2839} (level 51+) raises {faction:729}: win, capture towers and graveyards, and hand in the battleground's turn-ins; the Alterac Valley Reputation guide shows the fastest way. {npc:13219} waits at the Horde end of {zone:1416} outside the battleground; {npc:13218} inside {area:2839} sells the same mount."] = "{area:2839}（51级及以上）能提高{faction:729}声望：赢得战斗、占领塔楼和墓地，并交还战场收集任务；最快的方法见奥特兰克山谷声望指南。{npc:13219}在战场外、{zone:1416}的部落一端等候；{area:2839}内的{npc:13218}也出售相同坐骑。",
	["{npc:13219}, 200g"] = "{npc:13219}，200金",
}

G["forever/collectibles/mounts/horde/great-kodo"] = {
	["Any Horde race can buy these kodos, but riding one also takes {spell:18995}, which only Tauren get with {skill:762}. {npc:3690} teaches it to other races once they are Exalted with {faction:81} (the Thunder Bluff Reputation guide shows the way). Until then, don't buy a kodo for this character."] = "部落所有种族都能购买这些科多兽，但骑乘还需要{spell:18995}，只有牛头人会在学习{skill:762}时获得。其他种族需{faction:81}声望达到崇拜后，才能向{npc:3690}学习（可参阅“雷霆崖声望”指南）。在此之前，不要为这个角色购买科多兽。",
	["Great Kodo"] = "大型科多兽",
	["Journeyman {skill:762}"] = "中级{skill:762}",
	["Pick a colour"] = "选择颜色",
	["{item:18793}, 200g"] = "{item:18793}，200金",
	["{item:18794}, 200g"] = "{item:18794}，200金",
	["{item:18795}, 200g"] = "{item:18795}，200金",
	["{npc:3685} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:3685}出售其他颜色（无限 客户端中每个200金）。想要就买，如果喜欢获赠的那匹也可以不买。",
	["{npc:3690} and {npc:3685}'s kodos are in {area:222}, {zone:1412}. At 60 {npc:3690} teaches Journeyman {skill:762} to Tauren for 1,000g (10% less at Honored with {faction:81}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each great kodo costs 200g here."] = "{npc:3690}和{npc:3685}的科多兽都在{zone:1412}的{area:222}。60级时，牛头人可花1,000金币向{npc:3690}学习中级{skill:762}（{faction:81}声望尊敬后优惠10%）；暴雪称会附带一只坐骑。其他种族要向各自种族的骑术训练师学习。这里每只大型科多兽售价200金币。",
	["{npc:3690}, riding trainer"] = "{npc:3690}，骑术训练师",
	["{spell:18995} for other races"] = "其他种族学习{spell:18995}",
}

