	["{npc:4752} and {npc:3362}'s kennel are in {faction:76}'s {object:172958}. At 60 {npc:4752} teaches Journeyman {skill:762} to Orcs for 1,000g (10% less at Honored with {faction:76}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift wolf costs 200g here."] = "{npc:4752} 和 {npc:3362} 的狼舍位于 {faction:76} 的 {object:172958}。60 级时，{npc:4752} 会向兽人传授中级 {skill:762}，费用 1,000 金币（{faction:76} 声望尊敬可享 10% 折扣）；暴雪说明该训练会附赠一只坐骑。其他种族需找本族骑术训练师学习。这里每只迅捷狼售价 200 金币。",
	["{npc:4752}, riding trainer"] = "{npc:4752}，骑术训练师",
	["{spell:825} for other races"] = "其他种族学习{spell:825}",
}

G["forever/collectibles/mounts/horde/wolf"] = {
	["Any Horde race can buy these wolves, but riding one also takes {spell:825}, which only Orcs get with {skill:762}. {npc:4752} teaches it to other races once they are Exalted with {faction:76} (the Orgrimmar Reputation guide shows the way). Until then, don't buy a wolf for this character."] = "任何部落种族都能购买这些狼，但骑乘还需要 {spell:825}，只有兽人会在学习 {skill:762} 时获得它。其他种族与 {faction:76} 达到崇拜后，{npc:4752} 才会教授（奥格瑞玛声望指南有详细路线）。在那之前，不要为这个角色买狼。",
	["Learn to ride"] = "学习骑术",
	["Pick a colour"] = "挑选颜色",
	["Wolf"] = "狼",
	["{item:1041} is in the client (20g) but our data has no vendor selling it."] = "{item:1041}存在于客户端中（20金），但我们的数据中没有出售它的商人。",
	["{item:1132}, 20g"] = "{item:1132}，20金",
	["{item:5665}, 20g"] = "{item:5665}，20金",
	["{item:5668}, 20g"] = "{item:5668}，20金",
	["{npc:3362} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:3362}出售其他颜色（无限 客户端中每只20金）。想要哪只就买哪只；如果喜欢送你的那只，也可以不买。",
	["{npc:4752} and {npc:3362}'s kennel are in {faction:76}'s {object:172958}. At 40 {npc:4752} teaches {skill:762} to Orcs for 100g (10% less at Honored with {faction:76}), and it comes with a wolf. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4752} 和 {npc:3362} 的兽栏位于 {faction:76} 的 {object:172958}。40级时，兽人可以花100金币向 {npc:4752} 学习 {skill:762}（{faction:76} 声望达到尊敬可优惠10%），并获得一只狼。其他种族则要到各自种族的骑术训练师处学习 {skill:762}，同时获得自己的第一只坐骑。",
	["{npc:4752}, riding trainer"] = "{npc:4752}，骑术训练师",
	["{spell:825} for other races"] = "其他种族学习{spell:825}",
}

G["forever/collectibles/pets/black-tabby"] = {
	["The {npc:1920}, a rare level 21 mage at {area:233} in southern {zone:1421}, drops the {npc:7383} about once in 6 kills. It has a single spot and can take hours to come back, so check it whenever you pass. While it is down, the Dalaran Shield Guards, Theurgists and Summoners (level 31-35) at the {area:279} crater, where {zone:1416} meet {zone:1424}, drop it too, but only about once in 500 kills. The cat can be traded: look at the Auction House as well."] = "{npc:1920} 是 {zone:1421} 南部 {area:233} 的一名 21 级稀有法师，约每击杀 6 次掉落一次 {npc:7383}。它只有一个刷新点，可能数小时才会刷新，每次经过都可以看看。它没刷新时，也可以打 {area:279} 陨石坑内的达拉然持盾守卫、法师和召唤师（31-35 级），那里是 {zone:1416} 与 {zone:1424} 交界处，不过掉率只有约五百分之一。这只猫可以交易：也看看拍卖行。",
	["{area:279} mages"] = "{area:279}的法师",
}

G["forever/collectibles/pets/excitable-slime"] = {
	["Buy {item:278265} from {npc:4612} in the {zone:1458} canals first (25 copper for a stack of 5): you hand it in as soon as the slime offers its quest."] = "先在 {zone:1458} 运河里的 {npc:4612} 处购买 {item:278265}（一组5个，25铜币）：软泥怪提供任务后，你就要立即交还它。",
	["Find an {npc:269452}, a little critter in the canal water beside {npc:4612}, target it and /dance at it, again and again, until it dances back and offers {quest:97583}; this takes many tries. Hand in the sludge right away. If the slime seems tired, /dance with it again before you hand in."] = "在 {npc:4612} 旁边的运河水中找一只 {npc:269452}，它是小型环境生物；选中它，反复对它使用 /dance，直到它也跳舞并提供 {quest:97583}；需要尝试很多次。立即交还淤泥。如果软泥怪看起来累了，交还前再与它 /dance 一次。",
	["{item:278265}: {npc:4612}, in the canals"] = "{item:278265}：运河里的 {npc:4612}",
}

G["forever/collectibles/pets/halpa"] = {
