	["{npc:4551}, the bat handler"] = "{npc:4551}，蝙蝠管理员",
	["{npc:4551}: keep {item:16210}, Podrig takes it on the next stop at the {area:228}, at 22"] = "{npc:4551}：留着{item:16210}，22级时在下一站{area:228}交给波德里格",
	["{npc:4556}, the weapon merchant beside the bat handler"] = "{npc:4556}，蝙蝠管理员旁边的武器商人",
	["{npc:4586}, the engineering trainer, works in the {zone:1458}."] = "工程学训练师{npc:4586}在{zone:1458}工作。",
	["{npc:4586}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4586}：露营入门，来自提瑞斯法林地{npc:265812}的营火",
	["{npc:4598}, the mining trainer, works in the {zone:1458}."] = "采矿训练师{npc:4598}在{zone:1458}工作。",
	["{npc:4598}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4598}：露营入门，来自提瑞斯法林地{npc:265812}的营火",
	["{npc:4605}, the blacksmithing trainer, works in the {zone:1458}."] = "锻造训练师{npc:4605}在{zone:1458}工作。",
	["{npc:4605}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4605}：露营入门，来自提瑞斯法林地{npc:265812}的营火",
	["{npc:4949} stands in Grommash Hold. He offers {quest:98024} and {quest:93739} once {quest:95350} is handed in."] = "{npc:4949} 站在 Grommash Hold 内。交掉 {quest:95350} 后，他会提供 {quest:98024} 和 {quest:93739}。",
	["{npc:4949}, inside Grommash Hold"] = "{npc:4949}，在格罗玛什要塞里",
	["{npc:4949}: keep it, Thork at the Crossroads in the {zone:1413} guide"] = "{npc:4949}：先留着，在 {zone:1413} 指南中交给十字路口的索克",
	["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}：{quest:93739}，游览部落各位领袖",
	["{npc:5204}, in the Apothecarium"] = "{npc:5204}，在炼金房内",
	["{npc:5204}: Helbrim at the Crossroads, in the next guide"] = "{npc:5204}：交给十字路口的赫布瑞姆，见下一篇指南",
	["{npc:7088}, the skinning trainer, stands in the {object:172958}."] = "剥皮训练师{npc:7088}站在{object:172958}。",
	["{npc:7088}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:7088}：露营入门，来自{zone:1411}布拉克的营火",
	["{object:112888}, inside the keep; upstairs"] = "{object:112888}，在城堡里；楼上",
	["{object:1571}; upstairs"] = "{object:1571}；在楼上",
	["{object:1599}, just east of the keep"] = "{object:1599}，就在城堡东边",
	["{object:1661} lies under the {area:153}, beside the zeppelin towers. {npc:2050} stands at the inn by the way down; {npc:7683} on the way down to the Apothecarium, where {npc:11044} and {npc:5204} stand beside {npc:2055}."] = "{object:1661} 位于 {area:153} 地下，旁边就是飞艇塔。{npc:2050} 在下去入口旁的旅店；{npc:7683} 在通往炼金房的路上，{npc:11044} 和 {npc:5204} 就在炼金房内的 {npc:2055} 旁。",
	["{object:173016} is a few steps north."] = "{object:173016} 就在北边几步处。",
	["{object:173016} is a few steps north.\nThe {object:172960} is the canyon under the {object:172982}; {quest:829} stands at its far end."] = "{object:173016}在北边几步远。\n{object:172960}就是{object:172982}下方的峡谷；{quest:829}位于峡谷的另一端。",
	["{quest:264} is handed in at {object:24776}, a grave a few steps south of the crypt entrance, not to a person."] = "{quest:264}要在{object:24776}交付，那是墓穴入口南边几步远的一座坟墓，而不是交给某个人。",
	["{quest:6127}: {area:384}, next guide"] = "{quest:6127}：{area:384}，见下一个指南",
	["{zone:1454}'s {object:172982}"] = "{zone:1454}的{object:172982}",
}

G["forever/horde/04-the-barrens"] = {
	["A few steps east of {npc:14242}'s tree, a small camp: two Encroaching Soldiers and the {npc:268623} for Logmar. The {npc:268623} is elite: grouping up is advised."] = "{npc:14242}那棵树以东几步有个小营地：两个入侵的士兵，还有洛格玛要的{npc:268623}。{npc:268623}是精英：建议组队。",
	["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "协助{npc:261366}：当{npc:261367}和{area:21}水兵走上山脊时，待在他身边",
	["At the {object:147538}: summons {quest:882}"] = "在{object:147538}：召唤{quest:882}",
	["Back north into the Bristleback camps. Any Bristleback can drop a tusk for {npc:3432}, so collect them while you kill these for {npc:3430}. Keep one {item:5075}."] = "向北回到刺背野猪人营地。任何刺背野猪人都可能为{npc:3432}掉落獠牙，所以你在为{npc:3430}杀它们时顺手收集。留一个{item:5075}。",
	["Back to {area:380}"] = "回到{area:380}",
	["Bael'dun Excavator"] = "巴尔丹挖掘者",
	["Bael'dun Foreman"] = "巴尔丹工头",
	["Bael'dun fortress"] = "巴尔丹城堡",
	["Bloodfury Ambusher"] = "血怒伏击者",
	["Bloodfury Harpy"] = "血怒鹰身人",
	["Bloodfury Roguefeather"] = "血怒盗羽者",
	["Bloodfury Slayer"] = "血怒杀戮者",
	["Bristleback Geomancer"] = "刺背地卜师",
	["Bristleback Thornweaver"] = "刺背织棘者",
	["Bristleback Water Seeker"] = "刺背寻水者",
	["Bristleback camps"] = "刺背野猪人营地",
	["Cannoneer Smythe"] = "炮手斯迈斯",
	["Cannoneer Whessan"] = "炮手韦桑",
	["Captain Fairmount"] = "费尔蒙特上尉",
	["Cast {spell:18960}"] = "施放{spell:18960}",
	["Cast {spell:18960}. Tauren: join the two pendant halves at the {area:2362}, on the north-west shore of the lake, before you see {npc:11802} in {area:2361}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}。牛头人：先到湖边西北岸的{area:2362}把两半吊坠合起来，再去{area:2361}见{npc:11802}。{npc:11802}在他建筑的楼上：从里面上楼，箭头分不清楼层。",
	["Cenarion Botanist"] = "塞纳里奥植物学家",
	["Crossroads flight master"] = "十字路口飞行管理员",
	["Daughter of Cenarius"] = "塞纳留斯之女",
	["Dogran is chained up in the quilboar camp west of the road."] = "多格兰被锁在道路西边的野猪人营地里。",
	["Down the {area:458} to {area:378} again."] = "再次沿{area:458}向南前往{area:378}。",
	["East along the road from {area:2539} to {npc:4049}'s camp, on the way to {area:378}."] = "从{area:2539}沿道路向东到{npc:4049}的营地，就在前往{area:378}的路上。",
	["Encroaching Soldier"] = "进犯的士兵",
	["Fill the {item:7766} at the quilboar watering hole"] = "在野猪人的水坑装满{item:7766}",
	["Fizzule is by the Venture Co. tower north of the {area:382}. Before you go near him, use {item:8051} to fire two flares, then target him and /salute: he attacks anyone who comes in without signalling first."] = "菲祖尔在{area:382}以北的风险投资公司塔旁。靠近他之前，先用{item:8051}放出两支信号弹，然后选中他并输入/salute：没先发信号就靠近的人他都会攻击。",
	["Fly to Crossroads"] = "飞往十字路口",
	["Fly to the Crossroads from the wind rider master: {npc:2995} on {zone:1456}'s central rise."] = "从双足飞龙管理员处飞往十字路口：{npc:2995}在{zone:1456}的中央高台上。",
	["Fly to {area:1638}"] = "飞往{area:1638}",
	["Fly to {area:1638} and train your level 20 ranks: {npc:3033} is on {area:1639}."] = "飞往{area:1638}训练20级技能：{npc:3033}在{area:1639}。",
	["Fly to {area:1638} first: two of its elders give quests worked on this guide's and the next guide's walks."] = "先飞往{area:1638}：那里的两位长者会给出在本篇和下一篇指南路线中完成的任务。",
	["Fly to {area:1638} to train: {npc:3033} is on {area:1639}."] = "飞往{area:1638}训练：{npc:3033}在{area:1639}。",
	["Fly to {area:378}"] = "飞往{area:378}",
	["Fly to {area:380}"] = "飞往{area:380}",
	["Fly to {area:392}"] = "飞往{area:392}",
	["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "沿道路向北朝{area:467}前进。巨角鹿沿途吃草；腐蚀兽、夜行虎和灵龙在山峰下方的树林中游荡，塞纳里奥德鲁伊占据那里的树林。",
	["Follow the road west past Regthar's bunkers and Seereth's camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "沿道路向西，经过雷格萨的碉堡和塞雷思的营地进入石爪山脉：{npc:3995}在{area:2539}的地下等候，就在{area:1076}脚下。",
	["Follow the road west past Regthar's bunkers and {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "沿路向西，经过雷戈萨的地堡和{npc:4049}的营地，进入石爪山脉：{npc:3995}在{area:1076}脚下、{area:2539}的地下等候。",
	["Follow the road west past Regthar's bunkers: {npc:4049} camps beside it at the edge of Stonetalon."] = "沿道路向西经过雷戈萨的地堡：{npc:4049}在石爪山脉边缘的路旁扎营。",
	["Follow the {area:458} south to {area:378}."] = "沿{area:458}向南前往{area:378}。",
	["From {area:2539} follow the road east to Seereth's camp, then south-east across the plains to {area:378}."] = "从{area:2539}沿路向东到塞雷思的营地，再向东南穿过平原前往{area:378}。",
	["From {area:2539} follow the road east to {npc:4049}'s camp, then south-east across the plains to {area:378}."] = "从{area:2539}沿路向东到{npc:4049}的营地，再向东南穿过平原，前往{area:378}。",
	["From {area:378} follow the road west through the gate into {zone:1412}, then north past {area:222} to {zone:1456}; a lift at the foot of the bluffs takes you up."] = "从{area:378}沿道路向西穿过大门进入{zone:1412}，再向北经过{area:222}前往{zone:1456}；山崖脚下的升降梯会带你上去。",
	["Gaea Dirt Mounds"] = "盖亚土堆",
	["Gaea Seeds"] = "盖亚之种",
	["He gives you the {item:15826}"] = "他会给你{item:15826}",
	["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "他接下来会提供{quest:1838}（1838，30级）：它需要{area:1717}，还会让你跑遍卡利姆多和东部王国。战士职业指南{quest:1838}涵盖了它。",
	["Head back down the {area:1076} to {area:2539}."] = "沿 {area:1076} 下行，返回 {area:2539}。",
	["Head north from the {area:380} to {area:384} and fill the {item:15842} at the {object:19464}, then back to {npc:3448} in the {area:380}. No {skill:182}? {npc:3490} beside him sells {item:2449}, three at a time until he restocks."] = "从{area:380}向北到{area:384}，在{object:19464}处把{item:15842}装满，然后回到{area:380}的{npc:3448}那里。没有{skill:182}？他旁边的{npc:3490}卖{item:2449}，一次三个，直到他补货。",
	["Hecklefang Stalker"] = "斗牙潜伏者",
	["If you skipped {quest:92706}, grind here to level 19.43 to stay on the route's plan."] = "如果你跳过了{quest:92706}，在这里刷到19.43级，以保持在路线计划内。",
	["Inside"] = "在里面",
	["Keep it: the {object:107045} is beside {area:272}"] = "留着它：{object:107045}在{area:272}旁边",
	["Keep it: {npc:12696} in {zone:1440}, next guide"] = "留着它：交给{zone:1440}的{npc:12696}，见下一个指南",
	["Keep it: {npc:5875} in {zone:1454}, at the end of this guide"] = "留着它：交给{zone:1454}的{npc:5875}，在本指南结尾",
	["Level 19.43"] = "19.43级",
	["Mutated Venture Co. Drone"] = "变异的风险投资公司苦工",
	["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "向北前往{area:383}。{npc:3682}在山下扎营；他身后山脊上的隐士{npc:261366}要等{npc:3682}派你上去后才会给你任务。",
	["On the top floor"] = "在顶层",
	["On the way back down the {area:458} to {area:378}: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry {item:277277}. Hand them to {npc:3432} on your last {area:380} stop."] = "沿{area:458}返回{area:378}的路上：营地北边道路两侧刺背野猪人营地中的钢鬃掠夺者携带{item:277277}。最后一次在{area:380}停留时交给{npc:3432}。",
	["On the way back east to {npc:3341}: Hecklefang Stalkers and {npc:3238} lizards roam the plain between the ridge and his camp."] = "向东返回 {npc:3341} 处的途中：乱齿捕猎者和 {npc:3238} 蜥蜴在山脊与他营地之间的平原游荡。",
	["Outraged Pillager"] = "暴怒的掠夺者",
	["Pickpocket {npc:7287} for the tower key before opening the lockbox. Gallywix and his lockbox are at the top; the key does not open that box, which still needs Lockpicking. Gallywix is elite: grouping up is advised. If you postpone this optional job, resume it in the Class guide Poisons (Horde)."] = "打开保险箱前，先从{npc:7287}身上偷取塔楼钥匙。加里维克斯和他的保险箱在塔顶；这把钥匙打不开该保险箱，仍需开锁技能。加里维克斯是精英，建议组队。这段自选工作可以稍后从职业指南“毒药（部落）”继续。",
	["Raptor nests"] = "迅猛龙巢穴",
	["Savannah Patriarchs roam the plains east of the hills, and the Sprung Traps lie among them. {quest:876} leads the Witchwing harpies in the hills to the west.\nCareful: The route in passes stealthed Harpy Ambushers and an elite harpy that patrols."] = "萨凡纳雄狮在丘陵以东的平原游荡，弹开的陷阱就散布在它们中间。{quest:876}会引导西边丘陵里的巫翼鹰身人。\n注意：进来的路上有潜行的鹰身人伏击者和一只巡逻的精英鹰身人。",
	["Sickly Gazelle"] = "病弱的瞪羚",
	["Son of Cenarius"] = "塞纳留斯之子",
	["South of Camp Taurajo the Silithid Mounds dot the {area:390}; the eggs lie in them, and Silithid Swarmers come out to defend them. Silithid Harvesters are rare: if you see one, kill it for its head.\nCareful: Silithid Swarmers in the area release many tiny adds that interrupt spells; damage shields such as Thorns kill them in one hit."] = "陶拉祖营地以南，异种虫丘散布在{area:390}；卵就在里面，异种虫群居者会出来保护它们。异种虫收割者很稀有：看到就杀掉取头。\n注意：这一带的异种虫群居者会放出许多微小的增援打断施法；荆棘术之类的伤害护盾能一击杀死它们。",
	["South of Gann, the Bael'dun dwarves dig at {area:359}. Excavators and Foremen work the pit; {npc:3392} (26) carries the journal: pull him alone.\nCareful: Excavators (level 21-22) and Foremen (level 22-23) run off for help once they fall to 15% health, so more dwarves can join the fight."] = "加恩·石塔以南，巴尔丹矮人正在{area:359}挖掘。挖掘工和工头在坑中工作；{npc:3392}（26级）带着日志：单独把他引出来。\n小心：挖掘工（21-22级）和工头（22-23级）在生命值降至15%时会逃跑求援，可能引来更多矮人参战。",
	["South-west of Bael Modan, {npc:12576} waits at the top of the {area:1718}."] = "巴尔莫丹西南方，{npc:12576} 在 {area:1718} 顶端等待。",
	["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "烈日石居西南方是烧焦的{area:465}。把{item:16205}种在谷底的土堆里；火元素掉落{item:16312}。血怒鹰身人和血怒伏击者在北侧筑巢，血怒杀戮者和血怒游荡者在南侧。",
	["Stormhide"] = "风暴皮",
	["Sunscale Scytheclaws hunt the plains south of the {area:380}, around the {area:1697}; they drop the horns. Hand them in on your next pass through {area:392}.\nEast across the plains toward the coast: the stolen silver lies in a raptor nest north-west of {area:385}."] = "阳鳞镰爪龙在{area:380}以南、{area:1697}周围的平原狩猎；它们掉落角。下次经过{area:392}时交任务。\n向东穿过平原朝海岸走：被偷的银币在{area:385}西北的迅猛龙巢里。",
	["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue."] = "牛头人：{npc:11957}在桥上方的南边山丘上等候。天裔：{npc:272054}站在双桥南边。然后前往湖东边的兽穴：解除变形，点击入口处的雕像获得五分钟潜行，避开里面的灵魂，每种遗物各拿一件；{item:280680}在白色猎豹雕像脚下。",
	["The Bael'dun Soldiers, Riflemen and Officers guard the fortress on the east side of the dig; all three items drop from them.\nCareful: Riflemen (level 24-25) Shoot from 5-30 yd, so nearby ones can join a fight from range."] = "巴尔丹士兵、巴尔丹火枪手 和 巴尔丹军官 守卫着挖掘场东侧的堡垒；它们会掉落全部三种物品。\n小心：巴尔丹火枪手（24—25级）的射击射程为5—30码，附近的敌人可能从远处加入战斗。",
	["The Bristleback quilboar camps spread over the plains north of {area:378}, either side of the {area:458}. {npc:3432}'s wife lies at their north edge, on your way south. Leave the quilboar for now: {npc:3430} in {area:378} wants the same camps cleared. {quest:883}, a grey kodo, sometimes wanders here: his hoof starts a quest."] = "刺背野猪人营地散布在{area:378}以北的平原上，{area:458}两侧。{npc:3432}的妻子躺在营地北缘，正好在你往南的路上。野猪人先别管：{area:378}的{npc:3430}要清的正是这些营地。{quest:883}是一头灰色科多兽，有时会在这里游荡：它的蹄子能开启一个任务。",
	["The Gaea Seeds lie in the grass around the southern shore of {area:464}, north of Sun Rock.\nCareful: Pridewings around the lake can aggro as a linked group."] = "盖亚之种散布在烈日石居以北、{area:464} 南岸周围的草丛中。\n小心：湖边的雄翼双足飞龙可能会整群联动进入战斗。",
	["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "地区东北角矿洞的风险投资公司监督和风险投资公司执行者掉落{item:5097}。",
	["The antennae vanish fifteen minutes after they drop, so gather them now, on the way back north: kill the Silithid Swarmers and Creepers at the {area:390}' mounds until you have five, then take them straight to {npc:6394} in {area:378}.\nCareful: Silithid Swarmers (level 21-22) cast {npc:4196} both in and out of combat, which brings several small adds. Silithid Creepers (level 20-21) periodically cast {npc:5781} in combat, which spawns extra adds."] = "触角掉落后15分钟就会消失，所以现在就收集，回北边的路上：在{area:390}的虫丘旁杀异种虫群居者和爬行者，直到凑够五个，然后直接送到{area:378}的{npc:6394}。\n注意：异种虫群居者（21-22级）会在战斗内外施放{npc:4196}，会带来几个小增援。异种虫爬行者（20-21级）在战斗中会定期施放{npc:5781}，生成额外的增援。",
	["The dwarves' flying machine sits on its platform inside the dig site."] = "矮人的飞行器停在挖掘场内的平台上。",
	["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "矮人的飞行器停在挖掘场内的平台上。对它使用{npc:3341}给你的{item:5021}。",
	["The flying machine"] = "飞行器",
	["The road west"] = "西边的道路",
	["The road west past {npc:4049}'s camp"] = "向西经过{npc:4049}营地的道路",
	["The three nests sit together in the {area:1697} south-west of the oasis; Sunscale Scytheclaws guard them."] = "三个巢挨在一起，在绿洲西南的{area:1697}；阳鳞镰爪龙守着它们。",
	["The top of the {area:1718}"] = "{area:1718}顶部",
	["The {area:1718}"] = "{area:1718}",
	["The {area:2363}"] = "{area:2363}",
	["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960}是{object:172982}下方的峡谷。",
	["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177792}位于{area:382}北缘、风险投资公司的塔旁。里面装着{quest:30}所需的{item:15883}。",
	["The {object:667362} grows on the bottom of {area:464}, off the same southern shore: dive to the plants and the Dried Mirkweed Piles; both give pods. Watch your breath."] = "{object:667362}生长在{area:464}湖底，就在同一处南岸外：潜到这些植物和干枯的暗草堆旁；两者都能获得荚果。注意呼吸。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:209797} (level 20 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人来一起做。{npc:209797}（20级精英）需要2人小队。如果只有你一个人就跳过：路线会安排你刷怪补经验。",
	["Thunderhawk Cloudscrapers circle over the same plains south of the camp."] = "雷鹰破云者在营地南边同一片平原上空盘旋。",
	["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard, roams among them: his Tailspike starts a quest."] = "电角蜥蜴在{area:378}正南的平原上吃草。{quest:884}是一只蓝色的雷霆蜥蜴，在它们中间游荡：它的尾刺可以开始一个任务。",
	["To {area:378}"] = "前往{area:378}",
	["To {zone:1456}"] = "前往{zone:1456}",
	["Twitching Antennae"] = "颤抖的触角",
	["Twitching Antennae from the silithid"] = "从异种蝎身上获取颤抖的触角",
	["Up the {area:1076} past {npc:4201} and west to {area:460}."] = "沿着{area:1076}向上，经过{npc:4201}再向西到{area:460}。",
	["Up the {area:1076} past {npc:4201} and west to {area:460}; coming from {npc:4073}, back west past Ziz's hut."] = "沿{area:1076}上行，经过{npc:4201}，再向西到{area:460}；如果从{npc:4073}处过来，就向西折回经过菲兹克斯的小屋。",
	["Up the {area:1076} to {npc:4201}' hut, then east along the road toward {area:461}: {npc:4074} patrols the road just east of the fork, {npc:4073} the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them."] = "沿{area:1076}上行到{npc:4201}的小屋，再沿道路向东朝{area:461}前进：{npc:4074}在岔路口东边不远处的路上巡逻，{npc:4073}在更东北方峭壁下的山坡上。两者都是落单的伐木机器人；它们会四处游荡，所以沿路前进直到遇见它们。",
	["Upstairs"] = "楼上",
	["Venture Co. Lookout"] = "风险投资公司瞭望员",
	["Venture Co. Patroller"] = "风险投资公司巡逻者",
	["Venture Co. tower"] = "风险投资公司的塔",
	["West of Gann, the Razormane hold {area:1701}. {npc:3436} is on the east side, {npc:3434} to the south, {npc:3435} at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; {npc:5859}, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. {npc:3238} lizards and Hecklefang Stalkers roam the plain between {npc:3341} and the ridge. {quest:885}, a rare red wind serpent, flies over the ridge: its feather starts a quest.\nCareful: Razormane Stalkers move around in stealth and hit with {spell:1752}, so they can join a fight without warning."] = "加恩以西，钢鬃野猪人占据{area:1701}。{npc:3436}在东侧，{npc:3434}在南边，{npc:3435}在西端。洛克（25级）和钢鬃战狂（24-25级）比你高几级；稀有精英{npc:5859}有时会在山脊上走动：别惹他。寻路者和潜伏者掉背刺者，先知掉魔杖，钢鬃战狂掉战争之盾。{npc:3238}蜥蜴和斗牙潜伏者在{npc:3341}与山脊之间的平原游荡。{quest:885}是一条稀有的红色风蛇，飞越山脊：它的羽毛能开启一个任务。\n注意：钢鬃潜伏者会潜行移动，并用{spell:1752}攻击，所以它们可能毫无预警地加入战斗。",
	["West of Gann, the Razormane hold {area:1701}. {npc:3436} is on the east side, {npc:3434} to the south, {npc:3435} at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; {npc:5859}, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. {quest:885}, a rare red wind serpent, flies over the ridge: its feather starts a quest.\nCareful: Razormane Stalkers move around in stealth and hit with {spell:1752}, so they can join a fight without warning."] = "加恩·石塔西边的 {area:1701} 被钢鬃野猪人占据。{npc:3436} 在东侧，{npc:3434} 在南边，{npc:3435} 在最西端。洛克·奥克班恩（25 级）和战狂（24-25 级）比你高几级；稀有精英 {npc:5859} 有时会沿山脊巡逻：别招惹它。探路者和钢鬃捕猎者掉落 钢鬃背刺匕首，先知掉落 烧焦的钢鬃魔杖，战狂掉落 钢鬃大盾。{quest:885} 是一条稀有红色风蛇，会在山脊上空飞行：它的羽毛可以开启任务。\n小心：钢鬃捕猎者会潜行移动，并使用 {spell:1752} 攻击，可能毫无预警地加入战斗。",
	["While you are in the dig: {npc:3421} hides at the south edge of the dig; {object:3646} sits at the bottom of the excavation."] = "在挖掘场里时：{npc:3421}躲在挖掘场南缘；{object:3646}在挖掘坑底部。",
	["Wizzlecrank drives his shredder out of the camp: stay with him and kill whatever attacks him. {npc:3442} takes it in {area:392}.\nCareful: The route leads west and climbs a ramp. Once you reach the top, two Venture Company mobs ambush you."] = "维兹克兰克开着他的伐木机冲出营地：跟着他，杀掉任何攻击他的东西。{npc:3442}在{area:392}接收。\n注意：路线向西，爬上一段斜坡。一到顶上，两个风险投资公司的人会伏击你。",
	["XT:4"] = "XT:4",
	["XT:9"] = "XT:9",
	["grind on {npc:3256}"] = "刷{npc:3256}",
	["the {area:380}"] = "{area:380}",
	["{area:1697}: kill these as you meet them"] = "{area:1697}：遇到就杀",
	["{area:17}: kill these as you meet them"] = "{area:17}：遇到就杀",
	["{area:378} flight master"] = "{area:378}的飞行管理员",
	["{area:380} flight master"] = "{area:380}飞行管理员",
	["{area:385}, on the coast further south. The Theramore Marines and Preservers (15-16) drop the medals; {npc:3393} (20) and the two cannoneers (19) stand in the keep and on its walls, and they are why the hold waits until now.\nCareful: Each named target is linked to a healer and guards, and Fairmount has three extra marines with her. Killing the healer first makes the fight easier."] = "{area:385}，在更南边的海岸。塞拉摩水兵和守护者（15-16级）掉落勋章；{npc:3393}（20级）和两个炮手（19级）站在城堡里和城墙上，正因如此这个据点才等到现在。\n注意：每个有名字的目标都和一名治疗者及卫兵联动，费尔蒙特还多带三个水兵。先杀治疗者会让战斗更轻松。",
	["{area:385}: kill these as you meet them"] = "{area:385}：遇到就杀",
	["{area:465}: kill these as you meet them"] = "{area:465}：沿途遇到就击杀",
	["{item:10338}, from any zhevra; Zhevra Chargers graze around the tree"] = "{item:10338}，来自任何斑马；斑马冲锋者在大树周围吃草",
	["{item:15852}: Lost Barrens Kodos on the plains around the Kolkar camp"] = "{item:15852}：科卡尔营地周围平原上的落单的草原科多兽",
	["{item:15885}: use a half at the {area:2362}"] = "{item:15885}：在{area:2362}使用其中一半",
	["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "向{npc:3490}购买{item:2449}；草药师可以在平原上采集",
	["{item:2449}: herbalists pick it here"] = "{item:2449}：草药师可在这里采集",
	["{item:277936}, from any Bloodfury harpy"] = "{item:277936}，来自任何血怒鹰身人",
	["{npc:10079} stands at the top of the {area:1718}, beside {npc:12576}."] = "{npc:10079}站在{area:1718}顶部，在{npc:12576}旁边。",
	["{npc:10079}, at the top of the lift"] = "{npc:10079}，在升降梯顶部",
	["{npc:11798} in {area:2361} flies druids there"] = "{area:2361}的{npc:11798}载德鲁伊飞往那里",
	["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "{npc:11802}在{area:2361}他建筑的楼上：从里面上楼，箭头分不清楼层。",
	["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}：{npc:3033}的问候",
	["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}：从血怒鹰身人获取闪光的太阳石",
	["{npc:11860}: {npc:12576} is at the {area:1718}, later in this guide"] = "{npc:11860}：{npc:12576} 在 {area:1718}，在本篇指南后续步骤完成",
	["{npc:11861}, beside {npc:11862}"] = "{npc:11861}，在{npc:11862}旁边",
	["{npc:11862}, up on the ledge"] = "{npc:11862}，在上方的岩架上",
	["{npc:11862}: {npc:12736} at Zoram'gar, next guide"] = "{npc:11862}：交给佐拉姆加的 {npc:12736}，见下一篇指南",
	["{npc:11864} stands by the bonfire inside Sun Rock: Makaba's news that Kaya is alive is for her."] = "{npc:11864}站在烈日石居内的篝火旁：玛卡巴带来的卡娅还活着的消息正是要告诉她的。",
	["{npc:12296}: use the {item:15826} on them; they roam the plains all around the {area:380}"] = "{npc:12296}：对它们使用{item:15826}；它们在{area:380}周围的平原上游荡",
	["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}，在{npc:3341}正东的树上",
	["{npc:246344} teaches Paladins in {area:1638}. You have no flight path there yet: fly to {area:378}, head west through {zone:1412} and up a lift, and take the flight path from {npc:2995} on the central rise."] = "{npc:246344}在{area:1638}教圣骑士。你还没有到那里的飞行路线：飞到{area:378}，向西穿过{zone:1412}，乘升降梯上去，再从中央高地的{npc:2995}处乘飞行路线。",
	["{npc:262119} and his marines hold the wrecked caravan south of {npc:261366}. The marines are linked: pulling one calls the rest. Pull from the edge and run; they leash short, so you can thin the camp one at a time before tackling the Corporal."] = "{npc:262119}和他的水兵守着{npc:261366}南边被毁的商队。这些水兵会互相联动，拉到一个会引来其余敌人。从边缘引怪后拉开距离，它们脱战距离较短，可以逐个清理营地，再对付下士。",
	["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:3024} and {npc:4721} stand a short walk east of him."] = "双足飞龙管理员{npc:2995}站在中央高台上：如果还没有他的飞行路线，先开通。{npc:3024}和{npc:4721}站在他东边不远处。",
	["{npc:3024}: the {object:667362} grows in {area:464}, by Sun Rock"] = "{npc:3024}：{object:667362}生长在烈日石居旁的{area:464}",
	["{npc:3238}, by this stop"] = "{npc:3238}，在这个站点旁",
	["{npc:3341} waits in a small camp further south, on the road toward {area:359}."] = "{npc:3341}在更南边通往{area:359}的道路旁的一个小营地里等候。",
	["{npc:3341} waits in a small camp further south, on the road toward {area:359}; {npc:14242} sits up in the tree just east of him."] = "{npc:3341}在更南边通往{area:359}的道路旁的一个小营地里等候；{npc:14242}就在他东边的树上。",
	["{npc:3341} walks around {area:1701}: look inside the circle on the map"] = "{npc:3341}在{area:1701}附近巡逻，请在地图标出的圆圈内寻找",
	["{npc:3341} walks the road south toward {area:359}, between about 46,75 and 46,81: if he isn't at the arrow, follow the road until you meet him. {npc:14242} sits up in the tree just east of the road at 47.9,77.5."] = "{npc:3341}沿路向南往{area:359}方向走，大约在 46,75 到 46,81 之间：他不在箭头处，就沿路走直到碰上。{npc:14242}坐在路东边的树上，坐标 47.9,77.5。",
	["{npc:3354} is in the {object:172958}, {npc:5892} in the {object:172957}."] = "{npc:3354}在{object:172958}里，{npc:5892}在{object:172957}里。",
	["{npc:3375} walks around {area:359}: look inside the circle on the map"] = "{npc:3375}在{area:359}附近巡逻，请在地图标出的圆圈内寻找",
	["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "{npc:3389}站在{area:380}正西的科卡尔哨所。",
	["{npc:3391} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:3391}在他建筑的楼上：从里面上楼，箭头分不清楼层。",
	["{npc:3394} stands in the Kolkar camp north-west of {npc:3389}."] = "{npc:3394}站在{npc:3389}西北的科卡尔营地里。",
	["{npc:3395} walks among the Kolkar at the {area:388} south-east of the {area:380}."] = "{npc:3395}在{area:380}东南的{area:388}，在科卡尔半人马中间走动。",
	["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. Hand his head to {npc:3389} on your last {area:380} stop."] = "{npc:3396}率领着{area:387}西岸的科卡尔半人马，位于{npc:3389}南边。最后一次在{area:380}停留时把他的头颅交给{npc:3389}。",
	["{npc:3428}: the eggs are in the {area:390}, later"] = "{npc:3428}：蛋在{area:390}，稍后进行",
	["{npc:3429}, at the top of the tower"] = "{npc:3429}，在塔顶",
	["{npc:3429}. Keep it: Kadrak at the {area:1703}, next guide"] = "{npc:3429}。留着它：交给{area:1703}的卡德拉克，见下一个指南",
	["{npc:3430}, in the cage"] = "{npc:3430}，在笼子里",
	["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{quest:4921}交还后，{npc:3432}会提供{quest:95774}",
	["{npc:3433}, at the north edge of the camp"] = "{npc:3433}，在营地北缘",
	["{npc:3442} stands beside the flight master you land at."] = "{npc:3442}站在你降落处的飞行管理员旁边。",
	["{npc:3442}, beside the wind rider master. Keep it: {quest:1483} is in Stonetalon, later"] = "{npc:3442}，在双足飞龙管理员旁边。留着它：{quest:1483}在石爪山脉，稍后进行",
	["{npc:3442}: {quest:1094}, from {npc:4201}"] = "{npc:3442}：{quest:1094}，来自{npc:4201}",
	["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465}被锁在要塞里。和他交谈开始护送，并紧跟着他：出去的路上会有塞拉摩士兵袭击。他会和你一起走回{area:392}。",
	["{npc:3995}, below ground"] = "{npc:3995}：在地下",
	["{npc:4049}: {npc:4074} and {npc:4073} roam east of {npc:4201}, on the way up"] = "{npc:4049}：{npc:4074}和{npc:4073}在{npc:4201}东边游荡，就在上山的路上",
	["{npc:4128} walks around {area:1156}: look inside the circle on the map"] = "{npc:4128}在{area:1156}附近巡逻，请在地图标出的圆圈内寻找",
	["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197}住在{area:2539}，那处巨魔村庄就在石爪山入口内，位于{npc:3389}往西道路的尽头。",
	["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "{npc:4198}的下一个任务“奥达努斯”在{zone:1440}的联盟一方。跳过。",
	["{npc:4198}, outside the gate"] = "{npc:4198}，在大门外",
	["{npc:4721}: the phial comes from {zone:1440}, next guide"] = "{npc:4721}：药瓶来自{zone:1440}，见下一篇指南",
	["{npc:5878} camps beside the road east of the {area:380}."] = "{npc:5878}在{area:380}东边的路旁扎营。",
	["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "{npc:5899}的小屋在{area:378}南边野猪人水坑上方的山脊上，就在前往{area:359}的路上。",
	["{npc:5899}, just west of {npc:3341}"] = "{npc:5899}，就在{npc:3341}西边",
	["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}：蓝色水袋在{zone:1440}装满，见下一个指南",
	["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}：{area:272}的红色水袋",
	["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901}在{area:392}南边的山上等候，就在你北上的路上。",
	["{npc:5909}, a few steps away"] = "{npc:5909}，就在几步之外",
	["{npc:5911} stands by the flight master. His {npc:268623} (23) is elite: grouping up is advised; the two Encroaching Soldiers are not."] = "{npc:5911}站在飞行管理员旁。他要的{npc:268623}（23级）是精英：建议组队；两个入侵的士兵不是精英。",
	["{npc:5911}, beside the flight master"] = "{npc:5911}，在飞行管理员旁",
	["{npc:5911}: the soldiers and the pillager camp just east of {npc:3341}, on the way south"] = "{npc:5911}：那些士兵和掠夺者营地就在{npc:3341}以东，在往南的路上",
	["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018}站在城市西侧的{object:172961}里。",
	["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018}站在城西侧的{object:172961}。",
	["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}：{zone:1458}的{npc:4606}，见后面第二个指南",
	["{npc:6394}, inside"] = "{npc:6394}，在里面",
	["{object:3646}; below ground"] = "{object:3646}；在地下",
	["{object:3972} poster"] = "{object:3972}告示",
	["{quest:2458}: {npc:7233}, by the {area:382}"] = "{quest:2458}：{npc:7233}，在{area:382}旁",
	["{quest:865}, if still open: Sunscale Scytheclaws prowl among the lions"] = "{quest:865}，如果还没交：阳鳞镰爪龙在狮子中间游荡",
	["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}是一头巨大的鱼龙，在{area:391}外的浅水中游动，位于{npc:3388}东边。",
	["{quest:874} camps on the shore just north of {area:392}'s flight master."] = "{quest:874} 在 {area:392} 飞行管理员北边不远处的海岸扎营。",
	["{quest:882}, a big Sunscale raptor, only comes to a fresh kill: loot a {item:10338} from a zhevra, then use it at the {object:147538} north-west of {area:392}, north of the road to the {area:380}, and be ready when he arrives."] = "{quest:882}是一头巨大的阳鳞迅猛龙，只有新鲜尸体才能引来：从斑马身上拾取{item:10338}，然后在{area:392}西北、通往{area:380}的道路以北的{object:147538}使用它，等他来时做好准备。",
	["{zone:1442}: kill these as you meet them"] = "{zone:1442}：沿途击杀以下目标",
	["{zone:1454} class quests"] = "{zone:1454}职业任务",
	["{zone:1454} flight master"] = "{zone:1454}飞行管理员",
	["{zone:1456} first: two of its elders give quests worked on this guide's and the next guide's walks. Fly to {area:378}; from there it is a walk west into {zone:1412} and north to the bluffs."] = "先去{zone:1456}：那里的两位长者会给出在本篇和下一篇指南路线中完成的任务。飞往{area:378}；从那里向西步行进入{zone:1412}，再向北前往山崖。",
	["{zone:1456} flight master"] = "{zone:1456}飞行管理员",
	["{zone:1456}'s central rise"] = "{zone:1456}的中央高台",
}

G["forever/horde/05-stonetalon-mountains"] = {
	["Ashenvale Bear"] = "灰谷熊",
	["Ashenvale Outrunner"] = "灰谷先驱者",
	["Back north up the road to the {area:431} flight master and fly to {area:1637}."] = "沿路往北回到{area:431}的飞行管理员处，飞往{area:1637}。",
	["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "回到向南的道路。在道路向东转入{area:287}的地方，{npc:2214}在{area:285}等候。",
	["Back out of the inn to the flight master and fly to {area:1637}."] = "从旅店出来回到飞行管理员处，飞往{area:1637}。",
	["Back to the outpost before heading east to Thistlefur."] = "先回前哨站，再向东去蓟皮营地。",
	["Back to {npc:8582}"] = "回到{npc:8582}处",
	["Back west to Zoram'gar. {npc:12757} offers King of the Foulweald now; leave it for the next {area:331} visit at 26, when the walk east passes the Foulweald."] = "向西回到佐拉姆加前哨站。{npc:12757}现在会提供腐林之王；留到26级下次来{area:331}时再做，那时往东走会经过腐林。",
	["Back west to Zoram'gar. {npc:12757} offers King of the Foulweald now; leave it for the next {zone:1440} visit at 26, when the walk east passes the Foulweald."] = "向西返回佐拉姆加。{npc:12757}现在会提供《污林熊怪之王》；留到26级下次来{zone:1440}时再做，届时向东的路线会经过污林熊怪。",
	["Below ground"] = "在地下",
	["Bloodfury Ambusher"] = "血怒伏击者",
	["Bloodfury Harpy"] = "血怒鹰身人",
	["Bloodfury Roguefeather"] = "血怒盗羽者",
	["Bloodfury Slayer"] = "血怒杀戮者",
	["Cenarion Botanist"] = "塞纳里奥植物学家",
	["Dalaran Watcher"] = "达拉然守望者",
	["Dalaran Wizard"] = "达拉然巫师",
	["Daughter of Cenarius"] = "塞纳留斯之女",
	["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177790}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "沿道路穿过银松森林前往{area:228}：从飞艇塔出发的，向南穿过提瑞斯法；从{object:177790}出发的，从海岸向东南走到道路上。{npc:2121}和{npc:1937}站在墓穴入口旁。",
	["Druid trainer"] = "德鲁伊训练师",
	["East of Ziz, the Venture Company is clear-cutting {area:461}; one of the Operators carries the blueprints. {npc:4276} mines in the small mine on the east side: stay with him while he mines, Venture Co. thugs come for him.\nCareful: The kobolds arrive in waves. The first wave is melee fighters, and the second adds casters to the mix. Regular mobs in the mine respawn quickly and can join the fight while the waves are coming. A group is recommended."] = "在兹兹以东，风险投资公司正在砍伐{area:461}；其中一名操作员携带图纸。{npc:4276}在东边的小矿洞里挖矿：他挖矿时你留在他身边，风险投资公司的打手会来找他。\n注意：狗头人成波来袭。第一波是近战，第二波会混入施法者。矿洞里的普通怪物刷新很快，会在波次之间加入战斗。建议组队。",
	["East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.\nCareful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs."] = "佐拉姆加以东，蓟皮熊怪遍布村庄及其据点周围的山丘。\n注意：萨满祭司的生命值降到15%或以下时会逃跑求援，可能会引来更多熊怪。",
	["Every Wrathtail naga along the strand north of the outpost drops heads."] = "哨站北边海滩上的每个怒尾纳迦都会掉落头颅。",
	["Fly to {area:1637}"] = "飞往{area:1637}",
	["Fly to {area:431} and head south down the road to the {area:1703}."] = "飞到{area:431}，沿路向南前往{area:1703}。",
	["Fly to {area:431}: {npc:12837} waits in the inn for news of Ruul."] = "飞往{area:431}：{npc:12837}在旅店等候鲁尔的消息。",
	["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "沿道路向北朝{area:467}前进。巨角鹿沿途吃草；腐蚀兽、夜行虎和灵龙在山峰下方的树林中游荡，塞纳里奥德鲁伊占据那里的树林。",
	["Follow the road west to {area:460}."] = "沿道路向西前往{area:460}。",
	["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {area:331}."] = "从塞雷思的营地出发，向东北穿过{zone:1413}，到十字路口北边的道路。{npc:8582}站在道路进入{area:331}处的{area:1703}哨塔上。",
	["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}."] = "从希雷斯的营地向东北穿过{zone:1413}，到达十字路口北边的道路；从费苏勒的高塔过来的潜行者向西前往那条道路。道路进入{zone:1440}处有{area:1703}，{npc:8582}就站在那里的瞭望塔上。",
	["From the zeppelin towers, run south into Silverpine and west past the {area:240} to the coast: the {object:177790} lies at the bottom of very deep water there, beside an air fissure where you can breathe. Watch your breath on the way down. It holds the {item:15882} for Trial of the Sea Lion. Then on to the {area:228}."] = "从飞艇塔向南跑进银松森林，向西经过{area:240}到海岸：{object:177790}在那里的极深水底，旁边有一道能呼吸的气缝。下潜时留意呼吸。里面装着海狮试炼要的{item:15882}。然后前往{area:228}。",
	["From the zeppelin towers, run south through Tirisfal into Silverpine and down the road past the {area:228} and Pyrewood. The Ravenclaw undead haunt the ruins of {area:231} east of the road in the south-east of the forest; a {npc:1973} drops the {item:271343} that leads to the {object:645153}."] = "从飞艇塔向南跑，穿过提瑞斯法进入银松森林，沿路经过{area:228}和焚木村。鸦爪亡灵出没在森林东南、道路东侧的{area:231}废墟；某只{npc:1973}会掉落{item:271343}，可引向{object:645153}。",
	["From the zeppelin towers, run south through Tirisfal into Silverpine and down the road to the {area:228}. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "从飞艇塔向南跑，穿过提瑞斯法进入银松森林，沿路到{area:228}。{npc:2121}和{npc:1937}站在地穴入口旁。",
	["From the {area:380} follow the road north. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {area:331}. Open the {item:16783} he gives you."] = "从{area:380}沿路向北。{npc:8582}站在道路进入{area:331}处的{area:1703}哨塔上。打开他给你的{item:16783}。",
	["Gaea Dirt Mounds"] = "盖亚土堆",
	["Gaea Seeds"] = "盖亚之种",
	["Head back down the {area:1076} to {area:2539}."] = "沿{area:1076}往回走到{area:2539}。",
	["Head south to the {area:380}, then west along the road out of the {area:17} into Stonetalon. The troll village of {area:2539} sits at the entrance of the canyon."] = "向南到{area:380}，然后沿路向西走出{area:17}进入石爪山。巨魔村庄{area:2539}就在峡谷入口处。",
	["Head west along the main road across {area:331}, past {area:415} (Alliance: keep to the road), to the coast. {area:2897} is on the {area:414} in the north-west. Its other quests are for the next visit, at 27."] = "沿主路向西穿过{area:331}，经过{area:415}（联盟：贴着路走），一直到海岸。{area:2897}在西北的{area:414}上。它的其他任务留到下次27级时再来。",
	["Head west along the main road across {area:331}, past {area:415} (Alliance: keep to the road), to the coast. {area:2897} is on the {area:414} in the north-west: {npc:12719}, {npc:12721} and {npc:12757} stand around it, the {npc:12863} beside the flight master. Its other quests are for the next visit, at 26."] = "沿主路向西穿过{area:331}，经过{area:415}（联盟：贴着路走），一直到海岸。{area:2897}在西北的{area:414}上：{npc:12719}、{npc:12721}和{npc:12757}站在它周围，{npc:12863}在飞行管理员旁边。它的其他任务留到下次26级时再来。",
	["Head west along the main road across {zone:1440}, past {area:415} (Alliance: keep to the road), to the coast. {area:2897} is on the {area:414} in the north-west: {npc:12719}, {npc:12721} and {npc:12757} stand around it, the {npc:12863} beside the flight master. Its other quests are for the next visit, at 26."] = "沿主路向西穿过{zone:1440}，经过{area:415}（联盟领地：沿道路走），抵达海岸。{area:2897}在西北面的{area:414}：{npc:12719}、{npc:12721}和{npc:12757}站在周围，{npc:12863}在飞行管理员旁。这里的其他任务留到26级下次来时再做。",
	["If you did {quest:2478} with a group, {npc:3401} in the {object:172960} takes it now."] = "如果已经组队完成{quest:2478}，现在可交给{object:172960}的{npc:3401}。",
	["In the ruins of {quest:516}: The Ravenclaw undead haunt the ruins of {quest:516} east of the road in the south-east of the forest; a {npc:1973} drops the {item:271343} that leads to the {object:645153}."] = "在{quest:516}的废墟里：鸦爪亡灵出没在森林东南、道路东侧的{quest:516}废墟；某只{npc:1973}会掉落{item:271343}，可引向{object:645153}。",
	["Inside the hold, Troll Chests lie along the tunnels. {npc:12818} is held deep inside: free him and protect him all the way out, then he runs home to {area:428}.\nCareful: Two scripted ambushes occur, each made up of three Thistlefurs (a Shaman, a Pathfinder and an Avenger, Ursa or Den Watcher): the first when you come back to the tunnel's fork inside the cave, the second just beyond the gate where {npc:3987} roams."] = "据点内部的隧道沿线有巨魔的箱子。{npc:12818}被囚禁在深处：释放他并一路保护他离开，之后他会跑回{area:428}的家。\n小心：会触发两次固定伏击，每次由3名蓟皮熊怪组成（一名萨满祭司、一名探路者，以及一名复仇者、巨熊战士或巢穴守卫）：第一处在洞内返回隧道岔口时，第二处在越过{npc:3987}游荡的大门后不远处。",
	["Into {area:287}"] = "进入{area:287}",
	["Into {zone:1440}"] = "进入{zone:1440}",
	["Keep north on the road. The {npc:12862} waits at the Warsong lumber camp, south of Splintertree."] = "继续沿道路向北。{npc:12862}在碎木岗哨南边的战歌伐木营地等候。",
	["Learn the flight path here while you pick up the outpost's quests."] = "在这里学会飞行路径，同时接取哨站的任务。",
	["Naga brazier"] = "纳迦火盆",
	["Naga heads"] = "纳迦头颅",
	["On the way north from Seereth's camp, keep east of the road to the Venture Co. tower north of the {area:382}. Before you go near Fizzule, use {item:8051} to fire two flares, then target him and /salute: he attacks anyone who comes in without signalling first."] = "从希雷斯的营地向北走时，沿道路东侧前往{area:382}北边的风险投资公司高塔。靠近费苏勒之前，先用{item:8051}发射两枚信号弹，再选中他并使用/salute：未先发出信号就靠近的人都会遭到他的攻击。",
	["On the way west, {npc:267214} is stuck in a ravine south of the main road, south-east of {area:415}. Shadowhorn Stags and Ashenvale Bears roam the woods all around it."] = "向西行进途中，{npc:267214} 被困在主路南侧、{area:415} 东南方的一条峡谷里。周围林地中到处都有黑角鹿和灰谷熊。",
	["Out of the inn and south down the road to the lumber camp: {npc:12867} stands there. The night elf Outrunners (23-24) stalk the woods south-east of it; they stealth, so watch for them."] = "从旅店出来，沿路向南走到伐木营地：{npc:12867}就在那里。暗夜精灵灰谷先驱者（23-24级）在营地东南的树林里潜伏；他们会潜行，所以留意他们。",
	["Out of the inn to the {area:431} flight master and fly to {area:1637}."] = "走出旅店，去{area:431}的飞行管理员处，飞往{area:1637}。",
	["Paladin trainer"] = "圣骑士训练师",
	["Ravenclaw Drudger"] = "鸦爪苦工",
	["Ravenclaw Guardian"] = "鸦爪守卫",
	["Shadowhorn Stag"] = "影角雄鹿",
	["Son of Cenarius"] = "塞纳留斯之子",
	["South down the road past Pyrewood: Dalaran Watchers and Wizards patrol the roads around {area:233}, and south-west of the town the Ravenclaw Drudgers and Guardians haunt the ruins of {quest:516} in the south-east of the forest."] = "沿路向南经过焚木村：达拉然卫士和达拉然巫师在{area:233}周围的道路上巡逻；镇子西南方、森林东南部的{quest:516}废墟中，鸦爪苦工和鸦爪守护者出没。",
	["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "烈日石居西南方是烧焦的{area:465}。把{item:16205}种在谷底的土堆里；火元素掉落{item:16312}。血怒鹰身人和血怒伏击者在北侧筑巢，血怒杀戮者和血怒游荡者在南侧。",
	["Sputtervalve in {area:392}: the next guide passes there"] = "{area:392}的斯布特瓦夫：下一份指南会经过那里",
	["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "在四分钟内操控{npc:267214}的{npc:271181}离开峡谷到达主路；如果引导中断，再找{npc:267214}一次。",
	["Summoned Succubus"] = "召唤的魅魔",
	["The Gaea Seeds lie in the grass around the southern shore of {area:464}, north of Sun Rock.\nCareful: Pridewings around the lake can aggro as a linked group."] = "盖亚种子躺在{area:464}南岸周围的草丛里，就在日岩以北。\n注意：湖边的傲翼会作为关联群一起仇恨。",
	["The Ravenclaw undead haunt the ruins of {quest:516}, east of the road in the south-east of the forest; a {npc:1973} drops the {item:271343} that leads to the {object:645153}.\nAn elite spirit (20) often stands beside the {object:645153}: pull the Ravenclaws away from the stone before you fight them."] = "渡鸦爪亡灵在森林东南、道路以东的{quest:516}废墟出没；一只{npc:1973}会掉{item:271343}，它能引向{object:645153}。\n一个精英幽灵（20级）常站在{object:645153}旁：和渡鸦爪开打之前先把它们从石头旁拉开。",
	["The quest hands you a {item:210713}: use it beside the {object:645153} to offer your blood, then kill the elite spirit that answers.\n{quest:95883} is elite: grouping up is advised."] = "任务会给你一个{item:210713}：在{object:645153}旁使用它献上你的血，然后杀掉应召而来的精英幽灵。\n{quest:95883}是精英：建议组队。",
	["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "道路向北攀升，即{area:1076}。{quest:1483}的小屋在道路向东分岔通往{area:461}的地方。",
	["The road east to {area:285}"] = "向东通往{area:285}的道路",
	["The road north to {area:431}"] = "向北通往{area:431}的道路",
	["The {npc:12864} patrols the road east of {area:428} toward the {area:430}."] = "{npc:12864}在{area:428}东边朝{area:430}方向的道路上巡逻。",
	["Thistlefur Avenger"] = "蓟皮复仇者",
	["Thistlefur Hold"] = "蓟皮熊怪的巢穴",
	["Thistlefur Shaman"] = "蓟皮萨满",
	["Tortured Soul"] = "受折磨的灵魂",
	["Use the {npc:212753} at the {object:645153} for a willing sacrifice and kill the {npc:212753} that answers. {quest:95883} is elite: grouping up is advised."] = "在{object:645153}使用{npc:212753}作为自愿的祭品，杀死回应的{npc:212753}。{quest:95883}是精英任务：建议组队。",
	["Zeppelin to {zone:1458}"] = "乘飞艇前往{zone:1458}",
	["the {object:645153} offers {quest:95883} once the {item:271343} is in; below ground"] = "交还{item:271343}后，{object:645153}会提供{quest:95883}；位于地下",
	["{area:380} flight master"] = "{area:380}的飞行管理员",
	["{area:431} flight master"] = "{area:431}飞行管理员",
	["{area:431} is just north up the road."] = "{area:431}就在道路北边不远处。",
	["{area:431} is just north up the road. Coming in from the south, the flight master and {npc:12696}'s hunt board at {area:428} come first, then the vendors."] = "{area:431}就在沿路往北不远处。从南边进来时，先看到飞行管理员和{area:428}的{npc:12696}狩猎告示板，然后是商人。",
	["{area:431} is just north up the road. Coming in from the south, the flight master and {npc:12696}'s hunt board at {area:428} come first, then the vendors. {npc:12867} at the lumber camp offers Ashenvale Outrunners: leave it for the next {zone:1440} visit, at 26."] = "沿路向北不远就是{area:431}。从南边进入时，先经过飞行管理员和{area:428}的{npc:12696}狩猎告示板，再到商人处。伐木营地的{npc:12867}提供“灰谷先驱者”：留到下次26级来{zone:1440}时再做。",
	["{area:431} is just north up the road. Coming in from the south, the flight master and {npc:12696}'s hunt board at {area:428} come first, then the vendors. {npc:12867} at the lumber camp offers {quest:6503}: leave it for the way back, at 22."] = "{area:431}就在沿路往北不远处。从南边进来时，先看到飞行管理员和{area:428}的{npc:12696}狩猎告示板，然后是商人。伐木营地的{npc:12867}会提供{quest:6503}：留到22级回程时再做。",
	["{area:465}: kill these as you meet them"] = "{area:465}：遇到就杀",
	["{item:15882}, from the {object:177790}"] = "{item:15882}，来自{object:177790}",
	["{item:16746}, from the {item:16783}"] = "{item:16746}，从{item:16783}中取得",
	["{item:210713}, beside the {object:645153}: summons the elite spirit"] = "{item:210713}，在{object:645153}旁：召唤精英幽灵",
	["{item:271343}, from a {npc:1973}"] = "{item:271343}，来自{npc:1973}",
	["{item:271350}, from the Tortured Souls among the ruins; below ground"] = "{item:271350}，从废墟地下的被折磨的灵魂身上获得",
	["{item:277936}, from any Bloodfury harpy"] = "{item:277936}，来自任何血怒鹰身人",
	["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}：从血怒鹰身人获取闪光的太阳石",
	["{npc:11860}: Grish is at the {area:1718}, in the next guide"] = "{npc:11860}：瑞什在{area:1718}，下一份指南",
	["{npc:11861}, beside {npc:11862}"] = "{npc:11861}，在{npc:11862}旁边",
	["{npc:11862}, up on the ledge"] = "{npc:11862}，在上方的岩架上",
	["{npc:12696} stands at {area:428}, the Warsong camp just north-east of Splintertree, beside the hunt board.\nNorth up the road to {area:431} and {area:428} beside it."] = "{npc:12696}站在{area:428}，即碎木岗哨东北的战歌营地，就在狩猎公告板旁。\n沿路向北到{area:431}，{area:428}就在它旁边。",
	["{npc:12696}'s hunt targets (Ursangous, Shadumbra, Sharptalon) are for the next {area:331} visit, at 26."] = "{npc:12696}的狩猎目标（乌萨古斯、沙达姆布拉、锐爪）留到下次26级来{area:331}时再做。",
	["{npc:12696}'s hunt targets (Ursangous, Shadumbra, Sharptalon) are for the next {area:331} visit, at 27."] = "{npc:12696}的狩猎目标（乌萨古斯、沙达姆布拉、锐爪）留到下次27级来{area:331}时再做。",
	["{npc:12696}'s hunt targets (Ursangous, Shadumbra, Sharptalon) are for the next {zone:1440} visit, at 26."] = "{npc:12696}的狩猎目标（乌萨苟斯、萨杜布拉、沙普塔隆）留到26级下次来{zone:1440}时再做。",
	["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead; the Wrathtail naga drop the heads {npc:12719} wants."] = "{npc:12717}沿海滩向北走到一座纳迦火盆。熄灭火盆，再保护他抵挡一波波纳迦，直到沃尔沙被击杀；怒尾纳迦掉落{npc:12719}要的头颅。",
	["{npc:12717}: take it last, his escort starts at once"] = "{npc:12717}：最后再接，他的护送任务会立即开始",
	["{npc:12721}: the troll charms are in Thistlefur Hold, east of the outpost"] = "{npc:12721}：巨魔符咒在前哨站东边的蓟皮熊怪的巢穴",
	["{npc:12736} at Zoram'gar, at 27"] = "佐拉姆加的{npc:12736}，27级时",
	["{npc:12818}, below ground"] = "{npc:12818}：在地下",
	["{npc:12837}, inside the inn"] = "{npc:12837}，在旅店里",
	["{npc:12867} stands at the lumber camp. The night elf Outrunners stalk the woods south-east of it; they stealth, so watch for them."] = "{npc:12867}站在伐木营地。暗夜精灵灰谷先驱者在营地东南的树林里潜伏；他们会潜行，所以留意他们。",
	["{npc:1937}: Lydon in {area:272}, next guide"] = "{npc:1937}：{area:272}的林度恩，下一份指南再做",
	["{npc:2121}: {quest:516}, south-east of {area:233}"] = "{npc:2121}：{quest:516}，在{area:233}东南方",
	["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}：{area:272}的达萨利亚",
	["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{area:272}的{npc:2391}教授毒药：留着它",
	["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152}在{area:159}训练圣骑士，从飞艇塔沿道路向北步行不远即到。之后沿同一条路回来，前往银松森林。",
	["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344}，在{zone:1456}；{zone:1454}没有圣骑士训练师",
	["{npc:271181}, on the road"] = "{npc:271181}，在路上",
	["{npc:3034} in {zone:1412}; {zone:1454} has no druid trainer"] = "{npc:3034} 在 {zone:1412}；{zone:1454} 没有德鲁伊训练师",
	["{npc:3995}, below ground"] = "{npc:3995}，在地下",
	["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {area:331}. Skip it."] = "{npc:4198}的后续任务“奥达努斯”在{area:331}的联盟一侧。跳过它。",
	["{npc:4198}, outside the gate"] = "{npc:4198}，在大门外",
	["{npc:4201}, inside"] = "{npc:4201}，在里面",
	["{npc:4276}, below ground"] = "{npc:4276}，在地下",
	["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875}站在{object:172960}。在那里的召唤法阵上使用{item:6626}，击败魅魔来束缚她。",
	["{npc:6389} stands just west of the crypt entrance: hand him {item:16210} from the {zone:1458}."] = "{npc:6389}站在墓穴入口西边不远处：把从{zone:1458}带来的{item:16210}交给他。",
	["{quest:1483}, inside"] = "{quest:1483}，在里面",
	["{quest:2478} is for level 23 or more: the tower's drones are 25 and Gallywix a 23 elite. Do it when you can, with a group, from the Class guide Poisons (Horde)."] = "{quest:2478}适合23级及以上：塔内的苦工是25级，加里维克斯是23级精英。等有能力时组队，通过职业指南《制毒（部落）》完成。",
	["{zone:1421}: kill these as you meet them"] = "{zone:1421}：沿途遇到就击杀",
	["{zone:1442}: kill these as you meet them"] = "{zone:1442}：遇到就杀",
}

G["forever/horde/06-hillsbrad-foothills"] = {
	["After returning Mission: Possible But Not Probable to Shenthul, bring {quest:2479} to {npc:2391} in {area:272}. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill."] = "向申苏尔交付“不可能完成的任务”后，带着“{quest:2479}”来{area:272}找{npc:2391}。留在他身边，等制药目标完成后再交后续任务，学会毒药。即使赞吉尔之触已经被解除，也要完成这一步；单纯解掉负面效果不会学会毒药。",
	["Back down to Masoj on the hillside above {area:290}."] = "下山回到{area:290}上方山坡上的马索吉那里。",
	["Back to the Crossroads"] = "返回十字路口",
	["Back to {area:272}"] = "返回{area:272}",
	["Bears, creepers and lions"] = "熊、食苔蛛和山地狮",
	["Blacksmith Verringtan"] = "铁匠维林坦",
	["Careful: When one lion is attacked, nearby lions come to its aid, and the Vicious Black Bears sharing those fields can also join the fight."] = "小心：攻击一只狮子时，附近的狮子会前来支援，同一片田野上的凶猛黑熊也可能加入战斗。",
	["Cast {spell:18960}. Join the two pendant halves at the {area:2362}, on the north-west shore of the lake, before you see {npc:11802} in {area:2361}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}。去见{area:2361}的{npc:11802}之前，先在湖西北岸的{area:2362}把两半坠饰合起来。{npc:11802}在他那栋楼的楼上：从里面上楼，箭头分不清楼层。",
	["Citizen Wilkes"] = "公民威尔克斯",
	["Clerk Horrace Whitesteed"] = "书记员霍勒斯·怀特斯蒂德",
	["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings. Their locks need keys: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks.\nFrom {area:272} go south-east into the hills on the way to {area:275}. Rogues and Watchmen hold the camps along the way."] = "德鲁尔和{npc:2238}被锁在{area:275}庭院的建筑内。开锁需要钥匙：{npc:2427}携带{item:3467}，{npc:2428}携带{item:3499}，两人都在城堡里。击杀他们，然后打开两处锁。\n从{area:272}向东南进入山丘，朝{area:275}走。沿途营地由潜行者和卫兵占据。",
	["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings; open both locks.\nFrom {area:272} go south-east into the hills on the way to {area:275}. Rogues and Watchmen hold the camps along the way."] = "德鲁尔和{npc:2238}被锁在{area:275}的庭院建筑里，打开两把锁。\n从{area:272}向东南进入丘陵，前往{area:275}。沿途营地由盗贼和看守把守。",
	["Drull's ball and chain"] = "德鲁尔的镣铐",
	["East along the foothills, then down into {area:272}."] = "沿山脚向东，再下到 {area:272}。",
	["Farmer Getz"] = "农夫盖兹",
	["Farmer Kalaba"] = "农夫卡拉巴",
	["Farmer Ray"] = "农夫雷恩",
	["Fill the {item:7768} at the {object:107045} beside the inn"] = "在旅店旁的{object:107045}装满{item:7768}",
	["Fly on from {npc:2226}, the bat handler just east of the crypt, to the {area:1497}."] = "从墓穴东边不远处的蝙蝠管理员{npc:2226}继续飞往{area:1497}。",
	["Fly to the {area:1497}"] = "飞往{area:1497}",
	["Fly to {area:392}"] = "飞往{area:392}",
	["Fly to {area:392}. {quest:874} camps on the shore north of {area:392}."] = "飞往{area:392}。{quest:874}在{area:392}以北的湖岸上扎营。",
	["Follow the road east along the river, then north-east up into the hills to {area:272}."] = "沿河沿路向东，再向东北上山前往{area:272}。",
	["Follow the road south to the dwarf dig site at {area:359}. {npc:3421} hides at the south edge of the dig; {object:3646} sits at the bottom of the excavation."] = "沿道路向南前往{area:359}的矮人挖掘场。{npc:3421}躲在挖掘场南缘；{object:3646}在挖掘坑底部。",
	["Foreman Bonds"] = "工头邦兹",
	["From {area:287} town climb the mountain to the north, right up to its top on the Alterac border: the western vial goes there, not on the lower slope."] = "从{area:287}镇向北爬山，一直爬到奥特兰克边界上的山顶：西边那瓶要放那里，不是下面半山腰。",
	["From {area:287} town go north into the foothills of Alterac: the western vial goes on the hilltop just past the border."] = "从{area:287}镇向北进入奥特兰克的山麓：西边那瓶药剂放在刚过边界的山顶上。",
	["From {zone:1454} (zeppelin from the towers outside the {zone:1458}) fly to {area:378}."] = "从{zone:1454}（在{zone:1458}外的塔上乘飞艇）飞往{area:378}。",
	["Head east to the {area:380} and fly to {zone:1454}. Take the zeppelin from the towers outside {zone:1454} to {area:85}; the {zone:1458} lies below the {area:153}. The bat handler is in the {object:36078}."] = "向东前往{area:380}，飞往{zone:1454}。从{zone:1454}城外的塔楼乘飞艇到{area:85}；{zone:1458}位于{area:153}下方。蝙蝠管理员在{object:36078}。",
	["Hillsbrad Apprentice Blacksmith"] = "希尔斯布莱德见习铁匠",
	["Hillsbrad Councilman"] = "希尔斯布莱德议员",
	["Hillsbrad Farmer"] = "希尔斯布莱德农夫",
	["Hillsbrad Farmhand"] = "希尔斯布莱德雇农",
	["Hillsbrad Miner"] = "希尔斯布莱德矿工",
	["Hillsbrad Peasant"] = "希尔斯布莱德农民",
	["Inside"] = "在里面",
	["Inside {area:288}"] = "在{area:288}里面",
	["Just south of Masoj, the {item:3502} grow on the hillsides above the river."] = "在玛索吉南边不远处，{item:3502}长在河上方的山坡上。",
	["Keep it: the {area:287} coast, later on the route"] = "留着它：{area:287}海岸，路线后面会去",
	["Lady Sylvanas Windrunner"] = "希尔瓦娜斯·风行者女士",
	["Magistrate Burnside"] = "行政官伯恩赛德",
	["Masoj hides on the hillside above {area:290}, south of Durnholde, on the way down to the blossoms."] = "Masoj躲在{area:290}上方的山坡上，位于敦霍尔德城堡南边，就在下去采花的路上。",
	["Masoj hides on the hillside above {area:290}, south-west of Durnholde, on the way down to the blossoms."] = "亡灵哨兵玛索吉躲在{area:290}上方的山坡上，位于敦霍尔德城堡西南边，就在下去采花的路上。",
	["Masoj wants an Apothecary Vial placed on three peaks. The southern one is the hilltop above {area:290}, just south of him: use a vial at the top."] = "马索伊要你把药剂瓶放在三座山峰上。南边那座是{area:290}上方的山顶，就在他南面：在顶上使用一瓶药剂。",
	["Masoj wants an Apothecary Vial placed on three peaks. The southern one is the hilltop above {area:290}, south-east of the blossoms: use a vial at the top."] = "玛索吉要你在三座山峰上各放一个药剂师之瓶。南边那座是{area:290}上方的山顶，位于花丛东南边：在山顶使用药瓶。",
	["Miner Hackett"] = "矿工哈克特",
	["Poison chain unfinished? Resume your current stage in the Class guide Poisons (Horde); completed quests do not need restarting. Arrange a group for Gallywix, finish the Hinott follow-up, then return to this leveling guide."] = "毒药任务线尚未完成的话，可从职业指南“毒药（部落）”中的当前阶段继续，无需重做已交的任务。找队伍处理加里维克斯并完成希诺特的后续，再回当前练级指南。",
	["South-west of Bael Modan, {npc:12576} waits at the top of the {area:1718}."] = "在巴尔莫丹西南，{npc:12576}在{area:1718}顶端等候。",
	["South-west of Durnholde, the {item:3502} grow on the hillsides above the river."] = "在敦霍尔德城堡西南，{item:3502}长在河上方的山坡上。",
	["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "与{object:36126}里的{npc:10181}交谈：{quest:93739}",
	["Syndicate Rogue"] = "辛迪加盗贼",
	["Syndicate Watchman"] = "辛迪加看守",
	["Take the zeppelin from the towers outside the {zone:1458} to {zone:1454} and train before you fly on."] = "在{zone:1458}外的塔上乘飞艇前往{zone:1454}，继续飞行前先训练。",
	["Take {quest:31} from {npc:11802}, who stands upstairs in his building. Then {npc:11798} in {area:2361} flies druids to {area:1638}: {npc:3033} is on {area:1639}."] = "从楼上的{npc:11802}处接{quest:31}。然后{area:2361}的{npc:11798}会把德鲁伊飞到{area:1638}：{npc:3033}在{area:1639}。",
	["Talk to {npc:10181}"] = "与{npc:10181}交谈",
	["The Peasants work the fields south of the farmhouses. Every {area:287} human drops skulls; the Peasants drop them most often.\nCareful: A fleeing peasant that reaches the town hall can bring back many adds, including {area:287} footmen; snares, roots or similar effects keep them from escaping."] = "农夫在农舍南边的田地里干活。{area:287} 的所有人类都会掉落头骨，其中农夫掉落最频繁。\n注意：逃跑的农夫如果跑到市政厅，可能会带回许多敌人，包括 {area:287} 的步兵；减速、定身等效果能阻止他们逃跑。",
	["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "{area:287}镇东边的农场。{npc:232}在北边农舍旁的田里干活，{npc:2403}在更东南的那片田；到处都是希尔斯布莱德雇农和希尔斯布莱德农夫。{npc:2451}照料农场南边的田地。",
	["The middle of {zone:1454}"] = "{zone:1454}中部",
	["The northern peak"] = "北边的山峰",
	["The northern peak rises south-east of {area:272}, on the way down towards Durnholde."] = "北边的山峰位于{area:272}东南，在下山前往敦霍尔德城堡的路上。",
	["The smithy"] = "铁匠铺",
	["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "铁匠铺在{area:287}镇中央。{npc:2404}和他的希尔斯布莱德见习铁匠在熔炉旁干活；{object:1736}堆在旁边。{npc:2449}在它北边的街上走动。",
	["The southern peak"] = "南边的山峰",
	["The town hall is on the west side of {area:287}. {npc:2335} (30) and {npc:2448} are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town."] = "市政厅在{area:287}西侧。{npc:2335}（30级）和{npc:2448}在里面，旁边是希尔斯布莱德城镇文档；希尔斯布莱德宣言就贴在它旁边。希尔斯布莱德议员在镇上走动。",
	["The western peak"] = "西边的山峰",
	["The {area:1718}"] = "{area:1718}",
	["The {area:288} lies south of {area:287} town. Miners work the tunnels; {npc:2305} (30) and {npc:2450} (29) are deep inside."] = "{area:288}在{area:287}镇南边。希尔斯布莱德矿工在坑道里干活；{npc:2305}（30级）和{npc:2450}（29级）在深处。",
	["The {object:556670} poster by the inn"] = "旅店旁的{object:556670}告示",
	["The {quest:567} poster: Kalaba with the peasants, Wilkes at the smithy; the clerk and the miner on the visit at about 30; inside"] = "{quest:567}告示：卡拉巴在农民中间，维尔克斯在铁匠铺；书记员和矿工留到约30级再来时处理；告示在室内",
	["The {quest:567} poster: its targets come up along the way; inside"] = "{quest:567}告示：目标在沿途出现；在里面",
	["To the {zone:1458}"] = "前往{zone:1458}",
	["Town hall"] = "市政厅",
	["Train before you fly on: the next guide flies from here to the Crossroads."] = "继续飞行前先训练：下一份指南会从这里飞往十字路口。",
	["Train with {npc:3033}. Before you fly on, {npc:3024} and {npc:4721}, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts."] = "向{npc:3033}训练。继续飞行前，风骑士管理员东边不远处的{npc:3024}和{npc:4721}会给你两个任务，在接下来几份指南的路上完成；然后飞往十字路口，下一份指南从那里开始。",
	["Walk back up to {area:272} and fly to the {area:228}: {npc:2121} stands by the crypt entrance."] = "走回上方的{area:272}，飞往{area:228}：{npc:2121}站在墓穴入口旁。",
	["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "在塔伦米尔西边，{npc:2351}、{npc:2350}和{npc:2384}在通往农场的山丘上游荡。食苔蛛很少掉落{item:3477}；你只需要一个。",
	["While you're here: learn Polearms from {npc:11870} ({object:36070}, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "顺路提示：向{npc:11870}学习长柄武器（{object:36070}，1 金）；猎人的近战武器主要用于提供属性，双手武器的属性通常更多。",
	["While you're here: learn Polearms from {npc:11870} ({object:36070}, 1 gold); two-handers level a Warrior fastest."] = "顺路提示：向{npc:11870}学习长柄武器（{object:36070}，1 金）；战士使用双手武器升级最快。",
	["While you're here: learn Swords from {npc:11870} ({object:36070}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "顺便：在{npc:11870}处学习剑（{object:36070}，10银币）；主手持剑能让潜行者稳定升级。",
	["While you're here: learn {spell:202} from {npc:11870} ({object:36070}, 10 silver); two-handers level a Paladin fastest."] = "趁在这里：向 {npc:11870} 学习 {spell:202}（{object:36070}，10 银币）；圣骑士用双手武器升级最快。",
	["While you're here: learn {spell:202} from {npc:11870} ({object:36070}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向 {npc:11870} 学习 {spell:202}（{object:36070}，10 银币）；战士用双手武器升级最快。",
	["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
	["{area:272} flight master"] = "{area:272}的飞行管理员",
	["{area:272} is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square."] = "{area:272}是本指南的据点：炉石会两次把你带回这里。所有人都站在镇广场周围。",
	["{area:275}: kill these as you meet them"] = "{area:275}：沿途遇到就击杀",
	["{area:286}: kill these as you meet them"] = "{area:286}：沿途遇到就击杀",
	["{area:378} flight master"] = "{area:378}飞行管理员",
	["{item:15885}: use a half at the {area:2362}"] = "{item:15885}：在{area:2362}使用其中一半",
	["{item:3692}: the Peasants in the fields"] = "{item:3692}：田里的希尔斯布莱德农民",
	["{npc:10079} stands at the top of the {area:1718}, beside {npc:12576}."] = "{npc:10079}站在{area:1718}顶端，{npc:12576}旁边。",
	["{npc:10079}, at the top of the lift"] = "{npc:10079}，在升降梯顶端",
	["{npc:11798} in {area:2361} flies druids there"] = "{area:2361}的{npc:11798}载德鲁伊飞往那里",
	["{npc:2055}, in the Apothecarium"] = "{npc:2055}，在炼金房",
	["{npc:2055}, in the {zone:1458}"] = "{npc:2055}，在{zone:1458}",
	["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215}：给{npc:270438}的命令，在前往敦霍尔德城堡的路上",
	["{npc:2216}, inside"] = "{npc:2216}：在屋内",
	["{npc:2216}, inside: the {item:3502} grow south-west of Durnholde, on the walk there"] = "室内的{npc:2216}：{item:3502}长在敦霍尔德西南方，前往那里时顺路采集",
	["{npc:2229}, inside"] = "{npc:2229}：在屋内",
	["{npc:2230}, next to Lydon; inside"] = "{npc:2230}，在药剂师林度恩旁边；位于室内",
	["{npc:2238}'s ball and chain"] = "{npc:2238}的镣铐",
	["{npc:2261} walks around here: look inside the circle on the map"] = "{npc:2261}在附近巡逻，请在地图标示的圆圈内寻找",
	["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274}是{npc:232}的狗，在{area:286}北边的农舍旁。",
	["{npc:2388}: the last guide binds here, so this usually ticks at once"] = "{npc:2388}：上一份指南在这里绑定炉石，所以这一步通常会立即完成",
	["{npc:2391}: Poisons"] = "{npc:2391}：毒药",
	["{npc:2451} walks around {area:286}: look inside the circle on the map"] = "{npc:2451}在{area:286}附近巡逻，请在地图标出的圆圈内寻找",
	["{npc:270438}, once {quest:98094} is in"] = "{npc:270438}，接到{quest:98094}后",
	["{npc:3024}: {quest:97538}, the Mirkweed in {area:464} by Sun Rock"] = "{npc:3024}：{quest:97538}，在烈日石居旁的{area:464}采集暗色草",
	["{npc:3442}, by the docks in {area:392}"] = "{npc:3442}，在{area:392}的码头旁",
	["{npc:4606} stands in the {object:36070}."] = "{npc:4606}站在{object:36070}。",
	["{npc:4721}: {quest:1195}, the phial from {zone:1440}'s Laughing Sisters"] = "{npc:4721}：{quest:1195}，从{zone:1440}的欢笑姐妹身上获得小瓶",
	["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "{npc:5899}的小屋在{area:378}南边野猪人水坑上方的山脊上，就在前往{area:359}的路上。",
	["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}：蓝色水袋在{zone:1440}装满，见下一个指南",
	["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}：{area:272}的红色水袋",
	["{object:1761}, inside"] = "{object:1761}，在里面",
	["{object:3646}; below ground"] = "{object:3646}；在地下",
	["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}是一头巨大的鱼龙，在{area:391}外的浅水中游动，位于{npc:3388}东边。",
}

G["forever/horde/07-ashenvale"] = {
	["A short walk north of the Galak camps, the cave of {area:1557} leads down to its deepest chamber, where the {object:20807} burns. Use the {item:5868} on it, then loot the {item:5869} at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to {npc:2986}'s mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame."] = "从加拉克营地向北走一小段，{area:1557}的洞穴通往最深处的洞室，{object:20807}就在那里燃烧。对它使用{item:5868}，然后立刻拾取{item:5869}：火焰只会熄灭很短时间，如果重新燃起，药瓶就没了。然后向东前往{npc:2986}所在的石柱。\n小心：两名加拉克火焰卫士（30级）守在火盆旁，还有一名半人马守卫在洞内巡逻：熄灭火焰前，把它们一个个引开。",
	["Ashenvale Outrunner"] = "灰谷先驱者",
	["Back east to {area:484}: it lies on the way from {area:487} to {npc:2986}'s mesa."] = "向东回到{area:484}：它就在从{area:487}去{npc:2986}所在平顶山的路上。",
	["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "向南回到营地，然后上到{zone:1456}，飞往{area:378}。",
	["Back south-west to {area:421}. Befouled Water Elementals drift around its shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "向西南回到{area:421}。污浊的水元素在湖岸周围漂浮；瞭望台在岛上，俯瞰着联盟的前哨站。",
	["Back south-west to {area:421}. {npc:12759}, a corrupted water elemental, drifts around the lake's island and under the water. She drops the {item:16408} only once you have {quest:25} from {npc:12737}; it starts a quest for Splintertree."] = "向西南回到{area:421}。腐化的水元素{npc:12759}绕着湖中的岛和水下飘荡。只有你从{npc:12737}那里接了{quest:25}，她才会掉{item:16408}；它能开启碎木岗哨的一个任务。",
	["Back to Zoram'gar from the ruins before heading east for good."] = "从遗迹返回佐拉姆加，再向东离开，不再折返。",
	["Back to {area:484}"] = "回到{area:484}",
	["Back to {area:484}. The {area:2240}'s quests come with the next visit to the {area:439}, at 33."] = "返回 {area:484}。{area:2240} 的任务留到下次去 {area:439} 时再做，届时为 33 级。",
	["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "回到伐木营地的{npc:12867}处，就在向北通往碎木岗哨的路上。",
	["Back west to Zoram'gar before heading east for good."] = "向西回到佐拉姆加前哨站，然后再彻底向东出发。",
	["Befouled Water Elemental"] = "被污染的水元素",
	["Befouled Water Elementals drift around the lake's shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "污秽水元素在湖岸一带飘荡；凉亭在岛上，俯瞰着联盟前哨站。",
	["Below ground"] = "地下",
	["Broodmother Valraxx"] = "巢母瓦拉克斯",
	["Cairne Bloodhoof"] = "凯恩·血蹄",
	["Class trainer"] = "职业训练师",
	["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "沿小路爬上{area:2097}顶部。{npc:10646}被囚禁在{npc:10896}（29级）旁边：先清掉守卫和{npc:10896}，再救出她并在下山路上保护她；途中会有恐怖图腾伏击者袭击你。",
	["East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.\nCareful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs."] = "佐拉姆加以东，蓟皮熊怪占据了村庄和据点周围的山丘。\n注意：生命值降到15%或更低的萨满会跑去求援，可能带回更多熊怪。",
	["Felmusk satyrs"] = "魔草萨特",
	["Fly to {area:1638}"] = "飞往{area:1638}",
	["Fly to {area:1638} from Zoram'gar. If you don't know its flight path, fly to {area:378} and walk north through {zone:1412} instead."] = "从佐拉姆加飞往{area:1638}。如果你还没开通那里的飞行路线，就飞往{area:378}，再向北步行穿过{zone:1412}。",
	["Fly to {area:1638} if you know the flight path. If not, fly to {area:378}, head west into {area:215} past {area:222} to {area:1638} and take its flight path from {npc:2995} on the central rise."] = "如果已开通飞行路线，直接飞到{area:1638}。否则先飞到{area:378}，向西进入{area:215}，经{area:222}到{area:1638}，在中央高地上找{npc:2995}开飞行点。",
	["Fly to {area:2897}"] = "飞往{area:2897}",
	["Fly to {area:378}"] = "飞往{area:378}",
	["Fly to {area:378}. {npc:5899}'s hut stands on the ridge above the quilboar watering hole south of the camp, on the road to the {area:485}."] = "飞到{area:378}。{npc:5899}的小屋在营地以南野猪人饮水处上方的山脊上，就在通往{area:485}的路上。",
	["Follow the canyon east out of the mesas onto the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "沿峡谷向东离开石柱区，来到盐滩。{area:2240}的地精和侏儒是中立的，为两个阵营提供任务。",
	["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "沿主路向东经过{area:415}（联盟据点：别离开道路）。{npc:12678}是一头巨大的灰熊，在道路南边、{area:421}西边的{area:418}游荡。它的爪子可以开始下一个狩猎任务。",
	["From the {area:2360} head north-east to the Warsong lumber camp on the road: {npc:12867} stands there."] = "从{area:2360}向东北前往路边的战歌伐木营地：{npc:12867}站在那里。",
	["Galak Scout"] = "加拉克斥候",
	["Galak Windchaser"] = "加拉克逐风者",
	["Galak Wrangler"] = "加拉克牧者",
	["Galak centaurs"] = "加拉克半人马",
	["Gazebo"] = "瞭望台",
	["Gloomrise Hatchling"] = "格鲁姆莱斯雏龙",
	["Gloomrise Soldier"] = "格鲁姆莱斯士兵",
	["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "暮升毒液样本，从{npc:264096}获取",
	["Grimtotem camps below {area:2097}"] = "{area:2097} 下方的恐怖图腾营地",
	["His crate is for Stranglethorn, later on the route"] = "他的箱子要送去荆棘谷，在路线后面",
	["If you skipped {quest:5151} and are still short of 29.49, kill harpies here first: {area:487} is your next stop anyway. Past it, this step skips itself. Or, with a group, run the {area:2797} dungeon or the {area:796} dungeon (Graveyard) instead."] = "如果跳过了 {quest:5151}，而且还没到 29.49 级，先在此击杀鹰身人：反正下一站就是 {area:487}。已超过这个进度则自动跳过此步骤。也可组队前往 {area:2797} 副本或 {area:796} 副本（墓地）。",
	["If you skipped {quest:5151}, grind here to level 29.49 to stay on the route's plan."] = "如果跳过了{quest:5151}，在这里刷到29.49级，以保持在路线计划内。",
	["Inside the hold, Troll Chests lie along the tunnels. {npc:12818} is held deep inside: free him and protect him all the way out, then he runs home to {area:428}.\nCareful: Two scripted ambushes occur, each made up of three Thistlefurs (a Shaman, a Pathfinder and an Avenger, Ursa or Den Watcher): the first when you come back to the tunnel's fork inside the cave, the second just beyond the gate where {npc:3987} roams."] = "据点里，巨魔箱子散落在隧道沿途。{npc:12818}被关在最深处：救出他并一路护送到外面，然后他会跑回{area:428}。\n注意：会有两次剧情伏击，每次由三只蓟皮熊怪组成（一个萨满、一个探路者和一个复仇者、乌尔萨或巢穴看守）：第一次在洞内回到隧道岔路时，第二次在{npc:3987}游荡的大门之外。",
	["Into {area:1638} by a lift: {npc:2995}, the wind rider master, stands on the central rise. Take his flight path if you don't know it yet."] = "坐升降机进入{area:1638}：驭风者管理员{npc:2995}站在中央的高地上。还没学会他的飞行点就先跟他飞一次。",
	["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "继续沿道路向东。{npc:12858}在战歌伐木营地西南等候。他和他的步兵会猛攻{area:2360}：让他们吸引仇恨，跟着{npc:12858}直到{npc:12860}死去。",
	["Kill the {npc:10720} that comes for {npc:10638}"] = "杀死前来袭击{npc:10638}的{npc:10720}",
	["Laughing Sisters"] = "欢笑姐妹",
	["Level 28.9"] = "28.9 级",
	["Level 29.49"] = "等级 29.49",
	["Naga brazier"] = "纳迦火盆",
	["North of Thunder Bluff"] = "雷霆崖以北",
	["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "在营地北边，蜘蛛占据了{area:17044}的墓地。对{npc:264096}使用{npc:264074}的{item:273015}；那里的蜘蛛掉落{item:273181}。{npc:264082}在北端：她的{item:273658}可以开始{quest:96294}。",
	["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "在碎木岗哨西北，魔草萨特在树林里扎营。每个萨特都可能掉落角。",
	["On the road south to the {area:485}, turn east into the {area:359} dig. {npc:3421} hides at its south edge. {object:3646} stands on the bottom floor of the dwarves' fortress, beside {npc:3414} (30) and his Officers (26): pull them to you one at a time."] = "在往南去{area:485}的路上，向东拐进{area:359}的挖掘场。{npc:3421}躲在场地的南缘。{object:3646}在矮人要塞的最底层，旁边是{npc:3414}（30级）和他的军官（26级）：一次拉一个。",
	["On the way back north-east to Splintertree: {npc:12676} prowls the woods south-east of the Warsong lumber camp."] = "在向东北返回碎木岗哨的路上：{npc:12676}在战歌伐木营地东南的树林里徘徊。",
	["Only if the {npc:10617} dropped his plot for you: {npc:10638} stands at {area:2237}."] = "仅当{npc:10617}给你掉落了他的阴谋书时：{npc:10638}站在{area:2237}。",
	["Paladins know {area:1638}'s flight path from {npc:246344}'s training."] = "圣骑士在{npc:246344}的训练中已学过{area:1638}的飞行路线。",
	["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "乘升降梯下去，然后沿道路向东穿过峡谷前往{area:484}，那是一座建在石柱顶上的牛头人村庄。它的升降梯在北侧。",
	["Sapphires of Aku'Mai"] = "阿库麦尔蓝宝石",
	["Screeching Harpy"] = "尖啸鹰身人",
	["Screeching Roguefeather"] = "尖啸盗羽",
	["Screeching Windcaller"] = "尖啸唤风者",
	["Short of 28.9? The Grimtotem around these camps (25-28) are the right level: kill a few more before the climb to {npc:10646}. Past it, this step skips itself. Or, with a group, run the {area:2797} dungeon or the {area:1717} dungeon instead."] = "不到28.9级？这些营地周围的恐怖图腾（25-28级）等级正合适：爬上去找{npc:10646}之前再杀几个。过了这一步，这段会自动跳过。或者组队去刷{area:2797}副本或{area:1717}副本。",
	["Short of 28.9? The Grimtotem around these camps (27-29) are the right level: kill a few more before the climb to {npc:10646}. Past it, this step skips itself. Or, with a group, run the {area:2797} dungeon or the {area:1717} dungeon instead."] = "还不到28.9级？这些营地周围的恐怖图腾（27-29级）等级正合适：在爬向{npc:10646}之前再杀几只。过了那里，这一步会自动跳过。或者组队改去打{area:2797}副本或{area:1717}副本。",
	["South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; {area:421} is west of it. Use the {item:5867} at the moonwell to fill it."] = "从雷恩森林向南，月亮井位于河西边的一处洼地里，从路上很难看到；{area:421}在它西边。在月亮井处使用{item:5867}将其灌满。",
	["South of Darkcloud, the harpies of {area:487}. {npc:4490} (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are {npc:4877}'s."] = "在黑云峰南边是{area:487}的鹰身人。{npc:4490}（31级）在它们中间走动：引她之前先清掉她周围的鹰身人。那里的尖啸的鹰身人、尖啸的游荡者和尖啸的唤风者是{npc:4877}要的。",
	["South of Darkcloud, the harpies of {area:487}. {npc:4490} (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are {npc:4877}'s; her {quest:98069} lie on the ground along the foot of the cliff and in the cave up on top."] = "黑云峰南侧是 {area:487} 的鹰身人。{npc:4490}（31 级）在它们之间走动：引她之前，先清掉周围的鹰身人。那里的尖啸的鹰身人、尖啸的游荡者和尖啸的唤风者是 {npc:4877} 要你击杀的目标；她的 {quest:98069} 散落在崖脚沿线的地面和崖顶洞穴内。",
	["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "与{area:1638}的{npc:3057}交谈：{quest:93739}",
	["Take a lift down from {zone:1456}. The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}."] = "从{zone:1456}乘升降梯下去。大地之环的营地在高崖北边：{npc:264074}、{npc:264072}和{npc:259118}。",
	["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "乘升降梯下去。蛋在峡谷底部的一个巢里，位于三个地点之一：石柱东南（52.3,55.2）、东边（56.4,50.4）或西南（37.6,56.1）。",
	["Talk to {npc:3057}"] = "与{npc:3057}交谈",
	["The Earthen Ring"] = "大地之环",
	["The Earthen Ring camp and its three quests stand up on {area:17045}, north of {zone:1456}. Fly to {zone:1456} if you know its flight path and take a lift down, else fly to {area:378} and walk north through {zone:1412}; the arrow then leads round to the plateau's north end and up onto it."] = "大地之环的营地和它的三个任务在{zone:1456}以北的{area:17045}上。知道{zone:1456}的飞行点就先飞过去，再坐升降机下去；否则飞到{area:378}，向北穿过{zone:1412}步行；箭头随后带你绕到高原北端并爬上去。",
	["The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}. From {zone:1456}, take a lift down; coming on foot from {area:378}, keep north past the bluffs."] = "大地之环营地在高地北面：{npc:264074}、{npc:264072}和{npc:259118}都在那里。从{zone:1456}来就乘升降梯下去；从{area:378}步行过来，则沿高地继续向北。",
	["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "污林熊怪占据着{area:421}东边、道路南边的树林。把{item:16972}放在{object:178206}上并守护它：熊怪会来摧毁它。{npc:12918}最后出现；他的图腾会掉进篮子里。",
	["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks a long path between the camps: if you meet him, kill him, his note starts a quest for {area:2237}. Don't wait for him."] = "加拉克半人马的营地遍布乱风岗北边的峡谷；每个营地都有加拉克斥候、加拉克争斗者和加拉克逐风者。一个落单的{npc:10617}沿着一条很长的路线在营地之间走动：如果遇到他，就杀了他，他的信件可以开始一个{area:2237}的任务。不要专门等他。",
	["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks between the camps: kill him when you meet him, his note starts a quest for {area:2237}."] = "加拉克半人马的营地遍布乱风岗北边的峡谷；每个营地都有加拉克斥候、加拉克争斗者和加拉克逐风者。一个落单的{npc:10617}在营地之间走动：遇到就杀死他，他的信件可以开始一个{area:2237}的任务。",
	["The Laughing Sisters, dryads, wander {area:426} around {npc:12677}'s woods; one of them drops {npc:4721}'s {item:5867}, which can take several kills."] = "欢笑姐妹是一群树妖，在{area:426}中{npc:12677}所在的树林一带游荡；其中某一个会掉落{npc:4721}的{item:5867}，可能需要多杀几只。",
	["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "阿库麦尔蓝宝石是通往{area:2797}传送门的坑道墙壁上的蓝色水晶，位于地下、副本之外：从坑里潜下去，从墙下游进洞穴。坑道里的萨特和纳迦是精英：建议组队。水晶刷新很快，不用深入。",
	["The Wanted poster beside {npc:10537}"] = "{npc:10537}旁的通缉告示",
	["The fountain stands in the middle of the {area:418}, where {npc:12678} roams: use the {item:7767} there."] = "喷泉在{area:418}中央，{npc:12678}在那一带游荡：在那里使用{item:7767}。",
	["The fountain stands in the middle of the {area:418}: use the {item:7767} there."] = "喷泉在{area:418}中央：在那里使用{item:7767}。",
	["The next guide flies on from here to the Crossroads and {zone:1454}."] = "下一篇指南会从这里飞往十字路口和 {zone:1454}。",
	["The next guide flies on from here to {zone:1454}."] = "下一个指南从这里飞往{zone:1454}。",
	["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "暗夜精灵{quest:6503}（23-24级）在伐木营地南边和东南边的树林里潜伏；他们会潜行，所以留意他们。",
	["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "去阿库麦尔蓝宝石的路要穿过海滩北端沉没的废墟：沿台阶下到坑里。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:10992} is a level 30 elite: most classes solo it at level 32, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些都是精英怪：建议组队，找人一起完成。{npc:10992} 是 30 级精英：大多数职业到 32 级可以单独击败，但你可能仍需要帮助。独自一人就跳过：路线会安排刷怪补回这部分经验。",
	["Thistlefur Avenger"] = "蓟皮复仇者",
	["Thistlefur Hold"] = "蓟皮熊怪的巢穴",
	["Thistlefur Shaman"] = "蓟皮萨满",
	["Underwater"] = "在水下",
	["Warsong lumber camp"] = "战歌伐木营地",
	["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "在乱风岗西边，恐怖图腾的营地在{area:2097}下方。密信在东南、西南和西北营地的文件箱里。",
	["West of Mystral Lake, {npc:12678}, a big grizzly, roams the {area:418}: his paw now drops for you."] = "在密斯特拉湖西边，{npc:12678}是一头巨大的灰熊，在{area:418}游荡：现在你可以从它身上获得它的爪子了。",
	["West of Whitereach the wyverns nest on the {area:482} cliffs; the eggs lie in the nests. {npc:10427} waits on the east side of the nesting grounds: free him and keep him alive on the walk back to {area:2237}.\nCareful: Wyverns at level 28-29 fly overhead and can be pulled without warning. A group of three wyverns can ambush you once you pass the first pillar at the bottom."] = "在白沙岗哨西边，双足飞龙栖息于 {area:482} 的悬崖，蛋就在巢里。{npc:10427} 在巢区东侧等候：救出他，并在返回 {area:2237} 的途中保护他。\n小心：28-29 级的双足飞龙在头顶飞行，可能毫无预警地被引来。经过底部第一根石柱后，可能遭到三只双足飞龙的伏击。",
	["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "顺路提示：向{npc:11869}学习{spell:199}（10 银）；战士使用双手武器升级最快。",
