	["Your trainer is in {area:1638}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly there from {area:976}, then back to {area:976}."] = "你的训练师在{area:1638}：{area:1639}上的{npc:3033}（德鲁伊）、{npc:246344}（圣骑士）。从{area:976}飞过去，然后飞回{area:976}。",
