	["{quest:2863}: one hour from now"] = "{quest:2863}：从现在起一小时内",
	["{zone:1444}: kill these as you meet them"] = "{zone:1444}：沿途遇到就击杀",
	["{zone:1454} flight master"] = "{zone:1454}飞行管理员",
	["{zone:1456} flight master"] = "{zone:1456}飞行管理员",
}

G["forever/horde/40-50/03-feralas"] = {
	["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "往回向东经过{area:75}：阿塔莱神器在{quest:1424}的水里和岸边。",
	["Below ground"] = "在地下",
	["Coming from Stranglethorn, you carry these already. Starting here: {npc:5591} stands inside {area:75}'s great hall and {npc:1443} on its top floor."] = "从荆棘谷过来的话，你已经带着这些了。从这里开始：{npc:5591}在{area:75}的大厅里，{npc:1443}在它的顶层。",
	["Dragon caves"] = "龙穴",
	["East through the {area:511}: the Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps."] = "向东穿过{area:511}：火鬃斥候和火鬃灰尾龙人与灼热龙崽、灼热雏龙一起在北缘游荡；Scalebanes守着更东南方的龙穴。莫格穆洛克的鼻烟、烈酒和保险箱散落在龙人营地里。",
	["Firemane Ash Tail"] = "火鬃灰尾龙人",
	["Firemane Scalebane"] = "火鬃禁鳞龙人",
	["Firemane Scout"] = "火鬃斥候",
	["Fly to {area:1099}"] = "飞往{area:1099}",
	["Fly to {area:496}"] = "飞往{area:496}",
	["Fly to {area:75}"] = "飞往{area:75}",
	["Fly to {area:976}"] = "飞往{area:976}",
	["Follow the road south-east to the small Horde post on the shore. {npc:5592} takes the crocolisk flanks from the last swamp visit."] = "沿路向东南前往岸边的小型部落岗哨。{npc:5592}需要上次来沼泽时收集的鳄鱼肉。",
	["Forest walkers"] = "森林漫游者",
	["Frayfeather hippogryphs"] = "乱羽角鹰兽",
	["If you skipped {quest:1173}, grind here to level 45.41 to stay on the route's plan."] = "如果你跳过了{quest:1173}，就在这里刷到45.41级，以跟上本路线的进度规划。",
	["If you skipped {quest:1173}, grind here to level 45.41 to stay on the route's plan. Or, with a group, run the {area:978} dungeon or the {area:1517} dungeon instead."] = "如果你跳过了{quest:1173}，就在这里刷到45.41级，以跟上本路线的进度规划。或者组队改去打{area:978}副本或{area:1517}副本。",
	["Inside {area:498}"] = "进入{area:498}内部",
	["Keep {area:1417} for Marvon in {area:440}."] = "把{area:1417}留给{area:440}的马冯那一步。",
	["Level 45.37"] = "等级 45.37",
	["Level 45.41"] = "45.41级",
	["Marsh Flesheater"] = "沼泽食肉鱼人",
	["Marsh Inkspewer"] = "沼泽喷墨鱼人",
	["Marsh Murloc"] = "沼泽鱼人",
	["Marsh Oracle"] = "沼泽神谕者",
	["Murlocs of the Misty Reed"] = "芦苇丛中的鱼人",
	["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "沿道路向西北，狂暴的怒痕雪人住在山丘里的洞穴周围。它们也都可能掉落{quest:7738}，它可以开始一个单独的任务。",
	["Northspring Harpy"] = "北泉鹰身人",
	["Northspring Roguefeather"] = "北泉游羽鹰身人",
	["Northspring Slayer"] = "北泉杀戮者",
	["Northspring Windcaller"] = "北泉唤风者",
	["Northspring harpies"] = "北泉鹰身人",
	["On the way back south-east from the harpies, the Rage Scar yetis live around the caves in the hills by the road. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "从鹰身人那里向东南返回的路上，狂暴的怒痕雪人住在道路旁山丘里的洞穴周围。它们也都可能掉落{quest:7738}，它可以开始一个单独的任务。",
	["Onyxia's eggs"] = "奥妮克希亚的蛋",
	["Rage Scar yetis"] = "怒痕雪人",
	["Ride back north to Brackenwall."] = "向北骑回蕨墙村。",
	["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "向西北骑往{area:1108}；{npc:14637}在码头上等候。",
	["Ride south-west to the {object:2555}, then east through the {area:511}. The Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps."] = "向西南骑往{object:2555}，然后向东穿过{area:511}。火鬃斥候和火鬃灰尾龙人与灼热龙崽、灼热雏龙一起在北缘游荡；火鬃守卫守护着更东南的龙穴。莫格穆洛克的鼻烟、烈酒和保险箱都在龙人营地里。",
	["Ride south-west to the {object:2555}."] = "向西南骑行到{object:2555}处。",
	["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "沿道路向西骑行；卷轴在沼泽最西边的水边。",
	["Ride west into the middle of {zone:1444}. Kill a {npc:5308}, use {item:10699} on its body and kill the spirit that rises."] = "向西骑进{zone:1444}中部。杀一只{npc:5308}，对它的尸体使用{item:10699}，再杀掉升起的精魂。",
	["Riding at 40"] = "40级骑术",
	["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:4773} in {area:159}, a short ride north of the zeppelin towers, with {npc:4731}'s skeletal horses (20 gold each) beside her. Ride back to the towers for the {object:3202} zeppelin."] = "骑术需要40级，花费100金币；学会后会获得一只坐骑。各个种族都要找本族训练师学习。你的训练师是{area:159}的{npc:4773}，从飞艇塔骑行向北不远就到；她旁边是{npc:4731}出售的骷髅马（每匹20金币）。之后骑回高塔，乘飞艇前往{object:3202}。",
	["Rogue Vale opens just north of {npc:14637}'s dock. Kill a {npc:5308}, use {item:10699} on its body and kill the spirit that rises."] = "Rogue Vale就在{npc:14637}码头北边不远处。击杀一只{npc:5308}，对尸体使用{item:10699}，再击杀出现的灵魂。",
	["Rogue Vale screechers"] = "游荡的山谷尖啸者",
	["Sawtooth crocolisks"] = "盐齿鳄鱼",
	["Screecher Spirit"] = "尖啸者精魂",
	["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "海元素和巨型海元素沿着码头周围的海岸漂荡。先用{item:18904}电击巨人：被缩小后，它们就失去了精英的力量。海岸巨人在水中涉行；大地行者和峭壁巨人在更北边的山丘上游荡。",
	["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "骸骨军马：{npc:4731}，在{area:159}的{npc:4773}旁边。",
	["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "在山谷南边，乱羽角鹰兽栖息在山坡上；几乎每只都会掉落肌腱和金属碎片。",
	["South-west, the yetis den in {area:1105}; every yeti there can drop a thick hide."] = "在西南，雪人在{area:1105}筑巢；那里的每个雪人都可能掉落厚重的雪人皮。",
	["Sprite darters and forest walkers"] = "小精龙和森林漫游者",
	["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "奥妮克希亚的蛋在{area:511}东南的龙穴里，由火鬃守卫看守；砸碎五个。",
	["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "沼泽鱼人住在哨站南边的海滩上；沼泽喷墨鱼人在哨站东边的岸边，沼泽食腐鱼人在更西边、西岸的小屋周围。",
	["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "北泉鹰身人在遥远西北的山脊上筑巢。它们是48-50级，比你高几级：北泉唤风者会治疗，所以先杀它们，一次引一只。",
	["The crocolisks wallow in the pools around Galen's old camp, just north of {area:75}, on the way back east; about one in four drops a flank."] = "鳄鱼泡在加伦旧营地周围的水塘里，就在{area:75}以北，在往东回来的路上；大约四个掉一个侧肉。",
	["The next guide starts here and takes you to {area:440}.\nThe small Horde post on the southern shore."] = "下一篇攻略从这里开始，带你去{area:440}。\n南岸的部落小岗哨。",
	["The same murloc shore again: Inkspewers east of the post, Flesheaters around the western huts, and the Oracles among both."] = "又是同一段鱼人海岸：喷墨者在哨站以东，食肉者在西边的棚屋周围，神谕者混在两者中间。",
	["The snappers line the strand south of the post.\nThe Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see on the way south."] = "钳嘴龟排列在岗哨南边的滩涂上。\n巨型爬行者在东海岸的沙滩上零星游荡：南下的路上见一只杀一只。",
	["The snappers line the strand south of the post.\nThe Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see, the ones on the ride down from the pool too."] = "钳嘴龟分布在岗哨南边的海滩。\n巨型淤泥蟹沿东海岸的沙滩游荡，数量少且分散；看到就杀，从水池骑行南下途中遇到的也别漏掉。",
	["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "小精龙在营地正西的树林上空飞来飞去，携带{item:9589}；再往西一点的森林漫游者携带断裂的原木。",
	["The {area:511}"] = "{area:511}",
	["The {object:2555}"] = "{object:2555}",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:1173} needs a group of 3. Skip it if you are alone: the route has you grind the XP back.\n{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "这些是精英怪：建议组队，找人一起做。{quest:1173} 需要三人小队。独自一人就跳过：路线会让你打怪补回这部分经验。\n{npc:4500} 是精英：建议组队。把他打到投降，然后向 {npc:4501} 汇报。",
	["To {area:1099}"] = "前往{area:1099}",
	["Underwater"] = "在水下",
	["Zeppelin to {object:3202}"] = "乘飞艇前往{object:3202}",
	["Zeppelin to {zone:1458}"] = "乘飞艇前往{zone:1458}",
	["for the {npc:5598} in the {zone:1425}, around level 48"] = "交给{zone:1425}的{npc:5598}，大约48级时",
	["for the {object:2555} in {area:15}, later in this guide"] = "为了{area:15}的{object:2555}，本攻略后面会用到",
	["for the {object:2555} in {zone:1445}, later in this guide"] = "交给{zone:1445}的{object:2555}，在本指南稍后",
	["for the {zone:1425} owlbeasts, around level 48"] = "交给{zone:1425}的枭兽任务，大约48级时",
	["for {area:35}, around level 50"] = "为了{area:35}，约50级时去",
	["grind on {npc:4329}"] = "击杀{npc:4329}刷经验",
	["the {item:8523} from these errands: keep it, Tanaris Field Sampling hands it back in {area:976}"] = "这些差事给{item:8523}：留着，塔纳利斯野外采样会在{area:976}还给你",
	["the {object:2555}"] = "{object:2555}",
	["{area:1099} flight master"] = "{area:1099}的飞行管理员",
	["{area:1108}: kill these as you meet them"] = "{area:1108}：沿途击杀以下目标",
	["{area:1136}: kill these as you meet them"] = "{area:1136}：遇到就杀",
	["{area:2403}: kill these as you meet them"] = "{area:2403}：沿途遇到就击杀",
	["{area:496} flight master"] = "{area:496}的飞行管理员",
	["{area:510}: kill these as you meet them"] = "{area:510}：沿途遇到就击杀",
	["{area:976} flight master"] = "{area:976}飞行管理员",
	["{item:6168} along the way to {area:1978}"] = "{item:6168}，在去{area:1978}的路上",
	["{item:6168} on the way"] = "{item:6168}，顺路",
	["{npc:1443}, on the top floor"] = "{npc:1443}，位于最顶层",
	["{npc:2934}, on the way back to Zinge"] = "{npc:2934}，在返回金吉那里的路上",
	["{npc:4329} walks around {area:510}: look inside the circle on the map"] = "{npc:4329}在{area:510}附近巡逻，请在地图标出的圆圈内寻找",
	["{npc:4500}'s challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the {area:511}'s northern edge to level 45.37 before you ride back north, so you don't come back down for it. Or, with a group, run the {area:978} dungeon or the {area:1517} dungeon instead."] = "回到蕨墙村后，{npc:4500}的挑战需要三人小队。独自一人的话，在向北骑回去之前，就在{area:511}北缘这里击杀火鬃斥候刷到45.37级，免得之后还要专程回来。也可组队挑战{area:978}或{area:1517}副本。",
	["{npc:4500}, {npc:4502} and {npc:4501} (below ground) are in the village; their quests are for the {area:511} on this trip."] = "{npc:4500}、{npc:4502}和{npc:4501}（在地下）都在村里；他们的任务目标在本次要去的{area:511}。",
	["{npc:4501}, below ground"] = "{npc:4501}：在地下",
	["{npc:4773}, riding trainer"] = "{npc:4773}，骑术训练师",
	["{npc:5591}, inside"] = "{npc:5591}：在屋内",
	["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}：熊在{zone:1448}",
	["{npc:7825}, the {object:36126}"] = "{npc:7825}，在{object:36126}",
	["{npc:7854}, inside"] = "{npc:7854}：在屋内",
	["{npc:7881}, inside"] = "{npc:7881}，在屋里",
	["{npc:7882}, inside"] = "{npc:7882}，在屋里",
	["{npc:8579}: the screechers live in {zone:1444}"] = "{npc:8579}：尖啸者生活在{zone:1444}",
	["{object:3202} flight master"] = "{object:3202} 的飞行管理员。",
	["{quest:7738}, a rare drop"] = "{quest:7738}，稀有掉落",
}

G["forever/horde/40-50/04-tanaris"] = {
	["Back east to Fizzledowser on the west side of {area:976}; {npc:7771} is south from there."] = "向东回到{area:976}西侧的菲兹尔多瑟；{npc:7771}再往南。",
	["Back north, just south of {area:976}, use the {item:8524} now: the two-hour timer starts. The Blisterpaw Hyenas, Glasshide Basilisks and Scorpid Hunters share the dunes here. Each can drop an untested sample: use it, and it either passes as an acceptable one or is lost. Keep killing until you have eight of each."] = "向北返回，在{area:976}南边不远处，现在使用{item:8524}：两小时计时开始。疱爪土狼、玻璃皮蜥蜴和巨钳蝎猎手共同栖息在这片沙丘上。它们都可能掉落未检测的样本：使用它，样本要么通过检测成为合格样本，要么就此损失。持续击杀，直到每种各有八份。",
	["Below ground"] = "在地下",
	["Boat to {area:16727}"] = "乘船前往{area:16727}",
	["Careful: Shadow Mages (level 42-43) call a Voidwalker while out of combat and attack with Immolate and {spell:686}. Thieves can Disarm you, Rogues move around in Sneak, and Assassins use Execute once you are at 20% health or less."] = "小心：暗影法师（42-43级）会在脱战时召唤虚空行者，使用献祭和{spell:686}攻击。窃贼会缴械，潜行者会潜行移动，刺客则会在你生命值不超过20%时使用斩杀。",
	["Dark Iron Geologist"] = "黑铁地质学家",
	["Dark Iron Lookouts"] = "黑铁哨兵",
	["Dark Iron Slaver"] = "黑铁奴隶贩子",
	["Dark Iron Taskmaster"] = "黑铁监工",
	["Dunemaul Brute"] = "砂槌蛮兵",
	["Dunemaul Enforcer"] = "砂槌打手",
	["Fly to {area:976}"] = "飞往{area:976}",
	["From {area:16727}, ride into the {area:51} by its eastern pass, then west to the dig site. The {object:173265} stands at its southern end; the Dark Iron Geologists dig just north of it. Bring 15 {item:4306} (the Auction House sells it)."] = "从{area:16727}经东侧山口进入{area:51}，再向西到挖掘场。{object:173265}立在它的南端；黑铁地质学家就在它北边挖掘。带上15个{item:4306}（拍卖行有卖）。",
	["From {area:16727}, ride into the {zone:1427} by its eastern pass, then west to the dig site. The {object:173265} stands at its southern end; the Dark Iron Geologists dig just north of it. Bring 15 {item:4306} (the Auction House sells it)."] = "从 {area:16727} 骑行，经东侧山口进入 {zone:1427}，再向西到挖掘场。{object:173265} 在挖掘场南端；黑铁地质学家就在它北边不远处挖掘。带上 15 个 {item:4306}（拍卖行有售）。",
	["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "再往南，初级勘探员斯克林杰的装备在一个森提帕尔虫巢的入口处。\n注意：装备旁有一只虫子守着。隧道内有许多虫子巡逻，其中一些为50级，因此战斗时经常会引来额外的敌人。",
	["Gnarled Thistleshrub"] = "多节的蓟灌木",
	["Gor'marok the Ravager"] = "蹂躏者戈玛洛克",
	["Greater Lava Spider"] = "巨型熔岩蜘蛛",
	["Heavy War Golem"] = "重型战争傀儡",
	["Heavy War Golems patrol the Cauldron below Kalaran and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it.\nThe Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge.\n{area:1443} opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee."] = "重型战争傀儡在卡拉兰下方的火山口巡逻，掉落油；在它们中间游荡的岩浆元素和炽焰元素掉落心脏。黑铁监工和奴隶贩子在小路上驱赶奴隶；奴隶贩子可能掉落{item:11818}：留着。\n巨型熔岩蜘蛛在峡谷西南的高地和熔岩池出没。\n{area:1443}在火山口北部开口。炎蜥在其熔岩池里游泳：把它们拉到岸边。秘密计划就在坑的上层岩架。\n注意：黑铁奴隶贩子（45-46级）被拉时向15码内的盟友求援，还会从最多15码外撒网，并在近战中使用撕裂。",
	["Heavy War Golems patrol the Cauldron below {npc:8479} and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it.\nThe Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge.\n{area:1443} opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee."] = "重型战争傀儡在{npc:8479}下方的大锅炉巡逻，掉油；在它们中间飘荡的岩浆元素和烈焰元素掉心。黑铁工头和奴隶主在小路上驱赶奴隶；奴隶主可能掉{item:11818}：留着。\n巨型熔岩蜘蛛在峡谷西南的高地和熔岩池游荡。\n{area:1443}在大锅炉北边开口。焚化者龙在它的熔岩池里游动：把它们拉到边缘打。秘密计划在坑的上层台地上。\n注意：黑铁奴隶主（45-46级）被拉时会呼叫15码内的同伴，能从15码外撒网，近战时还会用撕裂。",
	["His next request needs the {item:10552} from elite cultists: leave it."] = "他的下一个请求需要精英信徒身上的{item:10552}：别接。",
	["Incendosaur"] = "炎蜥",
	["Into {area:51}"] = "进入{area:51}",
	["Into {zone:1427}"] = "进入{zone:1427}",
	["Kalaran Windblade"] = "卡拉兰·风刃",
	["Kalaran stands alone south of {area:1446}, at the edge of the Cauldron. Listen to his story."] = "卡拉然独自站在{area:1446}南边，大熔炉的边缘。听他讲他的故事。",
	["Keep the Model 4711-FTZ Power Source Bilgewhizzle gave you: it starts {quest:654}, a two-hour timer, so use it on the way back north from Scrimshank's hive."] = "保留比格维兹给你的4711-FTZ型能量源：它会开始{quest:654}，限时两小时，所以在从斯克林谢尔的虫巢向北返回的途中再使用。",
	["OOX-17/TN"] = "OOX-17/TN",
	["On the way"] = "顺路",
	["Only with the distress beacon: OOX-17/TN sits south-east of Scrimshank's hive. Escort it north to {area:977}; its reward waits with Oglethorpe in {area:35}.\nCareful: The escort has two ambushes. Three level 47 scorpids attack near the start. Near the end, by the beach, three Wastewander humans attack: one mage and two assassins, around level 44."] = "仅在持有求救信标时进行：OOX-17/TN 位于斯克林谢尔的虫巢东南方。护送它向北前往 {area:977}；奖励要到 {area:35} 找奥格索普领取。\n小心：护送途中有两次伏击。刚开始不久会有三只 47 级蝎子袭来。快到终点、靠近海滩时，会有三名废土人类袭击：一名法师和两名刺客，约 44 级。",
	["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "仅当你有{item:11818}时：向东回到挖掘场的{object:173265}。",
	["Ride back north to {area:1446}, just past {npc:8479}."] = "向北骑回{area:1446}，就在{npc:8479}过去一点。",
	["Ride back north to {area:1446}."] = "向北骑回{area:1446}。",
	["Ride back north to {area:1446}. Stay here: the next guide starts with the flight to {area:75}."] = "向北骑回{area:1446}。留在这里：下一个指南从飞往{area:75}开始。",
	["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "向西北骑过峡谷；{area:1446}是西北边搭着脚手架的营地。",
	["Ride south from {area:1446} into the Cauldron: the Dark Iron Taskmasters and Slavers drive the slaves on the paths, and the Heavy War Golems patrol the floor below Kalaran."] = "从{area:1446}向南骑进大熔炉：黑铁监工和奴隶主在小路上驱赶奴隶，重型战争魔像在卡拉兰下方一带巡逻。",
	["Ride south from {area:1446} into the Cauldron: the Dark Iron Taskmasters and Slavers drive the slaves on the paths, and the Heavy War Golems patrol the floor below {npc:8479}."] = "从{area:1446}向南骑进大锅炉：黑铁工头和奴隶主在小路上驱赶奴隶，重型战争傀儡在{npc:8479}下方的底部巡逻。",
	["Scrimshank's gear"] = "谢申克的勘探设备",
	["South of the {area:982} the Dunemaul ogres hold their compound, with {npc:12046} at its eastern end. Dig up {quest:3161} ornaments between the fights."] = "在{area:982}南边，砂槌食人魔占据着他们的营地，{npc:12046}在营地东端。在战斗间隙挖出{quest:3161}饰物。",
	["Take the pass out of {area:340}'s west side into the {area:51}, then ride south-west to the dig site. The {object:173265} stands at its southern end; the Dark Iron Geologists dig just north of it. Bring 15 {item:4306} (the Auction House sells it)."] = "从{area:340}西侧的山口进入{area:51}，然后向西南骑到挖掘场。{object:173265}立在它的南端；黑铁地质学家就在它北边挖掘。带15个{item:4306}（拍卖行有卖）。",
	["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "黑铁哨兵站在大熔炉南边哨塔周围的山脊上；大约十分之一带着{item:18960}。",
	["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "黑铁锻造师在大熔炉中央的熔炉旁干活；他们一半带着{item:10551}，十分之一带着{item:18959}。奴隶工、黑铁奴隶贩子和黑铁工头也带着匕首。",
	["The Steamsmiths' furnaces"] = "黑铁锻造师的熔炉",
	["The flight lands beside {npc:7876}. Take the town's quests before riding west to {area:979}."] = "飞行点落在{npc:7876}旁。向西骑去{area:979}之前，先接下镇上的任务。",
	["The {area:247}"] = "{area:247}",
	["The {object:142071} machine, in the middle of town: the egg is in southern {zone:1444}, around level 50"] = "镇中心的{object:142071}机器：蛋在{zone:1444}南部，大约50级时",
	["The {object:179827} board"] = "{object:179827}告示板",
	["Thistleshrub Rootshaper"] = "蓟灌木塑根者",
	["Use the {item:8524}"] = "使用{item:8524}",
	["Velarok Windblade"] = "维拉罗克·风刃",
	["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "沿道路向西再向南；{npc:7771}在{area:1938}的废墟旁扎营。戴上他的{item:9978}：它会显示埋在这里和{area:983}周围的饰物。",
	["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "在加基森西边，在巨魔营地的水坑旁使用{item:8584}。",
	["West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in {area:440} can drop OOX-17/TN's distress beacon, rarely: keep it if you see one.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs."] = "营地以西，仙人掌生物布满山谷；只有露水收集者携带露腺。{area:440}的大多数怪物都可能掉落OOX-17/TN的求救信标，但很稀有：看到就留着。\n注意：这一带其他蓟灌木怪物是49-50级，而且到处游荡，很容易多拉到怪。",
	["West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in {zone:1446} can drop OOX-17/TN's distress beacon, rarely: keep it if you see one.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs."] = "营地西侧的山谷遍布仙人掌般的生物；只有露水收集者携带露腺。{zone:1446} 的大多数怪物都有极低概率掉落 OOX-17/TN 的求救信标：看见就留着。\n小心：此地其他灌木怪为 49-50 级，四处游荡，很容易额外引怪。",
	["West, the Centipaar insects swarm around their hives; any of them drops the parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "西边的森提帕尔虫群聚集在巢穴周围；每种都会掉落部件。\n小心：森提帕尔群居蝎在战斗内外都会施放 {npc:4196}，召来会打断你的小怪。",
	["for {npc:5204} in the {zone:1458}, around level 52"] = "给{zone:1458}的{npc:5204}，大约52级",
	["for {npc:7010} in {zone:1454}, around level 50"] = "交给{zone:1454}的{npc:7010}，大约50级时",
	["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526}生长在{zone:1425}，大约48级时",
	["the {object:173265}"] = "{object:173265}",
	["{area:1099} flight master"] = "{area:1099}的飞行管理员",
	["{area:1938}: kill these as you meet them"] = "{area:1938}：沿途遇到就击杀",
	["{area:246}'s slavers and golems"] = "{area:246} 的奴隶贩子和傀儡",
	["{area:51}: kill these as you meet them"] = "{area:51}：遇到就杀",
	["{item:11818}, a rare drop"] = "{item:11818}，稀有掉落",
	["{item:8623}, a rare drop"] = "{item:8623}，稀有掉落",
	["{npc:5594}, inside"] = "{npc:5594}：在屋内",
	["{npc:5844} along the way to {area:1446}"] = "前往{area:1446}途中的{npc:5844}",
	["{npc:5846} along the way to {area:1446}"] = "前往{area:1446}途中的{npc:5846}",
	["{npc:5854} along the way to {area:1446}"] = "前往{area:1446}途中的{npc:5854}",
	["{npc:5858} on the way"] = "{npc:5858}，途中",
	["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955}在山谷里等候。一路带他到东北方沙漠另一头{area:977}的妻子{npc:6015}那里：紧跟着他，放慢速度等他，击退攻击他的敌人。别骑上坐骑或用炉石离开他的范围。{npc:8579}也站在港口里。",
	["{npc:5955}'s escort"] = "护送{npc:5955}",
	["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在双足飞龙管理员旁边",
	["{npc:8479} stands alone south of {area:1446}, at the edge of the Cauldron. Listen to his story."] = "{npc:8479}独自站在{area:1446}以南、大锅炉的边缘。听完他的故事。",
	["{quest:3362}: kill these as you meet them"] = "{quest:3362}：沿途击杀以下目标",
	["{zone:1427}: kill these as you meet them"] = "{zone:1427}：沿途击杀以下目标",
}

G["forever/horde/40-50/05-the-hinterlands"] = {
	["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "向西回到{area:350}；高原游侠和高原神射手待在旅舍附近，高原斥候和高原前锋在旅舍南边的山坡上。",
	["Careful: Stealthed wolves and griffons roam the {area:1883} area."] = "小心：{area:1883}一带有潜行的狼和狮鹫游荡。",
	["East of the village, the violet flower grows in the hills."] = "在村庄东边，紫色水生菇生长在山丘上。",
	["Fly to {area:272}"] = "飞往{area:272}",
	["Fly to {area:321}"] = "飞到{area:321}",
	["Fly to {area:75}"] = "飞往{area:75}",
	["Follow the roads east across the {area:47} to the troll village on the eastern coast."] = "沿道路向东穿过{area:47}，前往东海岸的巨魔村庄。",
	["Follow the roads east across the {area:47} to the troll village on the eastern coast. {npc:14736} stands up on top of the inn, above {npc:14731}: go up, the arrow cannot tell the levels apart."] = "沿路向东穿过{area:47}，到东海岸的巨魔村庄。{npc:14736}站在旅店顶上，就在{npc:14731}上方：上去找，箭头分不清楼层。",
	["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "沿道路向东穿过{zone:1425}，前往东海岸的巨魔村庄。",
	["Highvale"] = "高原精灵",
	["Highvale Marksman"] = "高地谷神射手",
	["Highvale Outrunner"] = "高地谷奔逃者",
	["Highvale Ranger"] = "高地谷游侠",
	["Highvale Scout"] = "高地谷斥候",
	["His next request, going on to the {area:355}, is for a group."] = "他的下一个请求要前往{area:355}，需要组队。",
	["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. Keep to the paths: the trolls inside are elite."] = "猎户莫克霍尔的颅骨在邪枝废墟下方的一堆骨头上，他的骨头在{area:354}脚下的一堆上。污染之血容器放在下层平台上，{npc:14757}被关在最顶上。沿着小路走：里面的巨魔都是精英。",
	["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. The trolls inside are elite: stay with your group and keep to the paths."] = "Huntsman Malkhor的头骨在邪枝废墟下方的一堆遗骸上，骨头则在{area:354}脚下的一堆遗骸上。Vessels of Tainted Blood分布在下层平台，{npc:14757}被关在最顶端。里面的巨魔都是精英：紧跟队伍，沿小路走。",
	["If you skipped {quest:7816} or the {area:354} group quests, grind here to level 49.02 to stay on the route's plan. Or, with a group, run the {area:2100} dungeon instead."] = "如果跳过了{quest:7816}或{area:354}的组队任务，就在这里刷到49.02级，以跟上路线进度。也可以组队去{area:2100}副本。",
	["If you skipped {quest:7816}, grind here to level 49.02 to stay on the route's plan."] = "如果跳过了{quest:7816}，在这里刷到49.02级，以保持在路线计划内。",
	["Level 49.02"] = "等级 49.02",
	["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "沿海岸向北，{npc:14731}的午餐篮在小岛上；一个{npc:14748}守着它。",
	["OOX-09/HL"] = "OOX-09/HL",
	["On the top floor"] = "在最顶层",
	["On the way"] = "途中",
	["On the way back east, the Vilebranch soothsayers hold the {area:355}, the troll temple south of the central hills. Qiaga and {npc:8636} (elite, 50) stand at its top: take the soothsayers on the lower steps.\nSouth-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "回程向东时，邪枝占卜者占据着{area:355}，即中央丘陵以南的巨魔神庙。恰加和{npc:8636}（50级精英）站在顶端：在下层台阶上打占卜者。\n西南方向，银鬃嗥叫者在枯木村以东的山丘游荡。",
	["Only with the distress beacon: the robot sits at the head of the river west of {area:351}. Escort it east to the shore beyond the {area:307}; its reward waits with Oglethorpe in {area:35}.\nCareful: Two ambushes spawn during the escort: first three wildkin owlbeasts, then three trolls. Before each, the robot halts and announces it senses danger. Oozes, stealthed wolves and a large turtle along the path can join fights, and they respawn even if cleared beforehand."] = "仅在持有求救定位器时进行：机器人位于 {area:351} 西侧的河流源头。护送它向东到 {area:307} 以外的海岸；奖励需去 {area:35} 找奥格索普·奥布诺提斯领取。\n小心：护送途中会出现两波伏兵，先是三只枭兽，再是三个巨魔。每次遇袭前，机器人都会停下并说它察觉到危险。沿途的软泥怪、潜行的狼和一只大海龟都可能加入战斗，即使提前清掉，它们也会刷新。",
	["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "一路向西骑到蛮锤矮人的城镇{area:348}，把警告放在镇中央的水井旁。镇上全是联盟守卫：进去，放好，然后离开。",
	["Ride back north through the canyon to {area:75}."] = "向北穿过峡谷骑回{area:75}。",
	["Ride back north to the bloodmages."] = "向北骑回血法师那里。",
	["Ride north-east from {area:272} into the {area:47} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "从{area:272}向东北骑进{area:47}，沿路向东；{npc:7801}在精灵的{area:350}以南的山丘扎营。",
	["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "从{area:272}向东北骑进{zone:1425}，再沿道路向东；{npc:7801}在精灵的{area:350}南边的山上扎营。",
	["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "从{area:75}向西出发，再向南穿过峡谷进入{zone:1419}；两位血法师就站在入口不远处的路旁。",
	["Saltwater Snapjaw"] = "咸水钳嘴鳄",
	["Savage Owlbeast"] = "野蛮枭兽",
	["Silvermane Howler"] = "银鬃嗥叫者",
	["Silvermane Stalker"] = "银鬃潜伏者",
	["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "在旅舍南边，枯木巨魔占据着他们的村庄。他们每个都携带头皮：收集到二十个后，使用{item:15002}做成尼姆布亚的长矛，然后把它插在村子里。",
	["South-west again, the exile hides by the ruins of {area:353}."] = "再次向西南，流放者躲在{area:353}的废墟旁。",
	["South-west of the lake, the Vilebranch soothsayers hold the {area:355}, the troll temple south of the central hills. Qiaga and {npc:8636} (elite, 50) stand at its top: take the soothsayers on the lower steps.\nSouth-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "湖西南面，邪枝占卜者占据着中央山丘以南的巨魔神庙{area:355}。Qiaga和{npc:8636}（50级精英）站在顶端：在下层台阶打占卜者即可。\n再往西南，银鬃嗥狼在枯木村落以东的山丘游荡。",
	["The Highvale elves camp around {area:350}. Burn the report, the notes and the records in their camps. {npc:7780} is held inside the lodge: lead him out and fight off the ambush on the way.\nCareful: Groups of about three elves ambush the escort, usually twice."] = "高等精灵驻扎在 {area:350} 周围。在他们的营地中烧毁报告、笔记和记录。{npc:7780} 被关在小屋中：带他出来，击退途中伏击的敌人。\n小心：每波约三名精灵会伏击护送队伍，通常有两波。",
	["The big turtles crawl along the beaches north of the village, and {npc:2491}'s bottles of port lie on the same beaches, from the village up to the {area:307}: pick them up as you go. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "大乌龟在村子以北的海滩上爬行，{npc:2491}的波特酒瓶就在同一片海滩上，从村子一直到{area:307}：边走边捡。硬颚鳄鱼很少掉 OOX-09/HL 的遇险信标：留着。",
	["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "大海龟沿着村庄北边的海滩爬行。{npc:2491}的酒瓶也在这些海滩上，但他的任务不在本路线上。钳嘴龟可能掉落OOX-09/HL定位器，但很少见：留着它。",
	["The bloodmages"] = "血法师",
	["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "一箱箱{item:8684}散落在{area:351}被遗弃的部落营地周围，混在软泥怪中间。",
	["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills.\nEast of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south.\nCareful: Scorpok Stingers use {spell:5416}; {npc:8301} adds Knockdown."] = "这五个任务需要同一批怪物的身体部件：一次扫荡全部收齐。道路西侧的丘陵中，{npc:5982} 秃鹫、饥饿的弯牙土狼、厚甲毒刺蝎和死眼蜥蜴共同出没。\n道路东侧的斜坡上，灰鬃野猪和格朗特与石化蜥蜴一起活动。避开更南侧 52 级的地狱野猪。\n小心：厚甲毒刺蝎会使用 {spell:5416}；{npc:8301} 还会使用击倒。",
	["The ghostly orc stands by the road where the swamp meets the canyon into the {zone:1419}. Listen to his story."] = "幽灵兽人站在沼泽与通往{zone:1419}的峡谷相接处的路边。听完他的故事。",
	["The next guide starts here, at {area:3317}."] = "下一个指南从这里开始，在{area:3317}。",
	["The secret lies on the {area:307}, above the beach."] = "林吉的秘密在海滩上方的{area:307}。",
	["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "他们的后续任务又要同样的部件，换取一件增益物品，而且不给经验：别接。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人来一起做。{npc:7977}是48级精英：大多数职业50级可以单挑，但可能需要帮忙。如果只有你一个人就跳过：路线会安排你刷怪补经验。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "这些都是精英怪：建议组队，找其他玩家一起完成。{npc:7977} 是48级精英：大多数职业50级时可以单杀，但你可能需要帮忙。如果只有自己，就跳过；路线会安排你刷怪补回经验。\n{npc:7977} 沿着{area:307}下方的海岸行走，范围从箭头处向南到大约75,66，向北到大约82,52：如果她不在箭头处，就沿着海岸寻找。",
	["Underwater"] = "在水下",
	["Vilebranch Scalper"] = "邪枝剥皮者",
	["Vilebranch Soothsayer"] = "邪枝占卜者",
	["West of the island, the Vilebranch scalpers hold the temples of {area:1884} and {area:1917}. Slagtree's tools lie at one of the temples.\nThe Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and {area:351}. Use the {item:9618} on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for {npc:14738}'s second message.\nCareful: Silvermane Stalkers are level 47-48 and stay stealthed while out of combat. Up close they use {spell:7367}. When a {npc:2925} falls to 50% health or lower, it calls for help from anything within 25 yd."] = "岛屿西侧，邪枝剥皮者占据着 {area:1884} 和 {area:1917} 的神庙。斯拉提的工具就在其中一座神庙。\n银鬃捕猎者、野蛮的枭兽和翱翔的锋喙狮鹫共同出没在神庙与 {area:351} 之间的丘陵。对杀死的枭兽使用 {item:9618}。翱翔的锋喙狮鹫还会掉落细长的狮鹫羽毛：保留十根，用于 {npc:14738} 的第二封信。\n小心：银鬃捕猎者为 47-48 级，非战斗状态下会保持潜行，近身时使用 {spell:7367}。{npc:2925} 生命值降到 50% 或以下时，会呼叫 25 码内的所有怪物援助。",
	["for {npc:6986} in {zone:1454}, around level 50"] = "交给{zone:1454}的{npc:6986}，大约50级时",
	["for {npc:7623} in {area:75}, after the {zone:1419}"] = "给{area:75}的{npc:7623}，{zone:1419}之后",
	["for {npc:7825} in the {zone:1458}, around level 50"] = "交给{zone:1458}的{npc:7825}，大约50级时",
	["grind on {npc:2505}"] = "击杀{npc:2505}刷经验",
	["{area:1440}: kill these as you meet them"] = "{area:1440}：沿途遇到就击杀",
	["{area:1446} flight master"] = "{area:1446}的飞行管理员",
	["{area:1917}: kill these as you meet them"] = "{area:1917}：沿途遇到就击杀",
	["{area:307}: kill these as you meet them"] = "{area:307}：沿途遇到就击杀",
	["{area:321} flight master"] = "{area:321}飞行管理员",
	["{area:3317} flight master"] = "{area:3317}的飞行管理员",
	["{area:348} well"] = "{area:348}水井",
	["{area:355}: kill these as you meet them"] = "{area:355}：沿途遇到就击杀",
	["{item:8704}, a rare drop"] = "{item:8704}，稀有掉落",
	["{npc:14731}'s lunch"] = "{npc:14731}的午餐",
	["{npc:14731}, inside"] = "{npc:14731}：在屋内",
	["{npc:14736} stands up on top of the inn, above {npc:14731}: go up, the arrow cannot tell the levels apart."] = "{npc:14736}站在旅店的屋顶上，在{npc:14731}上方：走上去，箭头无法区分上下层。",
	["{npc:14757}, at the top of {area:354}"] = "{npc:14757}，在{area:354}顶上",
	["{npc:2926} on the way"] = "{npc:2926}，途中",
	["{npc:7643}'s The {npc:950} is a level 55 quest: leave it."] = "{npc:7643}的{npc:950}是55级任务：放着别做。",
	["{npc:7801}'s camp"] = "{npc:7801}的营地",
	["{object:2068}, on the beaches"] = "{object:2068}，在海滩上",
	["{quest:7849}, {quest:7845} and {quest:7850} are group quests: they send you into {area:354}, whose trolls are elite (46-50). Take them with a group of three or more; skip them if you are alone, the route has you grind the experience back.\n{npc:14736} stands up on top of the inn, above {npc:14731}: go up, the arrow cannot tell the levels apart."] = "{quest:7849}、{quest:7845}和{quest:7850}都是组队任务，会让你进入{area:354}，里面的巨魔都是精英（46-50级）。至少三人组队再做；独自一人就跳过，路线会安排刷怪补回经验。\n{npc:14736}站在旅店顶上、{npc:14731}的上方：往上走，箭头无法区分高低层。",
}

G["forever/horde/40-50/06-azshara"] = {
	["\"Sea Wolf\" MacKinley, on the top floor"] = "“海狼”马克基雷，位于最顶层",
	["Back north-east to {npc:8420}."] = "向东北回到{npc:8420}那里。",
	["Back to {area:1099}"] = "返回{area:1099}",
	["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "回到神殿的{npc:11548}那里；待在{area:3137}守卫的西边。",
	["Back to {object:3202}"] = "返回{object:3202}",
	["Below ground"] = "在地下",
	["Captain Keelhaul"] = "尼哈鲁船长",
	["Captain Stillwater"] = "斯蒂沃特船长",
	["Class trainer"] = "职业训练师",
	["Continue south to {area:35}. {npc:7406} has his workshop on the upper ring of the bay."] = "继续向南前往{area:35}。{npc:7406}的工作室在海湾的上层环道上。",
	["Fleet Master Firallon"] = "舰队指挥官菲尔拉伦",
	["Fly to {area:1099}"] = "飞往{area:1099}",
	["Fly to {area:1637}"] = "飞往{area:1637}",
	["Fly to {area:1638}"] = "飞往{area:1638}",
	["Fly to {area:35}"] = "飞往{area:35}",
	["Fly to {area:976}"] = "飞往{area:976}",
	["Fly to {object:3202}"] = "飞往{object:3202}",
	["Fly to {zone:1456}; it is on the way to {area:1099}. No flight path there yet? Fly to {area:378} and ride west through {zone:1412}. Hamuul and {npc:4046} are on the {area:1639}; Druids and Paladins train here ({npc:3033}, {npc:246344})."] = "飞往{zone:1456}；它在前往{area:1099}的路上。还没有那里的飞行路线？飞往{area:378}，再向西骑马穿过{zone:1412}。哈缪尔和{npc:4046}在{area:1639}；德鲁伊和圣骑士在这里训练（{npc:3033}，{npc:246344}）。",
	["Follow the road north out of {area:35}; the basilisks bask on the rocks east of it in the middle of the jungle, on the way back to {object:3202}. Their shards drop often."] = "沿道路向北出{area:35}；在回{object:3202}的路上，蜥蜴在丛林中部道路东边的岩石上晒太阳。它们经常掉落碎片。",
	["Follow the road north to {area:1237}, the Horde camp."] = "沿道路向北前往部落营地{area:1237}。",
	["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "沿道路向南；蜥蜴在丛林中部道路东边的岩石上晒太阳。它们经常掉落碎片。",
	["Frayfeather Hippogryphs"] = "乱羽角鹰兽",
	["Haldarr Felsworn"] = "哈达尔邪誓者",
	["Haldarr Satyr"] = "哈达尔萨特",
	["Haldarr Trickster"] = "哈达尔欺诈者",
	["Highborne Apparition"] = "上层精灵幻影",
	["Highborne Lichling"] = "上层精灵小巫妖",
	["Hippogryph nests"] = "角鹰兽巢穴",
	["If you skipped {quest:8552} or {quest:591}, grind here to level 49.93 to stay on the route's plan."] = "如果你跳过了{quest:8552}或{quest:591}，就在这里刷到49.93级，以跟上本路线的进度规划。",
	["Ironjaw Basilisks"] = "铁腭蜥蜴",
	["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "留着给{npc:4046}、{npc:8659}和{npc:6522}的货物：你之后会经过{zone:1456}、{zone:1454}和{zone:1458}。",
	["Keep {npc:8659}'s payment and Ag'tor's {quest:3504}: they go back to {area:1237} on a later visit."] = "留着{npc:8659}的报酬和阿格图的{quest:3504}：之后再去{area:1237}时交还。",
	["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "留着{quest:3444}：{npc:7771}的箱子要之后再来时才能打开。",
	["Level 49.93"] = "49.93级",
	["Level 50"] = "等级50",
	["On the way through {zone:1454} to the flight master, step into the Drag: {npc:7010} takes the insect report from {zone:1446}, and its experience shortens the top-up to 50 in {zone:1447}."] = "在穿过{zone:1454}前往飞行管理员的路上，顺路进暗巷区：{npc:7010}接收来自{zone:1446}的昆虫报告，这份经验能缩短在{zone:1447}补到50级的时间。",
	["Only once all three robots are home"] = "仅当三个机器人都回家后",
	["Paladin trainer"] = "圣骑士训练师",
	["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "沿道路向东离开碎木岗哨。{npc:11548}在道路旁的{area:1235}等候，位于联盟{area:3137}西边几步远：从西边过去，避开艾萨拉哨兵和加罗迪努斯（精英）。",
	["Ride into {area:16}"] = "骑进{area:16}",
	["Ride into {zone:1447}"] = "骑马进入{zone:1447}",
	["Ride north-east to the goblin's camp on the cliffs above the {area:1227}."] = "向东北骑往{area:1227}上方悬崖上的地精营地。",
	["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "沿道路向南骑往{area:1938}；{npc:7771}在旁边扎营。从这里向西的道路通往{zone:1449}，下一个指南从那里开始。",
	["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "向西南骑往废墟。四块石板散落在废墟中，由恶鞭纳迦看守；任何恶鞭海妖或恶鞭侍从都可能携带{npc:8420}的符文。",
	["Ride west back to {area:1237}."] = "向西骑回{area:1237}。",
	["South down the road again.\nRide south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "再次沿路向南。\n沿大路向南骑到{area:1938}；{npc:7771}就在旁边扎营。从这里向西的路向下通往{zone:1449}，即下一篇攻略开始的地方。",
	["South of Booty Bay, three Bloodsail ships lie off the {area:43}: {npc:2550}, {npc:2548} and {npc:2546} each stand on a deck with their crews. Swim out and work from ship to ship."] = "在藏宝海湾以南，三艘血帆海盗船停在{area:43}外的海面上：{npc:2550}、{npc:2548}和{npc:2546}各带船员站在一层甲板上。游过去，一艘一艘清。",
	["Sprite Darters"] = "小精龙",
	["Stay here: the next guide starts with the flight to {area:976}."] = "留在这里：下一篇攻略从飞往{area:976}开始。",
	["Take the zeppelin back to {zone:1454}."] = "乘飞艇返回{zone:1454}。",
	["The Bloodsail ships"] = "血帆海盗船",
	["The Droffers' shop is a few steps further into the Drag."] = "德罗弗斯兄弟的商店就在暗巷区里再往前几步。",
	["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "上层精灵的幽灵在神殿正北的废墟里出没；哈达尔萨特在更北一点的地方扎营。",
	["The Sea Elementals and Sea Sprays wash along the shore around the dock.\nThe Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "海元素和巨型海元素沿着码头周围的海岸活动。\n大地行者和峭壁巨人在码头北面的山丘游荡。先对每个巨人使用{item:18904}：缩小后，它们就不再是精英。每个被缩小的巨人都会掉落残渣；还要对尸体使用山岭巨人灵魂精华容器。",
	["The Thunderhead Hippogryphs fly over the hills just south of {area:1237}."] = "雷首角鹰兽在{area:1237}正南的山丘上空飞翔。",
	["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "血精灵的营地就在{npc:8420}南边。他的四件设备在营地周围的箱子里。",
	["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "精灵龙在营地正西的树林里飞来飞去。对你杀死的每一只使用容器。",
	["The flight from {area:75} lands at {area:117}."] = "从{area:75}起飞的航班降落在{area:117}。",
	["The hippogryph nests are on the hills to the south, around the {area:2522}; each holds an egg for the {object:142071}."] = "角鹰兽巢穴位于南边的山丘上，在{area:2522}周围；每个巢穴里都有一枚供{object:142071}使用的蛋。",
	["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "角鹰兽在营地西南的山丘上筑巢。杀死一只，然后对它的尸体使用灵魂精华容器。",
	["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "树人在营地和{zone:1444}中部之间的林间道路上游荡；数量很少，所以沿着小路找。",
	["The {object:142071}, in the middle of town"] = "{object:142071}，在镇子中央",
	["The {object:2076} beside {npc:2519}"] = "{npc:2519}旁边的{object:2076}",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:818} (level 47 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.\nCareful: Two elite caster guards, around level 45, stand with {npc:818} and join the fight together with him."] = "这些怪物是精英：建议组队，找人一起完成。{npc:818}（47级精英）需要两人小队。独自一人就跳过：路线会安排刷怪补回经验。\n小心：{npc:818} 身边有两名约45级的精英施法守卫，会与他同时加入战斗。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英敌人，建议寻找其他玩家组队完成。{quest:8552}需要 2 人小队。独自一人时可跳过，路线会安排刷怪补回经验。",
	["To {object:3202}"] = "前往{object:3202}",
	["Top up here to level 50: {quest:4493}, from {npc:7010} in {zone:1454} at the end of {area:16}, needs it. Or, with a group, run the {area:2100} dungeon or the {area:1417} dungeon instead."] = "在这里补到50级：{zone:1454}中{area:16}尽头的{npc:7010}给出的{quest:4493}需要这个等级。或者组队改去打{area:2100}副本或{area:1417}副本。",
	["Top up here to level 50: {quest:4493}, from {npc:7010} in {zone:1454} at the end of {zone:1447}, needs it. Or, with a group, run the {area:2100} dungeon or the {area:1417} dungeon instead."] = "在这里补到50级：{zone:1447}结束后，{zone:1454}的{npc:7010}提供的{quest:4493}需要达到这个等级。也可以组队刷{area:2100}或{area:1417}地下城。",
	["Undamaged Hippogryph Feathers"] = "完好无损的角鹰兽羽毛",
	["Upstairs"] = "在楼上",
	["Wandering Forest Walkers"] = "森林漫游者",
	["Xylem's tower stands on the cliff just north of {area:1237}; the path winds up its north side."] = "克希雷姆的塔建在{area:1237}正北的悬崖上；小路沿塔的北侧蜿蜒而上。",
	["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
	["grind on {npc:6125}"] = "击杀{npc:6125}刷经验",
	["{area:1099} flight master"] = "{area:1099}的飞行管理员",
	["{area:1108}: kill these as you meet them"] = "{area:1108}：沿途击杀以下目标",
	["{area:1221}: kill these as you meet them"] = "{area:1221}：沿途遇到就击杀",
	["{area:1236}: kill these as you meet them"] = "{area:1236}：沿途遇到就击杀",
	["{area:1237} flight master"] = "{area:1237}的飞行管理员",
	["{area:35} flight master"] = "{area:35}的飞行管理员",
	["{area:75} flight master"] = "{area:75}的飞行管理员",
	["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{zone:1456}的{npc:246344}；{zone:1454}没有圣骑士训练师",
	["{npc:2487}, on the balcony of the same building"] = "{npc:2487}，在同一栋楼的阳台上",
	["{npc:2491}, in the inn"] = "{npc:2491}，在旅店里",
	["{npc:5594}, inside"] = "{npc:5594}：在屋内",
	["{npc:6117} walks around {area:1235}: look inside the circle on the map"] = "{npc:6117}在{area:1235}附近巡逻，请在地图标出的圆圈内寻找",
	["{npc:6986}, the Drag"] = "{npc:6986}，在暗巷区",
	["{npc:7010}, the Drag"] = "{npc:7010}，在暗巷区",
	["{npc:7010}, the Drag: if you still carry it"] = "{npc:7010}，在暗巷区：如果你还带着它",
	["{npc:7406}, inside"] = "{npc:7406}：在屋内",
	["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}：熊在{zone:1448}",
	["{npc:7854}, inside"] = "{npc:7854}，在屋里",
	["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "{npc:7876}要的焦油和匹斯特苏格要的样本都来自{zone:1449}。",
	["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在双足飞龙管理员旁边",
	["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}，在营地东缘：没有经验，只能传送到克希雷姆的法师塔",
	["{npc:8659}, the {object:172960}"] = "{npc:8659}，在{object:172960}",
	["{object:3202} flight master"] = "{object:3202} 的飞行管理员。",
	["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761}在下一个指南中收集；{npc:4046}的报酬之后交还给{npc:8587}。",
