G["forever/horde/50-60/03-winterspring"] = {
	["Back south to {npc:7775}. Keep the elixir and don't drink it yet: it kills you, and that is how you meet Gaeriyan by {area:976} later."] = "向南回到{npc:7775}那里。留着药剂，先别喝：它会杀死你，而你之后正是这样在{area:976}旁见到盖瑞恩。",
	["Below ground"] = "在地下",
	["Both {item:14047} donations are handed in later in the route: save sixty {item:14047} for each if you want them."] = "两项 {item:14047} 捐献都安排在路线后面交还：如果打算完成，每项各留六十块 {item:14047}。",
	["Chillwind chimaeras"] = "冰风奇美拉",
	["Fly to {area:1099}"] = "飞往{area:1099}",
	["Fly to {area:1637}"] = "飞往{area:1637}",
	["Fly to {area:1638}"] = "飞往{area:1638}",
	["Gregor's and Harlo's quests lead to other zones: keep them."] = "格雷戈和哈鲁的任务会把你带到其他地区：留着它们。",
	["Gregor's quests lead to other zones: keep them."] = "格雷戈的任务会把你带到其他地区：留着它们。",
	["He stands on {area:1641}. Each donation wants sixty cloth from your bags: take them if you save cloth, and hand in what you carry later in the route."] = "他站在{area:1641}上。每次捐献需要你包里的六十块布：如果你会存布就接，之后在路线上把手头的交掉。",
	["Ice Thistle yetis"] = "冰蓟雪人",
	["In the {object:172958}."] = "在{object:172958}。",
	["In the {object:172961}."] = "在{object:172961}。",
	["In the {object:172961}. Each donation takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest."] = "在 {object:172961} 内。每次捐赠会收取背包中的六十块毛料、丝绸或魔纹布：交还随身带的，其余跳过。",
	["Into {area:618}"] = "进入{area:618}",
	["Into {zone:1452}"] = "进入{zone:1452}",
	["Level 55.04"] = "等级 55.04",
	["Linken's letter"] = "林克的信",
	["Matriarchs and Patriarchs hit hard: pull them one at a time."] = "冰蓟雪人女王和冰蓟雪人王攻击很重：一次引一只。",
	["Pathfinders, Den Watchers and Totemics share the furbolg camps around the hot springs; Ragged Owlbeasts roam the slopes between them. Kill Totemics first. Save every {item:14047} you loot for Meilosh."] = "冬泉探路者、冬泉巢穴守卫和冬泉图腾师共处于温泉周围的熊怪营地；蓬毛枭兽在营地之间的山坡上游荡。先杀冬泉图腾师。把拾取到的每一块{item:14047}都留给梅罗什。",
	["Pristine Yeti Horns"] = "完美的雪人角",
	["Ragged Owlbeast"] = "褴褛枭兽",
	["Raging Owlbeast"] = "狂暴枭兽",
	["Raging Owlbeasts"] = "狂暴的枭兽",
	["Raging Owlbeasts roam the hills north of {area:2251}, by the road between {area:2246} and {area:2255}."] = "狂怒的枭兽出没于{area:2251}北面的山丘，就在{area:2246}与{area:2255}之间的路旁。",
	["Ride south from the tunnel: {npc:9298} camps among the steaming pools of {area:2246}, in the west of the valley."] = "从隧道向南骑：{npc:9298}在山谷西部{area:2246}的热气池之间扎营。",
	["Ride west along the road past {area:2251}; Raging Owlbeasts roam the hills north of it."] = "沿道路向西经过{area:2251}；狂暴的枭兽在它北边的山丘上游荡。",
	["The chimaeras roam the snowfields south and west of {area:2255}. Stay clear of {area:2245}'s cave: its blue dragonkin are elite."] = "奇美拉在{area:2255}南边和西边的雪原上游荡。远离{area:2245}的洞穴：里面的蓝龙龙人都是精英。",
	["The furbolg village fills the valley north-east of {area:2255}. Kill Shamans first; they heal. {npc:10738} in the cave at the back is elite: stay out."] = "熊怪村庄占满了{area:2255}东北的山谷。先杀冬泉萨满祭司；他们会治疗。后面洞穴里的{npc:10738}是精英：别进去。",
	["The yeti hills start just south-east of {area:2255}. Every yeti drops fur; only Matriarchs and Patriarchs drop horns, so keep those for after the turn-in."] = "雪人的山丘就在{area:2255}东南不远处开始。每个雪人都会掉落毛皮；只有冰蓟雪人女王和冰蓟雪人王掉落角，所以交还后再去打它们。",
	["The {item:11242} grows inside a ruined building north of {npc:7775}'s camp, east of the harpies' {area:1114}: climb in through the broken part of its wall."] = "{item:11242}长在{npc:7775}营地北边、鹰身人的{area:1114}东边的一座废墟建筑里：从墙上破损的地方爬进去。",
	["Top up here to level 55.04 before the hand-ins at {area:2255}: they take you to level 56."] = "在{area:2255}交任务前在这里补到55.04级：那些任务会把你带到56级。",
	["Top up here to level 55.04 before the hand-ins at {area:2255}: they take you to level 56. Or, with a group, run the {area:1584} dungeon or the {area:1583} dungeon (Lower) instead."] = "在这里补到55.04级，再去{area:2255}交任务，交完会升到56级。也可以组队去{area:1584}副本或{area:1583}副本（下层）。",
	["Umi's third prank targets goblins in {area:976} and Un'Goro: keep it for later."] = "乌米的第三个恶作剧针对的是{area:976}和安戈洛环形山的地精：留到之后。",
	["Winterfall Den Watcher"] = "冬泉巢穴看守",
	["Winterfall Pathfinder"] = "冬泉探路者",
	["Winterfall Shaman"] = "冬泉萨满",
	["Winterfall Totemic"] = "冬泉图腾者",
	["Winterfall Ursa"] = "冬泉乌尔萨",
	["grind on {npc:7460}"] = "击杀{npc:7460}刷经验",
	["{area:2246}: kill these as you meet them"] = "{area:2246}：沿途击杀以下目标",
	["{area:2255} flight master"] = "{area:2255}的飞行管理员",
	["{area:2255} is the goblin town on the east side of the valley, past the owlbeast hills."] = "{area:2255}是山谷东侧的地精镇子，在枭兽丘陵过去一点。",
	["{area:2255} is the goblin town on the east side of the valley."] = "{area:2255}是山谷东侧的地精城镇。",
	["{area:2408} flight master"] = "{area:2408}的飞行管理员",
	["{item:11243}, {npc:7775}'s reward"] = "{item:11243}，{npc:7775}的奖励",
	["{item:12771}, a rare drop from the Winterfall furbolgs"] = "{item:12771}，冬泉熊怪的稀有掉落",
	["{item:12771}: about one Winterfall furbolg in ten carries one; keep killing them until it drops"] = "{item:12771}：大约十个冬泉熊怪里有一个带着；一直杀到掉为止",
	["{npc:10431}, inside"] = "{npc:10431}：在屋内",
	["{npc:10881} and {npc:14728} stand on {area:1641}. Each of Rumstag's donations takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest."] = "{npc:10881}和{npc:14728}站在{area:1641}。拉姆斯塔格的每项捐献都需要背包中六十份毛料、丝绸或魔纹布：带了什么就交什么，其余跳过。",
	["{npc:11118}: the last guide binds here, so this usually ticks at once"] = "{npc:11118}：上一份指南在这里绑定炉石，所以这一步通常会立即完成",
	["{npc:11556} stands by the {area:618} exit of {area:1769}'s tunnel, north of the hot springs."] = "{npc:11556}站在温泉以北{area:1769}隧道的{area:618}出口旁。",
	["{npc:11556} stands right at the {area:618} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556}就站在{area:1769}隧道的{area:618}出口，也就是你出来的地方。",
	["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556}就站在{area:1769}隧道的{zone:1452}出口处，也就是你出来的地方。",
	["{npc:11754} walks around {area:2255}: look inside the circle on the map"] = "{npc:11754}在{area:2255}一带走动：看地图上的圆圈内",
	["{npc:3033} on {area:1639}; {npc:246344}"] = "{area:1639}的{npc:3033}；{npc:246344}",
	["{npc:7440} on the way"] = "{npc:7440}，途中",
	["{npc:7451} on the way"] = "{npc:7451}，途中",
	["{npc:7775}, a dwarf, camps in the {area:1137} north-west of {area:1099}. He brews the {item:11243} only from an {item:11242} you bring him."] = "矮人{npc:7775}在{area:1099}西北的{area:1137}扎营。他只用你带来的{item:11242}调制{item:11243}。",
	["{npc:7775}, a dwarf, camps in the {area:1137} north-west of {area:1099}; he has the elixir."] = "矮人{npc:7775}在{area:1099}西北的{area:1137}扎营；他有药剂。",
	["{npc:9087} buys {item:11040} grown from your {quest:3761}.\nCareful: Gorishi Workers and Stingers cast {spell:8137}, and Hive Guards cast {spell:14120}. When a Worker drops to 45% health, it has a 50% chance to call for help from mobs within 25 yd."] = "{npc:9087}收购由你的{quest:3761}种出的{item:11040}。\n注意：戈里什工蜂和刺虫会施放{spell:8137}，虫巢守卫会施放{spell:14120}。工蜂生命值降到45%时，有50%几率向25码内的怪物呼救。",
	["{npc:9087} buys {item:11040} grown from your {quest:3761}. {quest:3782} wants ten, and the {item:11020} gives one try every ten minutes: take it only if you already have the grain."] = "{npc:9087}收购用{quest:3761}种出的{item:11040}。{quest:3782}需要十份，而{item:11020}每十分钟只能尝试一次：已有足够晨光麦再接。",
	["{npc:9298} camps among the steaming pools of {area:2246}, in the west of the valley."] = "{npc:9298}在山谷西部{area:2246}的热气腾腾的水池间扎营。",
	["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123}在{zone:1450}等候：留到之后。",
	["{quest:3909} comes from {npc:7775} in {zone:1444}, later in this guide."] = "{quest:3909}来自{zone:1444}的{npc:7775}，在本指南稍后。",
	["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084}要在{zone:1448}的{object:176091}交还，留到之后那一趟。",
	["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "{quest:8471}，冬泉熊怪的稀有掉落",
	["{zone:1456} flight master"] = "{zone:1456}飞行管理员",
}

G["forever/horde/50-60/04-azshara"] = {
	["Blood Elf Reclaimer"] = "血精灵回收者",
	["Blood Elf Surveyor"] = "血精灵勘测员",
	["Both {item:14047} donations are handed in later in the route: save sixty {item:14047} for each if you want them."] = "两项{item:14047}捐献都在路线后段交付：想要的话各留六十张{item:14047}。",
	["Cleansed Water goes to the {area:2479} in {zone:1448}: keep it for later."] = "净化后的水要送到{zone:1448}的{area:2479}：留到之后。",
	["Crossroads flight master"] = "十字路口飞行管理员",
	["Fly to {area:1237}"] = "飞往{area:1237}",
	["Fly to {area:1637}"] = "飞往{area:1637}",
	["Fly to {area:392}"] = "飞往{area:392}",
	["Fly to {zone:1454} and train."] = "飞往 {zone:1454} 学习技能。",
	["Fly to {zone:1454}; {npc:4485} is in the {object:172958}."] = "飞往{zone:1454}；{npc:4485}在{object:172958}。",
	["In the {object:172958}."] = "在{object:172958}。",
	["In the {object:172961}. Each donation takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest."] = "在{object:172961}。每项捐献从你背包中消耗六十张毛料、丝绸或魔纹布：身上带着的就交，其余跳过。",
	["Inside"] = "在里面",
	["Into {zone:1411}"] = "进入{zone:1411}",
	["Lady Sylvanas holds the {object:36126}."] = "希尔瓦娜斯女士在{object:36126}。",
	["Liv's workshop is at the north end of {area:392}'s docks; {object:149036} stands inside it."] = "莉芙的工作室在{area:392}码头北端；{object:149036}就在里面。",
	["Only with {quest:79095} from {area:159}'s alchemy shop in your bags (the Library Books guide)"] = "仅在背包中带有从{area:159}炼金店取得的书籍《{quest:79095}》时进行，详见《图书馆藏书》指南",
	["Paladin trainer"] = "圣骑士训练师",
	["Ride back west to {area:1237}."] = "向西骑回{area:1237}。",
	["Ride east out of the {zone:1458} along the road; the {area:152} guards the way into the {zone:1422}."] = "从{zone:1458}沿路向东骑；{area:152}守着进入{zone:1422}的路。",
	["Ride east to the ruins on the coast. Fill Cuely's four vials at the tide pools along the shore; Spitelash naga patrol between them."] = "向东骑往海岸边的废墟。在沿岸的海潮之池装满科雷的四个瓶子；恶鞭纳迦在海潮之池之间巡逻。",
	["Ride north up the road to the Crossroads; {npc:256386} stands there. Open each crate she hands you and bring back what is inside. Fly on to {area:1237} from the Crossroads."] = "沿路骑马向北前往十字路口；{npc:256386}就在那里。逐个打开她给你的箱子，将里面的东西交回。从十字路口继续飞往{area:1237}。",
	["Rimtori's camp is at the east end of the base camp. Read the {object:151286} there, then kill the Magus.\nCareful: Which crystal is linked to Rimtori is random. Each of the other two summons a hostile infernal instead."] = "大法师雷姆托里的营地在基地营地东端。阅读那里的{object:151286}，然后击杀魔导师。\n小心：与大法师雷姆托里相连的水晶是随机的。另外两块水晶都会改为召唤一只敌对地狱火。",
	["Take the zeppelin from the tower outside {zone:1454} to {zone:1420} and ride into the {zone:1458}. Lady Sylvanas holds the {object:36126}."] = "从{zone:1454}城外的塔楼乘飞艇到{zone:1420}，再进入{zone:1458}。希尔瓦娜斯女士坐镇{object:36126}。",
	["The blood elves camp on the cliffs in the north-east, by the {area:1227}."] = "血精灵在东北的悬崖上扎营，就在{area:1227}旁边。",
	["Upstairs"] = "在楼上",
	["Zeppelin to {zone:1458}"] = "乘飞艇前往{zone:1458}",
	["{area:1237} flight master"] = "{area:1237}的飞行管理员",
	["{npc:10778}'s farm is the first one east of the {area:152}. Jabbering Ghouls on the farm carry the other half of her charm; {npc:11075} guards the cauldron in the field.\nCareful: One or two undead usually fight alongside him, and more cauldron lords can attack after you use the cauldron."] = "{npc:10778}的农场是{area:152}以东第一座农场。农场里的喋喋不休的食尸鬼携带她护符的另一半；{npc:11075}守着田里的大锅。\n小心：通常有一两只亡灵与他并肩战斗，使用大锅后还可能有更多护锅者来袭。",
	["{npc:11044}, in the Apothecarium"] = "{npc:11044}，在炼金房",
	["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{npc:15188}，在{object:172957}：留着它去{zone:1451}",
	["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{zone:1456}的{npc:246344}；{zone:1454}没有圣骑士训练师",
	["{npc:256386} stands in the {area:380}. Open each crate she hands you and bring back what is inside."] = "{npc:256386}站在{area:380}。打开她交给你的每一个箱子，把里面的东西带回来。",
	["{npc:256386}'s crates"] = "{npc:256386}的箱子",
	["{npc:4485}, {object:172958}: carried from the first {zone:1447} visit, else take it here for {npc:8576} in {area:1237}"] = "{npc:4485}，{object:172958}：第一次去{zone:1447}时就带着它，否则在这里为{area:1237}的{npc:8576}接",
	["{npc:5901} camps on the shore just north of {area:392}."] = "{npc:5901}在{area:392}正北的海岸上扎营。",
	["{npc:8390} and {npc:8393} work in the Apothecarium."] = "{npc:8390}和{npc:8393}在炼金房工作。",
	["{npc:8393}, beside him"] = "{npc:8393}，在他旁边",
	["{npc:8403}, nearby"] = "{npc:8403}，在附近",
	["{npc:8578}'s camp"] = "{npc:8578}的营地",
	["{npc:8659}, the {object:172960}"] = "{npc:8659}，在{object:172960}",
	["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050}要交还给{zone:1422}的{npc:10778}：留着它。",
	["{zone:1454} flight master"] = "{zone:1454}飞行管理员",
}

G["forever/horde/50-60/05-eastern-plaguelands"] = {
	["Back through the tunnel and take the {area:618} exit, then ride south to {area:2246}."] = "穿过隧道走{area:618}出口，然后向南骑到{area:2246}。",
	["Back through the tunnel and take the {zone:1452} exit, then ride south to {area:2246}."] = "穿过隧道回去，走{zone:1452}出口，然后向南骑往{area:2246}。",
	["Back to {area:2268}"] = "返回{area:2268}",
	["Below ground"] = "在地下",
	["Both quests lead to {zone:1451}: keep them."] = "两个任务都通往{zone:1451}：留着它们。",
	["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "小心：{npc:10411}脱离战斗时会隐形，战斗开始后会召唤岩翼石像鬼。它们只有3只，每15分钟刷新一次。",
	["Class trainer"] = "职业训练师",
	["Darrowshire Spirit"] = "达隆郡幽灵",
	["Drink the {item:11243} at the graveyard just east of {area:976}: it kills you, and only as a ghost can you see {npc:9299}, in a rocky crevice in the hills due north of it. Talk to him there, then run back to your body and resurrect: the Conspicuous Gravestone he sends you to stands in that graveyard."] = "在{area:976}东边不远处的墓地喝下{item:11243}：它会杀死你，只有以鬼魂形态才能看到{npc:9299}，他在墓地正北方山丘中的一道岩缝里。在那里和他交谈，然后跑回尸体处复活：他让你去找的显眼的墓碑就在那片墓地里。",
	["Fly to {area:1099}"] = "飞往{area:1099}",
	["Fly to {area:1099}. The hippogryph nests are in the south of {zone:1444}; each holds an egg for the {object:142071}."] = "飞往{area:1099}。角鹰兽的巢在{zone:1444}南部；每个巢里都有一个蛋，用于{object:142071}。",
	["Fly to {area:1497}"] = "飞往{area:1497}",
	["Fly to {area:1638}"] = "飞往{area:1638}",
	["Fly to {area:1997}"] = "飞往{area:1997}",
	["Fly to {area:2268}"] = "飞往{area:2268}",
	["Fly to {area:272}"] = "飞往{area:272}",
	["Fly to {area:541}"] = "飞往{area:541}",
	["Fly to {area:976}"] = "飞往{area:976}",
	["Fly to {zone:1456}"] = "飞往{zone:1456}",
	["Follow the road east from the {zone:1422}, over the river and across the whole {zone:1423}, to the {object:92525}'s chapel in the far east."] = "沿道路从{zone:1422}向东走，过河后穿越整个{zone:1423}，前往最东边{object:92525}的礼拜堂。",
	["Free Darrowshire Spirits: talk to them"] = "解放达隆郡之魂：与它们交谈",
	["Frenzied Plaguehound"] = "狂乱的瘟疫犬",
	["Frenzied Plaguehounds and Monstrous Plaguebats share the fields around {area:2272} and {area:2271}, south of {area:2273}."] = "狂怒的瘟疫犬和巨型瘟疫蝙蝠共处于{area:2273}南边、{area:2272}和{area:2271}周围的田野上。",
	["Go through {area:1769} and take the {area:493} branch of the tunnel. {npc:11801} is in {area:2361}."] = "穿过{area:1769}，走隧道的{area:493}分支。{npc:11801}在{area:2361}。",
	["Go through {area:1769} and take the {zone:1450} branch of the tunnel. {npc:11801} is in {area:2361}."] = "穿过{area:1769}，走隧道通往{zone:1450}的岔路。{npc:11801}在{area:2361}。",
	["Inside"] = "在里面",
	["Keep {quest:5152}: {npc:10927} lives at {area:197} in the {zone:1422}."] = "留着{quest:5152}：{npc:10927}住在{zone:1422}的{area:197}。",
	["Monstrous Plaguebat"] = "巨型瘟疫蝙蝠",
	["Moontouched Owlbeast"] = "月触枭兽",
	["Moontouched Owlbeasts"] = "月光枭兽",
	["Noxious Plaguebat"] = "剧毒瘟疫蝙蝠",
	["On {area:1641}. Each donation takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest."] = "在{area:1641}。每次捐献需要从背包里拿出六十份毛料、丝绸或魔纹布：身上有就交，没有就跳过。",
	["Only if a {quest:8471} dropped for you: {npc:11558} waits at the {zone:1448} entrance of {area:1769}, and speaks to you only at Neutral with the Timbermaw."] = "仅当你掉落了{quest:8471}时：{npc:11558}在{area:1769}的{zone:1448}入口处等候，只有你在木喉要塞声望达到中立时才会和你说话。",
	["Only if you found a {item:12820} flask in {area:618}: ride north up the road. The cauldron stands in {area:1762}, just south-west of {area:1769}; the Deadwood furbolgs there are hostile."] = "只有在{area:618}找到{item:12820}药瓶时才做：沿路向北骑。大锅在{area:1762}，就在{area:1769}西南；那里的死木熊怪是敌对。",
	["Pathstrider"] = "巡路者",
	["Plaguebat"] = "瘟疫蝙蝠",
	["Plaguehound"] = "瘟疫犬",
	["Plaguehound Runt"] = "瘟疫犬幼崽",
	["Plaguehound Runts and Plaguebats roam the hills north of the {area:2260}, Carrion Grubs crawl among them; work north toward {area:2627}."] = "瘟疫幼犬和瘟疫蝙蝠在{area:2260}北边的山丘上游荡，腐肉虫在它们中间爬行；一路向北朝{area:2627}推进。",
	["Plaguehounds and their runts roam the shores of the lake south-west of the chapel.\nThe shattered sword lies on the ground north-west of the lake."] = "瘟疫犬和它们的幼崽在教堂西南的湖岸游荡。\n断裂的剑躺在湖西北的地上。",
	["Plaguehounds and their runts roam the shores of the lake south-west of the chapel; Plaguebats and Carrion Grubs share the ground.\nThe shattered sword lies on the ground north-west of the lake."] = "瘟疫犬和瘟疫犬幼崽在礼拜堂西南方的湖岸游荡，瘟疫蝙蝠和腐肉虫也在同一带活动。\n破碎的剑在湖泊西北方的地面上。",
	["Ranger"] = "游侠",
	["Ride back south to {area:272} and fly to {area:2268}."] = "向南骑回{area:272}，然后飞往{area:2268}。",
	["Ride east out of the {area:1497} along the road; the {area:152} guards the way into the {area:28}."] = "沿道路向东骑出{area:1497}；{area:152}把守着进入{area:28}的通道。",
	["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Pull them one at a time."] = "向东骑往{area:2255}，再从那里向北出去；月光枭兽在{area:2241}南坡的山丘上游荡。一次引一只。",
	["Ride north up the road from {area:272}. {npc:10927}'s house stands by the road at {area:197}, and {npc:10936}'s monument is in the graveyard behind it."] = "从{area:272}沿道路向北骑行。{npc:10927}的房子就在{area:197}的路边，{npc:10936}的纪念碑在房子后面的墓地里。",
	["Ride north up the road. The cauldron stands in {area:1762}, just south-west of {area:1769}; the Deadwood furbolgs there are hostile."] = "沿路向北骑。大锅在{area:1762}，就在{area:1769}西南；那里的死木熊怪是敌对的。",
	["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "向西北骑进安多哈尔。{npc:10667}在镇子西侧被毁的旅店里等候；里面的骷髅是54-57级，所以沿着边缘走。",
	["Ride south from the lodge to {area:2264}, on the road. {item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with {spell:10228}. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk."] = "从旅舍沿道路向南骑到{area:2264}。{item:15447}十分钟内就会腐烂：尽快杀掉镇里的天灾，同时用{item:15454}一次刷齐七块碎片。\n小心：隐形仆从在生命降到40%后会向25码内的同伴呼救。战斗外它们还会用{spell:10228}隐形。如果在镇子内部发生呼救，可能会有大量怪物加入战斗。在外围附近作战能降低这个风险。",
	["Ride south from the lodge to {area:2264}, on the road. {item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with {spell:10228}. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.\nWith {quest:5211} in your log (from {npc:11063} at the start of this guide), the Scourge around the town leave Darrowshire Spirits: talk to each one to free it. Free them before you start on the {item:15447}."] = "从小屋沿道路向南骑往{area:2264}。{item:15447}十分钟内就会变质：快速杀死镇上的天灾军团，然后立刻用{item:15454}把七块研磨好。\n小心：隐形仆从血量降到40%时会呼叫25码内的同伴求援。脱离战斗时它们还会用{spell:10228}隐形。如果在镇子里触发求援，大量怪物可能加入战斗。在镇子外围战斗可以降低这种风险。\n如果你的任务日志里有{quest:5211}（来自本指南开头的{npc:11063}），镇子周围的天灾军团死后会留下达隆郡之魂：与每一个交谈以解放它。先解放它们，再开始收集{item:15447}。",
	["Ride south-west to the ruins of {area:2738}. The {object:179565} for {quest:1123} sits inside one of the ruined houses."] = "向西南骑到{area:2738}的废墟。{quest:1123}要的{object:179565}在其中一间破屋里。",
	["Ride west to the {area:2260}."] = "向西骑往{area:2260}。",
	["Scare {npc:7583} with {item:12928}"] = "用{item:12928}吓唬{npc:7583}",
	["Sprinkle"] = "斯普林科",
	["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "编年史混在安多哈尔市政厅的霉烂的书卷中；逐一打开，直到找到正确的那本。",
	["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "娃娃的头和两侧身体散落在{npc:10926}周围的房屋里；在背包里把它们组合起来。",
	["The flight from {area:1997} lands in {zone:1456}: {npc:3033} (Druids) trains on {area:1639}, {npc:246344} (Paladins) in the city too."] = "从{area:1997}的航班降落在{zone:1456}：{npc:3033}（德鲁伊）在{area:1639}训练，{npc:246344}（圣骑士）也在城里。",
	["The flight lands at {area:541}: {npc:9997} stands beside the flight master, and {npc:8737} by the cave a few steps away. {npc:9997}'s work is in Un'Goro on the next guide's way back north."] = "飞行点在{area:541}降落：{npc:9997}站在飞行管理员旁，{npc:8737}在几步外的洞穴旁。{npc:9997}的活在安戈洛，下一篇指南往北回来时做。",
	["The high elf Rangers, Pathstriders and Woodsmen guard the lodge by {area:2275}; the Registry lies inside. Rangers reach 60: pull one at a time. Noxious Plaguebats fly over the fields on the way.\nThe skull sits in the {area:2622}, among Blighted Horrors and Plague Monstrosities."] = "高等精灵游侠、巡路者和伐木工守卫着{area:2275}旁的小屋；登记册在屋内。游侠最高60级：逐个引怪。途中田野上空有毒性瘟疫蝙蝠飞过。\n头骨在{area:2622}，周围有荒芜水元素和瘟疫畸兽。",
	["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "从安戈洛环形山出来的山口通往{area:3077}，那是{zone:1451}东北部的墓地。{npc:13220}站在坟墓之间。",
	["The {object:142071} machine"] = "{object:142071}机器",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:11897} is a level 60 elite: most classes solo it at level 62, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人一起做。{npc:11897} 是 60 级精英：多数职业在 62 级能单人击败，但你可能需要帮助。独自一人就跳过：路线会让你打怪补回这部分经验。",
	["To {area:197}"] = "前往{area:197}",
	["Tortured Druid"] = "受折磨的德鲁伊",
	["Tortured Sentinel"] = "受折磨的哨兵",
	["Underwater"] = "在水下",
	["Upstairs"] = "在楼上",
	["Use {item:12928} on {npc:7583}, the goblin girl in {area:976}. {npc:10977} and {npc:10978} are scared later in the route."] = "对{area:976}的地精女孩{npc:7583}使用{item:12928}。{npc:10977}和{npc:10978}在路线后面再吓唬。",
	["Woodsman"] = "林地守卫",
	["Zaeldarr lurks just west of {area:2262}."] = "扎尔达尔潜伏在{area:2262}西边不远处。",
	["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
	["a message for {npc:11063} at {area:2268}"] = "带给{area:2268}的{npc:11063}的口信",
	["{area:2255} flight master"] = "{area:2255}的飞行管理员",
	["{area:2268} flight master"] = "{area:2268}的飞行管理员",
	["{area:2277}: kill these as you meet them"] = "{area:2277}：沿途击杀以下目标",
	["{area:272} flight master"] = "{area:272}的飞行管理员",
	["{area:976} flight master"] = "{area:976}的飞行管理员",
	["{item:13853} on the way"] = "路上用{item:13853}",
	["{item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with {spell:10228}. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk."] = "{item:15447}十分钟内就会腐烂：尽快杀掉镇里的天灾，同时用{item:15454}一次刷齐七块碎片。\n小心：隐形仆从在生命降到40%后会向25码内的同伴呼救。战斗外它们还会用{spell:10228}隐形。如果在镇子内部发生呼救，可能会有大量怪物加入战斗。在外围附近作战能降低这个风险。",
	["{npc:10778}'s farm is the first one east of the {area:152}. Jabbering Ghouls on the farm carry the other half of her charm; {npc:11075} guards the cauldron in the field.\nCareful: One or two undead usually fight alongside him, and more cauldron lords can attack after you use the cauldron."] = "{npc:10778}的农场是{area:152}以东的第一座农场。农场里的呓语食尸鬼带着她符咒的另一半；{npc:11075}守着田里的大锅。\n小心：通常有一两只亡灵和他一起战斗，你使用大锅后还可能有更多大锅领主来袭。",
	["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "{npc:10926}的鬼魂站在西南方{area:2262}的废墟中。",
	["{npc:10927}, upstairs"] = "{npc:10927}，在楼上",
	["{npc:11140} the ghost stands by a hut in {area:2627}, in the north-west corner."] = "鬼魂{npc:11140}站在西北角{area:2627}的一间小屋旁。",
	["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558}在附近巡逻，请在地图标示的圆圈内寻找",
	["{npc:15193}'s champion holds the {area:2260} farmhouse, north of the {area:2261}."] = "{npc:15193}的勇士占据着{area:2261}北边{area:2260}的农舍。",
	["{npc:3033} (Druids) trains on {area:1639}, {npc:246344} (Paladins) in the city too."] = "{npc:3033}（德鲁伊）在{area:1639}提供训练，{npc:246344}（圣骑士）也在城里。",
	["{npc:3033} on {area:1639}; {npc:246344}"] = "{area:1639}的{npc:3033}；{npc:246344}",
	["{npc:7771} camps by the {area:1336} road, south of {area:976}."] = "{npc:7771}在{area:976}南边通往{area:1336}的路旁扎营。",
	["{npc:8565} walks around {area:2276}: look inside the circle on the map"] = "{npc:8565}在{area:2276}附近巡逻，请在地图标出的圆圈内寻找",
	["{npc:8600} on the way"] = "路上找{npc:8600}",
	["{npc:9299} is a ghost at the graveyard just north of {area:976}; the Conspicuous Gravestone is south of it, outside the town wall."] = "{npc:9299}是{area:976}正北墓地里的一个鬼魂；明显的墓碑在它南边、城墙外面。",
	["{quest:3914} goes back to Linken in Un'Goro: keep it."] = "{quest:3914}要交还给安戈洛的林克：留着它。",
	["{quest:3914} goes back to {npc:8737} in Un'Goro: keep it."] = "{quest:3914}要交还给安戈洛的{npc:8737}：留着它。",
	["{quest:3941} goes to {npc:9117} in the cave here, on the next guide's return to {area:541}: keep it."] = "{quest:3941}要交给这里洞穴里的{npc:9117}，下一篇指南回到{area:541}时：留着它。",
	["{quest:5086} are in {zone:1448}, on a later trip: keep it if you have it."] = "{quest:5086}在{zone:1448}，之后那一趟再去：如果你有就留着。",
	["{quest:5086} are in {zone:1448}, on a later trip: keep it."] = "{quest:5086}在{zone:1448}，以后再去：留着它。",
	["{quest:5168}'s items lie in the later Plaguelands zones: keep it."] = "{quest:5168}要的物品在之后的瘟疫之地地区：留着它。",
	["{quest:5211}'s spirits come with the {area:2264} stop later in this guide: keep it."] = "{quest:5211}的灵魂会在本指南稍后前往{area:2264}时完成：留着它。",
	["{zone:1423}: kill these as you meet them"] = "{zone:1423}：沿途击杀以下目标",
	["{zone:1454} flight master"] = "{zone:1454}飞行管理员",
	["{zone:1456} flight master"] = "{zone:1456}飞行管理员",
}

G["forever/horde/50-60/06-silithus"] = {
	["A torn scroll lies at the entrance of the {area:2261}, the crypt south of the {area:2260}."] = "一张破损的卷轴在{area:2260}南边的墓穴{area:2261}的入口处。",
	["Andorhal Tower Four"] = "安多哈尔塔楼四",
	["Andorhal Tower One"] = "安多哈尔塔楼一",
	["Andorhal Tower Three"] = "安多哈尔塔楼三",
	["Andorhal Tower Two"] = "安多哈尔塔楼二",
	["Andorhal watchtowers and silos"] = "安多哈尔的哨塔和粮仓",
	["Back east past the {area:202} to {area:201}, the farm under the eastern hills: {npc:11078} guards its cauldron. Kill him for the key, then use the cauldron."] = "向东经过{area:202}回到{area:201}，那是东边丘陵下的农场：{npc:11078}守着它的大锅。杀他拿钥匙，然后使用大锅。",
	["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "回到南风村，爬上塔。搅动塔顶的虫巢会引出亚什伏击者；其中一个携带{item:17346}。",
	["Back to {area:3425}"] = "返回{area:3425}",
	["Below ground"] = "在地下",
	["Careful: Ghouls and skeletons usually stand next to the boxes and attack when you come close. Searing ghouls also hurt anyone nearby and will break stealth."] = "小心：食尸鬼和骷髅通常站在箱子旁，你一靠近就会攻击。灼热食尸鬼还会伤害周围的人，并会打破潜行。",
	["Careful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "小心：安戈洛猩猩（50-51 级）的生命值降到 25% 时，会呼叫 20 码内的同伴援助。此地有一座满是猩猩的洞穴，在里面战斗会引来许多额外怪物。",
	["Cavalier Durgen"] = "骑士杜尔根",
	["Class trainer"] = "职业训练师",
	["Collect twenty Encrypted Twilight Texts from the cultists here, ten for {npc:15306} and ten for Ortell."] = "从这里的教徒身上收集二十份加密的上古之神文卷，十个给{npc:15306}，十个给奥泰尔。",
	["Collie is inside it."] = "科利在里面。",
	["Dithers offers {quest:964} ({quest:838}). Skip it."] = "迪瑟斯会给{quest:964}（{quest:838}）。跳过它。",
	["Dredge Crusher"] = "挖掘碾压者",
	["Dredge Crushers and Pincers"] = "掘泥摧毁者和巨钳蝎",
	["Dredge Striker"] = "挖掘打击者",
	["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "掘泥打击者、石鞭蝎和掠沙蜘蛛共处于要塞正北的沙地上。",
	["East along the road, {npc:11077} guards the cauldron at {area:200}."] = "沿道路向东，{npc:11077}守着{area:200}的瘟疫之锅。",
	["Escort {npc:9999}"] = "护送{npc:9999}",
	["Flayers and Rock Stalkers"] = "石鞭掠夺者和石行蜘蛛",
	["Fly to {area:1637}"] = "飞往{area:1637}",
	["Fly to {area:541}"] = "飞往{area:541}",
	["Fly to {area:976}. Still carrying {quest:2741}? The machine stands in the middle of town."] = "飞往{area:976}。还带着{quest:2741}吗？机器立在镇中央。",
	["Fly to {area:976}. The {object:142071} stands in the middle of town."] = "飞往{area:976}。{object:142071}立在镇中央。",
	["Frankal Stonebridge"] = "弗兰克尔·石桥",
	["Frenzied Pterrordax"] = "狂乱的翼手龙",
	["Hameya hides among the Mossflayer trolls of {area:2273}, in the north-east corner.\nCareful: The trolls along the path to {area:2273} are level 57-59. They run away at low health and call for help, so they often bring adds with them."] = "哈米亚 藏在东北角{area:2273}的烂苔巨魔之中。\n小心：通往{area:2273}的路上，巨魔为57-59级。它们低血量时会逃跑求援，经常引来额外怪物。",
	["Hameya's mound"] = "哈米亚的土堆",
	["Hameya's scroll"] = "哈米亚的卷轴",
	["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "沿西部沙丘向北；掘泥摧毁者和石鞭巨钳蝎分布在从这里到要塞的一带。",
	["Huntsman Radley"] = "猎人拉德利",
	["If you skipped {quest:6135}, grind here to level 59.14 to stay on the route's plan."] = "如果你跳过了{quest:6135}，就在这里刷到59.14级，以符合路线安排。",
	["If you skipped {quest:6135}, grind here to level 59.14 to stay on the route's plan. Or, with a group, run the {quest:838} dungeon or the {area:2279} dungeon instead."] = "如果跳过了 {quest:6135}，就在此刷到 59.14 级，跟上路线规划。也可组队前往 {quest:838} 副本或 {area:2279} 副本。",
	["Inside"] = "在里面",
	["Into {area:139}"] = "进入{area:139}",
	["Into {area:28}"] = "进入{area:28}",
	["Into {zone:1422}"] = "进入{zone:1422}",
	["Into {zone:1423}"] = "进入{zone:1423}",
	["Keep the bait: {npc:9684} is level 56, and the second loop passes his lair."] = "留着诱饵：{npc:9684}是56级，第二圈会经过它的巢穴。",
	["Keep {quest:3942}: {npc:9116} is at the {area:2479}, on the next guide's way through {zone:1448}."] = "留着{quest:3942}：{npc:9116}在{area:2479}，下一个指南穿过{zone:1448}时会经过。",
	["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "向北护送{npc:9999}前往{area:541}。他昏倒时，对他使用{item:11804}唤醒。",
	["Level 58"] = "58 级",
	["Level 59.14"] = "等级 59.14",
	["Mar'alith's next errand, Into the Maw of Madness, leads into {area:2744} among elites. Skip it."] = "玛尔利斯接下来的任务“深入疯狂之口”会带你进入精英遍布的 {area:2744}。跳过它。",
	["Mar'alith's {quest:8304} needs level 58 and leads into {area:2744} among elites. Skip it."] = "玛拉利斯的{quest:8304}需要58级，会带你进入精英遍布的{area:2744}。跳过它。",
	["Mark {npc:10902} with the {item:12815}"] = "用{item:12815}标记{npc:10902}",
	["Mark {npc:10903} with the {item:12815}"] = "用{item:12815}标记{npc:10903}",
	["Mark {npc:10904} with the {item:12815}"] = "用{item:12815}标记{npc:10904}",
	["Mark {npc:10905} with the {item:12815}"] = "用{item:12815}标记{npc:10905}",
	["North to the lumber camp; set the termite barrel down in the middle of the mill."] = "向北前往伐木场；把白蚁桶放在锯木厂中央。",
	["Paladin trainer"] = "圣骑士训练师",
	["Pamela and the {area:2261}"] = "帕米拉和 {area:2261}",
	["Pterrordax"] = "翼手龙",
	["Quixxil"] = "奎克希尔",
	["Radley and Durgen"] = "猎人莱德雷和骑士杜尔根",
	["Ride east to {area:537}, climb it and use {npc:10541} at the lava vent near the top, then ride back west to {npc:10302}."] = "向东骑往{area:537}，爬上去，在接近山顶的熔岩口使用{npc:10541}，然后向西骑回{npc:10302}那里。",
	["Ride east to {npc:1855}'s hut by the {area:2619} and hear him out."] = "向东骑往{area:2619}旁{npc:1855}的小屋，听他把话说完。",
	["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "向东北骑往{area:3077}；你从旁边的山口离开{zone:1451}。",
	["Ride north-east to {area:3447}."] = "向东北骑往{area:3447}。",
	["Ride north-west to {npc:1855}'s hut."] = "向西北骑往{npc:1855}的小屋。",
	["Ride south into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by the silos in the middle of town to bring out Temporal Parasites."] = "向南骑进安多哈尔。{npc:10667}在城镇西侧被毁的旅店里等候。拿着{item:12815}站在四座塔的每一个门口来标记它；沿城镇边缘走。在镇中央的粮仓旁使用{item:12627}引出时光寄生虫。",
	["Ride south-east from {npc:1855} to the {area:2261}; the {object:177675} is just behind it."] = "从{npc:1855}向东南骑到{area:2261}；{object:177675}就在它后面。",
	["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "向东南骑往安戈洛悬崖下的{area:3447}。",
	["Ride south-west to the ruins of {area:2738}. The {object:179565} for {npc:11801} sits inside one of the ruined houses."] = "向西南骑往{area:2738}的废墟。给{npc:11801}的{object:179565}在其中一座毁坏的房子里。",
	["Ride south-west to {npc:10667} in Andorhal."] = "向西南骑往安多哈尔的{npc:10667}那里。",
	["Ride to {area:2262} in the south-west; Pamela plays among the houses. {npc:11886} lurks in the {area:2261}, the crypt just west of the town.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot."] = "骑马前往西南的 {area:2262}；帕米拉在房屋之间玩耍。{npc:11886} 潜伏在 {area:2261}，也就是镇子正西边的墓穴。\n小心：墨丘利奥会带来约四只非精英小怪。它们会走到墓前，而不是直接在原地出现。",
	["Ride west to the Horde camp north of {area:2744}."] = "向西骑往{area:2744}北边的部落营地。",
	["Ride west to the walled hold in the middle of the desert. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "向西骑往沙漠中央有城墙环绕的要塞。{npc:15189}站在他那座建筑的楼上：从里面上楼，箭头分不清楼层。",
	["Rutgar Glyphshaper"] = "鲁特加·雕文者",
	["Scare {npc:10977} with {npc:10980}"] = "用{npc:10980}吓唬{npc:10977}",
	["Scourge Champions"] = "天灾勇士",
	["Scourge Champions roam the {area:2270}, north of the chapel. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants."] = "天灾勇士在教堂北边的{area:2270}游荡。在你杀死的每一个身上晃一晃{npc:11063}的{item:13156}：产生共鸣的头骨就是他要的。",
	["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "水晶尘喷泉在南部沙漠各处喷发。走进喷泉留下的水晶尘，把它带到吉里卡营地的部落水晶尘提取器；战斗或骑上坐骑都会让它掉落。",
	["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "石鞭掠夺者和石行蜘蛛在吉里卡营地西南的沙丘上游荡。",
	["Temporal Parasite"] = "时空寄生虫",
	["The Spirits of Southwind"] = "南风之灵",
	["The glowing tablet fragments lie around the Twilight camp in the far north-west; the Dust Stormers and Desert Rumblers there drop them too."] = "发光的石板碎片散落在遥远西北的暮光营地周围；那里的灰尘风暴和沙漠奔行者也会掉落碎片。",
	["The lake for {quest:5845}"] = "{quest:5845}要去的湖",
	["The libram lies further north, on the way to {area:190}."] = "圣契在更北边，通往{area:190}的路上。",
	["The lockboxes sit in Andorhal's ruined houses around {npc:10667}'s inn. Careful: Ghouls and skeletons usually stand next to the boxes and attack when you come close. Searing ghouls also hurt anyone nearby and will break stealth."] = "锁箱放在{npc:10667}所在旅店周围的安多哈尔废弃房屋里。小心：食尸鬼和骷髅通常站在箱子旁，你靠近时会发动攻击。灼热食尸鬼还会伤害附近所有人，并会打破潜行。",
	["The lumber mill is right beside Radley: set {npc:11615}'s termite barrel down in the middle of it."] = "伐木场就在拉德利旁边：把{npc:11615}的白蚁桶放在伐木场中央。",
	["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "从安戈洛环形山出来的山口通往{area:3077}，那是{zone:1451}东北部的墓地。{npc:13220}站在坟墓之间。",
	["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "诺格的背包在遥远南方的山里，过了铜须营地。精英蝎子死亡弯钩在附近巡逻：趁它走开时拿走背包。",
	["The shield lies at {area:201}, south of {npc:1855}'s hut."] = "盾牌在{npc:1855}小屋南边的{area:201}。",
	["The spare texts from the cultists"] = "信徒身上多出来的密文信",
	["The wooden sign beside {npc:9997}"] = "{npc:9997}旁边的木牌",
	["The {object:177675} is just behind the {area:2261}."] = "{object:177675}就在{area:2261}后面。",
	["Through the pass and east along the northern cliffs to {area:541}. {npc:8737} stands by the cave."] = "穿过山口，沿北侧峭壁向东到{area:541}。{npc:8737}站在洞穴旁。",
	["Through the pass and east along the northern cliffs to {area:541}. {npc:8737} stands by the cave; J.D."] = "穿过山口，沿北侧峭壁向东到{area:541}。{npc:8737}站在洞穴旁；J.D.",
	["Through the pass and east along the northern cliffs to {area:541}. {npc:9997} stands beside the flight master."] = "穿过山口，沿北边悬崖向东到{area:541}。{npc:9997}站在飞行管理员旁。",
	["Tortured Druid"] = "受折磨的德鲁伊",
	["Tortured Sentinel"] = "受折磨的哨兵",
	["Twilight Vanguard"] = "暮光先锋军营地",
	["Underwater"] = "在水下",
	["Upstairs"] = "在楼上",
	["Use the {item:11833} where the arrow points, inside the Gorishi hive of the {area:540}, to call the {npc:10041} (level 56)."] = "在 {area:540} 的格里什虫巢内、箭头所指的位置使用 {item:11833}，召唤 {npc:10041}（56 级）。",
	["Use {npc:10980} on {npc:10977}"] = "对{npc:10977}使用{npc:10980}",
	["West to the {area:152} one last time."] = "最后一次向西去{area:152}。",
	["West to the {area:152}."] = "向西前往 {area:152}。",
	["West to the {area:152}. The next guide starts in the {zone:1458}, a short ride west."] = "向西前往{area:152}。下一个指南从西边不远的{zone:1458}开始。",
	["Zeppelin to {zone:1458}"] = "乘飞艇前往{zone:1458}",
	["from the cauldron, for {npc:11055} at the {area:152}"] = "来自大锅，交给{area:152}的{npc:11055}",
	["grind on {npc:10717}"] = "击杀{npc:10717}刷经验",
	["grind on {npc:11880}"] = "击杀 {npc:11880} 刷经验",
	["ten for each quest: {npc:15306} takes his ten before Ortell"] = "每个任务十个：{npc:15306}的那十个先于奥泰尔交",
	["{area:1099} flight master"] = "{area:1099}飞行管理员",
	["{area:190}'s Scarlets are level 58-60. Ride in to the high point marked on your map, look over the town, and get out.\nCareful: Sentinels posted at the gate can detect stealthed players. Additional sentinels are found within the town, and an elite walks a patrol route nearby."] = "{area:190} 的血色十字军是 58-60 级。骑马进去，到地图标记的高点俯瞰镇子，然后离开。\n小心：门口的哨兵能侦测潜行玩家。镇内还有更多哨兵，附近也有一名精英巡逻。",
	["{area:490}: kill these as you meet them"] = "{area:490}：遇到这些就杀",
	["{area:976} flight master"] = "{area:976}的飞行管理员",
	["{item:20375} on the way"] = "路上用{item:20375}",
	["{item:20377} from {npc:11739}, 130 yd south-west"] = "从{npc:11739}身上获取{item:20377}，在西南130码处",
	["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302}让你去找{zone:1452}的{npc:9298}：留着它。",
	["{npc:10302} the goblin sits at {area:543}, just east of the pylon."] = "地精{npc:10302}坐在水晶塔正东的{area:543}。",
	["{npc:10667}'s Battle of Darrowshire ends against elites. Skip it."] = "{npc:10667}的达隆郡之战最后要对付精英。跳过它。",
	["{npc:10667}, upstairs"] = "{npc:10667}：在楼上",
	["{npc:11613} stands east of the lumber camp; {npc:11611} guards the road north-east of {npc:11610}, toward {area:190}.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "{npc:11613} 站在伐木营地东边；{npc:11611} 守在 {npc:11610} 东北、通往 {area:190} 的道路旁。\n小心：塔底有守卫，另有一名绕塔巡逻。与杜根·挽锤交战前先清掉它们，避免它们加入战斗。",
	["{npc:11741} walks around {area:2738}: look inside the circle on the map"] = "{npc:11741}在{area:2738}附近巡逻，请在地图标出的圆圈内寻找",
	["{npc:11803} walks the Vanguard camp in the far south-west. Every cultist here drops Encrypted Twilight Texts, quest or not: collect twenty, ten for {npc:15306} and ten for Ortell."] = "{npc:11803}在遥远西南的暮光先锋军营地里走动。这里的每个信徒都会掉落暮光密文信，不管你有没有任务：收集二十份，十份给{npc:15306}，十份给奥泰尔。",
	["{npc:11803} walks the Vanguard camp in the far south-west. Keep every {item:20404} the cultists drop: {npc:15306} and Ortell want ten each later."] = "{npc:11803}在最西南的先遣军营地一带走动。教徒掉的{item:20404}全部留着：{npc:15306}和奥泰尔以后各要十个。",
	["{npc:11804} stands in the outpost west of {area:3425}. Keep any Encrypted Twilight Texts that drop here too."] = "{npc:11804}在{area:3425}以西的前哨站。这里掉的加密的上古之神文卷也都留着。",
	["{npc:11804} stands in the outpost west of {area:3425}. Top your Encrypted Twilight Texts up to twenty on the cultists here."] = "{npc:11804}站在{area:3425}西边的前哨站里。在这里的信徒身上把暮光密文信补到二十份。",
	["{npc:15171} and {npc:15170} camp at Bronzebeard's Encampment, just north of the satchel's mountains. Question them: go through each one's whole conversation; there is no need to fight them."] = "{npc:15171} 和 {npc:15170} 在 Bronzebeard's Encampment 扎营，就在丢失背包所在山地的北边。询问他们：与两人分别完成全部对话；无需战斗。",
	["{npc:15181}'s {quest:8304}, at {area:3425}, needs level 58: top up on the Twilight Avengers, Geolords and Stonecallers west of the outpost. Or, with a group, run the {area:1583} dungeon (Lower) or the {quest:838} dungeon instead."] = "{area:3425} 的 {npc:15181} 提供的 {quest:8304} 需要 58 级：击杀前哨站西侧的暮光复仇者、暮光地王和暮光唤石者补足经验。也可组队前往 {area:1583} 副本（下层）或 {quest:838} 副本。",
	["{npc:15189} and {npc:15190} stand upstairs in their building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189}和{npc:15190}站在他们那座建筑的楼上：从里面上楼，箭头分不清楼层。",
	["{npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189}站在他那座建筑的楼上：从里面上楼，箭头分不清楼层。",
	["{npc:15190} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15190}站在他那座建筑的楼上：从里面上楼，箭头分不清楼层。",
	["{npc:15200} holds the camp in the west."] = "{npc:15200}占据着西边的营地。",
	["{npc:15306}, on the west side of the Hold"] = "{npc:15306}，在要塞西侧",
	["{npc:15306}, on the west side of the Hold: the texts are already in your bags"] = "{npc:15306}，在要塞西侧：文本已经在你包里了",
	["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{zone:1456}的{npc:246344}；{zone:1454}没有圣骑士训练师",
	["{npc:9117} is inside the cave."] = "{npc:9117} 在洞穴内。",
	["{npc:9117}, below ground"] = "{npc:9117}：在地下",
	["{npc:9167} walks around here: look inside the circle on the map"] = "{npc:9167}在这里一带走动：看地图圆圈内",
	["{npc:9619} now asks for {npc:9622}'s pelt, back in the north-east cave: skip it."] = "{npc:9619}接下来要东北洞穴里{npc:9622}的毛皮：跳过它。",
	["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "{npc:9684}的巢穴就在水晶塔正南。在那里使用{npc:9619}的诱饵；{npc:9684}是56级，攻击很重，所以满血再开始。",
	["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999}坐在山脊上，迷路了，筋疲力尽。",
	["{zone:1449}: kill these as you meet them"] = "{zone:1449}：沿途击杀以下目标",
	["{zone:1451}: kill these as you meet them"] = "{zone:1451}：沿途击杀以下目标",
}

G["forever/horde/50-60/07-felwood"] = {
	["Any Winterfall furbolg can carry the beads; the camps just south of {npc:11556} are the closest."] = "任何冬泉熊怪都可能携带冬泉灵魂珠串；{npc:11556}正南的营地最近。",
	["Back into the Timbermaw tunnel and take the {area:618} exit; {npc:9298} camps by the hot springs just outside."] = "回到木喉隧道，从{area:618}方向的出口出去；{npc:9298}就守在出口外的温泉旁。",
	["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "回到木喉隧道，走{zone:1452}出口；{npc:9298}就在出口外的温泉旁扎营。",
	["Back south to the Sanctuary, a short ride."] = "向南回到翡翠圣地，路程很短。",
	["Below ground"] = "在地下",
	["Class trainer"] = "职业训练师",
	["Corrupted Soul Shards from the cultists, {quest:5887}"] = "从信徒身上收集腐化的灵魂碎片，{quest:5887}",
	["Dungeon instead of grinding"] = "用地下城代替刷怪",
	["Fly to {area:431}"] = "飞往{area:431}",
	["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {area:361}. The {area:2479} is the druids' camp just past the border."] = "飞往{area:431}，沿离开{zone:1440}的路向西北骑行进入{area:361}。{area:2479}就是刚过边界处的德鲁伊营地。",
	["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "飞往{area:431}，沿道路向西北离开{zone:1440}进入{zone:1448}。{area:2479}是刚过边界的德鲁伊营地。",
	["From Krakle in Un'Goro"] = "来自安戈洛的克拉兰克",
	["From the {zone:1458}, take the zeppelin from the tower outside the city to {zone:1454}."] = "在{zone:1458}城外的塔上乘飞艇前往{zone:1454}。",
	["Frostfire Winterfall camp"] = "冰火温泉的冬泉熊怪营地",
	["Grind to 60"] = "刷到60级",
	["In the {object:172961}."] = "在{object:172961}。",
	["In {zone:1454}: fly from {area:2255}"] = "在{zone:1454}：从{area:2255}飞过去",
	["In {zone:1456}: fly from {area:2255}"] = "在{zone:1456}：从{area:2255}飞过去",
	["Legacki"] = "莱加基",
	["Level 59.54"] = "59.54级",
	["Level 59.9"] = "等级 59.9",
	["Moora"] = "穆拉",
	["On the way back south to {npc:10922}, {npc:9529} takes the shards on the west side of the Sanctuary."] = "在向南返回{npc:10922}的路上，在翡翠圣地西侧把碎片交给{npc:9529}。",
	["Only if you carry {quest:5087}: the runners walk the road from {area:1769} toward {area:2244} in small groups; wait by the road near {npc:9298} and kill them as they pass. Each one carries a crate.\nCareful: Turning in spawns three or four level 56-57 Winterfall ambushers that attack you; you can escape them while mounted, in stealth or with {spell:5384}, and they then gather by the lake so you can take the next quest."] = "只有带着{quest:5087}时才做：信使会成小队从{area:1769}沿路走向{area:2244}；在{npc:9298}附近的路边等着，经过时杀掉。每个信使都带着一个箱子。\n小心：交任务会刷出三到四个56-57级的冬泉伏击者攻击你；可以骑马、潜行或用{spell:5384}逃脱，之后它们会聚集在湖边，方便你接下个任务。",
	["Only if {npc:9298} gave you {quest:5086}: ride north up the {area:361} road to {area:1767}; the {quest:5086} ooze between the trees."] = "只有{npc:9298}给了你{quest:5086}时才做：沿{area:361}的路向北骑到{area:1767}；树丛间游荡着{quest:5086}软泥怪。",
	["Only with 30 {quest:6031}, and only at Neutral with the Timbermaw: follow the road north to {area:1769}; {npc:11557} trades just inside the entrance."] = "仅当你有30块{quest:6031}，且木喉要塞声望达到中立时：沿道路向北前往{area:1769}；{npc:11557}就在入口里面交易。",
	["Optional. Running {area:2279}, {area:2057}, Lower Blackrock Spire or {area:1584} with a group instead of grinding gets you there faster."] = "可选。和队伍一起刷{area:2279}、{area:2057}、黑石塔下层或{area:1584}，代替刷怪能更快到达。",
	["Optional: with a group, a 55-60 dungeon replaces the grind below."] = "可选：有队伍时，用一个55-60级的地下城代替下面的刷怪。",
	["Ride back west to {area:2246}."] = "向西骑回{area:2246}。",
	["Ride east along the road to {area:2255}."] = "沿道路向东骑往{area:2255}。",
	["Ride east, then south down {area:2249}. The Frostmaul giants there are elite level 59: keep to the middle and keep moving. The strange source is at the mouth of {area:2256}, at the south end."] = "向东骑行，然后向南下到{area:2249}。那里的霜槌巨人是59级精英：走在中间，保持移动。奇怪的源头在南端{area:2256}的入口处。",
	["Ride north along the road, past {area:1763}, to {area:1997}."] = "沿道路向北骑行，经过{area:1763}，前往{area:1997}。",
	["Ride north up the {zone:1448} road to {area:1767}; the {quest:5086} ooze between the trees, and most of them drop a droplet."] = "沿{zone:1448}的路向北骑到{area:1767}；{quest:5086}在树间渗流，大多数都会掉一滴。",
	["Ride north-west to {area:1763}. The four braziers stand among the Shadow Council's buildings; use the Cleansed Water on each one.\nCareful: Shadow Council mobs of level 53-55 fill the cave and often come in large linked groups, many with stuns. A group of 2-3 players is recommended."] = "骑行向西北前往 {area:1763}。四座火盆位于暗影议会的建筑之间；对每一座使用净化过的水。\n小心：洞穴中遍布 53-55 级的暗影议会怪物，它们经常以多只联动的大群出现，其中许多会昏迷技能。建议 2-3 名玩家组队。",
	["Salia"] = "萨莉亚",
	["Scare {npc:10978} with {npc:10980}"] = "用{npc:10980}吓唬{npc:10978}",
	["South to the Sanctuary once more."] = "再次向南前往翡翠圣地。",
	["The Deadwood totem from {area:1762}, if {npc:11558} didn't take it then: she waits at the tunnel mouth of {area:1769} and speaks to you from Neutral with the Timbermaw, which the Deadwood furbolgs of {zone:1448} brought you to."] = "{area:1762}的死木图腾，如果当时{npc:11558}没收：她在{area:1769}的隧道口等着，只要木喉声望达到中立就会跟你说话——这个声望是你在{zone:1448}打死木熊怪刷出来的。",
	["The quests run out here. Rabid Shardtooths prowl {area:2249} in southern {area:618}, south of the road from {area:2255}."] = "这里的任务到头了。狂乱的碎齿熊在{area:618}南部的{area:2249}出没，位于{area:2255}道路以南。",
	["The quests run out here. Rabid Shardtooths prowl {area:2249} in southern {zone:1452}, south of the road from {area:2255}."] = "任务到这里就没了。疯狂的碎齿熊在{zone:1452}南部的{area:2249}潜行，位于从{area:2255}出发的道路南边。",
	["The runners walk the road from {area:1769} toward {area:2244} in small groups; wait by the road near {npc:9298} and kill them as they pass. Each one carries a crate.\nCareful: Turning in spawns three or four level 56-57 Winterfall ambushers that attack you; you can escape them while mounted, in stealth or with {spell:5384}, and they then gather by the lake so you can take the next quest."] = "信使三五成群地沿路从{area:1769}往{area:2244}走；在{npc:9298}附近的路边等着，路过就杀。每人带一个板条箱。\n注意：交任务会刷出三到四个56-57级的冬泉伏击者攻击你；骑马、潜行或者用{spell:5384}都能甩掉，之后他们会聚在湖边，方便你接下一个任务。",
	["The zeppelin towers"] = "飞艇塔",
	["The {area:2479}"] = "{area:2479}",
	["Through the Timbermaw tunnel to {area:493}. {npc:11939} reads in a house in {area:2361}."] = "穿过木喉隧道前往{area:493}。{npc:11939}在{area:2361}的一间屋子里读书。",
	["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "穿过木喉隧道前往{zone:1450}。{npc:11939}在{area:2361}的一座房子里读书。",
	["Top up here to level 59.54 before the hand-ins at {area:1997} : they take you to level 60."] = "先在这里补到59.54级，再去{area:1997}交任务：这些任务会把你带到60级。",
	["Top up here to level 59.9 before the hand-ins at {area:618}: they take you to level 60."] = "先在这里补到59.9级，再去{area:618}交任务：这些任务会把你带到60级。",
	["Top up here to level 59.9 before the hand-ins at {area:618}: they take you to level 60. Or, with a group, run the {area:2057} dungeon or the {area:2279} dungeon instead."] = "先在这里补到59.9级，再去{area:618}交任务：这些任务会把你带到60级。或者组队改打{area:2057}地下城或{area:2279}地下城。",
	["Top up here to level 59.9 before the hand-ins at {zone:1452}: they take you to level 60. The Rabid Shardtooths (59) of {area:2249}, just north of the strange source, give far more experience than the furbolgs by {area:1769}. Or, with a group, run the {area:2057} dungeon or the {area:2279} dungeon instead."] = "在{zone:1452}交任务之前，在这里补到59.9级：那些任务会把你带到60级。{area:2249}的狂怒碎牙（59级）就在奇异源头以北，经验比{area:1769}边的熊怪高得多。或者组队去刷{area:2057}副本或{area:2279}副本。",
	["With 30 {quest:6031} in your bags: follow the road north to {area:1769}; {npc:11557} trades just inside the entrance."] = "包里有30个{quest:6031}：沿路向北到{area:1769}；{npc:11557}就在入口里侧交易。",
	["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
	["grind on {npc:7441}"] = "刷{npc:7441}",
	["grind on {npc:7446}"] = "刷{npc:7446}",
	["grind on {npc:7446} at {area:2249}, {area:618}"] = "在{area:2249}、{area:618}刷{npc:7446}",
	["grind on {npc:7446} at {area:2249}, {zone:1452}"] = "在{zone:1452}的{area:2249}刷{npc:7446}",
	["sixty {item:14047}"] = "六十块{item:14047}",
	["sixty {item:14047}, if you carry them"] = "六十个{item:14047}（如果你带着的话）",
	["{npc:10306}'s next {quest:4741} would bring you back here from {area:618}. Skip it."] = "{npc:10306}的下一个{quest:4741}会让你从{area:618}再回到这里。跳过它。",
	["{npc:10306}'s next {quest:4741} would bring you back here from {zone:1452}. Skip it."] = "{npc:10306}的下一个任务{quest:4741}会让你从{zone:1452}跑回这里。跳过它。",
	["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558}在附近巡逻，请在地图标示的圆圈内寻找",
	["{npc:11558}, at the tunnel mouth; walks around here: look inside the circle on the map"] = "{npc:11558}，在隧道口；在这一带走动：看地图上的圆圈里",
	["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "{npc:11801}的魔藤碎片需要{area:2577}。跳过它。",
	["{npc:11939} walks around {area:2361}: look inside the circle on the map"] = "{npc:11939}在{area:2361}巡逻，请在地图标示的圆圈内寻找",
	["{npc:9116}'s Silver Heart needs an {item:11173} from northern {area:361} and a ride back here. Skip it."] = "{npc:9116}的银色之心需要一块来自{area:361}北部的{item:11173}，还要再骑回这里。跳过它。",
	["{npc:9116}'s Silver Heart needs an {item:11173} from northern {zone:1448} and a ride back here. Skip it."] = "{npc:9116}的银色之心需要{zone:1448}北部的一个{item:11173}，还要再骑回这里。跳过它。",
	["{npc:9116}, inside"] = "{npc:9116}：在屋内",
	["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "{npc:9298}接下来让你去对付{npc:10738}，他是洞穴里的精英。跳过它。",
	["{npc:9529} stands on the west side of the Sanctuary, the way out to {area:1763}. With {quest:4102} done, her {quest:5887} asks for six Corrupted Soul Shards: the Shadow Council cultists in {area:1763} and {area:1770} drop them about one kill in three, and you fight dozens of them for {npc:10922}."] = "{npc:9529}站在翡翠圣地的西侧，也就是通往{area:1763}的出口处。完成{quest:4102}后，她的{quest:5887}要求你收集六块腐化的灵魂碎片：{area:1763}和{area:1770}的暗影议会信徒大约每击杀三个会掉落一块，而你为{npc:10922}要击杀几十个这样的信徒。",
	["{npc:9861}, {npc:9860} and {npc:9517} wait at the back of {area:1770}, the cave in {area:1763}'s north. Clear the tunnel as you go.\nCareful: The three bosses fight as a group. Kill the nearby mobs first so you don't pull extra enemies."] = "{npc:9861}、{npc:9860} 和 {npc:9517} 在 {area:1770} 深处等着，那是 {area:1763} 北边的洞穴。边走边清理通道。\n小心：三名首领会一起战斗。先清掉周围的小怪，避免额外引怪。",
	["{zone:1454} flight master"] = "{zone:1454}飞行管理员",
}

G["forever/horde/orc/01-durotar"] = {
	["Armored Scorpid"] = "装甲蝎子",
	["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "{npc:3126}在{area:362}西边的平原上爬行。驯服一只，然后返回{npc:3171}处。",
	["Back east to the shore north of {npc:275657}. Spitelash Scouts and Attendants hold the beach below {area:370}. Hunters: tame a {npc:3107} on the beach."] = "向东回到{npc:275657}北边的海岸。恶鞭斥候与恶鞭侍从占据着{area:370}下方的海滩。猎人：在海滩上驯服一只{npc:3107}。",
	["Back north-west to {area:362}: {npc:3139} first, then {npc:3147} in the watchtower, then {npc:3142} and {npc:266940} on the way out east to the shore."] = "向西北返回{area:362}：先找{npc:3139}，然后是瞭望塔里的{npc:3147}，再在向东前往海岸的路上找{npc:3142}和{npc:266940}。",
	["Back over the bridge and south along the {area:14} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "回到桥那边，沿{area:14}一侧的河岸向南，到一条窄径攀上山的地方：{npc:5900}在山顶守着神龛。上山时当心边缘，再沿同一条小径下来。",
	["Back over the bridge and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "返回桥的另一边，沿河流的{zone:1411}一岸向南，找到一条上山的狭窄小径：{npc:5900}守着山顶的神龛。上山时小心边缘，并沿原路下来。",
	["Back south to {area:362}."] = "向南返回{area:362}。",
	["Back to the Den"] = "返回洞穴",
	["Back to {area:14}"] = "回到{area:14}",
	["Back to {area:362}."] = "返回{area:362}。",
	["Back to {area:362}: {npc:3139}, then {npc:3142}."] = "回到{area:362}：先{npc:3139}，再{npc:3142}。",
	["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "回到{object:172960}找{npc:5875}。在那里的召唤法阵上使用{item:7464}，击败虚空行者以束缚它。",
	["Back to {zone:1411}"] = "返回{zone:1411}",
	["Below ground"] = "在地下",
	["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "火刃氏族祭司占据着{quest:827}的洞穴；任何一个都会掉落{item:4871}。{npc:3204}是14级术士，站在洞穴深处，掉落{item:4903}。",
	["Class trainer"] = "职业训练师",
	["Deathskip to Northern Durotar"] = "利用死亡传送至杜隆塔尔北部",
	["Deathskip to {area:367}"] = "通过死亡赶路前往{area:367}",
	["Die to the mobs at 52.0,21.4 ({npc:3118}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "在52.0,21.4让怪物（{npc:3118}）杀死你：在那里死亡会被送到这座墓地。释放灵魂，并接受{npc:6491}的复活。",
	["Die to the mobs at 66.9,87.2 ({npc:3206}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "在 66.9,87.2 让怪物（{npc:3206}）杀死你：在那里死亡会送你到这座墓地。释放灵魂，找 {npc:6491} 复活。",
	["Dire Mottled Boar"] = "凶暴杂斑野猪",
	["Druid trainer"] = "德鲁伊训练师",
	["Dustwind Savage"] = "尘风野蛮人",
	["Dustwind Storm Witch"] = "尘风风暴女巫",
	["Felstalkers roam the slope below the cave, on the valley's north side."] = "地狱捕猎者在山谷北侧、洞穴下方的山坡上游荡。",
	["Follow the road north from {area:362} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "沿道路从{area:362}向北到{zone:1454}的正门，就在{area:817}西边。{npc:3352}和猎人训练师一起站在{object:172958}。",
	["Follow the road north from {area:379} to {area:1637}'s main gate. The next guide starts in {area:1637}: {quest:829} takes the cultists' quest, the trainers teach your new ranks, and the zeppelin leaves from the towers outside the gate for {zone:1420} and {zone:1421}. {area:17} come after Silverpine."] = "沿道路从{area:379}向北到{area:1637}的正门。下一份指南从{area:1637}开始：{quest:829}接取邪教徒的任务，训练师教你新的技能等级，飞艇从门外的塔楼飞往{zone:1420}和{zone:1421}。{area:17}排在银松森林之后。",
	["Follow the road north from {area:379} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "从 {area:379} 沿路向北，前往 {zone:1454} 正门，就在 {area:817} 西边。{npc:3352} 与猎人训练师一起站在 {object:172958}。",
	["Follow the road north from {area:379} to {zone:1454}'s main gate. The next guide starts in {zone:1454}: {quest:829} takes the cultists' quest, the trainers teach your new ranks, and the zeppelin leaves from the towers outside the gate for {zone:1420} and {zone:1421}. {zone:1413} come after Silverpine."] = "从 {area:379} 沿路向北到 {zone:1454} 正门。下一篇指南从 {zone:1454} 开始：将邪教徒任务交给 {quest:829}，向训练师学习新等级技能，再从城门外的飞艇塔乘飞艇前往 {zone:1420} 和 {zone:1421}。银松森林之后再去 {zone:1413}。",
	["Follow the road west from {area:362} over the {area:814} bridge; {area:379} sits just above it on the {area:17} side."] = "从{area:362}沿路向西，过{area:814}桥；{area:379}就在桥上方{area:17}那一侧。",
	["Follow the road west from {area:362} over the {area:814} bridge; {npc:5810} stands at {area:379}, just above it on the {area:17} side."] = "从{area:362}沿路向西，过{area:814}桥；{npc:5810}站在{area:379}，就在桥上方{area:17}那一侧。",
	["Free {npc:275811} and see her safely out of the crag"] = "救出{npc:275811}，护送她安全离开峭壁",
	["Head north-east to the road toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "向东北前往通向 {zone:1454} 的道路。{npc:3293} 在路旁扎营；失窃的袋子散落在他南面的道路沿线。",
	["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "向南穿过群岛。被遗忘的洛阿神像散落在南部各岛；巫毒巨魔和{npc:3207}守着它们，并掉落{item:275724}。{quest:826}和明希纳的笼子在最南边的岛上。",
	["Hexed Troll"] = "妖术巨魔",
	["Inside"] = "在里面",
	["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "进入洞穴后，在第一个岔口直走，然后右转，沿左手边的溪流走到瀑布：镐在水边、一根石柱后面发光。",
	["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "进入洞穴后，一直沿右侧洞壁绕行，越过溪流：{npc:3183}在尽头等候。",
	["Into {zone:1454}"] = "进入{zone:1454}",
	["Kul Tiras Marine"] = "库尔提拉斯陆战队员",
	["Kul Tiras Sailor"] = "库尔提拉斯水手",
	["Lazy Peon"] = "懒惰的苦工",
	["Level 10"] = "等级 10",
	["Lieutenant Benedict"] = "本尼迪克特中尉",
	["Mage trainer"] = "法师训练师",
	["Makrura and surf crawlers line the beaches north-east of Sen'jin.\nThe gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin."] = "龙虾人和冲浪蟹分布在森金东北的海滩上。\n侏儒工具箱在{area:362}以东和东南沿岸的残骸里。沿海岸向南到森金。",
	["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "米莎·托克伦的小屋在蜥蜴南边。西边{area:814}沿岸的鳄鱼带着{item:4891}。",
	["Mottled Boar"] = "杂斑野猪",
	["North-east to the beach below {area:370}, north of {npc:275657}: Spitelash Scouts and Attendants hold it. Hunters: tame a {npc:3107} on the beach."] = "向东北到{area:370}下方的海滩，在{npc:275657}以北：恨鳞斥候和侍从占着那里。猎人：在海滩上驯服一只{npc:3107}。",
	["On the way"] = "途中",
	["Paladin trainer"] = "圣骑士训练师",
	["Prickly pears"] = "仙人掌果",
	["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "钢鬃野猪人和钢鬃斥候占据着镇子西边的小屋；钢鬃传令兵和钢鬃卫兵占据着更西边的营地。",
	["Razormane Battleguard"] = "钢鬃战斗守卫",
	["Razormane Dustrunner"] = "钢鬃奔尘者",
	["Razormane Quilboar"] = "钢鬃野猪人",
	["Razormane Scout"] = "钢鬃斥候",
	["Ridgeshade Creeper"] = "脊影爬行者",
	["Ridgeshade Lurker"] = "脊影潜伏者",
	["Savages and Storm Witches nest in {area:370}, east of {npc:3293}. A Storm Witch drops the {item:277661}. Shamans: the Burning Blade Cultists by {area:371}, at the ravine's south end, drop the {item:6652}."] = "恶鞭海妖和风暴女巫栖居在 {npc:3293} 东侧的 {area:370}。风暴女巫会掉落 {item:277661}。萨满祭司注意：峡谷南端 {area:371} 旁的火刃祭司会掉落 {item:6652}。",
	["Spitelash naga"] = "恶鞭纳迦",
	["Summoned Voidwalker"] = "召唤的虚空行者",
	["Surf Crawler"] = "冲浪蟹",
	["Tame it with the {item:15908}"] = "用{item:15908}驯服它",
	["The gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin.\nMakrura and surf crawlers line the beaches north-east of Sen'jin."] = "侏儒工具箱散落在{area:362}东边和东南边海岸的残骸中。沿海岸向南前往森金村。\n森金村东北的海滩上遍布着玛克鲁拉和浪花蟹。",
	["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "城堡位于{area:362}东南方的海岸上。袭击者的斧头、弓和盾牌在城堡外围。库尔提拉斯水手和库尔提拉斯水兵掉落{item:4870}。{npc:3192}在城堡顶层等候；他的钥匙能打开他旁边的箱子，里面有{item:4881}。",
	["The prickly pears grow among the quilboar huts just west of town."] = "仙人掌果生长在镇子西边的野猪人小屋之间。",
	["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "被遗弃的训练武器散落在洞穴和训练场周围；{npc:3098}在整个山谷谷底游荡。",
	["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595}在{area:817}，就在你刚才对付的祭司中间。",
	["Thunder Lizards and Lightning Hides graze on {area:369} across the bridge; any of them can drop a {item:6486}."] = "{npc:3130}和{npc:3131}在桥对面的{area:369}上吃草；任何一只都可能掉落{item:6486}。",
	["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}."] = "雷霆蜥蜴和闪电蜥蜴在 {area:369} 活动，就在北上 {zone:1454} 的路旁；两者都可能掉落 {item:6486}。下一篇指南经过 {area:379} 时，将它交给 {npc:5810}。",
	["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "雷霆蜥蜴和闪电蜥蜴在 {area:369} 活动，就在北上 {zone:1454} 的路旁；两者都可能掉落 {item:6486}。下一篇指南经过 {area:379} 时，将它交给 {npc:5810}。\n小心：12级精英哈利科尔在{area:369}的蜥蜴群中游荡：拉怪前先留意他的位置。",
	["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nFizzle holds the Burning Blade camp on {area:369}, north-west of {area:362}. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly."] = "雷霆蜥蜴和闪电蜥蜴在 {npc:3293} 西面及西南面不远处的 {area:369} 吃草。\n费索 占据着 {area:362} 西北面 {area:369} 的火刃营地。猎人：途中用 {item:15908} 驯服一只 {npc:3099}。\n小心：费索 周围有火刃教徒，部分敌人两两联动，会一起进入战斗，而且刷新很快。",
	["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nFizzle holds the Burning Blade camp on {area:369}, north-west of {area:362}. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "雷霆蜥蜴和闪电蜥蜴在 {npc:3293} 西面及西南面不远处的 {area:369} 吃草。\n费索占据着 {area:362} 西北面 {area:369} 的火刃营地。猎人：途中用 {item:15908} 驯服一只 {npc:3099}。\n小心：费索周围有火刃祭司，部分敌人两两联动，会一起进入战斗，而且刷新很快。\n小心：12级精英哈利科尔在{area:369}的蜥蜴群中游荡：拉怪前先留意他的位置。",
	["Thunder lizards across the river"] = "河对岸的雷霆蜥蜴",
	["Thunder lizards on the way north"] = "北上途中的雷霆蜥蜴",
	["To {area:1637}"] = "前往{area:1637}",
	["To {zone:1454}"] = "前往{zone:1454}",
	["Top up here to level 10: {quest:840}, at {area:362}, needs level 10."] = "在这里补足经验到10级：{area:362} 的 {quest:840} 需要10级。",
	["Training weapons and boars"] = "训练武器和野猪",
	["Underwater"] = "在水下",
	["Upstairs"] = "在楼上",
	["Vile Familiar"] = "邪恶小鬼",
	["Voodoo Troll"] = "巫毒巨魔",
	["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there.\nDurotar Tigers roam the isle as well as the shore south of Sen'jin, and the Taillasher eggs sit in nests on the isles and along the beach."] = "涉水前往北侧的回音岛。血爪族母 在那里的迅猛龙之间徘徊。\n杜隆塔尔猛虎在岛上以及森金村南侧的海岸游荡，鞭尾龙的卵则在群岛上和海滩沿线的巢中。",
	["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there.\nWade back west to the shore south of Sen'jin. Durotar Tigers roam it and the Taillasher eggs sit in nests along the beach."] = "涉水到北边的回音群岛。女族长在那里的一群迅猛龙中游荡。\n再涉水向西回到森金以南的海岸。杜隆塔尔虎在那里游荡，尾鞭蛇的蛋在沿滩的巢里。",
	["Wake {quest:5441} with the {item:16114}"] = "用{item:16114}叫醒{quest:5441}",
	["West from {area:362} over the {area:814} bridge: {npc:3337} and {npc:5810} stand together at {area:379} above it. From there the road north through {area:14} leads to {zone:1454}."] = "从{area:362}向西，过{area:814}桥：{npc:3337}和{npc:5810}一起站在桥上方的{area:379}。从那里沿道路向北穿过{area:14}就到{zone:1454}。",
	["West from {area:362} over the {area:814} bridge: {npc:3337} and {npc:5810} stand together at {area:379} above it. From there the road north through {zone:1411} leads to {zone:1454}."] = "从 {area:362} 向西，过 {area:814} 的桥：{npc:3337} 和 {npc:5810} 一起站在桥上方的 {area:379}。从那里沿路向北，穿过 {zone:1411} 即可到 {zone:1454}。",
	["West over the {area:814} bridge, past {area:379} and on along the ridge: {npc:5907} stands alone above the Razormane camp."] = "向西跨过 {area:814} 的桥，经过 {area:379}，沿山脊继续走：{npc:5907} 独自站在钢鬃营地上方。",
	["West over the {area:814} bridge: {npc:3337} stands at {area:379} above it, on your way to {npc:5907}."] = "向西过 {area:814} 的桥：{npc:3337} 在桥上方的 {area:379}，去找 {npc:5907} 时顺路经过。",
	["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "顺便：在{npc:2704}处学习法杖（{object:172958}，10银币）；猎人的近战武器主要看属性，而双手武器属性最多。",
	["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "顺便：向{npc:2704}（{object:172958}，10银币）学习法杖；升级期间，法杖提供的法术属性比单手武器多。",
	["grind on {npc:3111}"] = "击杀{npc:3111}刷经验",
