	["the bounty board"] = "悬赏布告板",
	["{area:16622}: kill these as you meet them"] = "{area:16622}：沿途击杀以下目标",
	["{area:16623}: kill these as you meet them"] = "{area:16623}：沿途击杀以下目标",
