	["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "{npc:3063}的任务：击败他旁边的三名{npc:10721}（或在决斗中击败玩家）。",
	["{npc:3065} stands at the north end of {area:222}. Tame with the {item:15908}: an {npc:2956} on the plains, a {npc:2959} north of the village, a {npc:2970} to the north-west."] = "{npc:3065} 站在 {area:222} 北端。用 {item:15908} 驯服：平原上的一只 {npc:2956}、村庄北侧的一只 {npc:2959}，以及西北方的一只 {npc:2970}。",
	["{npc:3067}: Camping 101 asks you to learn it"] = "{npc:3067}：露营 101 要求你学习这项技能",
	["{npc:3069}, beside {npc:3067}: {quest:97934}"] = "{npc:3069}，在{npc:3067}旁边：{quest:97934}",
	["{npc:3155} in {zone:1411}; {zone:1412} has no rogue trainer"] = "{zone:1411} 的 {npc:3155}；{zone:1412} 没有潜行者训练师",
	["{npc:3156} in {zone:1411}; {zone:1412} has no warlock trainer"] = "{zone:1411}的{npc:3156}；{zone:1412}没有术士训练师",
	["{npc:3209} walks around {area:221}: look inside the circle on the map"] = "{npc:3209}在{area:221}附近巡逻，请在地图标出的圆圈内寻找",
	["{npc:3209}, next to {npc:2980}; walks around {area:221}: look inside the circle on the map"] = "{npc:3209}，在 {npc:2980} 旁；会绕着 {area:221} 走动：查看地图圆圈内的区域",
	["{npc:3222} walks around {area:222}: look inside the circle on the map"] = "{npc:3222}在{area:222}附近巡逻，请在地图标出的圆圈内寻找",
	["{npc:3418} stands at {area:378}, where the road from {zone:1412} meets the {area:458} north to the Crossroads."] = "{npc:3418}站在{area:378}，即从{zone:1412}出来的道路与向北通往十字路口的{area:458}交汇处。",
	["{npc:3418}: for {npc:3429} at the Crossroads"] = "{npc:3418}：交给十字路口的{npc:3429}",
	["{npc:3429}, by the wind rider tower"] = "{npc:3429}，在双足飞龙塔旁",
	["{npc:3441}: for {quest:860} at the Crossroads"] = "{npc:3441}：交给十字路口的{quest:860}",
	["{npc:3441}: for {quest:860} at the {area:380}"] = "{npc:3441}：交给{area:380}的{quest:860}",
	["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}：鹰身女妖以后才会出现，在{area:383}",
	["{npc:3483} sells armor on the north side of the Crossroads. His bundle goes to {npc:3615}, who sends it with you on the flight to {zone:1456} you take for {npc:3033} anyway."] = "{npc:3483}在十字路口北侧出售护甲。他的包裹要交给{npc:3615}，后者会让你飞往{zone:1456}时一并带上，反正你也要去找{npc:3033}。",
	["{npc:3483} sells armor on the north side of the {area:380}. His bundle goes to {npc:3615}, who sends it with you on the flight to {zone:1456} you take for {npc:3033} anyway."] = "{npc:3483}在{area:380}北侧出售护甲。他的包裹要交给{npc:3615}；你反正会为{npc:3033}飞往{zone:1456}，他就让包裹随你一同送达。",
	["{npc:3615}, the wind rider master"] = "{npc:3615}，双足飞龙管理员",
	["{npc:5543} stands in the {area:2197}, the cave under {area:1640}: go down inside, the arrow cannot tell the floors apart."] = "{npc:5543}站在{area:2197}，即{area:1640}下方的洞穴里：走进去下楼，箭头无法区分楼层。",
	["{npc:5769}: for {npc:3448} at the Crossroads"] = "{npc:5769}：交给十字路口的{npc:3448}",
	["{npc:5769}: for {npc:3448} at the {area:380}"] = "{npc:5769}：交给{area:380}的{npc:3448}",
	["{npc:5888} stands in {area:221}. {quest:1516} needs level 4, which you reach with the turn-ins here."] = "{npc:5888}站在{area:221}。{quest:1516}需要4级，交完这里的任务就能达到。",
	["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}：{npc:5873}和你的{item:5175}",
	["{npc:5906}, a few steps from {npc:5543} on {area:1640}"] = "{npc:5906}，在 {area:1640}，距 {npc:5543} 只有几步",
	["{npc:6290}, beside {npc:3067}: {quest:97936}"] = "{npc:6290}，在{npc:3067}旁边：{quest:97936}",
	["{npc:6746}, at the south end of the central rise: the hearth from {quest:5922} brings you back here"] = "{npc:6746}，在中央高地的南端：{quest:5922}中的炉石会带你回到这里",
	["{npc:6746}: {quest:5926}, for {npc:3033} on {area:1639}"] = "{npc:6746}：{quest:5926}，交给 {area:1639} 的 {npc:3033}。",
	["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to {npc:2980}."] = "{npc:6775}站在营地西端，位于{npc:2961}出没的山丘西北角：接下他的任务，从那里向南和向东猎杀美洲狮，然后回到{npc:2980}处。",
	["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, then hunt the cougars south through the hills towards the Seer's tent at their foot."] = "{npc:6775}站在营地西端，位于山狮出没的山丘西北角：接下他的任务，然后向南穿过山丘猎杀山狮，一路走向山脚下灰舌先知的帐篷。",
	["{npc:8359}, by the wind riders on the central rise"] = "{npc:8359}，在中央高地的风骑士旁",
	["{object:2910}, 170 yd east"] = "{object:2910}，东边170码",
	["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "{quest:96130}是一只独狼，在村子西边的平原上潜行。{npc:2959}和{npc:3035}在村子北边和西边的平原上游荡。",
	["{zone:1412}: kill these as you meet them"] = "{zone:1412}：沿途击杀以下目标",
	["{zone:1454}'s {object:172982}"] = "{zone:1454}的{object:172982}",
}

G["forever/horde/troll/01-durotar"] = {
	["Armored Scorpid"] = "装甲蝎子",
	["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "{npc:3126}在{area:362}西边的平原上爬行。驯服一只，然后返回{npc:3171}处。",
	["Back east to the shore north of {npc:275657}. Spitelash Scouts and Attendants hold the beach below {area:370}. Hunters: tame a {npc:3107} on the beach."] = "向东回到{npc:275657}北边的海岸。恶鞭斥候与恶鞭侍从占据着{area:370}下方的海滩。猎人：在海滩上驯服一只{npc:3107}。",
	["Back north-west to {area:362}: {npc:3139} first, then {npc:3147} in the watchtower, then {npc:3142} and {npc:266940} on the way out east to the shore."] = "返回西北方的{area:362}：先找{npc:3139}，然后是瞭望塔里的{npc:3147}，再在向东前往海岸的路上找{npc:3142}和{npc:266940}。",
	["Back over the bridge and south along the {area:14} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "回到桥那边，沿{area:14}一侧的河岸向南，到一条窄径攀上山的地方：{npc:5900}在山顶守着神龛。上山时当心边缘，再沿同一条小径下来。",
	["Back over the bridge and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "返回桥的另一边，沿河流的{zone:1411}一岸向南，找到一条上山的狭窄小径：{npc:5900}守着山顶的神龛。上山时小心边缘，并沿原路下来。",
	["Back south to {area:362}."] = "向南返回{area:362}。",
	["Back to the Den"] = "返回洞穴",
	["Back to {area:14}"] = "回到{area:14}",
	["Back to {area:362}."] = "返回{area:362}。",
	["Back to {area:362}: {npc:3139}, then {npc:3142}."] = "回到{area:362}：先{npc:3139}，再{npc:3142}。",
	["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "回到{object:172960}找{npc:5875}。在那里的召唤法阵上使用{item:7464}，击败虚空行者以束缚它。",
	["Back to {zone:1411}"] = "返回{zone:1411}",
	["Below ground"] = "在地下",
	["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "火刃氏族祭司占据着{quest:827}的洞穴；任何一个都会掉落{item:4871}。{npc:3204}是14级术士，站在洞穴深处，掉落{item:4903}。",
	["Class trainer"] = "职业训练师",
	["Deathskip to Northern Durotar"] = "利用死亡传送至杜隆塔尔北部",
	["Die to the mobs at 52.0,21.4 ({npc:3118}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "在52.0,21.4让怪物（{npc:3118}）杀死你：在那里死亡会被送到这座墓地。释放灵魂，并接受{npc:6491}的复活。",
	["Dire Mottled Boar"] = "凶暴杂斑野猪",
	["Druid trainer"] = "德鲁伊训练师",
	["Dustwind Savage"] = "尘风野蛮人",
	["Dustwind Storm Witch"] = "尘风风暴女巫",
	["Felstalkers roam the slope below the cave, on the valley's north side."] = "地狱捕猎者在山谷北侧、洞穴下方的山坡上游荡。",
	["Follow the road east out of the valley to {area:367} on the coast."] = "沿道路向东离开山谷，到海岸边的{area:367}。",
	["Follow the road north from {area:362} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "从{area:362}沿路向北到{zone:1454}正门，就在{area:817}以西。{npc:3352}和猎人训练师们站在{object:172958}里。",
	["Follow the road north from {area:379} to {area:1637}'s main gate. The next guide starts in {area:1637}: {quest:829} takes the cultists' quest, the trainers teach your new ranks, and the zeppelin leaves from the towers outside the gate for {zone:1420} and {zone:1421}. {area:17} come after Silverpine."] = "沿道路从{area:379}向北到{area:1637}的正门。下一份指南从{area:1637}开始：{quest:829}接取邪教徒的任务，训练师教你新的技能等级，飞艇从门外的塔楼飞往{zone:1420}和{zone:1421}。{area:17}排在银松森林之后。",
	["Follow the road north from {area:379} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "从{area:379}沿路向北，前往{zone:1454}正门，就在{area:817}西边。{npc:3352}和猎人训练师们一起站在{object:172958}。",
	["Follow the road north from {area:379} to {zone:1454}'s main gate. The next guide starts in {zone:1454}: {quest:829} takes the cultists' quest, the trainers teach your new ranks, and the zeppelin leaves from the towers outside the gate for {zone:1420} and {zone:1421}. {zone:1413} come after Silverpine."] = "从{area:379}沿路向北前往{zone:1454}正门。下篇指南从{zone:1454}开始：把邪教徒相关的任务交给{quest:829}，找训练师学习新等级技能，然后到城门外的高塔乘飞艇，前往{zone:1420}和{zone:1421}。银松森林之后才去{zone:1413}。",
	["Follow the road west from {area:362} over the {area:814} bridge; {area:379} sits just above it on the {area:17} side."] = "从{area:362}沿路向西，过{area:814}桥；{area:379}就在桥上方{area:17}那一侧。",
	["Follow the road west from {area:362} over the {area:814} bridge; {npc:5810} stands at {area:379}, just above it on the {area:17} side."] = "从{area:362}沿路向西，过{area:814}桥；{npc:5810}站在{area:379}，就在桥上方{area:17}那一侧。",
	["Free {npc:275811} and see her safely out of the crag"] = "救出{npc:275811}，护送她安全离开峭壁",
	["Grunt Kor'ja"] = "步兵科尔加",
	["Head north-east to the road toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "向东北前往通向 {zone:1454} 的道路。{npc:3293} 在路旁扎营；失窃的袋子散落在他南面的道路沿线。",
	["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle.\nWade back west to the shore south of Sen'jin when the isles are done."] = "向南穿过群岛。洛阿神像遍布南部岛屿；巫毒巨魔和妖术巨魔守着它们，并掉落妖术护符。{quest:826}和敏希娜的笼子在最南端的岛上。\n完成群岛后，涉水向西返回森金村南边的海岸。",
	["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle.\nWade back west to the shore south of Sen'jin. Durotar Tigers roam it and the Taillasher eggs sit in nests along the beach."] = "向南穿过群岛。洛阿神像遍布南部岛屿；巫毒巨魔和中邪的巨魔守着它们，并掉落中邪吊坠。{quest:826}和明希娜的笼子在最南边的岛上。\n向西涉水回到森金以南的海岸。杜隆塔尔猛虎在那里游荡，鞭尾鳄的蛋在沿海滩的巢里。",
	["Heal and fortify {npc:12430}"] = "治疗{npc:12430}并为她施加坚韧",
	["Hexed Troll"] = "中邪的巨魔",
	["Inside"] = "在里面",
	["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "进入洞穴后，在第一个岔口直走，然后右转，沿左手边的溪流走到瀑布：镐在水边、一根石柱后面发光。",
	["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "进入洞穴后，一直沿右侧洞壁绕行，越过溪流：{npc:3183}在尽头等候。",
	["Into {zone:1454}"] = "进入{zone:1454}",
	["Kul Tiras Marine"] = "库尔提拉斯水兵",
