	["{npc:6784} stands by the farmhouse at the {area:156}, on the way to the Crusader's Outpost."] = "{npc:6784}站在{area:156}的农舍旁，在前往十字军前哨的路上。",
	["{npc:6784}, by the farmhouse: talk to him for the duel; he offers it once {npc:5688} has his letter"] = "{npc:6784}，在农舍旁：与他交谈开始决斗；{npc:5688} 收到他的信后，他才会提供这个任务",
	["{object:1661} is under the {area:153}, beside the zeppelin towers. {npc:5675} is in the {object:36082}: use the {item:6284} on the summoning circle beside him and defeat the voidwalker. {npc:4606} is in the {object:36070}. {npc:4568} is in the {object:36082} too."] = "{object:1661}在{area:153}下方，飞艇塔旁边。{npc:5675}在{object:36082}：在他旁边的召唤法阵上使用{item:6284}，击败虚空行者。{npc:4606}在{object:36070}。{npc:4568}也在{object:36082}。",
	["{object:178090} is in the {area:154} graveyard, beside the church."] = "{object:178090}在教堂旁的{area:154}墓地里。",
	["{object:37098} stands beside {npc:1662} at the camp's south end."] = "{object:37098}在营地南端的{npc:1662}旁边。",
	["{quest:90902}: the {npc:259377} lie around the church. Heal five of them with {spell:635}."] = "{quest:90902}：{npc:259377}躺在教堂周围，用{spell:635}治疗其中5人。",
	["{quest:91208}: the {npc:246143} fled into the hills west of the church, on the way to {area:155}."] = "{quest:91208}：{npc:246143} 逃进了教堂西边的山丘，就在前往 {area:155} 的路上。",
	["{zone:1420}: kill these as you meet them"] = "{zone:1420}：沿途遇到就击杀",
}

G["forever/miscellaneous/stalk-with-the-earthmother"] = {
	["A one-hand blade or mace at 11 from {npc:205729}'s three tests in and around {zone:1456}, for a Tauren of any class."] = "11级时完成{npc:205729}在{zone:1456}内外的三项考验，可获得一把单手剑或单手锤，适合任何职业的牛头人。",
	["Back to {npc:205729} in {zone:1456}. He gives you the {item:206176} for his next test."] = "回到 {zone:1456} 找 {npc:205729}。他会给你 {item:206176}，用于下一项考验。",
	["Back to {npc:205729}. He hands you the {item:206344} for the last test."] = "回到{npc:205729}。他给你{item:206344}，用于最后一项考验。",
	["Back to {npc:205729}. He hands you the {item:206344}: the fish must be filleted in front of him."] = "回到{npc:205729}那里。他会把{item:206344}交给你：鱼必须在他面前切成鱼片。",
	["Buy a {item:6291} at the Auction House ({npc:8674}, north of the pool), or fish one yourself: {npc:3028} trains {skill:356} and {npc:3029} beside him sells the {item:6256} and a {item:6529}; the pool on the main mesa gives smallfish at any skill."] = "在拍卖行（{npc:8674}，水塘北边）买一个{item:6291}，或者自己钓：{npc:3028}教授{skill:356}，他旁边的{npc:3029}出售{item:6256}和{item:6529}；主台地上的水塘在任何技能等级都能钓到小鱼。",
	["Buy a {item:6291} at the Auction House ({npc:8674}, north of the pool), or fish one yourself: {npc:3028} trains {skill:356} and {npc:3029} beside him sells the {item:6256} and a {item:6529}; the pool on the main mesa gives smallfish at any skill. Then use the {item:206344} on it, wherever you are."] = "在拍卖行买一条{item:6291}（{npc:8674}，在水池以北），或者自己钓：{npc:3028}教{skill:356}，他旁边的{npc:3029}卖{item:6256}和{item:6529}；主台地的水池随便什么技能都能钓到小鱼。然后在你所在的地方对它使用{item:206344}。",
	["Fish Chunks"] = "鱼肉块",
	["Loot 5 Seaforium Mining Charges from the Blasting Supplies"] = "从爆破物资中拾取5个硝化甘油采矿炸药",
	["Loot 5 Seaforium Mining Charges from the {object:403041}"] = "从{object:403041}中拾取5枚塞弗拉姆采矿炸药",
	["Ride down the lift and south-east across {zone:1412} to the {area:360}. Put on the disguise, then open the carts of Blasting Supplies inside the mine and on the slope outside its far side; stay on the upper levels where you can, the lower tunnels are packed. Five charges."] = "乘升降机下去，向东南穿过{zone:1412}到{area:360}。穿上伪装，然后在矿洞内以及矿洞另一侧外的斜坡上打开爆破物资推车；尽量待在上层，下层隧道里怪物很密集。五个炸药。",
	["Ride down the lift and south-east across {zone:1412} to the {area:360}. Put on the disguise, then open the carts of {object:403041} inside the mine and on the slope outside it; stay on the upper levels where you can, the lower tunnels are packed. Five charges."] = "坐升降机下去，向东南穿过{zone:1412}到{area:360}。换上伪装，然后打开矿洞里和外面坡上的{object:403041}车；能待在上层就待上层，下层隧道挤得很。五次充能。",
	["Ride down the lift and south-east across {zone:1412} to the {area:360}. Put on the disguise, then open the carts of {object:403041} inside the mine and on the slope outside its far side; stay on the upper levels where you can, the lower tunnels are packed. Five charges."] = "乘升降机下去，向东南穿过{zone:1412}到{area:360}。穿上伪装，然后打开矿内和矿另一侧外面坡地上的{object:403041}推车；尽量待在上层，下层坑道挤满了怪。需要五份炸药。",
	["Stand beside {npc:205729} and use the {item:206344} on the smallfish: it only counts next to him. Then take your weapon: the {item:277988} or the {item:278002}."] = "站在{npc:205729}旁边，对小鱼使用{item:206344}：只有在他身边才算数。然后领取武器：{item:277988}或{item:278002}。",
	["Take your weapon from {npc:205729}: the {item:277988} or the {item:278002}."] = "从{npc:205729}那里领取武器：{item:277988}或{item:278002}。",
	["Venture Co. Mine"] = "风险投资公司矿洞",
	["Windfury Cones"] = "风怒球果",
	["Windfury Cones lie on the ground under the harpies' nest trees on {area:819}, north-west of {zone:1456}; the harpies do not drop them. The Windfury Sorceresses (level 9-10) and Matriarchs (10-11) there stand close together: pick the cones from the edges. Once you have eight, use the {item:206176} to grind them."] = "风怒球果 散落在{zone:1456}西北面{area:819}的鹰身人巢树下；鹰身人不会掉落。当地的风怒女巫（9-10级）和族母（10-11级）站得很密：从边缘拾取松果。收集8个后，使用{item:206176}研磨。",
	["fillet the smallfish into {item:206345} (where players did it, on the way back to {npc:205729})"] = "把小鱼片成{item:206345}（玩家都在这做，就在回{npc:205729}的路上）",
	["grind the eight cones"] = "磨碎八个松果",
	["grind the eight cones into the {item:206175}"] = "把八个锥果在研钵里磨成{item:206175}",
	["in front of {npc:205729}"] = "在{npc:205729}面前",
	["the mortar takes all eight"] = "研钵要全部八个",
	["{item:206157}, from the {object:403041}"] = "{item:206157}，来自{object:403041}",
	["{item:6291}: the Auction House, or the pool"] = "{item:6291}：拍卖行，或水塘",
	["{item:6291}: the Auction House, or the pool; the knife takes it"] = "{item:6291}：拍卖行，或者水池；刀能处理它",
	["{npc:205729} hides in stealth on the main mesa of {zone:1456}, south of its pool: walk to where the arrow points until his outline shows. He hands you the Venture Co Disguise. The quest opens at level 4, but the mine holds Venture Co. Workers (level 8-9), Supervisors (9-10) and {npc:3051} (12): go at 9 or 10."] = "{npc:205729}潜行藏在{zone:1456}主台地上、水塘南边：走到箭头所指的位置，直到他的轮廓显现。他会把风险投资公司伪装交给你。任务4级就能接，但矿里有风险投资公司工人（8-9级）、监工（9-10级）和{npc:3051}（12级）：9级或10级再去。",
	["{npc:205729} hides in stealth on the main mesa of {zone:1456}, south of its pool: walk to where the arrow points until his outline shows. He hands you the {item:206159}. The quest opens at level 4, but the mine holds Venture Co. Workers (level 8-9), Supervisors (9-10) and {npc:3051} (12): go at 9 or 10."] = "{npc:205729}潜行在{zone:1456}主台地上、水池南边：走到箭头所指的位置，直到他的轮廓显现。他会交给你{item:206159}。任务4级即可接，但矿洞里有风险投资公司工人（8-9级）、监工（9-10级）和{npc:3051}（12级）：建议9或10级再去。",
}

G["forever/reputation/darkspear-trolls"] = {
	["+150"] = "+150",
	["A {npc:3118} may drop a {item:277661}: use it to start {quest:97281}. Once you hand that in, {npc:3293} offers {quest:97282}."] = "{npc:3118} 可能掉落 {item:277661}：使用它开始 {quest:97281}。交还后，{npc:3293} 会提供 {quest:97282}。",
	["Blackrock Mountain, with a group"] = "黑石山，组队前往",
	["Bloodtalon Matriarch Eggs"] = "血爪族母的蛋",
	["Boars, weapons and peons"] = "野猪、武器与苦工",
	["Darkspear Trolls Reputation"] = "暗矛巨魔声望",
	["Darkspear reputation comes from quests and cloth. {npc:14727}, the Darkspear cloth quartermaster, stands in {zone:1454}'s {object:172961}. She takes four one-time donations of 60 cloth (150 each) and then {quest:7837}, 20 {item:14047} for 50, as often as you like. Every point you earn with the {faction:530} also gives a quarter as much to {zone:1454}, {zone:1456} and the {zone:1458}. While you level, do the Darkspear quests within 5 levels of them: {zone:1411} at 5 to 12, {area:414} in {zone:1440} at 19 to 27, {object:3202} in Stranglethorn at 34 to 46. The Legacy perk Diplomat adds up to 10%. Rewards: at Honored the Darkspear merchants sell to you for 10% less (the Classic rule), the raptor vendor included; at Exalted other races can buy the raptors: 20 gold for a level 40 raptor, 200 gold for a swift raptor at level 60, once you have mount training. The {faction:530} have no tabard or other reward."] = "暗矛声望来自任务和布料。暗矛布料军需官{npc:14727}站在{zone:1454}的{object:172961}。她先接受四次各60块布的一次性捐献（每次150声望），然后开放{quest:7837}，每20块{item:14047}换50声望，可无限重复。你每获得一点{faction:530}声望，也会向{zone:1454}、{zone:1456}和{zone:1458}各溢出四分之一。练级时，在任务等级与自身相差不超过5级时完成暗矛任务：5到12级做{zone:1411}，19到27级做{zone:1440}的{area:414}，34到46级做荆棘谷的{object:3202}。传承的外交家特长最多增加10%。奖励：尊敬时，暗矛商人的售价降低10%（经典版规则），包括迅猛龙商人；崇拜后其他种族也能购买迅猛龙：学会坐骑骑术后，40级迅猛龙20金币，60级迅捷迅猛龙200金币。{faction:530}没有战袍或其他奖励。",
	["Dustwind Savage"] = "尘风野蛮人",
	["Dustwind Storm Witch"] = "尘风风暴女巫",
	["Exalted with the {faction:530}"] = "{faction:530}声望达到崇拜",
	["For The Horde! (Rend's head, {area:1583}) and The Lord of Blackrock (Nefarian's head) pay 200 to every Horde city, the {faction:530} included. {area:340} in the {zone:1418} starts the Rend chain: {quest:4903}, {npc:3144}'s Wisdom, then For The Horde!. Take them when your group goes. The Spider God chain of the {zone:1458} guide ({area:978} and the {zone:1425}) pays 225 Darkspear on the way (a fifth at 60 in Classic)."] = "\"为了部落！\"（雷德的头颅，{area:1583}）和\"黑石之王\"（奈法利安的头颅）给每个部落主城200点，{faction:530}也包括在内。{zone:1418}的{area:340}开启雷德任务链：{quest:4903}、{npc:3144}的智慧，然后是\"为了部落！\"。队伍去的时候接上。{zone:1458}指南中的蜘蛛之神任务链（{area:978}和{zone:1425}）沿途给225点暗矛声望（经典旧世60级时只有五分之一）。",
	["For The Horde! (Rend's head, {area:1583}) and The Lord of Blackrock (Nefarian's head) pay 200 to every Horde city, the {faction:530} included. {area:340} in the {zone:1418} starts the Rend chain: {quest:4903}, {npc:3144}'s Wisdom, then For The Horde!. Take them when your group goes. The Spider God chain of the {zone:1458} guide ({area:978} and the {zone:1425}) pays 225 Darkspear on the way."] = "《为了部落！》（雷德之首，{area:1583}）和《黑石之王》（奈法利安之首）给每个部落城市200点，包括{faction:530}。{zone:1418}的{area:340}开启雷德任务链：{quest:4903}、{npc:3144}的“智慧”，然后是《为了部落！》。组队去的时候顺便接。{zone:1458}指南里的蜘蛛之神任务链（{area:978}和{zone:1425}）路上给225点暗矛声望。",
	["Forever pays these old quests in full at any level. The {area:363} is the best of them: about 1,400 {zone:1454} and 1,400 Darkspear reputation in 25 minutes. {npc:3143} waits in the Den, the big hut; {npc:10176} stands outside it."] = "Forever 里这些旧任务任何等级都足额给分。{area:363}是其中最好的：25分钟约1,400点{zone:1454}和1,400点暗矛巨魔声望。{npc:3143}在大棚屋“洞穴”里等着，{npc:10176}站在外面。",
	["Forever pays these old quests in full at any level. {area:362} and north {zone:1411}: about 1,650 {zone:1454} and 1,650 Darkspear reputation in 80 minutes. {npc:3142} and {npc:3139} stand in the middle of the town, {npc:3191} by the barracks, {npc:3147} and Turroc at the edges."] = "Forever 里这些旧任务任何等级都足额给分。{area:362}和{zone:1411}北部：80分钟约1,650点{zone:1454}和1,650点暗矛巨魔声望。{npc:3142}和{npc:3139}站在镇子中间，{npc:3191}在兵营旁，{npc:3147}和图洛克在边上。",
	["Forever pays these old quests in full at any level. {area:367} and the {area:368}: about 625 {zone:1454} and 650 Darkspear reputation in 25 minutes. {npc:3188} and {npc:3304} stand by the huts, {npc:3194} near the water, {npc:7953} south of the village."] = "Forever 里这些旧任务任何等级都足额给分。{area:367}和{area:368}：25分钟约625点{zone:1454}和650点暗矛巨魔声望。{npc:3188}和{npc:3304}站在棚屋旁，{npc:3194}在水边，{npc:7953}在村子以南。",
	["From here it is cloth. Wool, Silk and Mageweave must all be handed in before {npc:14727} offers the {item:14047} donation, and {quest:7837} needs the {item:14047} donation. Buy cloth at the Auction House, or farm it: humanoids drop it, Wool from level 15 to 25, Silk 25 to 40, Mageweave 40 to 50, {item:14047} 50 and up. At 60 farm mobs of level 52 or more: lower ones are grey."] = "接下来靠交布。必须先交完毛料、丝绸和魔纹布，{npc:14727}才会开放{item:14047}捐献，而{quest:7837}又要求先完成{item:14047}捐献。可在拍卖行买布，也可自行刷取：人型生物会掉落，15到25级掉毛料，25到40级掉丝绸，40到50级掉魔纹布，50级及以上掉{item:14047}。60级时刷52级或更高的怪物：更低的已是灰色。",
	["Go back into the cave and keep to the right-hand wall all the way, over a small stream, to {npc:3183} on a ledge above a pool."] = "返回洞穴，始终沿右侧墙走，越过一条小溪，到水池上方凸台上的{npc:3183}处。",
	["Hexed Troll"] = "中邪的巨魔",
	["Honored to Revered is 12,000: 240 hand-ins, 4,800 {item:14047}. The Auction House price of a stack decides whether to farm or buy."] = "从尊敬到崇敬需要12,000声望：交还240次，共4,800块 {item:14047}。根据拍卖行每组售价，决定自己刷还是购买。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. The {area:363} is the best of them: about 1,400 {zone:1454} and 1,400 Darkspear reputation in 25 minutes (about 280 each at a fifth). {npc:3143} waits in the Den, the big hut; {npc:10176} stands outside it."] = "经典旧世中，低于你6级以上的任务声望奖励打折（60级时只有五分之一）；一份无限测试报告则称是全额。你第一次交任务就能验证：若只有五分之一，就跳过这些任务点。{area:363}是其中最好的：25分钟约得1400点{zone:1454}和1400点暗矛声望（五分之一时约各280）。{npc:3143}在兽穴——那间大屋——里等着；{npc:10176}站在屋外。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. {area:362} and north {zone:1411}: about 1,800 {zone:1454} and 1,650 Darkspear reputation in 80 minutes (360 and 330 at a fifth). {npc:3142} and {npc:3139} stand in the middle of the town, {npc:3191} by the barracks, {npc:3147} and {npc:266940} at the edges."] = "经典旧世中，低于你6级以上的任务声望奖励打折（60级时只有五分之一）；一份无限测试报告则称是全额。你第一次交任务就能验证：若只有五分之一，就跳过这些任务点。{area:362}和{zone:1411}北部：80分钟约得1800点{zone:1454}和1650点暗矛声望（五分之一时为360和330）。{npc:3142}和{npc:3139}站在镇中央，{npc:3191}在兵营旁，{npc:3147}和{npc:266940}在镇子边缘。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. {area:367} and the {area:368}: about 700 {zone:1454} and 650 Darkspear reputation in 25 minutes (140 and 130 at a fifth). {npc:3188} and {npc:3304} stand by the huts, {npc:3194} near the water, {npc:7953} south of the village."] = "经典旧世中，低于你6级以上的任务声望奖励打折（60级时只有五分之一）；一份无限测试报告则称是全额。你第一次交任务就能验证：若只有五分之一，就跳过这些任务点。{area:367}和{area:368}：25分钟约得700点{zone:1454}和650点暗矛声望（五分之一时为140和130）。{npc:3188}和{npc:3304}站在茅屋旁，{npc:3194}在水边，{npc:7953}在村子南面。",
	["Kul Tiras Marine"] = "库尔提拉斯水兵",
	["Kul Tiras Sailor"] = "库尔提拉斯水手",
	["Lazy Peon"] = "懒惰的苦工",
	["Lieutenant Benedict"] = "本尼迪克特中尉",
	["Mageweave: the Jadefire satyrs in southern {zone:1448} and the Dunemaul ogres in {zone:1446} drop it about one kill in three, or buy it."] = "魔纹布：{zone:1448} 南部的碧火萨特和 {zone:1446} 的砂槌食人魔大约每击杀三只掉落一次，也可以购买。",
	["Makrura and surf crawlers walk the beaches east and south of Sen'jin. The {quest:97223} is east of the village."] = "龙虾人和碎浪爬行者在森金以东和以南的海滩上活动。{quest:97223}在村子以东。",
	["Makrura and surf crawlers walk the beaches east and south of Sen'jin. The {quest:97223} is east of the village. The Ridgeshade spiders are along the road south of {area:362} and north-east of the Den."] = "森金村东面和南面的海滩上有马克鲁拉和激浪爬行蟹出没。{quest:97223}在村子东面。脊影蜘蛛在{area:362}以南和兽穴东北的路边。",
	["Mottled Boar"] = "杂斑野猪",
	["North of the Den"] = "兽穴以北",
	["North {zone:1411}"] = "{zone:1411} 北部",
	["Razormane Battleguard"] = "钢鬃战斗卫士",
	["Razormane Dustrunner"] = "钢鬃逐尘者",
	["Razormane Quilboar"] = "钢鬃野猪人",
	["Razormane Scout"] = "钢鬃斥候",
	["Reputation · Cities"] = "声望 · 主城",
	["Revered to Exalted is 21,000: 420 hand-ins, 8,400 {item:14047}. At Exalted, {npc:7952} in {area:367} sells the raptors to every Horde race: 20 gold for a level 40 raptor, 200 gold for a swift raptor at level 60 (Forever's prices); in Classic other races needed Exalted to buy them."] = "崇敬到崇拜需要21,000：交还420次、8,400块{item:14047}。崇拜后，{area:367}的{npc:7952}会向所有部落种族出售迅猛龙：40级迅猛龙20金币，60级迅捷迅猛龙200金币（无限服价格）；经典版中其他种族需要崇拜才能购买。",
	["Ridgeshade Creeper"] = "脊影爬行者",
	["Ridgeshade Lurker"] = "脊影潜伏者",
	["Run out of {zone:1454}'s west gate and over the bridge into the {zone:1413}. {npc:3337} and {quest:809} stand at {area:379}."] = "从{zone:1454}西门跑出去，过桥进入{zone:1413}。{npc:3337}和{quest:809}站在{area:379}。",
	["Silk: the Syndicate in {area:287} and Alterac drop it about one kill in three, or buy it."] = "丝绸：{area:287} 和奥特兰克的辛迪加约每三次击杀掉落一次，也可以购买。",
	["Swim to the largest of the {area:368}, south-east of the village. {quest:826}, the idols and the skulls at the circle of power are all there; the Durotar Tigers prowl the smaller islands."] = "游到村庄东南面 {area:368} 中最大的岛。{quest:826}、神像和力量法阵处的头骨都在那里；杜隆塔尔猛虎在较小的岛屿上徘徊。",
	["The Charged Thunder Lizard Organs come from the thunder lizards on {area:369}, just west of {npc:3293}."] = "带电的雷霆蜥蜴器官由 {area:369} 的雷霆蜥蜴掉落，就在 {npc:3293} 正西方。",
	["The Razormane camps are south-west and west of {area:362}. Then head to the {area:368} for the {object:3240}: each nest gives an egg every time."] = "钢鬃野猪人的营地在{area:362}西南和西边。然后去{area:368}找{object:3240}：每个巢每次都给一个蛋。",
	["The Razormane camps are south-west and west of {area:362}; the Prickly Pear cacti grow among them. Then head to the {area:368} for the {object:3240}: each nest gives an egg every time."] = "钢鬃营地在{area:362}西南和西面；仙人掌果就长在营地之间的仙人掌上。然后前往{area:368}找{object:3240}：每个巢每次都能拿到一枚蛋。",
	["The cactus apples grow beside the cacti north of the Den. {npc:3287} lies wounded by the rocks to the north; {quest:790}, his big scorpid, roams close by. {quest:792} swarm at the mouth of the {area:365}; {quest:6394} lies inside: take the middle tunnel where it splits three ways."] = "仙人掌果长在巢穴北面的仙人掌旁。{npc:3287}负伤躺在北面岩石旁；他的大蝎子{quest:790}在附近游荡。{quest:792}聚集在{area:365}洞口；{quest:6394}在洞内：遇到三岔路时走中间的隧道。",
	["The coast and the road"] = "海岸与道路",
	["The keep is south of {area:362} on the coast. {npc:3192} is in the keep's only building; his key opens {object:3239} on the roof, and the {item:4881} inside starts {quest:830}. The sailors and marines drop the {item:4870}."] = "要塞在{area:362}以南的海岸上。{npc:3192}在要塞唯一的那栋楼里；他的钥匙能打开屋顶的{object:3239}，里面的{item:4881}会开启{quest:830}。水手和陆战队员掉{item:4870}。",
	["The keep is south of {area:362} on the coast. {npc:3192} is in the keep's only building; his key opens {object:3239} on the roof, and the {item:4881} inside starts {quest:830}. The sailors and marines drop the {item:4870}; the {item:275713}, Battleaxe and Shield lie outside the keep."] = "城堡在{area:362}以南的海岸上。{npc:3192}在城堡唯一的建筑里；他的钥匙能打开屋顶上的{object:3239}，里面的{item:4881}可开启{quest:830}。水手和水兵掉落{item:4870}；{item:275713}、战斧和盾牌就放在城堡外面。",
	["The training weapons lie on the ground in the Den and among the boars to the north. For the peons: target a sleeping {npc:10556} and use the {item:16114} on it."] = "训练用武器散落在巢穴内及北面野猪群之间。至于苦工：选中睡着的{npc:10556}，对其使用{item:16114}。",
	["The wreck"] = "沉船",
