	["{quest:750}, +100"] = "{quest:750}，+100",
	["{quest:752}, +100"] = "{quest:752}，+100",
	["{quest:755}, +100"] = "{quest:755}，+100",
	["{quest:757}, +150"] = "{quest:757}，+150",
	["{quest:763}, +75: to {npc:2993}"] = "{quest:763}，+75 点声望：交给 {npc:2993}",
	["{quest:764}, +75"] = "{quest:764}，+75",
	["{quest:765}, +100"] = "{quest:765}，+100",
	["{quest:780} graze east of the camp; the Bristleback quilboar and {npc:8554} hold {area:358} beyond them. A {item:4851} lies in the ravine: reading it starts {quest:781}."] = "{quest:780} 在营地东侧觅食；更远处的 {area:358} 被刺背野猪人和 {npc:8554} 占据。峡谷里有一张 {item:4851}：阅读可开始 {quest:781}。",
	["{quest:780}, +150"] = "{quest:780}，+150",
	["{quest:7825} to Exalted"] = "{quest:7825}刷到崇拜",
	["{quest:7825} to Honored"] = "{quest:7825}刷到尊敬",
	["{quest:7825} to Revered"] = "{quest:7825}刷到崇敬",
	["{quest:7825}, +50"] = "{quest:7825}，+50",
	["{quest:7825}: 20 {item:14047} for 50 reputation, as often as you like. Friendly to Honored is 6,000: 120 hand-ins, 2,400 {item:14047}, less what the quests gave you (a tauren starts at Friendly 1,000: 100 hand-ins; an Undead at Neutral 500 first needs 50 more to reach Friendly). Hand in every 20 you carry, one after another."] = "{quest:7825}：每 20 个 {item:14047} 换取 50 点声望，可以无限重复。从友善到尊敬需要 6,000 点：交还 120 次，共 2,400 个 {item:14047}，再扣除任务已提供的声望（牛头人起始为友善 1,000 点：需交还 100 次；亡灵起始为中立 500 点，先额外交还 50 次才能达到友善）。把身上每 20 个作为一组，逐次交还。",
	["{quest:98424}, +100"] = "{quest:98424}，+100",
	["{quest:98427}, +150"] = "{quest:98427}，+150",
	["{quest:98427}, +150: needs {quest:98424}"] = "{quest:98427}，+150：需要{quest:98424}",
	["{quest:99079} waits by the eastern border. The {object:2908} of the ravaged caravan lies north-east of the village: open it to start the next quest."] = "{quest:99079}在东部边界等着。被毁商队的{object:2908}在村子东北：打开它就能接下一个任务。",
	["{quest:99079} waits by the eastern border. The {object:2908} of the ravaged caravan lies north-east of the village: open it to start the next quest. {quest:764} mine is further north-east; the elite shredder Venture Co. Clearcutter works deep inside."] = "{quest:99079}在东部边界旁等你。被洗劫商队的{object:2908}就在村子东北方：打开它开启下一个任务。{quest:764}的矿井在更远的东北方；精英伐木机风险投资公司清砍者在深处作业。",
	["{quest:99080}, +100"] = "{quest:99080}，+100",
	["{quest:99081}, +10"] = "{quest:99081}，+10",
	["{quest:99082}, +10: to {npc:3057} in {faction:81}"] = "{quest:99082}，+10：交给 {faction:81} 的 {npc:3057}",
	["{quest:99101}, +10"] = "{quest:99101}，+10",
	["{zone:1412} quests while you level, {zone:1452} quests and {item:11040} from 55, then {item:14047} to Exalted."] = "练级时做{zone:1412}的任务，55级起做{zone:1452}的任务和交{item:11040}，然后交{item:14047}交到崇拜。",
	["{zone:1452}'s level 56-60 quests, {item:11040} and {item:14047} to Exalted, with {zone:1412}'s old quests as an optional extra."] = "{zone:1452}的56-60级任务，加上{item:11040}和{item:14047}刷到崇拜；{zone:1412}的旧任务可选做。",
}

G["forever/reputation/undercity"] = {
	["+150"] = "+150",
	["Andorhal Tower Four"] = "安多哈尔四号塔",
	["Andorhal Tower One"] = "安多哈尔一号塔",
	["Andorhal Tower Three"] = "安多哈尔三号塔",
	["Andorhal Tower Two"] = "安多哈尔二号塔",
	["Around {area:154}"] = "{area:154}周围",
	["Around {area:159}"] = "{area:159}周围",
	["Borelgore"] = "波雷戈尔",
	["Exalted with the {faction:68}"] = "{faction:68}崇拜",
	["Forever pays these old quests in full at any level. {area:154}, the Forsaken start at the west end of Tirisfal: about 900 {faction:68} reputation in 25 minutes. Starting-zone quests give the other cities no share. {npc:1661}, {npc:1570} and {npc:1740} stand in the village."] = "Forever 里这些旧任务任何等级都足额给分。{area:154}，提瑞斯法西端的被遗忘者新手村：25分钟约900点{faction:68}声望。新手区任务不分给其他城市。{npc:1661}、{npc:1570}和{npc:1740}站在村里。",
	["Forever pays these old quests in full at any level. {area:159} and the fields around it: about 1,100 {faction:68} reputation in 45 minutes. {npc:1515}, {npc:1499}, {npc:1518}, {npc:1496} and {npc:1500} are in the town."] = "Forever 里这些旧任务任何等级都足额给分。{area:159}和周围的田地：45分钟约1,100点{faction:68}声望。{npc:1515}、{npc:1499}、{npc:1518}、{npc:1496}和{npc:1500}在镇上。",
	["From here it is cloth. Wool, Silk and Mageweave must all be handed in before {npc:14729} offers the {item:14047} donation, and {quest:7819} needs the {item:14047} donation. Buy cloth at the Auction House, or farm it: humanoids drop it, Wool from level 15 to 25, Silk 25 to 40, Mageweave 40 to 50, {item:14047} 50 and up. At 60 farm mobs of level 52 or more: lower ones are grey."] = "接下来靠交布。必须先交完毛料、丝绸和魔纹布，{npc:14729}才会开放{item:14047}捐献，而{quest:7819}又要求先完成{item:14047}捐献。可在拍卖行买布，也可自行刷取：人型生物会掉落，15到25级掉毛料，25到40级掉丝绸，40到50级掉魔纹布，50级及以上掉{item:14047}。60级时刷52级或更高的怪物：更低的已是灰色。",
	["Honored to Revered is 12,000: 240 hand-ins, 4,800 {item:14047}. The {item:12358} ({area:1584}) pays 150 in full."] = "尊敬到崇敬需要 12,000 点：交还 240 次，共 4,800 个 {item:14047}。{item:12358}（{area:1584}）会给予全额 150 点声望。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. {area:154}, the Forsaken start at the west end of Tirisfal: about 900 {faction:68} reputation in 25 minutes (180 at a fifth). Starting-zone quests give the other cities no share. {npc:1661}, {npc:1570} and {npc:1740} stand in the village."] = "经典旧世里，比你低6级以上的任务声望奖励会减少（60级时只剩五分之一）；无限测试服的一份报告称全额支付。你第一次交任务就能看出来：如果只给五分之一，就跳过这些据点。{area:154}是被遗忘者在提瑞斯法西端的新手村：约25分钟拿900点{faction:68}声望（五分之一时为180点）。新手村任务不给其他主城分成。{npc:1661}、{npc:1570}和{npc:1740}在村里。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. {area:159} and the fields around it: about 1,100 {faction:68} reputation in 45 minutes (220 at a fifth). {npc:1515}, {npc:1499}, {npc:1518}, {npc:1496} and {npc:1500} are in the town."] = "经典旧世里，比你低6级以上的任务声望奖励会减少（60级时只剩五分之一）；无限测试服的一份报告称全额支付。你第一次交任务就能看出来：如果只给五分之一，就跳过这些据点。{area:159}及其周围的农场：约45分钟拿1100点{faction:68}声望（五分之一时为220点）。{npc:1515}、{npc:1499}、{npc:1518}、{npc:1496}和{npc:1500}在镇里。",
	["Mageweave: the Jadefire satyrs in southern {zone:1448} and the Dunemaul ogres in {zone:1446} drop it about one kill in three, or buy it."] = "魔纹布：{zone:1448} 南部的碧火萨特和 {zone:1446} 的砂槌食人魔大约每击杀三只掉落一次，也可以购买。",
	["Mark {npc:10902} with the {item:12815}"] = "用{item:12815}标记{npc:10902}",
	["Mark {npc:10903} with the {item:12815}"] = "用{item:12815}标记{npc:10903}",
	["Mark {npc:10904} with the {item:12815}"] = "用{item:12815}标记{npc:10904}",
	["Mark {npc:10905} with the {item:12815}"] = "用{item:12815}标记{npc:10905}",
	["Monstrous Plaguebat"] = "巨型瘟疫蝙蝠",
	["Motivate 5 Deathguards"] = "激励5名亡灵卫兵",
	["Night Web Spider"] = "夜网蜘蛛",
	["Noxious Plaguebat"] = "剧毒瘟疫蝙蝠",
	["Pathstrider"] = "巡路者",
	["Plaguebats, {area:2276} and {area:2264}"] = "瘟疫蝙蝠、{area:2276} 和 {area:2264}",
	["Ranger"] = "游侠",
	["Read {item:9323} at the altar of {area:353} to call {npc:2707}, an elite level 55 spider: she drops her venom every time."] = "在 {area:353} 的祭坛阅读 {item:9323}，召来 {npc:2707}，这是一只 55 级精英蜘蛛：她必定掉落毒液。",
	["Reputation · Cities"] = "声望·主城",
	["Revered to Exalted is 21,000: 420 hand-ins, 8,400 {item:14047}. For The Horde! (Rend's head) and The Lord of Blackrock (Nefarian's head) pay 200 to every Horde city. At Exalted, {npc:4731} in {area:159} sells the skeletal horses to every Horde race: 20 gold for a level 40 horse, 200 gold for a level 60 warhorse (Forever's prices); in Classic other races needed Exalted to buy them."] = "从崇敬到崇拜需要21,000声望：交还420次，共8,400块 {item:14047}。“为部落而战！”（雷德的头颅）和“黑石之王”（奈法利安的头颅）各给每座部落主城200声望。达到崇拜后，{area:159} 的 {npc:4731} 会向所有部落种族出售骸骨马：40级马20金币，60级战马200金币（无限服价格）；在经典旧世中，其他种族购买时需要崇拜。",
	["Rot Hide Graverobber"] = "腐皮盗墓贼",
	["Rot Hide Mongrel"] = "腐皮恶犬",
	["Silk: the Syndicate in {area:287} and Alterac drop it about one kill in three, or buy it."] = "丝绸：{area:287} 和奥特兰克的辛迪加约每三次击杀掉落一次，也可以购买。",
	["Six quests across the {zone:1425}, {area:272}, {area:367}, {area:978} and the {faction:68}: 600 {faction:68} and 225 Darkspear reputation. {quest:2937} and {quest:2938} are level 55 and pay 400 in full at 60; the four before them are level 43 to 45 (a fifth at 60 in Classic, 440 {faction:68} in all then). Allow about 90 minutes with the travel. The {quest:2933} stand on the tables of the Witherbark village in the west of the {zone:1425}: click one to start."] = "横跨{zone:1425}、{area:272}、{area:367}、{area:978}和{faction:68}的六个任务：600点{faction:68}和225点暗矛声望。{quest:2937}和{quest:2938}是55级，60级时全额给400点；前面四个是43到45级（经典旧世60级时按五分之一算，那样合计440点{faction:68}）。算上跑路约需90分钟。{quest:2933}摆在{zone:1425}西部枯木村的桌子上：点击一份开始。",
	["Six quests across the {zone:1425}, {area:272}, {area:367}, {area:978} and the {faction:68}: 600 {faction:68} and 225 Darkspear reputation. {quest:2937} and {quest:2938} are level 55 and pay 400 in full at 60; the four before them are level 43 to 45 and pay in full too. Allow about 90 minutes with the travel. The {quest:2933} stand on the tables of the Witherbark village in the west of the {zone:1425}: click one to start."] = "{zone:1425}、{area:272}、{area:367}、{area:978}和{faction:68}一带的六个任务：600点{faction:68}和225点暗矛巨魔声望。{quest:2937}和{quest:2938}是55级，60级足额给400；在它们之前的四个是43到45级，也足额给。加上跑路大概留90分钟。{quest:2933}放在{zone:1425}西部枯木村落的桌上：点一个就能开始。",
	["The Noxious Plaguebats fly in the south of the zone, the Monstrous Plaguebats further north-west. {area:2276} is north-west of {area:2268}; the {item:15847} lies inside. Do {area:2264} last: its Scourge drop {item:15447}, which lasts only 10 minutes. With 7 in your bags, use the {item:15454} at once for the {item:15448}."] = "毒性瘟疫蝙蝠在地区南部飞行，巨型瘟疫蝙蝠则在更西北。{area:2276} 位于 {area:2268} 西北；{item:15847} 就在里面。最后再做 {area:2264}：那里的天灾军团会掉落 {item:15447}，它只能保存 10 分钟。背包里凑齐 7 个后，立即使用 {item:15454} 获取 {item:15448}。",
	["The Plaguelands' level 55-60 quests and {item:14047} to Exalted, with Tirisfal's old quests as an optional extra."] = "通过瘟疫之地的55-60级任务和{item:14047}刷到崇拜，提瑞斯法林地的旧任务可选做。",
	["The Scarlet camp"] = "血色营地",
	["The Scarlet camp is south-east of {area:154}. {npc:1667} leads it."] = "血色营地在 {area:154} 东南方，由 {npc:1667} 统领。",
	["The Witherbark Broodguards crawl around {area:353} in the south-west of the {zone:1425}; about one in ten carries an undamaged sac."] = "枯木巢穴守卫在 {zone:1425} 西南的 {area:353} 周围爬行；约十分之一携带完整的毒囊。",
	["The level 55 to 60 quests pay in full. First the {area:152}: {npc:10879}, by the {faction:68}'s elevators, sends you there."] = "55 至 60 级任务会给予完整奖励。先去 {area:152}：{faction:68} 升降梯旁的 {npc:10879} 会让你前往。",
	["The skeletons of {area:157} drop the ribs; the Darkeye Bonecasters the skulls."] = "{area:157}的骷髅掉落肋骨；暗眼骷髅法师掉落颅骨。",
	["The {object:164662} are all around the village. {quest:380} is the mine north-west; the {npc:271961} hang inside. {npc:1919} waits at the ruined camp by the road north-east: bury his remains at {object:178090}, in the front row of the village graveyard."] = "{object:164662} 散布在村庄周围。{quest:380} 是西北方的矿洞；{npc:271961} 悬挂在洞内。{npc:1919} 在东北方道路旁的废弃营地等待：将他的遗骸埋在村庄墓地前排的 {object:178090}。",
	["Tirisfal quests while you level, the Plaguelands quests from 55, then {item:14047} to Exalted."] = "升级时做提瑞斯法林地的任务，55级起做瘟疫之地的任务，然后上交{item:14047}直到崇拜。",
	["Undercity Reputation"] = "幽暗城声望",
	["Use the {item:286176} on five Deathguards around {area:159}. For {quest:99141}, talk to {npc:1496} west of {area:159}, {npc:251001} at the waystation east of it and {npc:10666} on the road. The Rot Hide gnolls dig at the mass grave north of {area:159}. The {npc:1525} walk around the old bridge west of {area:159}; the dry branches lie under the trees there. Darkhounds roam everywhere."] = "对{area:159}周围的5名亡灵卫兵使用{item:286176}。做{quest:99141}时，与{area:159}西面的{npc:1496}、东面驿站的{npc:251001}及路上的{npc:10666}交谈。腐皮豺狼人在{area:159}北面的乱葬岗挖掘。{npc:1525}在{area:159}西面旧桥周围行走；干树枝散落在那里的树下。黑暗犬到处都有。",
